--
-- Name: ai_tool_find_entity(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ai_tool_find_entity(args jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  n text := args->>'name';
  k text := coalesce(args->>'kind', 'any');
  out jsonb := '[]'::jsonb;
  r jsonb;
begin
  if n is null then return jsonb_build_object('error', 'name is required'); end if;
  if k in ('any', 'team') then
    r := public.ai_resolve_team(n); out := out || jsonb_build_array(jsonb_build_object('kind', 'team') || r); end if;
  if k in ('any', 'competition') then
    r := public.ai_resolve_competition(n); out := out || jsonb_build_array(jsonb_build_object('kind', 'competition') || r); end if;
  if k in ('any', 'player') then
    r := public.ai_resolve_fpl_player(n, public.fpl_current_season_id());
    out := out || jsonb_build_array(jsonb_build_object('kind', 'fpl_player (current season)') || r); end if;
  return jsonb_build_object('tool', 'find_entity', 'source', jsonb_build_array('teams', 'team_aliases', 'leagues', 'fpl_players'),
    'as_of', now(), 'kind', 'observed', 'rows', out);
end $$;


ALTER FUNCTION public.ai_tool_find_entity(args jsonb) OWNER TO postgres;

--
-- Name: ai_tool_get_club_accounts(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ai_tool_get_club_accounts(args jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare t jsonb; tid bigint; yrs int := least(coalesce((args->>'years')::int, 1), 10);
begin
  if not args ? 'team' then return jsonb_build_object('error', 'team is required'); end if;
  t := public.ai_resolve_team(args->>'team'); if t ? 'error' then return t; end if;
  tid := (t->>'team_id')::bigint;
  return jsonb_build_object('tool', 'get_club_accounts',
    'source', jsonb_build_array('finance_published_periods', 'finance_published_provenance'), 'as_of', now(), 'kind', 'observed',
    'note', 'Published statutory accounts from Companies House filings, most recent first. Values are in the stated currency; multiply by unit_scale (e.g. 1 = units). NULL = not disclosed, not zero. Financial years do not align with football seasons.',
    'club', t->>'team',
    'rows', coalesce((select jsonb_agg(r) from (
      select v.period_start, v.period_end, v.period_months, v.reporting_entity, v.company_number, v.is_consolidated,
             v.currency, v.unit_scale, v.revenue_total, v.revenue_matchday, v.revenue_broadcast, v.revenue_commercial,
             v.revenue_other, v.staff_costs, v.player_amortisation, v.operating_profit, v.profit_before_tax,
             v.profit_after_tax, v.cash, v.borrowings, v.net_assets, v.average_employees, v.filing_date, v.source_url,
             case when coalesce((args->>'include_sources')::boolean, false) then
               (select jsonb_agg(jsonb_build_object('metric', pv.metric_key, 'xbrl_concept', pv.original_xbrl_concept,
                        'value_in_filing', pv.original_value, 'filing_reference', pv.filing_reference, 'source_url', pv.source_url))
                  from finance_published_provenance pv where pv.team_id = v.team_id and pv.period_end = v.period_end) end sources
        from finance_published_periods v
        join finance_periods fp on fp.team_id = v.team_id and fp.period_end = v.period_end
                               and fp.is_current_version and fp.validation_status = 'published'
       where v.team_id = tid and v.validation_status = 'published'
       order by v.period_end desc limit yrs) r), '[]'::jsonb));
end $$;


ALTER FUNCTION public.ai_tool_get_club_accounts(args jsonb) OWNER TO postgres;

--
-- Name: ai_tool_get_competition_summary(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ai_tool_get_competition_summary(args jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare c jsonb; lid bigint; sid bigint;
begin
  if not args ? 'competition' then return jsonb_build_object('error', 'competition is required'); end if;
  c := public.ai_resolve_competition(args->>'competition'); if c ? 'error' then return c; end if;
  lid := (c->>'league_id')::bigint;
  sid := public.ai_resolve_season(lid, args->>'season');
  return jsonb_build_object('tool', 'get_competition_summary', 'source', jsonb_build_array('matches'),
    'as_of', now(), 'kind', 'observed',
    'rows', (select jsonb_agg(r) from (
      select c->>'competition' competition, public.ai_season_label(sid) season, count(*) matches_played,
             sum(full_time_home_goals + full_time_away_goals) total_goals,
             round(avg(full_time_home_goals + full_time_away_goals), 2) goals_per_game,
             round(avg(full_time_home_goals), 2) home_goals_per_game, round(avg(full_time_away_goals), 2) away_goals_per_game,
             count(*) filter (where full_time_result = 'H') home_wins, count(*) filter (where full_time_result = 'D') draws,
             count(*) filter (where full_time_result = 'A') away_wins,
             min(match_date) first_match, max(match_date) latest_match
        from matches where league_id = lid and season_id = sid and full_time_home_goals is not null) r));
end $$;


ALTER FUNCTION public.ai_tool_get_competition_summary(args jsonb) OWNER TO postgres;

--
-- Name: ai_tool_get_data_status(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ai_tool_get_data_status(args jsonb) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select jsonb_build_object('tool', 'get_data_status',
    'source', jsonb_build_array('matches', 'fixtures', 'leagues', 'seasons', 'model_fit_runs', 'fpl_players', 'fpl_player_projections', 'fixture_broadcasts'),
    'as_of', now(), 'kind', 'observed',
    'freshness', jsonb_build_object(
      'results_last_loaded', (select max(updated_at) from matches),
      'latest_result_date', (select max(match_date) from matches),
      'fixtures_last_changed', (select max(updated_at) from fixtures),
      'latest_accepted_model_fit', (select max(fitted_at) from model_fit_runs where status = 'accepted'),
      'fpl_data_last_loaded', (select max(updated_at) from fpl_players where season_id = public.fpl_current_season_id()),
      'fpl_projections_generated', (select max(generated_at) from fpl_player_projections where model_version = 'leaguewide_v6'),
      'tv_listings_last_synced', (select max(last_synced_at) from fixture_broadcasts)),
    'coverage', (select jsonb_agg(r order by r.competition_type, r.country, r.competition) from (
      select l.name competition, l.code, c.name country, l.competition_type,
             public.ai_season_label((select s1.season_id from seasons s1 where s1.start_year = min(sn.start_year))) first_season, public.ai_season_label((select s1.season_id from seasons s1 where s1.start_year = max(sn.start_year))) latest_season,
             count(distinct m.season_id) seasons, count(*) results
        from matches m join seasons sn on sn.season_id = m.season_id join leagues l using (league_id) left join countries c on c.country_id = l.country_id
       group by l.name, l.code, c.name, l.competition_type) r),
    'fpl_seasons', (select jsonb_agg(distinct public.ai_season_label(season_id)) from fpl_player_season_totals))
$$;


ALTER FUNCTION public.ai_tool_get_data_status(args jsonb) OWNER TO postgres;

--
-- Name: ai_tool_get_fixtures(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ai_tool_get_fixtures(args jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  t jsonb; c jsonb; tid bigint; lid bigint;
  lim int := least(coalesce((args->>'limit')::int, 5), 20);
  d_from date := coalesce((args->>'from_date')::date, current_date);
  d_to date := (args->>'to_date')::date;
begin
  if args ? 'team' then t := public.ai_resolve_team(args->>'team'); if t ? 'error' then return t; end if; tid := (t->>'team_id')::bigint; end if;
  if args ? 'competition' then c := public.ai_resolve_competition(args->>'competition'); if c ? 'error' then return c; end if; lid := (c->>'league_id')::bigint; end if;
  if tid is null and lid is null then return jsonb_build_object('error', 'Give a team, a competition, or both.'); end if;
  return jsonb_build_object('tool', 'get_fixtures', 'source', jsonb_build_array('fixtures', 'teams', 'leagues'),
    'as_of', now(), 'kind', 'observed',
    'note', 'Scheduled fixtures from today. Kick-off times are UK local time. Results are in get_results.',
    'rows', coalesce((select jsonb_agg(r) from (
      select f.kickoff_date, to_char(f.kickoff_time, 'HH24:MI') kickoff_time_uk, l.name competition, f.round, f.matchweek,
             h.display_name home_team, a.display_name away_team, f.status
        from fixtures f join leagues l using (league_id)
        join teams h on h.team_id = f.home_team_id join teams a on a.team_id = f.away_team_id
       where f.status in ('scheduled', 'postponed') and f.kickoff_date >= d_from
         and (d_to is null or f.kickoff_date <= d_to)
         and (tid is null or tid in (f.home_team_id, f.away_team_id))
         and (lid is null or f.league_id = lid)
       order by f.kickoff_date, f.kickoff_time nulls last limit lim) r), '[]'::jsonb));
end $$;


ALTER FUNCTION public.ai_tool_get_fixtures(args jsonb) OWNER TO postgres;

--
-- Name: ai_tool_get_fpl_players(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ai_tool_get_fpl_players(args jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  cur bigint := public.fpl_current_season_id();
  sid bigint; pl jsonb; t jsonb; tid bigint; pid int;
  pos int := case upper(args->>'position') when 'GK' then 1 when 'DEF' then 2 when 'MID' then 3 when 'FWD' then 4 end;
  sort text := coalesce(args->>'sort_by', 'total_points');
  lim int := least(coalesce((args->>'limit')::int, 10), 30);
  avail text := coalesce(args->>'availability', 'any');
begin
  sid := case when args->>'season' in ('last', 'last season', 'previous') then public.previous_season_id(cur)
              when args ? 'season' and args->>'season' not in ('current', 'this season', '') then
                (select season_id from seasons where label = regexp_replace(args->>'season', '[^0-9]', '', 'g')
                   or label = right(split_part(args->>'season', '/', 1), 2) || right(split_part(args->>'season', '/', 2), 2) limit 1)
              else cur end;
  if sid is null then return jsonb_build_object('error', 'Unknown season.'); end if;
  if sort not in ('total_points', 'price', 'minutes', 'goals', 'assists', 'expected_goals', 'goals_minus_xg',
                  'defensive_contribution_points', 'selected_by_percent') then
    return jsonb_build_object('error', 'Unknown sort_by.'); end if;

  if sid <> cur then
    -- Past season: final totals.
    return jsonb_build_object('tool', 'get_fpl_players', 'source', jsonb_build_array('fpl_player_season_totals'),
      'as_of', now(), 'kind', 'observed', 'season', public.ai_season_label(sid),
      'note', 'Final FPL season totals. Prices in £m.',
      'rows', coalesce((select jsonb_agg(r) from (
        select web_name player, full_name, team_name team, public.ai_fpl_position(element_type) position,
               round(start_cost / 10.0, 1) start_price, round(end_cost / 10.0, 1) end_price, total_points, minutes,
               goals_scored goals, assists, clean_sheets, bonus, selected_by_percent
          from fpl_player_season_totals
         where season_id = sid
           and (pos is null or element_type = pos)
           and (not args ? 'player' or public.ai_norm(web_name) like '%' || trim(public.ai_norm(args->>'player')) || '%'
                or public.ai_norm(full_name) like '%' || trim(public.ai_norm(args->>'player')) || '%')
           and (not args ? 'team' or public.ai_norm(team_name) like '%' || trim(public.ai_norm(args->>'team')) || '%')
         order by case sort when 'price' then end_cost when 'minutes' then minutes when 'goals' then goals_scored
                            when 'assists' then assists else total_points end desc nulls last
         limit lim) r), '[]'::jsonb));
  end if;

  if args ? 'player' then
    pl := public.ai_resolve_fpl_player(args->>'player', cur); if pl ? 'error' then return pl; end if;
    pid := (pl->>'fpl_player_id')::int;
  end if;
  if args ? 'team' then t := public.ai_resolve_team(args->>'team'); if t ? 'error' then return t; end if; tid := (t->>'team_id')::bigint; end if;

  return jsonb_build_object('tool', 'get_fpl_players',
    'source', jsonb_build_array('fpl_players', 'fpl_player_gameweeks'), 'as_of', now(), 'kind', 'observed',
    'season', public.ai_season_label(cur),
    'note', 'Official FPL data this season. Price in £m. availability filter: injured_doubtful_or_suspended = status d/i/s; not_available = anything but a (also includes loans and departures). status: a = available, d = doubtful, i = injured, s = suspended, u = unavailable, n = not in squad. chance_of_playing is FPL''s own %. defensive_contribution_points = FPL points from the defensive contribution rule this season.',
    'rows', coalesce((select jsonb_agg(r) from (
      with dc as (
        select g.fpl_player_id, sum((s->>'points')::int) pts
          from fpl_player_gameweeks g
          cross join lateral jsonb_array_elements(g.source_payload->'explain') e
          cross join lateral jsonb_array_elements(e->'stats') s
         where g.season_id = cur and s->>'identifier' = 'defensive_contribution'
         group by g.fpl_player_id)
      select p.web_name player, p.first_name || ' ' || p.second_name full_name, tm.display_name team,
             public.ai_fpl_position(p.element_type) position, round(p.now_cost / 10.0, 1) price,
             p.total_points, p.event_points last_gameweek_points, p.minutes, p.goals_scored goals, p.assists,
             p.clean_sheets, p.bonus, round(p.expected_goals, 2) expected_goals, round(p.expected_assists, 2) expected_assists,
             round(p.goals_scored - p.expected_goals, 2) goals_minus_xg, coalesce(dc.pts, 0) defensive_contribution_points,
             p.selected_by_percent, p.status, p.chance_of_playing_next_round, nullif(p.news, '') news
        from fpl_players p
        left join teams tm on tm.team_id = p.canonical_team_id
        left join dc on dc.fpl_player_id = p.fpl_player_id
       where p.season_id = cur
         and (pid is null or p.fpl_player_id = pid)
         and (tid is null or p.canonical_team_id = tid)
         and (pos is null or p.element_type = pos)
         and (avail = 'any' or (avail = 'injured_doubtful_or_suspended' and p.status in ('d', 'i', 's'))
              or (avail = 'not_available' and p.status <> 'a'))
       order by case sort when 'price' then p.now_cost::numeric when 'minutes' then p.minutes when 'goals' then p.goals_scored
                          when 'assists' then p.assists when 'expected_goals' then p.expected_goals
                          when 'goals_minus_xg' then p.goals_scored - p.expected_goals
                          when 'defensive_contribution_points' then coalesce(dc.pts, 0)
                          when 'selected_by_percent' then p.selected_by_percent
                          else p.total_points end desc nulls last, p.total_points desc
       limit lim) r), '[]'::jsonb));
end $$;


ALTER FUNCTION public.ai_tool_get_fpl_players(args jsonb) OWNER TO postgres;

--
-- Name: ai_tool_get_fpl_projections(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ai_tool_get_fpl_projections(args jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  cur bigint := public.fpl_current_season_id();
  gw int := coalesce((args->>'gameweek')::int,
                     (select min(fpl_event_id) from fpl_gameweeks where season_id = cur and not finished));
  n_gw int := least(coalesce((args->>'gameweeks')::int, 1), 6);
  pos int := case upper(args->>'position') when 'GK' then 1 when 'DEF' then 2 when 'MID' then 3 when 'FWD' then 4 end;
  maxp numeric := (args->>'max_price')::numeric;
  lim int := least(coalesce((args->>'limit')::int, 10), 30);
  pl jsonb; t jsonb; pid int; tid bigint;
begin
  if args ? 'player' then pl := public.ai_resolve_fpl_player(args->>'player', cur); if pl ? 'error' then return pl; end if; pid := (pl->>'fpl_player_id')::int; end if;
  if args ? 'team' then t := public.ai_resolve_team(args->>'team'); if t ? 'error' then return t; end if; tid := (t->>'team_id')::bigint; end if;
  return jsonb_build_object('tool', 'get_fpl_projections',
    'source', jsonb_build_array('fpl_projection_frontend_feed_v6', 'fixtures', 'fpl_players'), 'as_of', now(),
    'kind', 'model_estimate', 'model_version', 'leaguewide_v6',
    'gameweeks', case when n_gw = 1 then gw::text else gw || '-' || (gw + n_gw - 1) end,
    'note', 'FixtureShark projections: expected FPL points and components summed over the gameweeks requested (double gameweeks count both fixtures). These are model estimates, not FPL data. Price in £m.',
    'rows', coalesce((select jsonb_agg(r) from (
      select p.web_name player, tm.display_name team, public.ai_fpl_position(p.element_type) position,
             round(p.now_cost / 10.0, 1) price, count(*) fixtures,
             round(sum(v.expected_fpl_points), 2) expected_points, round(sum(v.expected_minutes)) expected_minutes,
             round(avg(v.start_probability), 2) avg_start_probability,
             round(sum(v.expected_goals), 2) expected_goals, round(sum(v.expected_assists), 2) expected_assists,
             round(avg(v.clean_sheet_probability), 2) avg_clean_sheet_probability, round(sum(v.expected_bonus), 2) expected_bonus
        from fpl_projection_frontend_feed_v6 v
        join fixtures f on f.fixture_id = v.fixture_id
        join fpl_players p on p.fpl_player_id = v.fpl_player_id and p.season_id = cur
        left join teams tm on tm.team_id = p.canonical_team_id
       where f.league_id = 1 and f.season_id = cur and f.matchweek between gw and gw + n_gw - 1
         and (pid is null or v.fpl_player_id = pid)
         and (tid is null or p.canonical_team_id = tid)
         and (pos is null or p.element_type = pos)
         and (maxp is null or p.now_cost <= maxp * 10)
       group by p.web_name, tm.display_name, p.element_type, p.now_cost
       order by sum(v.expected_fpl_points) desc
       limit lim) r), '[]'::jsonb));
end $$;


ALTER FUNCTION public.ai_tool_get_fpl_projections(args jsonb) OWNER TO postgres;

--
-- Name: ai_tool_get_league_table(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ai_tool_get_league_table(args jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare c jsonb; lid bigint; sid bigint;
begin
  if not args ? 'competition' then return jsonb_build_object('error', 'competition is required'); end if;
  c := public.ai_resolve_competition(args->>'competition'); if c ? 'error' then return c; end if;
  lid := (c->>'league_id')::bigint;
  sid := public.ai_resolve_season(lid, args->>'season');
  if sid is null then return jsonb_build_object('error', 'Unknown season.'); end if;
  return jsonb_build_object('tool', 'get_league_table', 'source', jsonb_build_array('league_standings', 'point_deductions', 'league_season_formats'),
    'as_of', now(), 'kind', 'observed', 'competition', c->>'competition', 'season', public.ai_season_label(sid),
    'note', 'points already include any deduction (shown in deduction) and, in split formats, any halving of regular-season points (split_adjustment, negative). split_group 1 is the championship group: after the split, groups are locked, so a club in group 1 ranks above every club in group 2 whatever the points. European play-off ties are not in the table. Sorted by position.',
    'rows', coalesce((select jsonb_agg(r) from (
      select s.position, t.display_name team, s.played, s.won, s.drawn, s.lost, s.goals_for, s.goals_against,
             s.goals_for - s.goals_against goal_difference, s.deduction, s.split_adjustment, s.split_group, s.points,
             s.home_won || '-' || s.home_drawn || '-' || s.home_lost home_wdl,
             s.away_won || '-' || s.away_drawn || '-' || s.away_lost away_wdl
        from league_standings s join teams t using (team_id)
       where s.league_id = lid and s.season_id = sid
       order by s.position) r), '[]'::jsonb));
end $$;


ALTER FUNCTION public.ai_tool_get_league_table(args jsonb) OWNER TO postgres;

--
-- Name: ai_tool_get_results(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ai_tool_get_results(args jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  t jsonb; o jsonb; c jsonb; tid bigint; oid_ bigint; lid bigint; sid bigint;
  lim int := least(coalesce((args->>'limit')::int, 10), 50);
  venue text := coalesce(args->>'venue', 'any');
begin
  if args ? 'team' then t := public.ai_resolve_team(args->>'team'); if t ? 'error' then return t; end if; tid := (t->>'team_id')::bigint; end if;
  if args ? 'opponent' then o := public.ai_resolve_team(args->>'opponent'); if o ? 'error' then return o; end if; oid_ := (o->>'team_id')::bigint; end if;
  if args ? 'competition' then c := public.ai_resolve_competition(args->>'competition'); if c ? 'error' then return c; end if; lid := (c->>'league_id')::bigint; end if;
  if tid is null and lid is null then return jsonb_build_object('error', 'Give a team, a competition, or both.'); end if;
  if args ? 'season' then
    if lid is null then return jsonb_build_object('error', 'season needs a competition'); end if;
    sid := public.ai_resolve_season(lid, args->>'season');
    if sid is null then return jsonb_build_object('error', 'Unknown season "' || (args->>'season') || '".'); end if;
  end if;
  return jsonb_build_object('tool', 'get_results', 'source', jsonb_build_array('matches', 'teams', 'leagues', 'seasons'),
    'as_of', now(), 'kind', 'observed', 'note', 'Most recent first. HT = half time.',
    'rows', coalesce((select jsonb_agg(r) from (
      select m.match_date, l.name competition, public.ai_season_label(m.season_id) season,
             h.display_name home_team, a.display_name away_team,
             m.full_time_home_goals home_goals, m.full_time_away_goals away_goals,
             m.half_time_home_goals ht_home, m.half_time_away_goals ht_away, m.decided_by
        from matches m join leagues l using (league_id)
        join teams h on h.team_id = m.home_team_id join teams a on a.team_id = m.away_team_id
       where m.full_time_home_goals is not null
         and (tid is null or (venue = 'home' and m.home_team_id = tid) or (venue = 'away' and m.away_team_id = tid)
              or (venue = 'any' and tid in (m.home_team_id, m.away_team_id)))
         and (oid_ is null or oid_ in (m.home_team_id, m.away_team_id))
         and (lid is null or m.league_id = lid)
         and (sid is null or m.season_id = sid)
       order by m.match_date desc limit lim) r), '[]'::jsonb));
end $$;


ALTER FUNCTION public.ai_tool_get_results(args jsonb) OWNER TO postgres;

--
-- Name: ai_tool_get_tv_listings(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ai_tool_get_tv_listings(args jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare t jsonb; tid bigint; lim int := least(coalesce((args->>'limit')::int, 5), 20);
begin
  if args ? 'team' then t := public.ai_resolve_team(args->>'team'); if t ? 'error' then return t; end if; tid := (t->>'team_id')::bigint; end if;
  return jsonb_build_object('tool', 'get_tv_listings', 'source', jsonb_build_array('upcoming_watch_guide'), 'as_of', now(),
    'kind', 'observed',
    'note', 'UK listings for upcoming fixtures. status not_televised = confirmed not shown live in the UK (includes the Saturday 3pm blackout rule). A fixture with no rows here has no UK listing yet (unknown, not the same as not televised).',
    'rows', coalesce((select jsonb_agg(r) from (
      select g.kickoff_date, to_char(g.kickoff_time, 'HH24:MI') kickoff_time_uk, g.league_name competition,
             g.home_team_name home_team, g.away_team_name away_team, g.status, g.is_live, g.broadcaster, g.channel,
             g.streaming_service, g.service_product, g.access_type, g.is_free_to_air, g.is_subscription, g.is_ppv,
             g.confidence, g.availability_notes, g.watch_url, g.source, g.verified_at::date verified
        from upcoming_watch_guide g
       where (tid is null or tid in (g.home_team_id, g.away_team_id))
         and (not args ? 'from_date' or g.kickoff_date >= (args->>'from_date')::date)
         and (not args ? 'to_date' or g.kickoff_date <= (args->>'to_date')::date)
       order by g.kickoff_date, g.kickoff_time limit lim) r), '[]'::jsonb));
end $$;


ALTER FUNCTION public.ai_tool_get_tv_listings(args jsonb) OWNER TO postgres;

--
-- Name: apply_uk_3pm_blackout(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.apply_uk_3pm_blackout() RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  n_del int;
  n_ins int;
begin
  -- Rule rows that no longer apply: another row now exists for the
  -- fixture, or the fixture has moved out of the blackout window.
  with gone as (
    delete from public.fixture_broadcasts fb
    where fb.source = 'rule:3pm_blackout' and fb.airtable_record_id is null
      and (
        exists (select 1 from public.fixture_broadcasts o
                where o.fixture_id = fb.fixture_id and o.market = fb.market and o.broadcast_id <> fb.broadcast_id)
        or not exists (
          select 1 from public.fixtures f join public.leagues l on l.league_id = f.league_id
          where f.fixture_id = fb.fixture_id
            and l.code in ('E0','E1','E2','E3','EC')
            and extract(isodow from f.kickoff_date) = 6
            and f.kickoff_time between time '14:45' and time '17:15'))
    returning 1)
  select count(*) into n_del from gone;

  with added as (
    insert into public.fixture_broadcasts (fixture_id, market, status, source, verified_at, availability_notes, confidence)
    select f.fixture_id, 'GB', 'confirmed_not_televised', 'rule:3pm_blackout', now(),
           'Saturday 3pm kick-offs are not shown live in the UK.', 'probable'
    from public.fixtures f
    join public.leagues l on l.league_id = f.league_id
    where l.code in ('E0','E1','E2','E3','EC')
      and f.status = 'scheduled'
      and f.kickoff_date >= current_date
      and extract(isodow from f.kickoff_date) = 6
      and f.kickoff_time between time '14:45' and time '17:15'
      and not exists (select 1 from public.fixture_broadcasts fb where fb.fixture_id = f.fixture_id and fb.market = 'GB')
    returning 1)
  select count(*) into n_ins from added;

  return jsonb_build_object('removed', n_del, 'added', n_ins);
end;
$$;


ALTER FUNCTION public.apply_uk_3pm_blackout() OWNER TO postgres;

--
-- Name: backfill_fixture_predictions(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.backfill_fixture_predictions() RETURNS integer
    LANGUAGE sql
    SET search_path TO 'public', 'pg_temp'
    AS $$
with latest_fit as (
 select distinct on (league_id) league_id,fit_run_id,rho,home_advantage,window_start_date,window_end_date,fitted_at from public.model_fit_runs where status='accepted' order by league_id,fitted_at desc
), appearances as (
 select lf.league_id,lf.fit_run_id,x.team_id,count(*)::numeric n
 from latest_fit lf join lateral (
   select m.home_team_id team_id from public.matches m where m.league_id=lf.league_id and m.match_date between lf.window_start_date and lf.window_end_date
   union all
   select m.away_team_id from public.matches m where m.league_id=lf.league_id and m.match_date between lf.window_start_date and lf.window_end_date
 ) x on true group by lf.league_id,lf.fit_run_id,x.team_id
), base as (
 select f.fixture_id,lf.fit_run_id,
 -- The model's own terms, with overrides deliberately NOT included --
 -- they're added separately below so both versions come from one
 -- expression rather than two that could drift apart.
 lf.home_advantage + hr.attack_strength*(case when f.league_id=1 and coalesce(ha.n,0)<12 then coalesce(ha.n,0)/(coalesce(ha.n,0)+12) else 1 end)
 - ar.defence_strength*(case when f.league_id=1 and coalesce(aa.n,0)<12 then coalesce(aa.n,0)/(coalesce(aa.n,0)+12) else 1 end)
 + case when f.league_id=1 then coalesce(hadj.centered_home_attack_dev,0)*(case when coalesce(ha.n,0)<12 then coalesce(ha.n,0)/(coalesce(ha.n,0)+12) else 1 end) - coalesce(aadj.centered_away_defence_dev,0)*(case when coalesce(aa.n,0)<12 then coalesce(aa.n,0)/(coalesce(aa.n,0)+12) else 1 end) else 0 end
 as home_exponent,
 ar.attack_strength*(case when f.league_id=1 and coalesce(aa.n,0)<12 then coalesce(aa.n,0)/(coalesce(aa.n,0)+12) else 1 end)
 - hr.defence_strength*(case when f.league_id=1 and coalesce(ha.n,0)<12 then coalesce(ha.n,0)/(coalesce(ha.n,0)+12) else 1 end)
 + case when f.league_id=1 then coalesce(aadj.centered_away_attack_dev,0)*(case when coalesce(aa.n,0)<12 then coalesce(aa.n,0)/(coalesce(aa.n,0)+12) else 1 end) - coalesce(hadj.centered_home_defence_dev,0)*(case when coalesce(ha.n,0)<12 then coalesce(ha.n,0)/(coalesce(ha.n,0)+12) else 1 end) else 0 end
 as away_exponent,
 coalesce(hov.attack_adjustment,0) - coalesce(aov.defence_adjustment,0) as home_override,
 coalesce(aov.attack_adjustment,0) - coalesce(hov.defence_adjustment,0) as away_override,
 case when f.league_id=1 then 'dc_home_away_sparse_shrink_v2' else 'dc_baseline_v1' end model_version
 from fixtures f join latest_fit lf on lf.league_id=f.league_id join team_ratings hr on hr.team_id=f.home_team_id and hr.fit_run_id=lf.fit_run_id join team_ratings ar on ar.team_id=f.away_team_id and ar.fit_run_id=lf.fit_run_id
 left join appearances ha on ha.league_id=f.league_id and ha.fit_run_id=lf.fit_run_id and ha.team_id=f.home_team_id left join appearances aa on aa.league_id=f.league_id and aa.fit_run_id=lf.fit_run_id and aa.team_id=f.away_team_id
 left join team_home_away_adjustment_v1 hadj on hadj.team_id=f.home_team_id left join team_home_away_adjustment_v1 aadj on aadj.team_id=f.away_team_id
 left join team_strength_manual_override hov on hov.team_id=f.home_team_id left join team_strength_manual_override aov on aov.team_id=f.away_team_id
 where f.status in('scheduled','postponed')
   -- Kick-off guard (2026-09-23): never refresh from a fit dated on/after kick-off.
   and lf.fitted_at::date < f.kickoff_date
), preds as (
 select fixture_id, fit_run_id, model_version,
   exp(home_exponent + home_override) as pred_home,
   exp(away_exponent + away_override) as pred_away,
   exp(home_exponent) as raw_home,
   exp(away_exponent) as raw_away
 from base
), updated as (
 update fixtures f set
   predicted_home_goals=p.pred_home, predicted_away_goals=p.pred_away,
   raw_predicted_home_goals=p.raw_home, raw_predicted_away_goals=p.raw_away,
   prediction_fit_run_id=p.fit_run_id, prediction_model_version=p.model_version, predicted_at=now()
 from preds p where p.fixture_id=f.fixture_id and f.status in('scheduled','postponed') returning f.fixture_id
) select count(*)::integer from updated;
$$;


ALTER FUNCTION public.backfill_fixture_predictions() OWNER TO postgres;

--
-- Name: backfill_historic_fixture_predictions(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.backfill_historic_fixture_predictions(target_season_id bigint) RETURNS integer
    LANGUAGE sql
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with candidate_fits as (
    select
      f.fixture_id,
      mfr.fit_run_id,
      mfr.rho,
      mfr.home_advantage,
      row_number() over (partition by f.fixture_id order by mfr.fitted_at desc) as rn
    from public.fixtures f
    join public.model_fit_runs mfr
      on mfr.league_id = f.league_id
      and mfr.status = 'accepted'
      and mfr.fitted_at::date < f.kickoff_date
    where f.season_id = target_season_id
      and f.predicted_home_goals is null
  ),
  chosen as (
    select fixture_id, fit_run_id, rho, home_advantage
    from candidate_fits
    where rn = 1
  ),
  preds as (
    select
      c.fixture_id,
      c.fit_run_id,
      exp(c.home_advantage + hr.attack_strength - ar.defence_strength) as pred_home,
      exp(ar.attack_strength - hr.defence_strength) as pred_away
    from chosen c
    join public.fixtures f on f.fixture_id = c.fixture_id
    join public.team_ratings hr on hr.team_id = f.home_team_id and hr.fit_run_id = c.fit_run_id
    join public.team_ratings ar on ar.team_id = f.away_team_id and ar.fit_run_id = c.fit_run_id
  ),
  updated as (
    update public.fixtures f
    set predicted_home_goals = p.pred_home,
        predicted_away_goals = p.pred_away,
        prediction_fit_run_id = p.fit_run_id,
        predicted_at = now()
    from preds p
    where p.fixture_id = f.fixture_id
      and f.predicted_home_goals is null
    returning f.fixture_id
  )
  select count(*)::integer from updated;
$$;


ALTER FUNCTION public.backfill_historic_fixture_predictions(target_season_id bigint) OWNER TO postgres;

--
-- Name: backfill_match_odds(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.backfill_match_odds() RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_rows integer;
begin
  with resolved as (
    select r.raw_data, m.match_id
    from public.source_match_rows r
    join public.matches m
      on m.match_date = r.source_match_date
     and m.home_team_id = (
       select ta.team_id from public.team_aliases ta
       where ta.source_name = 'football-data.co.uk' and ta.raw_name = r.source_home_team limit 1
     )
     and m.away_team_id = (
       select ta.team_id from public.team_aliases ta
       where ta.source_name = 'football-data.co.uk' and ta.raw_name = r.source_away_team limit 1
     )
    -- only matches with no odds yet: keeps the daily call fast
    where not exists (select 1 from public.match_odds o
                      where o.match_id = m.match_id and o.source_name = 'football-data.co.uk')
      -- only rows carrying at least one price the unpivot reads (pre-2000/01
      -- history rows have none; re-reading them every call cost ~5s)
      and r.raw_data ?| array[
        'B365H','B365CH','BWH','BWCH','IWH','IWCH','PSH','PSCH','WHH','WHCH','VCH','VCCH','MaxH','MaxCH','AvgH','AvgCH','BFEH','BFECH',
        'B365>2.5','B365C>2.5','Max>2.5','MaxC>2.5','Avg>2.5','AvgC>2.5','P>2.5','PC>2.5','BFE>2.5','BFEC>2.5',
        'B365<2.5','B365C<2.5','Max<2.5','MaxC<2.5','Avg<2.5','AvgC<2.5','P<2.5','PC<2.5','BFE<2.5','BFEC<2.5',
        'B365AHH','B365CAHH','MaxAHH','MaxCAHH','AvgAHH','AvgCAHH','PAHH','PCAHH','BFEAHH','BFECAHH',
        'B365AHA','B365CAHA','MaxAHA','MaxCAHA','AvgAHA','AvgCAHA','PAHA','PCAHA','BFEAHA','BFECAHA']
  ),
  unpivoted as (
    select match_id, '1x2' as market, bm as bookmaker, is_close,
      public.safe_numeric(raw_data->>(bm || case when is_close then 'C' else '' end || 'H')) as price_home,
      public.safe_numeric(raw_data->>(bm || case when is_close then 'C' else '' end || 'D')) as price_draw,
      public.safe_numeric(raw_data->>(bm || case when is_close then 'C' else '' end || 'A')) as price_away,
      null::numeric as line, null::numeric as price_over, null::numeric as price_under
    from resolved
    cross join (values ('B365'), ('BW'), ('IW'), ('PS'), ('WH'), ('VC'), ('Max'), ('Avg'), ('BFE')) b(bm)
    cross join (values (false), (true)) c(is_close)

    union all

    select match_id, 'ou25', bm, is_close,
      null, null, null, 2.5,
      public.safe_numeric(raw_data->>(bm || case when is_close then 'C' else '' end || '>2.5')),
      public.safe_numeric(raw_data->>(bm || case when is_close then 'C' else '' end || '<2.5'))
    from resolved
    cross join (values ('B365'), ('Max'), ('Avg'), ('P'), ('BFE')) b(bm)
    cross join (values (false), (true)) c(is_close)

    union all

    -- Asian handicap: one shared line per file (AHh opening, AHCh closing),
    -- home price in price_home, away price in price_away.
    select match_id, 'ah', bm, is_close,
      public.safe_numeric(raw_data->>(bm || case when is_close then 'C' else '' end || 'AHH')),
      null,
      public.safe_numeric(raw_data->>(bm || case when is_close then 'C' else '' end || 'AHA')),
      coalesce(public.safe_numeric(raw_data->>(case when is_close then 'AHCh' else 'AHh' end)), public.safe_numeric(raw_data->>(bm || case when is_close then 'C' else '' end || 'AH'))),
      null, null
    from resolved
    cross join (values ('B365'), ('Max'), ('Avg'), ('P'), ('BFE')) b(bm)
    cross join (values (false), (true)) c(is_close)
  )
  insert into public.match_odds (
    match_id, source_name, market, bookmaker, is_closing,
    price_home, price_draw, price_away, line, price_over, price_under
  )
  select match_id, 'football-data.co.uk', market, bookmaker, is_close,
    price_home, price_draw, price_away, line, price_over, price_under
  from unpivoted
  where coalesce(price_home, price_away, price_over, price_under) is not null
  on conflict do nothing;

  get diagnostics v_rows = row_count;
  return v_rows;
end;
$$;


ALTER FUNCTION public.backfill_match_odds() OWNER TO postgres;

--
-- Name: backfill_match_predictions(bigint, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.backfill_match_predictions(p_league_id bigint, p_season_id bigint) RETURNS integer
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with chosen as (
    select distinct on (m.match_id)
      m.match_id, mfr.fit_run_id, mfr.fitted_at,
      exp(mfr.home_advantage + hr.attack_strength - ar.defence_strength) as ph,
      exp(ar.attack_strength - hr.defence_strength) as pa
    from public.matches m
    join public.model_fit_runs mfr
      on mfr.league_id = m.league_id
     and mfr.status = 'accepted'
     and mfr.fitted_at::date < m.match_date::date
    join public.team_ratings hr on hr.fit_run_id = mfr.fit_run_id and hr.team_id = m.home_team_id
    join public.team_ratings ar on ar.fit_run_id = mfr.fit_run_id and ar.team_id = m.away_team_id
    where m.league_id = p_league_id
      and m.season_id = p_season_id
    order by m.match_id, mfr.fitted_at desc
  ),
  up as (
    insert into public.match_predictions as mp
      (match_id, fit_run_id, fit_as_of_date, predicted_home_goals, predicted_away_goals)
    select match_id, fit_run_id, fitted_at::date, ph, pa from chosen
    on conflict (match_id) do update
      set fit_run_id = excluded.fit_run_id,
          fit_as_of_date = excluded.fit_as_of_date,
          predicted_home_goals = excluded.predicted_home_goals,
          predicted_away_goals = excluded.predicted_away_goals,
          predicted_at = now()
      where mp.fit_run_id is distinct from excluded.fit_run_id
    returning 1
  )
  select count(*)::integer from up;
$$;


ALTER FUNCTION public.backfill_match_predictions(p_league_id bigint, p_season_id bigint) OWNER TO postgres;

--
-- Name: broadcast_confidence_rank(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.broadcast_confidence_rank(p text) RETURNS integer
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
  select case p when 'confirmed_primary' then 4 when 'confirmed_secondary' then 3
    when 'probable' then 2 when 'needs_verification' then 1 else 3 end;
$$;


ALTER FUNCTION public.broadcast_confidence_rank(p text) OWNER TO postgres;

--
-- Name: capture_upcoming_odds(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.capture_upcoming_odds() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_catalog'
    AS $$
declare
  v_run bigint;
  v_status int;
  v_body text;
  v_rows int := 0;
  v_matched int := 0;
  v_inserted int := 0;
  v_unmapped text[];
begin
  insert into public.pipeline_runs (job_name, started_at, status) values ('capture-upcoming-odds', now(), 'running') returning run_id into v_run;
  begin
    select status, content into v_status, v_body
    from extensions.http(('GET', 'https://www.football-data.co.uk/fixtures.csv',
      array[extensions.http_header('User-Agent', 'Mozilla/5.0 (compatible; fixtureshark-odds/1.0)')], null, null)::extensions.http_request);
    if v_status <> 200 then raise exception 'fixtures.csv returned HTTP %', v_status; end if;
    v_body := replace(v_body, chr(65279), '');

    drop table if exists _fx;
    create temp table _fx on commit drop as
    with lines as (select t.l, t.n from regexp_split_to_table(v_body, E'\r?\n') with ordinality t(l, n) where length(trim(t.l)) > 0),
    hdr as (select string_to_array(l, ',') h from lines where n = 1),
    rws as (select string_to_array(l, ',') r from lines where n > 1)
    select r, h, r[array_position(h, 'Div')] as div, r[array_position(h, 'HomeTeam')] as home_raw, r[array_position(h, 'AwayTeam')] as away_raw,
      to_date(r[array_position(h, 'Date')], 'DD/MM/YYYY') as d
    from rws, hdr;
    select count(*) into v_rows from _fx;
    if v_rows = 0 then raise exception 'fixtures.csv had no rows; format may have changed'; end if;

    drop table if exists _fxm;
    create temp table _fxm on commit drop as
    select x.*, f.fixture_id
    from (
      select fx.*, l.league_id, coalesce(ha.team_id, ht.team_id) home_id, coalesce(aa.team_id, at.team_id) away_id
      from _fx fx
      join public.leagues l on l.code = fx.div
      left join public.team_aliases ha on ha.source_name = 'football-data.co.uk' and ha.raw_name = fx.home_raw
      left join public.teams ht on ht.canonical_name = fx.home_raw
      left join public.team_aliases aa on aa.source_name = 'football-data.co.uk' and aa.raw_name = fx.away_raw
      left join public.teams at on at.canonical_name = fx.away_raw
    ) x
    left join lateral (
      select f.fixture_id from public.fixtures f
      where f.league_id = x.league_id and f.season_id = public.current_season_id()
        and f.home_team_id = x.home_id and f.away_team_id = x.away_id
        and f.kickoff_date between x.d - 3 and x.d + 3
      order by abs(f.kickoff_date - x.d) limit 1
    ) f on true;

    select array_agg(distinct n order by n) into v_unmapped from (
      select home_raw n from _fxm where home_id is null and exists (select 1 from public.fixtures f where f.league_id = _fxm.league_id)
      union select away_raw from _fxm where away_id is null and exists (select 1 from public.fixtures f where f.league_id = _fxm.league_id)) u;
    select count(*) into v_matched from _fxm where fixture_id is not null;

    with prices as (
      select m.fixture_id, b.bookmaker, b.market, b.is_closing,
        case when b.market = 'ah' then nullif(m.r[array_position(m.h, case when b.is_closing then 'AHCh' else 'AHh' end)], '')::numeric end as line,
        nullif(m.r[array_position(m.h, b.col_h)], '')::numeric ph, nullif(m.r[array_position(m.h, b.col_d)], '')::numeric pd,
        nullif(m.r[array_position(m.h, b.col_a)], '')::numeric pa,
        nullif(m.r[array_position(m.h, b.col_o)], '')::numeric po, nullif(m.r[array_position(m.h, b.col_u)], '')::numeric pu
      from _fxm m
      cross join (values
        ('Avg', '1x2', false, 'AvgH', 'AvgD', 'AvgA', null, null),
        ('Max', '1x2', false, 'MaxH', 'MaxD', 'MaxA', null, null),
        ('B365', '1x2', false, 'B365H', 'B365D', 'B365A', null, null),
        ('BFE', '1x2', false, 'BFEH', 'BFED', 'BFEA', null, null),
        ('Avg', '1x2', true, 'AvgCH', 'AvgCD', 'AvgCA', null, null),
        ('BFE', '1x2', true, 'BFECH', 'BFECD', 'BFECA', null, null),
        ('Avg', 'ou25', false, null, null, null, 'Avg>2.5', 'Avg<2.5'),
        ('BFE', 'ou25', false, null, null, null, 'BFE>2.5', 'BFE<2.5'),
        ('Avg', 'ah', false, 'AvgAHH', null, 'AvgAHA', null, null),
        ('Avg', 'ou25', true, null, null, null, 'AvgC>2.5', 'AvgC<2.5'),
        ('Avg', 'ah', true, 'AvgCAHH', null, 'AvgCAHA', null, null)
      ) b(bookmaker, market, is_closing, col_h, col_d, col_a, col_o, col_u)
      where m.fixture_id is not null
    )
    insert into public.fixture_odds_snapshots (fixture_id, bookmaker, market, is_closing, line, price_home, price_draw, price_away, price_over, price_under)
    select fixture_id, bookmaker, market, is_closing, line, ph, pd, pa, po, pu
    from prices
    where (market = '1x2' and ph > 1 and pd > 1 and pa > 1)
       or (market = 'ou25' and po > 1 and pu > 1)
       or (market = 'ah' and ph > 1 and pa > 1 and line is not null)
    on conflict do nothing;
    get diagnostics v_inserted = row_count;

    update public.pipeline_runs set finished_at = now(),
      status = case when v_unmapped is null then 'success' else 'failed' end,
      summary = jsonb_build_object('rows', v_rows, 'matched_fixtures', v_matched, 'new_prices', v_inserted)::text,
      error_message = case when v_unmapped is not null then 'unmapped club names (add team_aliases, source football-data.co.uk): ' || array_to_string(v_unmapped, ', ') end
    where run_id = v_run;
    return jsonb_build_object('rows', v_rows, 'matched_fixtures', v_matched, 'new_prices', v_inserted, 'unmapped', v_unmapped);
  exception when others then
    update public.pipeline_runs set finished_at = now(), status = 'failed', error_message = sqlerrm where run_id = v_run;
    raise warning 'capture_upcoming_odds failed: %', sqlerrm;
    return jsonb_build_object('status', 'failed', 'error', sqlerrm);
  end;
end;
$$;


ALTER FUNCTION public.capture_upcoming_odds() OWNER TO postgres;

