--
-- Name: check_club_grounds(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.check_club_grounds() RETURNS TABLE(check_name text, status text, found bigint, detail text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select 'club_grounds_complete', case when n = 0 then 'ok' else 'failed' end, n,
    'Clubs playing in the top five English divisions since 1 July with no row in club_grounds'
  from (select count(distinct t.team_id) n
        from public.matches m
        join public.leagues l on l.league_id = m.league_id and l.code in ('E0', 'E1', 'E2', 'E3', 'EC')
        join public.teams t on t.team_id in (m.home_team_id, m.away_team_id)
        where m.match_date >= make_date(extract(year from now() - interval '6 months')::int, 7, 1)
          and not exists (select 1 from public.club_grounds g where g.team_id = t.team_id)) x
  union all
  select 'club_grounds_postcode_checked', case when n = 0 then 'ok' else 'warning' end, n,
    'Club grounds whose postcode has not been looked up (run the club-grounds-verify workflow)'
  from (select count(*) n from public.club_grounds where postcode_checked_at is null) x
  union all
  select 'club_grounds_near_postcode', case when n = 0 then 'ok' else 'failed' end, n,
    'Club grounds more than 1.5 km from their own postcode, or whose postcode does not exist (reviewed exceptions excluded)'
  from (select count(*) n from public.club_grounds
        where postcode_checked_at is not null and postcode_far_reason is null
          and (postcode_distance_m is null or postcode_distance_m > 1500)) x
$$;


ALTER FUNCTION public.check_club_grounds() OWNER TO postgres;

--
-- Name: check_fpl_history_integrity(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.check_fpl_history_integrity(p_season_id bigint) RETURNS TABLE(players_checked bigint, points_mismatch bigint, minutes_mismatch bigint, goals_mismatch bigint, assists_mismatch bigint, worst_points_gap integer)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with gw as (
    select fpl_code,
      sum(total_points) pts, sum(minutes) mins,
      sum(goals_scored) gls, sum(assists) ast
    from public.fpl_player_gameweek_history
    where season_id = p_season_id
    group by fpl_code
  )
  select
    count(*)::bigint,
    count(*) filter (where gw.pts <> t.total_points)::bigint,
    count(*) filter (where gw.mins <> t.minutes)::bigint,
    count(*) filter (where gw.gls <> t.goals_scored)::bigint,
    count(*) filter (where gw.ast <> t.assists)::bigint,
    coalesce(max(abs(gw.pts - t.total_points)), 0)::integer
  from gw
  join public.fpl_player_season_totals t
    on t.season_id = p_season_id and t.fpl_code = gw.fpl_code;
$$;


ALTER FUNCTION public.check_fpl_history_integrity(p_season_id bigint) OWNER TO postgres;

--
-- Name: check_intl_integrity(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.check_intl_integrity() RETURNS TABLE(check_name text, status text, found bigint, detail text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select 'intl_fresh',
    case when age_days is null or age_days >= 5 then 'failed' when age_days >= 2 then 'warning' else 'ok' end,
    coalesce(age_days, -1)::bigint,
    'Days since the last successful intl_import run (daily on GitHub Actions; warns at 2, fails at 5; -1 = never)'
  from (select extract(day from now() - max(finished_at))::int age_days
        from public.pipeline_runs where job_name = 'intl_import' and status = 'success') x
  union all
  select 'intl_major_games_staged', case when n = 0 then 'ok' else 'failed' end, n,
    'World Cup and Euro finals games without an edition and stage'
  from (select count(*) n from intl.matches
        where competition in ('FIFA World Cup', 'UEFA Euro') and (edition_key is null or stage_code is null)) x
  union all
  select 'intl_stage_rows', case when n = 0 then 'ok' else 'failed' end, n,
    'Matches whose edition and stage have no intl.stages row'
  from (select count(*) n from intl.matches m
        where m.edition_key is not null
          and not exists (select 1 from intl.stages s where s.edition_key = m.edition_key and s.code = m.stage_code)) x
  union all
  select 'intl_elo_complete', case when n = 0 then 'ok' else 'failed' end, n,
    'Matches without Elo ratings'
  from (select count(*) n from intl.matches where elo_change is null) x
  union all
  -- The results file trails the games by days to weeks; this is a watch, not a fault.
  select 'intl_results_lag', case when n = 0 then 'ok' else 'warning' end, n,
    'Fixtures more than 14 days old with no result in the results file yet'
  from (select count(*) n from public.intl_fixtures
        where kickoff_utc < now() - interval '14 days' and match_key is null) x
$$;


ALTER FUNCTION public.check_intl_integrity() OWNER TO postgres;

--
-- Name: check_model_integrity(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.check_model_integrity() RETURNS TABLE(check_name text, status text, found bigint, detail text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with cur as (select se.season_id s from public.seasons se
                where se.start_year = (select max(sm.start_year) from public.seasons sm
                                        where sm.season_id in (select m.season_id from public.matches m where m.league_id between 1 and 5)))
  -- Incident 2026-09-23: predictions from fits later retired, or from fits
  -- dated on/after kick-off (hindsight). Played fixtures must never carry one.
  select 'played_prediction_point_in_time', case when n = 0 then 'ok' else 'failed' end, n,
    'Played fixtures this season predicted from a non-accepted fit or a fit dated on/after kick-off'
  from (select count(*) n from public.fixtures f join public.model_fit_runs r on r.fit_run_id = f.prediction_fit_run_id
        where f.season_id = (select s from cur) and f.status = 'played'
          and (r.status <> 'accepted' or r.fitted_at::date >= f.kickoff_date)) x
  union all
  select 'upcoming_prediction_from_accepted_fit', case when n = 0 then 'ok' else 'failed' end, n,
    'Upcoming fixtures predicted from a fit that is not accepted'
  from (select count(*) n from public.fixtures f join public.model_fit_runs r on r.fit_run_id = f.prediction_fit_run_id
        where f.status in ('scheduled', 'postponed') and f.kickoff_date >= current_date and r.status <> 'accepted') x
  union all
  -- Incident 2026-09-23: the June fits predicted ~30% too few goals and passed
  -- every gate. Every accepted fit from the last 7 days must reproduce its
  -- window's weighted goals within 5%.
  select 'recent_fits_scoring_level', case when n = 0 then 'ok' else 'failed' end, n,
    'Accepted fits from the last 7 days whose ratings are more than 5% off the weighted in-window goals'
  from (select count(*) n from (
          select f.fit_run_id,
            sum(power(0.5, (f.window_end_date - m.match_date::date) / f.decay_half_life_days) * exp(f.home_advantage + h.attack_strength - a.defence_strength))
              / nullif(sum(power(0.5, (f.window_end_date - m.match_date::date) / f.decay_half_life_days) * m.full_time_home_goals), 0) rh,
            sum(power(0.5, (f.window_end_date - m.match_date::date) / f.decay_half_life_days) * exp(a.attack_strength - h.defence_strength))
              / nullif(sum(power(0.5, (f.window_end_date - m.match_date::date) / f.decay_half_life_days) * m.full_time_away_goals), 0) ra
          from public.model_fit_runs f
          join public.matches m on m.league_id = f.league_id and m.match_date::date between f.window_start_date and f.window_end_date and m.full_time_home_goals is not null
          join public.team_ratings h on h.fit_run_id = f.fit_run_id and h.team_id = m.home_team_id and not coalesce(h.is_estimated, false)
          join public.team_ratings a on a.fit_run_id = f.fit_run_id and a.team_id = m.away_team_id and not coalesce(a.is_estimated, false)
          where f.status = 'accepted' and f.fitted_at > now() - interval '7 days' and not f.is_retrofit
          group by f.fit_run_id) y
        where abs(rh - 1) > 0.05 or abs(ra - 1) > 0.05) x
  union all
  -- Versioning (2026-09-23): every new fit must name the settings that made it.
  select 'new_fits_versioned', case when n = 0 then 'ok' else 'failed' end, n,
    'Fits made since versioning began with no model_version'
  from (select count(*) n from public.model_fit_runs where fitted_at > '2026-09-24' and not is_retrofit and model_version is null) x
  union all
  -- Retro-fits must be stamped as-of 23:59:59 UTC or point-in-time selection breaks.
  select 'retrofit_stamps', case when n = 0 then 'ok' else 'failed' end, n,
    'Retro-fits whose fitted_at or window end does not match their as-of date'
  from (select count(*) n from public.model_fit_runs where is_retrofit
          and (fitted_at <> (as_of_date + time '23:59:59') at time zone 'UTC' or window_end_date <> as_of_date)) x
  union all
  select 'archive_predictions_point_in_time', case when n = 0 then 'ok' else 'failed' end, n,
    'Archived-match predictions from a non-accepted fit or a fit dated on/after the match'
  from (select count(*) n from public.match_predictions mp join public.matches m using (match_id)
          join public.model_fit_runs r on r.fit_run_id = mp.fit_run_id
        where r.status <> 'accepted' or r.fitted_at::date >= m.match_date::date) x
  union all
  -- Incident 2026-09-23: a new table lacked a service_role grant and a
  -- workflow's read got a 403. Every public table must be readable by it.
  select 'service_role_can_read_tables', case when n = 0 then 'ok' else 'failed' end, n,
    'Public tables service_role cannot SELECT: ' || coalesce(names, '')
  from (select count(*) n, string_agg(c.relname, ', ') names from pg_class c join pg_namespace ns on ns.oid = c.relnamespace
        where ns.nspname = 'public' and c.relkind = 'r' and not has_table_privilege('service_role', c.oid, 'SELECT')) x
  union all
  -- Fixtures still 'scheduled' days after kick-off: the status lag that let
  -- hindsight re-predictions through. The kick-off guard now blocks those,
  -- but a growing count means results aren't being marked played.
  -- 2026-09-25: FAILS (was a warning nobody saw). See incidents.md.
  select 'stale_scheduled_fixtures', case when n = 0 then 'ok' else 'failed' end, n,
    'Fixtures still SCHEDULED more than 3 days after kick-off (played but result missed, or postponed but not marked): ' || coalesce(ids, '')
  from (select count(*) n, string_agg(fixture_id::text, ', ' order by fixture_id) ids
        from public.fixtures where status = 'scheduled' and kickoff_date < current_date - 3) x
  union all
  select 'stale_postponed_fixtures', case when n = 0 then 'ok' else 'warning' end, n,
    'Fixtures postponed more than 3 days ago with no new date yet'
  from (select count(*) n from public.fixtures where status = 'postponed' and kickoff_date < current_date - 3) x
  union all
  select 'played_without_result', case when n = 0 then 'ok' else 'failed' end, n,
    'Fixtures PLAYED more than 3 days ago with no result in matches (no results feed for that competition, or a mapping gap): ' || coalesce(ids, '')
  from (select count(*) n, string_agg(f.fixture_id::text, ', ' order by f.fixture_id) ids
        from public.fixtures f
        where f.status = 'played' and f.kickoff_date < current_date - 3
          and not exists (select 1 from public.matches m
                          where m.league_id = f.league_id and m.season_id = f.season_id
                            and m.home_team_id = f.home_team_id and m.away_team_id = f.away_team_id
                            and m.match_date = f.kickoff_date)) x
  union all
  select 'cup_ingestion_current', case when n = 0 then 'ok' else 'failed' end, n,
    'Cup feed (ingest-cup-data): latest run not a full success within 30h -- ' || coalesce(why, '')
  from (select case when r.ingestion_run_id is null then 1
                    when r.status <> 'success' or r.started_at < now() - interval '30 hours' then 1 else 0 end n,
               case when r.ingestion_run_id is null then 'no run recorded'
                    else 'run ' || r.ingestion_run_id || ' ' || r.status || ' at ' || to_char(r.started_at, 'YYYY-MM-DD HH24:MI')
                         || coalesce(': ' || r.error_message, '') end why
        from (select 1) one
        left join lateral (select * from public.result_ingestion_runs
                           where source_name = 'FootballWebPages (cups)'
                           order by started_at desc limit 1) r on true) x
  union all
  select 'no_stuck_runs', case when n = 0 then 'ok' else 'failed' end, n,
    'Runs still marked running after 6h (died without recording an outcome): ' || coalesce(names, '')
  from (select count(*) n, string_agg(distinct j, ', ') names from (
          select 'pipeline_runs:' || job_name j from public.pipeline_runs where status = 'running' and started_at < now() - interval '6 hours'
          union all
          select 'fpl_ingestion_runs' from public.fpl_ingestion_runs where status = 'running' and started_at < now() - interval '6 hours'
          union all
          select 'result_ingestion_runs:' || source_name from public.result_ingestion_runs where status = 'running' and started_at < now() - interval '6 hours'
        ) s) x
  union all
  select 'unique_function_names', case when n = 0 then 'ok' else 'failed' end, n,
    'Public function names defined more than once (an ambiguous call breaks the site): ' || coalesce(names, '')
  from (select count(*) n, string_agg(proname, ', ') names from (
          select p.proname from pg_proc p join pg_namespace ns on ns.oid = p.pronamespace
          where ns.nspname = 'public' and p.prokind = 'f'
            and not exists (select 1 from pg_depend d where d.classid = 'pg_proc'::regclass and d.objid = p.oid and d.deptype = 'e')
          group by p.proname having count(*) > 1) q) x
  union all
  select 'public_views_readable_by_anon', case when n = 0 then 'ok' else 'failed' end, n,
    'Public-facing views anon cannot SELECT (grants silently dropped, e.g. by CREATE OR REPLACE VIEW): ' || coalesce(names, '')
  from (select count(*) n, string_agg(v, ', ') names from (
          select unnest(array[
            'team_strength_current', 'fpl_team_strength_current', 'league_standings',
            'model_scorecard_matches', 'history_streaks', 'history_league_matches', 'team_season_summary', 'league_season_summary', 'league_pace_benchmarks', 'league_table_reliability'
          ]) v) q
        where not has_table_privilege('anon', ('public.' || q.v)::regclass, 'SELECT')) x
  union all
  -- Season rollover (2026-09-27): see docs/season-rollover.md.
  select 'season_rollover_ready',
    case when sr.cov is null or sr.fpl_ahead > 0 then 'failed'
         when sr.nxt is null and current_date >= make_date(sr.sy + 1, 3, 1) then 'warning'
         when current_date between make_date(extract(year from current_date)::int, 6, 15)
                               and make_date(extract(year from current_date)::int, 7, 31) then 'warning'
         else 'ok' end,
    sr.fpl_ahead,
    case when sr.cov is null then 'No seasons row covers today, so current_season_id() is stuck on ' || sr.lbl || '. Add next season''s row (docs/season-rollover.md).'
         when sr.fpl_ahead > 0 then sr.fpl_ahead || ' FPL gameweek(s) with a deadline after their season ended are stored under the old season: private.refresh_fpl() loaded the new FPL game before 1 August. See docs/season-rollover.md.'
         when sr.nxt is null and current_date >= make_date(sr.sy + 1, 3, 1) then 'Next season (' || (sr.sy + 1) || '/' || right((sr.sy + 2)::text, 2) || ') has no seasons row; add it now: the Norwegian, Swedish and Finnish seasons that start this spring are stored under it (docs/season-rollover.md).'
         when current_date between make_date(extract(year from current_date)::int, 6, 15)
                               and make_date(extract(year from current_date)::int, 7, 31)
           then 'Until 1 August private.refresh_fpl() stores FPL data under last season. Once FPL relaunches, pause cron jobs fpl-refresh-6-hourly and fpl-live-current-6-hourly until 1 August (docs/season-rollover.md).'
         else 'Current season ' || sr.lbl || ' is covered' || case when sr.nxt is null then '; next season''s row is not needed until 1 March' else ' and next season''s row exists' end || '.' end
  from (select c.cov, s.start_year sy, s.start_year || '/' || right(s.end_year::text, 2) lbl,
               (select n.season_id from public.seasons n where n.start_year = s.start_year + 1) nxt,
               (select count(*) from public.fpl_gameweeks g join public.seasons gs on gs.season_id = g.season_id
                 where g.deadline_time >= make_date(gs.start_year + 1, 7, 1)) fpl_ahead
          from (select public.season_id_for_date(current_date) cov) c
          join public.seasons s on s.season_id = public.current_season_id()) sr
  union all
  -- Split formats (2026-09-27): league_standings needs a league_season_formats
  -- row for every split-format season; warn once a season is past its split
  -- without one.
  select 'split_formats_configured', case when n = 0 then 'ok' else 'warning' end, n,
    'League-seasons past their split with no league_season_formats row (ranked on total points): ' || coalesce(names, '')
  from (select count(*) n, string_agg(ls, ', ' order by ls) names from (
          select distinct l.code || ' ' || se.label ls
          from public.matches m
          join public.seasons se on se.season_id = m.season_id
          join public.leagues l on l.league_id = m.league_id
          join lateral (select f.regular_meetings from public.league_season_formats f
                        join public.seasons fs on fs.season_id = f.season_id
                        where f.league_id = m.league_id and f.format = 'split' and fs.start_year < se.start_year
                        order by fs.start_year desc limit 1) prev on true
          where m.league_id in (select f.league_id from public.league_season_formats f where f.format = 'split')
            and not exists (select 1 from public.league_season_formats f2
                            where f2.league_id = m.league_id and f2.season_id = m.season_id)
          group by l.code, se.label, least(m.home_team_id, m.away_team_id), greatest(m.home_team_id, m.away_team_id), prev.regular_meetings
          having count(*) > prev.regular_meetings) q) x
  union all
  -- History layer (2026-09-27): each team's latest team_match_snapshot row
  -- must equal its league_standings row. Split formats excluded (halving).
  select 'history_snapshot_reconciles', case when n = 0 then 'ok' else 'failed' end, n,
    'Team-seasons whose latest team_match_snapshot row disagrees with league_standings (run refresh_history_derived(true)): ' || coalesce(names, '')
  from (select count(*) n, string_agg(l.league_id || '/' || l.season_id || '/' || l.team_id, ', ') filter (where rn <= 10) names
        from (select s.*, row_number() over () rn
              from (select distinct on (league_id, season_id, team_id) * from public.team_match_snapshot
                    order by league_id, season_id, team_id, matches_played desc) s
              join public.league_standings ls using (league_id, season_id, team_id)
              where not exists (select 1 from public.league_season_formats f
                                where f.league_id = s.league_id and f.season_id = s.season_id and f.format = 'split')
                and (ls.played <> s.matches_played or ls.won <> s.won or ls.drawn <> s.drawn or ls.lost <> s.lost
                     or ls.goals_for <> s.cum_goals_for or ls.goals_against <> s.cum_goals_against or ls.points <> s.points)) l) x
  union all
  -- Reported scores (2026-09-27): the fixture feed's score must match
  -- football-data's once both exist. A difference is a scraping, mapping or
  -- source error in one of them.
  select 'reported_vs_confirmed', case when n = 0 then 'ok' else 'warning' end, n,
    'Fixtures whose reported (feed) score differs from the confirmed result in matches: ' || coalesce(names, '')
  from (select count(*) n, string_agg(f.fixture_id || ' ' || f.reported_home_goals || '-' || f.reported_away_goals
                                      || ' v ' || m.full_time_home_goals || '-' || m.full_time_away_goals, ', ')
                                      filter (where rn <= 10) names
        from (select f.*, row_number() over (order by f.kickoff_date desc) rn from public.fixtures f
              where f.reported_home_goals is not null) f
        join public.matches m on m.league_id = f.league_id and m.season_id = f.season_id
          and m.home_team_id = f.home_team_id and m.away_team_id = f.away_team_id
          and m.match_date between f.kickoff_date - 3 and f.kickoff_date + 3
        where m.full_time_home_goals is not null
          and (m.full_time_home_goals <> f.reported_home_goals or m.full_time_away_goals <> f.reported_away_goals)) x
  union all
  -- Upcoming odds (2026-09-28): fixtures.csv prices should arrive at least
  -- weekly while fixtures are scheduled in the next fortnight.
  select 'upcoming_odds_fresh',
    case when not exists (select 1 from public.fixtures where status = 'scheduled' and kickoff_date between current_date and current_date + 14)
           or exists (select 1 from public.fixture_odds_snapshots where captured_at > now() - interval '8 days')
         then 'ok' else 'warning' end,
    (select count(*) from public.fixture_odds_snapshots where captured_at > now() - interval '8 days'),
    'Upcoming-match odds prices captured in the last 8 days (capture_upcoming_odds, pg_cron capture-upcoming-odds; see pipeline_runs)'
  union all
  -- FPL scoring engine (2026-09-28): fpl_score() must reproduce FPL's own
  -- points for every season held (fpl_scoring_regression).
  select 'fpl_scoring_regression',
    case when coalesce(sum(mismatches), 0) = 0 then 'ok' else 'failed' end,
    coalesce(sum(mismatches), 0),
    'Rows where fpl_score() disagrees with FPL''s points (fpl_scoring_regression; rules in fpl_scoring_rules)'
  from public.fpl_scoring_regression
  union all
  -- FPL market goals (2026-09-28): Premier League fixtures in the next
  -- fortnight should carry market expected goals written in the last 2 days.
  select 'fpl_market_goals_fresh',
    case when count(*) filter (where market_rated_at is null or market_rated_at < now() - interval '2 days') = 0
         then 'ok' else 'warning' end,
    count(*) filter (where market_rated_at is null or market_rated_at < now() - interval '2 days'),
    'Premier League fixtures in the next 14 days without market expected goals from the last 2 days (refresh_market_goals.py; FPL projection falls back to the model)'
  from public.fixtures
  where league_id = 1 and status = 'scheduled' and kickoff_date between current_date and current_date + 14
  union all
  -- FPL exit bands (2026-09-28): refreshed at the start of every FPL
  -- pipeline run; stale bands mean appearance and clean-sheet points drift.
  select 'fpl_exit_bands_fresh',
    case when not exists (select 1 from public.fixtures where league_id = 1 and status = 'scheduled' and kickoff_date between current_date and current_date + 14)
           or exists (select 1 from public.fpl_player_exit_bands where season_id = public.fpl_current_season_id() and updated_at > now() - interval '2 days')
         then 'ok' else 'warning' end,
    (select count(*) from public.fpl_player_exit_bands where season_id = public.fpl_current_season_id() and updated_at > now() - interval '2 days'),
    'Current-season players with exit bands refreshed in the last 2 days (refresh_exit_bands.py; without them FPL points fall back to 2 appearance points and the full-match clean sheet for every starter)'
  union all
  -- Squad state (2026-09-28): API-sourced injured/doubtful/suspended rows
  -- that are still active after 7 days override the live FPL availability.
  select 'fpl_squad_state_not_stale',
    case when count(*) = 0 then 'ok' else 'warning' end,
    count(*),
    'Active injured/doubtful/suspended squad-state rows from the FPL API older than 7 days (they override live availability): ' || coalesce(string_agg(fpl_player_id::text, ', '), '')
  from public.fpl_player_squad_state_current
  where source_name = 'official_fpl_api' and state in ('injured', 'doubtful', 'suspended')
    and updated_at < now() - interval '7 days'
  union all
  -- Catalogue (2026-09-26): every live, non-scratch object has a description,
  -- reviewed since its definition last changed. Warning, not failure.
  select 'catalogue_current', case when n = 0 then 'ok' else 'warning' end, n,
    'Objects undocumented or changed since their catalogue entry was reviewed (see meta_catalogue_gaps): ' || coalesce(names, '')
  from (select count(*) n, string_agg(node_key, ', ' order by node_key) filter (where rn <= 10) names
        from (select node_key, row_number() over (order by node_key) rn from public.meta_catalogue_gaps) g) x;
$$;


ALTER FUNCTION public.check_model_integrity() OWNER TO postgres;

--
-- Name: check_nfl_integrity(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.check_nfl_integrity() RETURNS TABLE(check_name text, status text, found bigint, detail text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select 'nfl_results_fresh', case when n = 0 then 'ok' else 'failed' end, n,
    'NFL games kicked off more than 2 days ago still without a score'
  from (select count(*) n from nfl.games where kickoff_at < now() - interval '2 days' and home_score is null) x
  union all
  select 'nfl_standings_complete', case when n = 0 then 'ok' else 'failed' end, n,
    'Complete NFL seasons whose standings do not have 32 teams each with the full regular-season schedule'
  from (select count(*) n from (
          select s.season from public.nfl_standings s where s.season_complete
          group by s.season
          having count(*) <> 32
              or count(*) filter (where s.played + case when s.season = 2022 and s.franchise in ('BUF', 'CIN') then 1 else 0 end
                                    <> case when s.season >= 2021 then 17 else 16 end) > 0) y) x
  union all
  select 'nfl_games_mapped', case when n = 0 then 'ok' else 'failed' end, n,
    'NFL games missing from public.nfl_games (unmapped team code)'
  from (select (select count(*) from nfl.games) - (select count(*) from public.nfl_games) n) x
  union all
  select 'nfl_division_winners', case when n = 0 then 'ok' else 'failed' end, n,
    'Completed NFL division-seasons without exactly one division winner from the play-off bracket'
  from (select count(*) n from (
          select s.season, s.conference, s.division from public.nfl_standings s where s.season_complete
          group by 1, 2, 3 having count(*) filter (where s.won_division) <> 1) y) x
  union all
  select 'nfl_fantasy_points_match', case when n = 0 then 'ok' else 'failed' end, n,
    'NFL player-weeks (non-kickers) where our standard or PPR points differ from nflverse by more than 0.01'
  from (select count(*) n from nfl.player_weeks w
        where w.position <> 'K' and w.src_points_std is not null
          and w.fg_att = 0 and w.pat_made = 0 and w.pat_missed = 0
          and (abs(nfl.points_std(w) - w.src_points_std) > 0.011
               or abs(nfl.points_std(w) + w.receptions - w.src_points_ppr) > 0.011)) x
  union all
  select 'nfl_player_stats_fresh', case when n = 0 then 'ok' else 'failed' end, n,
    'Scored NFL games (2016+) older than 3 days with no player stats'
  from (select count(*) n from nfl.games g
        where g.season >= 2016 and g.home_score is not null and g.kickoff_at < now() - interval '3 days'
          and not exists (select 1 from nfl.player_weeks w where w.game_id = g.game_id)) x
  union all
  select 'nfl_model_fresh', case when n = 0 then 'ok' else 'failed' end, n,
    'NFL games kicking off in the next 48 hours without a model prediction from the last 36 hours'
  from (select count(*) n from nfl.games g
        where g.kickoff_at between now() and now() + interval '48 hours'
          and not exists (select 1 from nfl.model_predictions p
                          where p.game_id = g.game_id and p.predicted_at > now() - interval '36 hours')) x
$$;


ALTER FUNCTION public.check_nfl_integrity() OWNER TO postgres;

--
-- Name: check_tennis_integrity(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.check_tennis_integrity() RETURNS TABLE(check_name text, status text, found bigint, detail text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select 'tennis_fresh',
    case when age_days is null then 'warning' when age_days >= 7 then 'failed' when age_days >= 3 then 'warning' else 'ok' end,
    coalesce(age_days, -1)::bigint,
    'Days since the last successful tennis_import run (runs on Chris''s PC; warns at 3, fails at 7; -1 = never run)'
  from (select extract(day from now() - max(finished_at))::int age_days
        from public.pipeline_runs where job_name = 'tennis_import' and status = 'success') x
  union all
  select 'tennis_sets_consistent', case when n = 0 then 'ok' else 'warning' end, n,
    'Completed tennis matches where sets won do not match the set scores (winner must take more sets)'
  from (select count(*) n from tennis.matches m
        where m.status = 'Completed' and m.w_sets is not null
          and (m.w_sets <= m.l_sets
               or m.w_sets <> (select count(*) from generate_subscripts(m.w_games, 1) i where m.w_games[i] > m.l_games[i])
               or m.l_sets <> (select count(*) from generate_subscripts(m.l_games, 1) i where m.l_games[i] > m.w_games[i]))) x
  union all
  select 'tennis_matches_mapped', case when n = 0 then 'ok' else 'failed' end, n,
    'Tennis matches missing from public.tennis_matches (unmapped player or tournament)'
  from (select (select count(*) from tennis.matches) - (select count(*) from public.tennis_matches) n) x
$$;


ALTER FUNCTION public.check_tennis_integrity() OWNER TO postgres;

--
-- Name: current_season_id(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.current_season_id() RETURNS bigint
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  -- The football season in play today. If next season's seasons row has not
  -- been added by 1 July, this stays on the latest season that has started
  -- (so feeds keep working on the old season) and check_model_integrity()
  -- fails 'season_rollover_ready' until the row is added.
  select coalesce(
    public.season_id_for_date(current_date),
    (select s.season_id from public.seasons s
      where make_date(s.start_year, 7, 1) <= current_date
      order by s.start_year desc limit 1))
$$;


ALTER FUNCTION public.current_season_id() OWNER TO postgres;

--
-- Name: earlier_season(bigint, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.earlier_season(a bigint, b bigint) RETURNS bigint
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  -- least(a, b) by start_year: nulls ignored, as least() does.
  select case when a is null then b
              when b is null then a
              when public.season_start_year(a) <= public.season_start_year(b) then a
              else b end
$$;


ALTER FUNCTION public.earlier_season(a bigint, b bigint) OWNER TO postgres;

--
-- Name: export_schema_definitions(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.export_schema_definitions() RETURNS TABLE(kind text, name text, definition text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  select 'view', c.relname::text,
    format('create or replace view public.%I%s as%s%s;', c.relname,
      case when c.reloptions is null then '' else ' with (' || array_to_string(c.reloptions, ', ') || ')' end,
      E'\n', rtrim(pg_get_viewdef(c.oid), ';'))
  from pg_class c
  where c.relnamespace = 'public'::regnamespace and c.relkind = 'v'
    and not exists (select 1 from pg_depend d where d.objid = c.oid and d.deptype = 'e')
  union all
  select 'materialized_view', c.relname::text,
    format('create materialized view public.%I as%s%s;', c.relname, E'\n', rtrim(pg_get_viewdef(c.oid), ';'))
  from pg_class c
  where c.relnamespace = 'public'::regnamespace and c.relkind = 'm'
  union all
  select 'function', p.proname::text || '(' || pg_get_function_identity_arguments(p.oid) || ')',
    pg_get_functiondef(p.oid) || ';'
  from pg_proc p
  where p.pronamespace = 'public'::regnamespace and p.prokind in ('f', 'p')
    and not exists (select 1 from pg_depend d where d.objid = p.oid and d.deptype = 'e')
  order by 1, 2;
$$;


ALTER FUNCTION public.export_schema_definitions() OWNER TO postgres;

--
-- Name: fanteam_projection_inputs(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fanteam_projection_inputs(p_matchweek integer) RETURNS TABLE(fixture_id bigint, matchweek integer, kickoff_date date, kickoff_time text, fpl_player_id integer, fpl_code integer, web_name text, first_name text, second_name text, element_type integer, team_id integer, team_name text, opponent_name text, is_home boolean, now_cost integer, status text, start_probability numeric, sub_appearance_probability numeric, expected_minutes numeric, expected_goals numeric, expected_assists numeric, expected_saves numeric, xpts_clean_sheet numeric, xpts_goals_conceded numeric, xpts_penalties numeric, xpts_cards_own_goals numeric, team_goals numeric, opp_goals numeric, p_off_before_60 numeric, p_off_60_84 numeric, p_full numeric, generated_at timestamp with time zone)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select pr.fixture_id::bigint, f.matchweek::int, f.kickoff_date::date, f.kickoff_time::text,
         pr.fpl_player_id::int, p.fpl_code::int, p.web_name::text, p.first_name::text, p.second_name::text,
         p.element_type::int, p.canonical_team_id::int, t.canonical_name::text, o.canonical_name::text,
         p.canonical_team_id = f.home_team_id,
         p.now_cost::int, p.status::text,
         least(1, greatest(0, pr.start_probability))::numeric,
         least(greatest(0, 1 - least(1, greatest(0, pr.start_probability))), greatest(0, pr.sub_appearance_probability))::numeric,
         pr.expected_minutes::numeric,
         pr.expected_goals::numeric, pr.expected_assists::numeric, pr.expected_saves::numeric,
         pr.xpts_clean_sheet::numeric, pr.xpts_goals_conceded::numeric, pr.xpts_penalties::numeric, pr.xpts_cards_own_goals::numeric,
         (case when p.canonical_team_id = f.home_team_id
               then coalesce(f.market_home_goals, f.predicted_home_goals)
               else coalesce(f.market_away_goals, f.predicted_away_goals) end)::numeric,
         (case when p.canonical_team_id = f.home_team_id
               then coalesce(f.market_away_goals, f.predicted_away_goals)
               else coalesce(f.market_home_goals, f.predicted_home_goals) end)::numeric,
         eb.p_off_before_60::numeric, eb.p_off_60_84::numeric, eb.p_full::numeric,
         pr.generated_at
  from public.fpl_player_projections pr
  join public.fixtures f on f.fixture_id = pr.fixture_id
  join public.fpl_players p on p.season_id = pr.season_id and p.fpl_player_id = pr.fpl_player_id
  left join public.teams t on t.team_id = p.canonical_team_id
  left join public.teams o on o.team_id = case when p.canonical_team_id = f.home_team_id then f.away_team_id else f.home_team_id end
  left join public.fpl_player_exit_bands eb on eb.season_id = pr.season_id and eb.fpl_player_id = pr.fpl_player_id
  where pr.model_version = 'leaguewide_v6'
    and f.league_id = 1
    and f.season_id = public.fpl_current_season_id()
    and f.matchweek = p_matchweek
$$;


ALTER FUNCTION public.fanteam_projection_inputs(p_matchweek integer) OWNER TO postgres;

--
-- Name: fanteam_save_paste(jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fanteam_save_paste(p_paste jsonb, p_rows jsonb) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_id bigint;
begin
  perform public._require_admin();
  if jsonb_typeof(p_rows) <> 'array' or jsonb_array_length(p_rows) = 0 then
    raise exception 'fanteam_save_paste: no rows';
  end if;
  insert into public.fanteam_price_pastes
    (contest_name, season_id, matchweek, rules_id, budget_m, stacking_penalty, safety_net,
     raw_text, row_count, parser_version, pasted_by)
  values
    (p_paste->>'contest_name', (p_paste->>'season_id')::int, (p_paste->>'matchweek')::int,
     (p_paste->>'rules_id')::bigint, (p_paste->>'budget_m')::numeric,
     (p_paste->>'stacking_penalty')::boolean, (p_paste->>'safety_net')::boolean,
     p_paste->>'raw_text', jsonb_array_length(p_rows), p_paste->>'parser_version', auth.uid())
  returning paste_id into v_id;

  insert into public.fanteam_player_prices
    (paste_id, row_no, name_raw, club_raw, position, price_m, team_id, fpl_code, match_method)
  select v_id, (r->>'row_no')::int, r->>'name_raw', r->>'club_raw', r->>'position',
         (r->>'price_m')::numeric, nullif(r->>'team_id','')::int, nullif(r->>'fpl_code','')::int,
         r->>'match_method'
  from jsonb_array_elements(p_rows) r;
  return v_id;
end $$;


ALTER FUNCTION public.fanteam_save_paste(p_paste jsonb, p_rows jsonb) OWNER TO postgres;

--
-- Name: fixture_derived_markets(numeric, numeric, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fixture_derived_markets(p_lambda_home numeric, p_lambda_away numeric, p_rho numeric) RETURNS TABLE(home_win numeric, draw numeric, away_win numeric, over_2_5 numeric, under_2_5 numeric, btts numeric, home_clean_sheet numeric, away_clean_sheet numeric)
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with grid as (
    select h, a,
      case
        when h = 0 and a = 0 then 1 - p_lambda_home * p_lambda_away * p_rho
        when h = 0 and a = 1 then 1 + p_lambda_home * p_rho
        when h = 1 and a = 0 then 1 + p_lambda_away * p_rho
        when h = 1 and a = 1 then 1 - p_rho
        else 1
      end
      * (exp(-p_lambda_home) * power(p_lambda_home, h) / (select coalesce(prod, 1) from (select exp(sum(ln(g))) as prod from generate_series(1, greatest(h,1)) g where h > 0) x))
      * (exp(-p_lambda_away) * power(p_lambda_away, a) / (select coalesce(prod, 1) from (select exp(sum(ln(g))) as prod from generate_series(1, greatest(a,1)) g where a > 0) y))
      as p
    from generate_series(0, 8) h, generate_series(0, 8) a
  ),
  t as (select sum(p) as total from grid)
  select
    round((sum(p) filter (where h > a) / total * 100)::numeric, 2),
    round((sum(p) filter (where h = a) / total * 100)::numeric, 2),
    round((sum(p) filter (where h < a) / total * 100)::numeric, 2),
    round((sum(p) filter (where h + a > 2) / total * 100)::numeric, 2),
    round((sum(p) filter (where h + a <= 2) / total * 100)::numeric, 2),
    round((sum(p) filter (where h > 0 and a > 0) / total * 100)::numeric, 2),
    round((sum(p) filter (where a = 0) / total * 100)::numeric, 2),
    round((sum(p) filter (where h = 0) / total * 100)::numeric, 2)
  from grid, t group by total;
$$;


ALTER FUNCTION public.fixture_derived_markets(p_lambda_home numeric, p_lambda_away numeric, p_rho numeric) OWNER TO postgres;

--
-- Name: fpl_current_season_id(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fpl_current_season_id() RETURNS bigint
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  -- The FPL season in play: the latest season FPL has published gameweeks
  -- for. Rolls over by itself when next season's bootstrap is first loaded.
  -- Latest by start_year: season_id is not in date order.
  select s.season_id from public.seasons s
   where s.start_year = (select max(sg.start_year) from public.seasons sg
                          where sg.season_id in (select g.season_id from public.fpl_gameweeks g));
$$;


ALTER FUNCTION public.fpl_current_season_id() OWNER TO postgres;

--
-- Name: fpl_entry_fetch(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fpl_entry_fetch(p_entry_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET statement_timeout TO '7s'
    AS $$
declare
  base text := 'https://fantasy.premierleague.com/api/entry/' || p_entry_id::text;
  st int;
  body text;
  entry jsonb;
  hist jsonb;
  trans jsonb;
  picks jsonb;
  prev jsonb := null;
  ev int;
begin
  if p_entry_id is null or p_entry_id < 1 or p_entry_id > 99999999 then
    return jsonb_build_object('status', 'bad_id');
  end if;

  delete from private.fpl_entry_calls where called_at < now() - interval '2 minutes';
  if (select count(*) from private.fpl_entry_calls where called_at > now() - interval '1 minute') >= 120 then
    return jsonb_build_object('status', 'busy');
  end if;
  insert into private.fpl_entry_calls default values;

  perform extensions.http_set_curlopt('CURLOPT_TIMEOUT_MS', '2500');

  begin
    select status, content into st, body from extensions.http_get(base || '/');
  exception when others then
    return jsonb_build_object('status', 'unavailable', 'fpl_status', 0);
  end;
  if st = 404 then return jsonb_build_object('status', 'not_found'); end if;
  if st <> 200 then return jsonb_build_object('status', 'unavailable', 'fpl_status', st); end if;
  entry := body::jsonb;
  ev := (entry ->> 'current_event')::int;
  if ev is null then return jsonb_build_object('status', 'not_started'); end if;

  begin
    select status, content into st, body from extensions.http_get(base || '/event/' || ev || '/picks/');
  exception when others then st := 0;
  end;
  if st <> 200 then return jsonb_build_object('status', 'unavailable', 'fpl_status', st); end if;
  picks := body::jsonb;

  begin
    select status, content into st, body from extensions.http_get(base || '/history/');
    hist := case when st = 200 then body::jsonb end;
  exception when others then hist := null;
  end;
  begin
    select status, content into st, body from extensions.http_get(base || '/transfers/');
    trans := case when st = 200 then body::jsonb end;
  exception when others then trans := null;
  end;

  if picks ->> 'active_chip' = 'freehit' and ev > 1 then
    begin
      select status, content into st, body from extensions.http_get(base || '/event/' || (ev - 1) || '/picks/');
    exception when others then st := 0;
    end;
    if st <> 200 then return jsonb_build_object('status', 'unavailable', 'fpl_status', st); end if;
    prev := body::jsonb;
  end if;

  return jsonb_build_object(
    'status', 'ok',
    'entry', jsonb_build_object(
      'id', p_entry_id,
      'name', entry -> 'name',
      'current_event', ev,
      'last_deadline_bank', entry -> 'last_deadline_bank',
      'overall_rank', entry -> 'summary_overall_rank',
      'total_points', entry -> 'summary_overall_points'
    ),
    'chips', coalesce((select jsonb_agg(jsonb_build_object('name', c ->> 'name', 'event', (c ->> 'event')::int)) from jsonb_array_elements(hist -> 'chips') c), '[]'::jsonb),
    'transfers_known', trans is not null,
    'transfers', coalesce((select jsonb_agg(jsonb_build_object(
        'element_in', (t ->> 'element_in')::int, 'element_in_cost', (t ->> 'element_in_cost')::int,
        'element_out', (t ->> 'element_out')::int, 'element_out_cost', (t ->> 'element_out_cost')::int,
        'event', (t ->> 'event')::int, 'time', t ->> 'time')) from jsonb_array_elements(trans) t), '[]'::jsonb),
    'picks', jsonb_build_object('active_chip', picks -> 'active_chip', 'bank', picks -> 'entry_history' -> 'bank', 'picks', picks -> 'picks'),
    'prev_picks', case when prev is null then null
      else jsonb_build_object('active_chip', prev -> 'active_chip', 'bank', prev -> 'entry_history' -> 'bank', 'picks', prev -> 'picks') end
  );
end;
$$;


ALTER FUNCTION public.fpl_entry_fetch(p_entry_id bigint) OWNER TO postgres;

