-- Name: fpl_gameweek_for_date(bigint, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fpl_gameweek_for_date(p_season_id bigint, p_date date) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select max(fpl_event_id)::integer
  from public.fpl_gameweeks
  where season_id = p_season_id
    and (deadline_time at time zone 'Europe/London')::date < p_date;
$$;


