--
-- Name: fpl_score(bigint, integer, integer, integer, integer, integer, integer, integer, integer, integer, integer, integer, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fpl_score(p_season_id bigint, p_element_type integer, p_minutes integer, p_goals integer, p_assists integer, p_clean_sheets integer, p_goals_conceded integer, p_saves integer, p_penalties_saved integer, p_penalties_missed integer, p_own_goals integer, p_yellow_cards integer, p_red_cards integer, p_bonus integer, p_defensive_contribution integer DEFAULT 0) RETURNS integer
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select public.fpl_score_calc(rs, p_minutes, p_goals, p_assists, p_clean_sheets, p_goals_conceded, p_saves,
    p_penalties_saved, p_penalties_missed, p_own_goals, p_yellow_cards, p_red_cards, p_bonus, p_defensive_contribution)
  from public.fpl_scoring_rule_sets rs
  where rs.season_id = p_season_id and rs.element_type = p_element_type
$$;


ALTER FUNCTION public.fpl_score(p_season_id bigint, p_element_type integer, p_minutes integer, p_goals integer, p_assists integer, p_clean_sheets integer, p_goals_conceded integer, p_saves integer, p_penalties_saved integer, p_penalties_missed integer, p_own_goals integer, p_yellow_cards integer, p_red_cards integer, p_bonus integer, p_defensive_contribution integer) OWNER TO postgres;

SET default_tablespace = '';

SET default_table_access_method = heap;

--
-- Name: fpl_scoring_rules; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.fpl_scoring_rules (
    rule_id bigint NOT NULL,
    season_id bigint NOT NULL,
    rule_code text NOT NULL,
    player_position text,
    points numeric NOT NULL,
    threshold numeric,
    notes text,
    source_name text NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);


ALTER TABLE public.fpl_scoring_rules OWNER TO postgres;

--
-- Name: fpl_scoring_rule_sets; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.fpl_scoring_rule_sets WITH (security_invoker='true') AS
 SELECT r.season_id,
    pos.element_type,
    pos.code AS "position",
    max(r.points) FILTER (WHERE (r.rule_code = 'appearance_under_60'::text)) AS appearance_pts,
    max(r.threshold) FILTER (WHERE (r.rule_code = 'appearance_under_60'::text)) AS appearance_min,
    max(r.points) FILTER (WHERE (r.rule_code = 'appearance_60_plus'::text)) AS full_pts,
    max(r.threshold) FILTER (WHERE (r.rule_code = 'appearance_60_plus'::text)) AS full_min,
    max(r.points) FILTER (WHERE (r.rule_code = 'goal'::text)) AS goal_pts,
    max(r.points) FILTER (WHERE (r.rule_code = 'assist'::text)) AS assist_pts,
    max(r.points) FILTER (WHERE (r.rule_code = 'clean_sheet'::text)) AS clean_sheet_pts,
    max(r.threshold) FILTER (WHERE (r.rule_code = 'clean_sheet'::text)) AS clean_sheet_min,
    max(r.points) FILTER (WHERE (r.rule_code = 'save'::text)) AS save_pts,
    max(r.threshold) FILTER (WHERE (r.rule_code = 'save'::text)) AS saves_per,
    max(r.points) FILTER (WHERE (r.rule_code = 'goals_conceded'::text)) AS conceded_pts,
    max(r.threshold) FILTER (WHERE (r.rule_code = 'goals_conceded'::text)) AS conceded_per,
    max(r.points) FILTER (WHERE (r.rule_code = 'penalty_save'::text)) AS penalty_save_pts,
    max(r.points) FILTER (WHERE (r.rule_code = 'penalty_miss'::text)) AS penalty_miss_pts,
    max(r.points) FILTER (WHERE (r.rule_code = 'own_goal'::text)) AS own_goal_pts,
    max(r.points) FILTER (WHERE (r.rule_code = 'yellow_card'::text)) AS yellow_pts,
    max(r.points) FILTER (WHERE (r.rule_code = 'red_card'::text)) AS red_pts,
    max(r.points) FILTER (WHERE (r.rule_code = 'defensive_contribution'::text)) AS defcon_pts,
    max(r.threshold) FILTER (WHERE (r.rule_code = 'defensive_contribution'::text)) AS defcon_min
   FROM (public.fpl_scoring_rules r
     JOIN ( VALUES (1,'GK'::text), (2,'DEF'::text), (3,'MID'::text), (4,'FWD'::text)) pos(element_type, code) ON (((r.player_position IS NULL) OR (r.player_position = pos.code))))
  GROUP BY r.season_id, pos.element_type, pos.code;


ALTER VIEW public.fpl_scoring_rule_sets OWNER TO postgres;

--
-- Name: fpl_score_calc(public.fpl_scoring_rule_sets, integer, integer, integer, integer, integer, integer, integer, integer, integer, integer, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fpl_score_calc(rs public.fpl_scoring_rule_sets, p_minutes integer, p_goals integer, p_assists integer, p_clean_sheets integer, p_goals_conceded integer, p_saves integer, p_penalties_saved integer, p_penalties_missed integer, p_own_goals integer, p_yellow_cards integer, p_red_cards integer, p_bonus integer, p_defensive_contribution integer) RETURNS integer
    LANGUAGE sql IMMUTABLE
    AS $$
  select (
      case when p_minutes >= rs.full_min then rs.full_pts
           when p_minutes >= rs.appearance_min then rs.appearance_pts else 0 end
    + p_goals * coalesce(rs.goal_pts, 0)
    + p_assists * coalesce(rs.assist_pts, 0)
    + case when p_clean_sheets > 0 and p_minutes >= rs.clean_sheet_min then rs.clean_sheet_pts else 0 end
    + coalesce(floor(p_saves / rs.saves_per) * rs.save_pts, 0)
    + coalesce(floor(p_goals_conceded / rs.conceded_per) * rs.conceded_pts, 0)
    + p_penalties_saved * coalesce(rs.penalty_save_pts, 0)
    + p_penalties_missed * coalesce(rs.penalty_miss_pts, 0)
    + p_own_goals * coalesce(rs.own_goal_pts, 0)
    + p_yellow_cards * coalesce(rs.yellow_pts, 0)
    + p_red_cards * coalesce(rs.red_pts, 0)
    + case when coalesce(p_defensive_contribution, 0) >= rs.defcon_min then rs.defcon_pts else 0 end
  )::int + coalesce(p_bonus, 0)
$$;


ALTER FUNCTION public.fpl_score_calc(rs public.fpl_scoring_rule_sets, p_minutes integer, p_goals integer, p_assists integer, p_clean_sheets integer, p_goals_conceded integer, p_saves integer, p_penalties_saved integer, p_penalties_missed integer, p_own_goals integer, p_yellow_cards integer, p_red_cards integer, p_bonus integer, p_defensive_contribution integer) OWNER TO postgres;

--
-- Name: generate_fixture_slug(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.generate_fixture_slug() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_home_slug text;
  v_away_slug text;
begin
  if new.slug is not null then
    return new;
  end if;
  select slug into v_home_slug from public.teams where team_id = new.home_team_id;
  select slug into v_away_slug from public.teams where team_id = new.away_team_id;
  if v_home_slug is null or v_away_slug is null then
    raise exception 'Cannot generate fixture slug: missing team slug for home_team_id=% or away_team_id=%', new.home_team_id, new.away_team_id;
  end if;
  new.slug := v_home_slug || '-v-' || v_away_slug || '-' || new.kickoff_date::text;
  return new;
end;
$$;


ALTER FUNCTION public.generate_fixture_slug() OWNER TO postgres;

--
-- Name: generate_fpl_player_slug(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.generate_fpl_player_slug() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_base text;
  v_candidate text;
  v_suffix int := 1;
begin
  v_base := public.slugify(coalesce(nullif(trim(coalesce(new.first_name,'') || ' ' || coalesce(new.second_name,'')), ''), new.web_name));
  if v_base is null then
    new.slug := null;
    return new;
  end if;

  -- Unchanged name on an update: keep the existing slug so a public URL
  -- stays stable rather than churning on every ingestion pass.
  if tg_op = 'UPDATE' and new.slug is not null
     and public.slugify(coalesce(nullif(trim(coalesce(old.first_name,'') || ' ' || coalesce(old.second_name,'')), ''), old.web_name)) is not distinct from v_base then
    return new;
  end if;

  v_candidate := v_base;
  while exists (
    select 1 from public.fpl_players
    where season_id = new.season_id and slug = v_candidate
      and fpl_player_id is distinct from new.fpl_player_id
  ) loop
    v_suffix := v_suffix + 1;
    v_candidate := v_base || '-' || v_suffix;
  end loop;

  new.slug := v_candidate;
  return new;
end;
$$;


ALTER FUNCTION public.generate_fpl_player_slug() OWNER TO postgres;

--
-- Name: get_actual_value_table(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_actual_value_table(p_season_id bigint DEFAULT public.fpl_current_season_id()) RETURNS TABLE(fpl_player_id bigint, web_name text, slug text, team_name text, position_label text, price numeric, total_points integer, points_per_million numeric, minutes integer, goals integer, assists integer, clean_sheets integer, bonus integer, ownership numeric)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with latest as (
    select max(snapshot_date) as d from public.fpl_player_snapshots where season_id = p_season_id
  ),
  snap as (
    select s.* from public.fpl_player_snapshots s, latest l where s.snapshot_date = l.d
  ),
  totals as (
    select g.fpl_player_id,
      sum(coalesce(g.minutes, 0))::integer as mins,
      sum(coalesce(g.goals_scored, 0))::integer as gls,
      sum(coalesce(g.assists, 0))::integer as ast,
      sum(coalesce(g.clean_sheets, 0))::integer as cs,
      sum(coalesce(g.bonus, 0))::integer as bns
    from public.fpl_player_gameweeks g
    where g.season_id = p_season_id
    group by g.fpl_player_id
  )
  select
    p.fpl_player_id, p.web_name, p.slug, t.display_name,
    case p.element_type when 1 then 'GKP' when 2 then 'DEF' when 3 then 'MID' when 4 then 'FWD' else '?' end,
    round(sn.now_cost / 10.0, 1),
    coalesce(sn.total_points, 0),
    case when sn.now_cost > 0 then round((coalesce(sn.total_points, 0) / (sn.now_cost / 10.0))::numeric, 2) else 0 end,
    coalesce(tt.mins, 0), coalesce(tt.gls, 0), coalesce(tt.ast, 0), coalesce(tt.cs, 0), coalesce(tt.bns, 0),
    round(sn.selected_by_percent::numeric, 1)
  from snap sn
  join public.fpl_players p on p.fpl_player_id = sn.fpl_player_id and p.season_id = sn.season_id
  left join public.teams t on t.team_id = p.canonical_team_id
  left join totals tt on tt.fpl_player_id = sn.fpl_player_id
  where p.web_name is not null and coalesce(sn.total_points, 0) > 0
  order by 8 desc;
$$;


ALTER FUNCTION public.get_actual_value_table(p_season_id bigint) OWNER TO postgres;

--
-- Name: get_all_time_top_scorers(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_all_time_top_scorers() RETURNS TABLE(display_name text, goals bigint, seasons_covered bigint)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select t.display_name,
    sum(case when m.home_team_id = t.team_id then m.full_time_home_goals else m.full_time_away_goals end)::bigint,
    (select count(distinct season_id) from public.matches)::bigint
  from public.matches m
  join public.teams t on t.team_id in (m.home_team_id, m.away_team_id)
  group by t.display_name
  order by 2 desc
  limit 4;
$$;


ALTER FUNCTION public.get_all_time_top_scorers() OWNER TO postgres;

--
-- Name: get_best_defence_rating(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_best_defence_rating(p_league_id bigint) RETURNS TABLE(canonical_name text, goals_against_per_game numeric)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with latest_fit as (
    select fit_run_id from public.model_fit_runs
    where league_id = p_league_id and status = 'accepted'
    order by fitted_at desc
    limit 1
  )
  select t.canonical_name,
    exp(-(tr.defence_strength + coalesce(o.defence_adjustment, 0))) as goals_against_per_game
  from public.team_ratings tr
  join latest_fit lf on lf.fit_run_id = tr.fit_run_id
  join public.teams t on t.team_id = tr.team_id
  left join public.team_strength_manual_override o on o.team_id = tr.team_id
  order by goals_against_per_game asc
  limit 4;
$$;


ALTER FUNCTION public.get_best_defence_rating(p_league_id bigint) OWNER TO postgres;

--
-- Name: get_betting_bets(numeric, text, boolean, boolean, numeric, bigint, bigint, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_betting_bets(p_edge numeric DEFAULT 0.05, p_market text DEFAULT '1x2'::text, p_closing boolean DEFAULT true, p_best_price boolean DEFAULT true, p_stake numeric DEFAULT 10, p_season_id bigint DEFAULT public.current_season_id(), p_league_id bigint DEFAULT NULL::bigint, p_promoted text DEFAULT 'all'::text) RETURNS TABLE(match_id bigint, match_date date, home_team text, away_team text, home_goals integer, away_goals integer, selection text, model_p numeric, price numeric, edge numeric, won boolean, stake numeric, profit numeric, prices jsonb, predicted_from date, retrofit boolean, league_id bigint, league_name text, home_promoted boolean, away_promoted boolean)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
#variable_conflict use_column
-- Price basis (p_best_price):
--   true  -> highest price on file: every bookmaker row plus the market 'Max'
--            row ('Max' is not always highest -- Pinnacle's close can beat it)
--   false -> the 'Avg' row: market average price
-- 'Max' and 'Avg' are NOT bookmakers; before 2026-09-23 "median" was the
-- median of Avg, Max and two or three real books together.
declare max_p numeric;
begin
  if p_promoted not in ('all', 'exclude', 'only') then
    raise exception 'p_promoted must be all, exclude or only (got %)', p_promoted;
  end if;
  -- fixture_derived_markets returns PERCENTAGES; if that ever changes, the
  -- /100 below would silently bet on everything, so check it.
  select max(greatest(home_win, draw, away_win)) into max_p from public.fixture_derived_markets(1.6, 1.1, -0.1);
  if max_p is null or max_p <= 1.5 then
    raise exception 'fixture_derived_markets no longer returns percentages (max %), so the /100 here is wrong', max_p;
  end if;

  return query
  with played as materialized (
    select f.predicted_home_goals::numeric as lh, f.predicted_away_goals::numeric as la,
           coalesce(mfr.rho, 0)::numeric as rho, m.match_id, m.match_date::date as md,
           m.home_team_id, m.away_team_id, m.league_id as lg, m.season_id as sid,
           m.full_time_home_goals as hg, m.full_time_away_goals as ag,
           mfr.fitted_at::date as pf, coalesce(mfr.is_retrofit, false) as rf
    from public.fixtures f
    join public.matches m
      on m.home_team_id = f.home_team_id and m.away_team_id = f.away_team_id
     and m.match_date::date = f.kickoff_date::date
    left join public.model_fit_runs mfr on mfr.fit_run_id = f.prediction_fit_run_id
    where f.season_id = p_season_id and f.status = 'played'
      and f.predicted_home_goals is not null and m.full_time_home_goals is not null
    union all
    select mp.predicted_home_goals::numeric, mp.predicted_away_goals::numeric,
           coalesce(mfr2.rho, 0)::numeric, m2.match_id, m2.match_date::date,
           m2.home_team_id, m2.away_team_id, m2.league_id, m2.season_id,
           m2.full_time_home_goals, m2.full_time_away_goals,
           mp.fit_as_of_date, coalesce(mfr2.is_retrofit, false)
    from public.match_predictions mp
    join public.matches m2 on m2.match_id = mp.match_id
    left join public.model_fit_runs mfr2 on mfr2.fit_run_id = mp.fit_run_id
    where m2.season_id = p_season_id and m2.full_time_home_goals is not null
      and not exists (
        select 1 from public.fixtures f2
        where f2.season_id = p_season_id and f2.status = 'played'
          and f2.predicted_home_goals is not null
          and f2.home_team_id = m2.home_team_id and f2.away_team_id = m2.away_team_id
          and f2.kickoff_date::date = m2.match_date::date)
  ),
  rows_ as materialized (
    select o.* from public.match_odds o
    where o.match_id in (select pl.match_id from played pl)
      and o.market = p_market and (o.is_closing = p_closing or o.is_closing is null) and o.bookmaker <> 'BFE'
  ),
  prices as materialized (
    select o.match_id,
      case when p_best_price then max(o.price_home) else max(o.price_home) filter (where o.bookmaker = 'Avg') end as price_home,
      case when p_best_price then max(o.price_draw) else max(o.price_draw) filter (where o.bookmaker = 'Avg') end as price_draw,
      case when p_best_price then max(o.price_away) else max(o.price_away) filter (where o.bookmaker = 'Avg') end as price_away,
      case when p_best_price then max(o.price_over) else max(o.price_over) filter (where o.bookmaker = 'Avg') end as price_over,
      case when p_best_price then max(o.price_under) else max(o.price_under) filter (where o.bookmaker = 'Avg') end as price_under,
      jsonb_object_agg(o.bookmaker, o.price_home) filter (where o.price_home is not null) as src_home,
      jsonb_object_agg(o.bookmaker, o.price_draw) filter (where o.price_draw is not null) as src_draw,
      jsonb_object_agg(o.bookmaker, o.price_away) filter (where o.price_away is not null) as src_away,
      jsonb_object_agg(o.bookmaker, o.price_over) filter (where o.price_over is not null) as src_over,
      jsonb_object_agg(o.bookmaker, o.price_under) filter (where o.price_under is not null) as src_under
    from rows_ o group by o.match_id
  ),
  markets as (
    select pl.*, pr.price_home, pr.price_draw, pr.price_away, pr.price_over, pr.price_under,
           pr.src_home, pr.src_draw, pr.src_away, pr.src_over, pr.src_under,
           dm.home_win / 100.0 as home_win, dm.draw / 100.0 as draw, dm.away_win / 100.0 as away_win,
           dm.over_2_5 / 100.0 as over_2_5, dm.under_2_5 / 100.0 as under_2_5
    from played pl join prices pr on pr.match_id = pl.match_id
    cross join lateral public.fixture_derived_markets(pl.lh, pl.la, pl.rho) dm
  ),
  candidates as (
    select mk.*, 'Home'::text as sel, mk.home_win::numeric as mp_, mk.price_home as px, (mk.hg > mk.ag) as w, mk.src_home as src from markets mk where p_market='1x2' and mk.price_home is not null
    union all select mk.*, 'Draw', mk.draw::numeric, mk.price_draw, (mk.hg = mk.ag), mk.src_draw from markets mk where p_market='1x2' and mk.price_draw is not null
    union all select mk.*, 'Away', mk.away_win::numeric, mk.price_away, (mk.ag > mk.hg), mk.src_away from markets mk where p_market='1x2' and mk.price_away is not null
    union all select mk.*, 'Over 2.5', mk.over_2_5::numeric, mk.price_over, (mk.hg + mk.ag > 2.5), mk.src_over from markets mk where p_market='ou25' and mk.price_over is not null
    union all select mk.*, 'Under 2.5', mk.under_2_5::numeric, mk.price_under, (mk.hg + mk.ag < 2.5), mk.src_under from markets mk where p_market='ou25' and mk.price_under is not null
  )
  select c.match_id, c.md, ht.canonical_name, at.canonical_name, c.hg, c.ag,
         c.sel, c.mp_, c.px, c.mp_ - (1.0 / c.px), c.w, p_stake,
         case when c.w then p_stake * c.px - p_stake else -p_stake end,
         c.src, c.pf, c.rf,
         c.lg, lgn.name, coalesce(hm.is_promoted, false), coalesce(am.is_promoted, false)
  from candidates c
  join public.teams ht on ht.team_id = c.home_team_id
  join public.teams at on at.team_id = c.away_team_id
  join public.leagues lgn on lgn.league_id = c.lg
  -- Promoted: arrived from a lower division this season (team_season_movement).
  left join public.team_season_movement hm on hm.team_id = c.home_team_id and hm.league_id = c.lg and hm.season_id = c.sid
  left join public.team_season_movement am on am.team_id = c.away_team_id and am.league_id = c.lg and am.season_id = c.sid
  where c.px > 1 and c.mp_ between 0 and 1 and c.mp_ - (1.0 / c.px) >= p_edge
    and (p_league_id is null or c.lg = p_league_id)
    and (p_promoted = 'all'
      or (p_promoted = 'exclude' and not (coalesce(hm.is_promoted, false) or coalesce(am.is_promoted, false)))
      or (p_promoted = 'only' and (coalesce(hm.is_promoted, false) or coalesce(am.is_promoted, false))))
  order by c.md, ht.canonical_name, c.sel;
end $$;


ALTER FUNCTION public.get_betting_bets(p_edge numeric, p_market text, p_closing boolean, p_best_price boolean, p_stake numeric, p_season_id bigint, p_league_id bigint, p_promoted text) OWNER TO postgres;

--
-- Name: get_betting_returns(numeric, text, boolean, boolean, numeric, bigint, bigint, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_betting_returns(p_edge numeric DEFAULT 0.05, p_market text DEFAULT '1x2'::text, p_closing boolean DEFAULT true, p_best_price boolean DEFAULT true, p_stake numeric DEFAULT 10, p_season_id bigint DEFAULT public.current_season_id(), p_league_id bigint DEFAULT NULL::bigint, p_promoted text DEFAULT 'all'::text) RETURNS TABLE(selection text, bets integer, staked numeric, returned numeric, profit numeric, roi_pct numeric, wins integer, hit_rate_pct numeric, avg_odds numeric, avg_edge_pct numeric)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  -- A summary of get_betting_bets, so the bet list and these totals can never disagree.
  select b.selection, count(*)::integer,
    round(sum(b.stake), 2),
    round(sum(case when b.won then b.stake * b.price else 0 end), 2),
    round(sum(b.profit), 2),
    round(100 * sum(b.profit) / nullif(sum(b.stake), 0), 1),
    count(*) filter (where b.won)::integer,
    round(100.0 * count(*) filter (where b.won) / nullif(count(*), 0), 1),
    round(avg(b.price), 2),
    round(100 * avg(b.edge), 1)
  from public.get_betting_bets(p_edge, p_market, p_closing, p_best_price, p_stake, p_season_id, p_league_id, p_promoted) b
  group by b.selection order by b.selection;
$$;


ALTER FUNCTION public.get_betting_returns(p_edge numeric, p_market text, p_closing boolean, p_best_price boolean, p_stake numeric, p_season_id bigint, p_league_id bigint, p_promoted text) OWNER TO postgres;

--
-- Name: get_biggest_comebacks(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_biggest_comebacks() RETURNS TABLE(home text, away text, ht_home integer, ht_away integer, ft_home integer, ft_away integer, match_date date, league_code text, deficit integer)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select ht.display_name, at.display_name,
    m.half_time_home_goals, m.half_time_away_goals,
    m.full_time_home_goals, m.full_time_away_goals,
    m.match_date, l.code,
    greatest(m.half_time_away_goals - m.half_time_home_goals,
             m.half_time_home_goals - m.half_time_away_goals) as deficit
  from public.matches m
  join public.teams ht on ht.team_id = m.home_team_id
  join public.teams at on at.team_id = m.away_team_id
  join public.leagues l on l.league_id = m.league_id
  where m.half_time_home_goals is not null
    and (
      (m.half_time_away_goals - m.half_time_home_goals >= 2 and m.full_time_home_goals > m.full_time_away_goals)
      or (m.half_time_home_goals - m.half_time_away_goals >= 2 and m.full_time_away_goals > m.full_time_home_goals)
    )
  order by deficit desc, m.match_date desc
  limit 8;
$$;


ALTER FUNCTION public.get_biggest_comebacks() OWNER TO postgres;

--
-- Name: get_completed_gameweeks(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_completed_gameweeks(p_season_id bigint DEFAULT public.fpl_current_season_id()) RETURNS TABLE(fpl_event_id integer, players bigint, total_points bigint, best_score integer)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select h.gameweek::integer, count(*)::bigint, sum(h.total_points)::bigint, max(h.total_points)::integer
  from public.fpl_player_gameweek_history h
  where h.season_id = p_season_id
  group by h.gameweek
  union all
  select g.fpl_event_id::integer, count(*)::bigint, sum(g.total_points)::bigint, max(g.total_points)::integer
  from public.fpl_player_gameweeks g
  where g.season_id = p_season_id
    and not exists (select 1 from public.fpl_player_gameweek_history h2 where h2.season_id = p_season_id)
    and g.total_points is not null
    and g.fpl_event_id in (
      select f.fpl_event_id from public.fpl_fixtures f
      where f.season_id = p_season_id group by f.fpl_event_id having bool_and(f.finished)
    )
  group by g.fpl_event_id
  order by 1 desc;
$$;


ALTER FUNCTION public.get_completed_gameweeks(p_season_id bigint) OWNER TO postgres;

--
-- Name: get_countries_by_relevance(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_countries_by_relevance() RETURNS TABLE(country_id bigint, name text, code text, teams_with_matches bigint)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select c.country_id, c.name, c.code,
    -- one pass over matches (a per-team EXISTS on home OR away scanned
    -- matches once per team: 13.6s after the European history load)
    count(distinct t.team_id) filter (where p.team_id is not null)
  from countries c
  left join teams t on t.country_id = c.country_id
  left join (select home_team_id as team_id from matches
             union select away_team_id from matches) p on p.team_id = t.team_id
  group by c.country_id, c.name, c.code
  order by 4 desc, c.name asc;
$$;


ALTER FUNCTION public.get_countries_by_relevance() OWNER TO postgres;

--
-- Name: get_country_competitiveness(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_country_competitiveness() RETURNS TABLE(league_code text, season_label text, clubs bigint, points_spread numeric, bottom_not_losing_pct numeric)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with base as (
    select l.code, s.label, m.home_team_id h, m.away_team_id a, m.full_time_result r
    from public.matches m
    join public.leagues l on l.league_id = m.league_id
    join public.seasons s on s.season_id = m.season_id
    where l.competition_type = 'league' and (l.tier = 1 or l.code = 'E0')
      and m.full_time_result is not null
  ), pts as (
    select code, label, team, sum(p)::numeric / count(*) ppg from (
      select code, label, h team, case r when 'H' then 3 when 'D' then 1 else 0 end p from base
      union all
      select code, label, a, case r when 'A' then 3 when 'D' then 1 else 0 end from base
    ) x group by code, label, team
  ), halves as (
    select code, label, team, ppg,
      percent_rank() over (partition by code, label order by ppg desc) < 0.5 top_half
    from pts
  ), cross_half as (
    select b.code, b.label,
      count(*) games,
      count(*) filter (where (th.top_half and b.r <> 'H') or (ta.top_half and b.r <> 'A')) bottom_not_losing
    from base b
    join halves th on th.code = b.code and th.label = b.label and th.team = b.h
    join halves ta on ta.code = b.code and ta.label = b.label and ta.team = b.a
    where th.top_half <> ta.top_half
    group by b.code, b.label
  )
  select h.code, h.label, count(*)::bigint,
    round(stddev_pop(h.ppg), 3),
    round(100.0 * max(c.bottom_not_losing) / nullif(max(c.games), 0), 1)
  from halves h join cross_half c on c.code = h.code and c.label = h.label
  group by h.code, h.label
  order by h.code, (select se.start_year from public.seasons se where se.label = h.label);
$$;


ALTER FUNCTION public.get_country_competitiveness() OWNER TO postgres;

--
-- Name: get_country_league_summary(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_country_league_summary() RETURNS TABLE(country_id bigint, country_name text, league_code text, league_name text, season_label text, matches bigint, goals_per_game numeric, home_goals_per_game numeric, away_goals_per_game numeric, home_win_pct numeric, draw_pct numeric, away_win_pct numeric, yellows_per_game numeric, reds_per_game numeric, over_two_five_pct numeric, both_scored_pct numeric, nil_nil_pct numeric, comeback_pct numeric)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select c.country_id, c.name, l.code, public.league_name_for_season(l.league_id, s.season_id), s.label,
    count(*)::bigint,
    round(avg(m.full_time_home_goals + m.full_time_away_goals)::numeric, 2),
    round(avg(m.full_time_home_goals)::numeric, 2),
    round(avg(m.full_time_away_goals)::numeric, 2),
    round(100.0 * avg(case when m.full_time_result = 'H' then 1 else 0 end)::numeric, 1),
    round(100.0 * avg(case when m.full_time_result = 'D' then 1 else 0 end)::numeric, 1),
    round(100.0 * avg(case when m.full_time_result = 'A' then 1 else 0 end)::numeric, 1),
    round((avg(m.home_yellow_cards + m.away_yellow_cards) filter (where m.source_file not like '%/new/%' and m.home_shots is not null))::numeric, 2),
    round((avg(m.home_red_cards + m.away_red_cards) filter (where m.source_file not like '%/new/%' and m.home_shots is not null))::numeric, 3),
    round(100.0 * avg(case when m.full_time_home_goals + m.full_time_away_goals > 2.5 then 1 else 0 end)::numeric, 1),
    round(100.0 * avg(case when m.full_time_home_goals > 0 and m.full_time_away_goals > 0 then 1 else 0 end)::numeric, 1),
    round(100.0 * avg(case when m.full_time_home_goals = 0 and m.full_time_away_goals = 0 then 1 else 0 end)::numeric, 1),
    round(100.0 * (
      count(*) filter (where m.half_time_result is not null and m.half_time_result <> 'D' and m.half_time_result <> m.full_time_result)::numeric
      / nullif(count(*) filter (where m.half_time_result is not null and m.half_time_result <> 'D'), 0)
    ), 1)
  from public.matches m
  join public.leagues l on l.league_id = m.league_id
  join public.countries c on c.country_id = l.country_id
  join public.seasons s on s.season_id = m.season_id
  where l.competition_type = 'league' and (l.tier = 1 or l.code = 'E0')
    and m.full_time_result is not null
  group by c.country_id, c.name, l.code, l.league_id, s.season_id, s.label
  order by c.name, min(s.start_year);
$$;


ALTER FUNCTION public.get_country_league_summary() OWNER TO postgres;

--
-- Name: get_cross_league_summary(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_cross_league_summary() RETURNS TABLE(league_code text, league_name text, season_label text, matches bigint, goals_per_game numeric, home_goals_per_game numeric, away_goals_per_game numeric, home_win_pct numeric, draw_pct numeric, away_win_pct numeric, yellows_per_game numeric, reds_per_game numeric, over_two_five_pct numeric, both_scored_pct numeric, nil_nil_pct numeric, comeback_pct numeric)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select l.code, public.league_name_for_season(l.league_id, s.season_id), s.label,
    count(*)::bigint,
    round(avg(m.full_time_home_goals + m.full_time_away_goals)::numeric, 2),
    round(avg(m.full_time_home_goals)::numeric, 2),
    round(avg(m.full_time_away_goals)::numeric, 2),
    round(100.0 * avg(case when m.full_time_result = 'H' then 1 else 0 end)::numeric, 1),
    round(100.0 * avg(case when m.full_time_result = 'D' then 1 else 0 end)::numeric, 1),
    round(100.0 * avg(case when m.full_time_result = 'A' then 1 else 0 end)::numeric, 1),
    -- Cards are stored as 0 where the source has none: a division-season
    -- without a single card has no card data and returns null.
    round((case when max(m.home_yellow_cards + m.away_yellow_cards + m.home_red_cards + m.away_red_cards) > 0
      then avg(m.home_yellow_cards + m.away_yellow_cards) end)::numeric, 2),
    round((case when max(m.home_yellow_cards + m.away_yellow_cards + m.home_red_cards + m.away_red_cards) > 0
      then avg(m.home_red_cards + m.away_red_cards) end)::numeric, 3),
    round(100.0 * avg(case when m.full_time_home_goals + m.full_time_away_goals > 2.5 then 1 else 0 end)::numeric, 1),
    round(100.0 * avg(case when m.full_time_home_goals > 0 and m.full_time_away_goals > 0 then 1 else 0 end)::numeric, 1),
    round(100.0 * avg(case when m.full_time_home_goals = 0 and m.full_time_away_goals = 0 then 1 else 0 end)::numeric, 1),
    -- Share of matches where the side leading at half time did not win.
    -- Null half-time data is excluded from the denominator rather than
    -- counted as "no comeback", which would understate it.
    round(100.0 * (
      count(*) filter (
        where m.half_time_result is not null and m.half_time_result <> 'D'
          and m.half_time_result <> m.full_time_result
      )::numeric
      / nullif(count(*) filter (where m.half_time_result is not null and m.half_time_result <> 'D'), 0)
    ), 1)
  from public.matches m
  join public.leagues l on l.league_id = m.league_id
  join public.seasons s on s.season_id = m.season_id
  where l.code in ('E0', 'E1', 'E2', 'E3', 'EC')
    and m.full_time_result is not null
  group by l.code, l.league_id, s.season_id, s.label
  having count(*) >= 100
  order by l.code, min(s.start_year);
$$;


ALTER FUNCTION public.get_cross_league_summary() OWNER TO postgres;

--
-- Name: get_daily_digest(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_daily_digest(p_season_id bigint DEFAULT public.fpl_current_season_id()) RETURNS TABLE(change_type text, fpl_player_id bigint, web_name text, slug text, team_name text, position_label text, ownership numeric, old_value text, new_value text, detail text, from_date date, to_date date)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with dates as (
    select max(snapshot_date) as to_d,
           (select max(snapshot_date) from public.fpl_player_snapshots
            where season_id = p_season_id
              and snapshot_date < (select max(snapshot_date) from public.fpl_player_snapshots where season_id = p_season_id)) as from_d
    from public.fpl_player_snapshots
    where season_id = p_season_id
  ),
  cur as (
    select s.* from public.fpl_player_snapshots s, dates d where s.snapshot_date = d.to_d
  ),
  prev as (
    select s.* from public.fpl_player_snapshots s, dates d where s.snapshot_date = d.from_d
  ),
  joined as (
    select c.fpl_player_id, c.now_cost as c_cost, p.now_cost as p_cost,
      c.selected_by_percent as c_own, p.selected_by_percent as p_own,
      c.status as c_status, p.status as p_status, c.news as c_news,
      pl.web_name, pl.slug, pl.element_type, t.display_name as team_name
    from cur c
    join prev p on p.fpl_player_id = c.fpl_player_id and p.season_id = c.season_id
    join public.fpl_players pl on pl.fpl_player_id = c.fpl_player_id and pl.season_id = c.season_id
    left join public.teams t on t.team_id = pl.canonical_team_id
    where pl.web_name is not null
  ),
  labelled as (
    select j.*,
      case j.element_type when 1 then 'GKP' when 2 then 'DEF' when 3 then 'MID' when 4 then 'FWD' else '?' end as pos
    from joined j
  )
  select 'price_rise', fpl_player_id, web_name, slug, team_name, pos,
    round(c_own::numeric, 1),
    '£' || round(p_cost / 10.0, 1)::text || 'm', '£' || round(c_cost / 10.0, 1)::text || 'm',
    null, (select from_d from dates), (select to_d from dates)
  from labelled where c_cost > p_cost

  union all
  select 'price_fall', fpl_player_id, web_name, slug, team_name, pos,
    round(c_own::numeric, 1),
    '£' || round(p_cost / 10.0, 1)::text || 'm', '£' || round(c_cost / 10.0, 1)::text || 'm',
    null, (select from_d from dates), (select to_d from dates)
  from labelled where c_cost < p_cost

  union all
  -- Availability changes are the ones people most want pushed at them,
  -- and the only category where the direction of travel matters more
  -- than the magnitude.
  select 'availability', fpl_player_id, web_name, slug, team_name, pos,
    round(c_own::numeric, 1), p_status, c_status, nullif(c_news, ''),
    (select from_d from dates), (select to_d from dates)
  from labelled where c_status is distinct from p_status

  union all
  select 'ownership', fpl_player_id, web_name, slug, team_name, pos,
    round(c_own::numeric, 1),
    round(p_own::numeric, 1)::text || '%', round(c_own::numeric, 1)::text || '%',
    null, (select from_d from dates), (select to_d from dates)
  from labelled
  where abs(c_own::numeric - p_own::numeric) >= 0.5

  order by 7 desc nulls last;
$$;


ALTER FUNCTION public.get_daily_digest(p_season_id bigint) OWNER TO postgres;

