--
-- Name: get_market_efficiency(text, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_market_efficiency(p_bookmaker text DEFAULT 'Avg'::text, p_closing boolean DEFAULT true) RETURNS TABLE(league_code text, league_name text, market text, matches bigint, overround numeric, roi_favourite numeric, roi_outsider numeric, roi_home numeric, roi_draw numeric, roi_away numeric)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with q as (
    select l.code, l.name, o.market, m.league_id, m.season_id,
      o.price_home, o.price_draw, o.price_away,
      m.full_time_result res
    from public.match_odds o
    join public.matches m on m.match_id = o.match_id
    join public.leagues l on l.league_id = m.league_id
    where o.market = '1x2'
      and o.bookmaker = p_bookmaker
      and o.is_closing = p_closing
      and o.price_home is not null and o.price_draw is not null and o.price_away is not null
      and m.full_time_result is not null
  ),
  tagged as (
    select *,
      -- Favourite/outsider by price, which is how the market itself
      -- ranks them -- not by home/away, which confounds the two.
      least(price_home, price_draw, price_away) as fav_price,
      greatest(price_home, price_draw, price_away) as dog_price,
      case
        when price_home <= price_draw and price_home <= price_away then 'H'
        when price_away <= price_home and price_away <= price_draw then 'A'
        else 'D'
      end as fav_outcome,
      case
        when price_home >= price_draw and price_home >= price_away then 'H'
        when price_away >= price_home and price_away >= price_draw then 'A'
        else 'D'
      end as dog_outcome
    from q
  )
  select code,
    -- The division's name(s) over the seasons pooled here, oldest first.
    (select string_agg(e.era_name, ' / ' order by e.first_year)
       from (select public.league_name_for_season(x.league_id, x.season_id) era_name, min(s.start_year) first_year
               from (select distinct t2.league_id, t2.season_id from tagged t2 where t2.code = tagged.code) x
               join public.seasons s on s.season_id = x.season_id
              group by 1) e),
    market, count(*)::bigint,
    round(avg(1/price_home + 1/price_draw + 1/price_away)::numeric, 4),
    round(100 * (sum(case when res = fav_outcome then fav_price - 1 else -1 end) / count(*))::numeric, 2),
    round(100 * (sum(case when res = dog_outcome then dog_price - 1 else -1 end) / count(*))::numeric, 2),
    round(100 * (sum(case when res = 'H' then price_home - 1 else -1 end) / count(*))::numeric, 2),
    round(100 * (sum(case when res = 'D' then price_draw - 1 else -1 end) / count(*))::numeric, 2),
    round(100 * (sum(case when res = 'A' then price_away - 1 else -1 end) / count(*))::numeric, 2)
  from tagged
  group by code, name, market
  order by code;
$$;


ALTER FUNCTION public.get_market_efficiency(p_bookmaker text, p_closing boolean) OWNER TO postgres;

--
-- Name: get_matchweek_head_to_head(bigint, bigint, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_matchweek_head_to_head(p_league_id bigint, p_season_id bigint, p_matchweek integer DEFAULT NULL::integer) RETURNS TABLE(fixture_id bigint, meetings bigint, home_wins bigint, draws bigint, away_wins bigint, last_meeting_date date, last_home_goals integer, last_away_goals integer, last_home_was_fixture_home boolean)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with fx as (
    select f.fixture_id, f.home_team_id as fx_home, f.away_team_id as fx_away
    from public.fixtures f
    where f.league_id = p_league_id
      and f.season_id = p_season_id
      and (p_matchweek is null or f.matchweek = p_matchweek)
  ),
  met as (
    select fx.fixture_id, fx.fx_home, fx.fx_away,
      m.home_team_id as m_home, m.full_time_result as res,
      m.match_date, m.full_time_home_goals as hg, m.full_time_away_goals as ag
    from fx
    join public.matches m
      on (m.home_team_id = fx.fx_home and m.away_team_id = fx.fx_away)
      or (m.home_team_id = fx.fx_away and m.away_team_id = fx.fx_home)
    where m.full_time_result is not null
  ),
  agg as (
    select fixture_id,
      count(*)::bigint as meetings,
      count(*) filter (where (m_home = fx_home and res = 'H') or (m_home = fx_away and res = 'A'))::bigint as home_wins,
      count(*) filter (where res = 'D')::bigint as draws,
      count(*) filter (where (m_home = fx_away and res = 'H') or (m_home = fx_home and res = 'A'))::bigint as away_wins
    from met group by fixture_id
  ),
  latest as (
    select distinct on (fixture_id) fixture_id, match_date, hg, ag, (m_home = fx_home) as home_was_home
    from met order by fixture_id, match_date desc
  )
  select a.fixture_id, a.meetings, a.home_wins, a.draws, a.away_wins,
         l.match_date, l.hg, l.ag, l.home_was_home
  from agg a left join latest l on l.fixture_id = a.fixture_id;
$$;


ALTER FUNCTION public.get_matchweek_head_to_head(p_league_id bigint, p_season_id bigint, p_matchweek integer) OWNER TO postgres;

--
-- Name: get_model_accuracy(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_model_accuracy(p_league_id bigint DEFAULT NULL::bigint) RETURNS TABLE(fixture_id bigint, league_code text, kickoff_date date, home_team text, away_team text, p_home numeric, p_draw numeric, p_away numeric, picked text, actual text, correct boolean, p_actual numeric, brier numeric)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select
    f.fixture_id, l.code, f.kickoff_date,
    ht.display_name, at2.display_name,
    dm.home_win, dm.draw, dm.away_win,
    case when dm.home_win >= dm.draw and dm.home_win >= dm.away_win then 'H'
         when dm.draw    >= dm.away_win then 'D' else 'A' end,
    m.full_time_result,
    (case when dm.home_win >= dm.draw and dm.home_win >= dm.away_win then 'H'
          when dm.draw    >= dm.away_win then 'D' else 'A' end) = m.full_time_result,
    round(case m.full_time_result when 'H' then dm.home_win when 'D' then dm.draw else dm.away_win end, 2),
    round(
      power(dm.home_win/100 - (case when m.full_time_result='H' then 1 else 0 end), 2)
    + power(dm.draw    /100 - (case when m.full_time_result='D' then 1 else 0 end), 2)
    + power(dm.away_win/100 - (case when m.full_time_result='A' then 1 else 0 end), 2)
    , 4)
  from public.fixtures f
  join public.model_fit_runs r on r.fit_run_id = f.prediction_fit_run_id
  join public.leagues l on l.league_id = f.league_id
  join public.teams ht on ht.team_id = f.home_team_id
  join public.teams at2 on at2.team_id = f.away_team_id
  -- No FK between fixtures and matches; joined on the natural key, as
  -- documented in the project notes.
  join public.matches m on m.league_id = f.league_id and m.season_id = f.season_id
    and m.home_team_id = f.home_team_id and m.away_team_id = f.away_team_id
    and m.match_date = f.kickoff_date
  cross join lateral public.fixture_derived_markets(
    f.predicted_home_goals::numeric, f.predicted_away_goals::numeric, r.rho::numeric) dm
  where f.status = 'played'
    and f.predicted_home_goals is not null
    and r.rho is not null
    and m.full_time_result is not null
    and (p_league_id is null or f.league_id = p_league_id)
  order by f.kickoff_date desc;
$$;


ALTER FUNCTION public.get_model_accuracy(p_league_id bigint) OWNER TO postgres;

--
-- Name: get_model_accuracy_summary(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_model_accuracy_summary(p_league_id bigint DEFAULT NULL::bigint) RETURNS TABLE(fixtures integer, correct integer, hit_rate numeric, always_home_hit_rate numeric, model_brier numeric, uniform_brier numeric, mean_p_actual numeric)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with a as (select * from public.get_model_accuracy(p_league_id))
  select
    count(*)::int,
    count(*) filter (where correct)::int,
    round(100.0 * count(*) filter (where correct) / nullif(count(*),0), 1),
    -- Baseline 1: always pick the home team. Home advantage alone is a
    -- surprisingly strong predictor, so beating it is the real bar.
    round(100.0 * count(*) filter (where actual = 'H') / nullif(count(*),0), 1),
    round(avg(brier), 4),
    -- Baseline 2: a model that always says 33.3/33.3/33.3 scores 0.6667.
    0.6667,
    round(avg(p_actual), 1)
  from a;
$$;


ALTER FUNCTION public.get_model_accuracy_summary(p_league_id bigint) OWNER TO postgres;

--
-- Name: get_model_calibration(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_model_calibration(p_league_id bigint DEFAULT NULL::bigint) RETURNS TABLE(band text, forecasts integer, mean_predicted numeric, actual_rate numeric, gap numeric)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with forecasts as (
    select unnest(array[a.p_home, a.p_draw, a.p_away]) as p,
           unnest(array[
             (a.actual = 'H')::int, (a.actual = 'D')::int, (a.actual = 'A')::int
           ]) as hit
    from public.get_model_accuracy(p_league_id) a
  ),
  banded as (
    select case
      when p < 10 then '0-10'   when p < 20 then '10-20'
      when p < 30 then '20-30'  when p < 40 then '30-40'
      when p < 50 then '40-50'  when p < 60 then '50-60'
      else '60+' end as band,
      p, hit
    from forecasts
  )
  select band, count(*)::int, round(avg(p),1), round(100.0*sum(hit)/count(*),1),
         round(100.0*sum(hit)/count(*) - avg(p), 1)
  from banded group by band
  order by case band when '0-10' then 1 when '10-20' then 2 when '20-30' then 3
                     when '30-40' then 4 when '40-50' then 5 when '50-60' then 6 else 7 end;
$$;


ALTER FUNCTION public.get_model_calibration(p_league_id bigint) OWNER TO postgres;

--
-- Name: get_model_scorecard(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_model_scorecard() RETURNS TABLE(league_id bigint, season_id bigint, team_type text, phase text, n bigint, ll_model numeric, ll_market numeric, brier_model numeric, brier_market numeric, p_draw numeric, m_draw numeric, draws bigint, pred_goals numeric, goals bigint)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select s.league_id, s.season_id, s.team_type, s.phase, count(*),
    sum(-ln(case s.result when 'H' then s.p_home when 'D' then s.p_draw else s.p_away end)),
    sum(-ln(case s.result when 'H' then s.m_home when 'D' then s.m_draw else s.m_away end)),
    sum((s.p_home - (s.result = 'H')::int)^2 + (s.p_draw - (s.result = 'D')::int)^2 + (s.p_away - (s.result = 'A')::int)^2),
    sum((s.m_home - (s.result = 'H')::int)^2 + (s.m_draw - (s.result = 'D')::int)^2 + (s.m_away - (s.result = 'A')::int)^2),
    sum(s.p_draw), sum(s.m_draw), count(*) filter (where s.result = 'D'),
    sum(s.lh + s.la), sum(s.hg + s.ag)
  from public.model_scorecard_matches s
  group by 1, 2, 3, 4;
$$;


ALTER FUNCTION public.get_model_scorecard() OWNER TO postgres;

--
-- Name: get_model_scorecard_calibration(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_model_scorecard_calibration() RETURNS TABLE(league_id bigint, season_id bigint, outcome text, bin integer, n bigint, predicted numeric, happened bigint)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  with o as (
    select s.league_id, s.season_id, 'Home'::text outcome, s.p_home p, (s.result = 'H') hit from public.model_scorecard_matches s
    union all select s.league_id, s.season_id, 'Draw', s.p_draw, s.result = 'D' from public.model_scorecard_matches s
    union all select s.league_id, s.season_id, 'Away', s.p_away, s.result = 'A' from public.model_scorecard_matches s)
  select o.league_id, o.season_id, o.outcome, least(9, floor(o.p * 10))::int, count(*), sum(o.p), count(*) filter (where o.hit)
  from o group by 1, 2, 3, 4;
$$;


ALTER FUNCTION public.get_model_scorecard_calibration() OWNER TO postgres;

--
-- Name: get_model_xi_history(bigint, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_model_xi_history(p_season_id bigint DEFAULT public.fpl_current_season_id(), p_league_id bigint DEFAULT 1) RETURNS TABLE(fpl_event_id integer, actual_xi_points integer, model_xi_actual_points integer, model_xi_projected numeric, overlap_count integer, players_projected integer, generated_before_deadline boolean, deadline_time timestamp with time zone)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with weeks as (
    select gw.fpl_event_id as e, gw.deadline_time
    from public.fpl_gameweeks gw
    where gw.season_id = p_season_id and gw.finished and gw.data_checked
  ),
  cover as (
    select f.matchweek as e,
           count(distinct pr.fpl_player_id)::int as players_projected,
           min(pr.generated_at) as first_generated
    from public.fpl_player_projections pr
    join public.fixtures f on f.fixture_id = pr.fixture_id
    where f.season_id = p_season_id and f.league_id = p_league_id
      and pr.model_version = 'leaguewide_v6' and pr.scenario_key = 'baseline'
    group by f.matchweek
  )
  select w.e::integer, t.actual_xi_points, t.model_xi_actual_points, t.model_xi_projected,
         t.overlap_count, c.players_projected,
         (c.first_generated < w.deadline_time) as generated_before_deadline,
         w.deadline_time
  from weeks w
  join cover c on c.e = w.e
  cross join lateral public.get_totw_vs_model(w.e::int, p_season_id) t
  where c.players_projected > 0
  order by w.e;
$$;


ALTER FUNCTION public.get_model_xi_history(p_season_id bigint, p_league_id bigint) OWNER TO postgres;

--
-- Name: get_model_xi_players(integer, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_model_xi_players(p_event_id integer, p_season_id bigint DEFAULT public.fpl_current_season_id()) RETURNS TABLE(fpl_player_id bigint, web_name text, team_name text, position_label text, element_type integer, projected_points numeric, actual_points integer, minutes integer, in_perfect_xi boolean)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with proj as (
    select pr.fpl_player_id, p.element_type, p.web_name,
      sum(pr.expected_fpl_points) as proj_pts,
      row_number() over (partition by p.element_type order by sum(pr.expected_fpl_points) desc) as rn
    from public.fpl_player_projections pr
    join public.fixtures f on f.fixture_id = pr.fixture_id
    join public.fpl_players p on p.fpl_player_id = pr.fpl_player_id and p.season_id = p_season_id
    where pr.model_version = 'leaguewide_v6' and pr.scenario_key = 'baseline'
      and f.season_id = p_season_id and f.matchweek = p_event_id
    group by pr.fpl_player_id, p.element_type, p.web_name
  ),
  model_xi as (
    select * from proj
    where (element_type=1 and rn<=1) or (element_type=2 and rn<=3)
       or (element_type=3 and rn<=3) or (element_type=4 and rn<=1)
    union all
    select * from (
      select * from proj
      where (element_type=2 and rn between 4 and 5) or (element_type=3 and rn between 4 and 5)
         or (element_type=4 and rn between 2 and 3)
      order by proj_pts desc limit 3
    ) rest
  ),
  totw as (select fpl_player_id from public.get_team_of_the_week(p_event_id, p_season_id))
  select mx.fpl_player_id::bigint,
         mx.web_name,
         coalesce(t.name, '')::text as team_name,
         (case mx.element_type when 1 then 'GK' when 2 then 'DEF' when 3 then 'MID' else 'FWD' end)::text,
         mx.element_type,
         round(mx.proj_pts, 1) as projected_points,
         coalesce(g.total_points, 0)::integer as actual_points,
         coalesce(g.minutes, 0)::integer as minutes,
         (mx.fpl_player_id in (select fpl_player_id from totw)) as in_perfect_xi
  from model_xi mx
  left join public.fpl_players p on p.fpl_player_id = mx.fpl_player_id and p.season_id = p_season_id
  left join public.fpl_teams t on t.fpl_team_id = p.fpl_team_id and t.season_id = p_season_id
  left join public.fpl_player_gameweeks g
    on g.fpl_player_id = mx.fpl_player_id and g.season_id = p_season_id and g.fpl_event_id = p_event_id
  order by mx.element_type, mx.proj_pts desc;
$$;


ALTER FUNCTION public.get_model_xi_players(p_event_id integer, p_season_id bigint) OWNER TO postgres;

--
-- Name: get_most_common_scoreline(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_most_common_scoreline(p_league_id bigint) RETURNS TABLE(home_goals integer, away_goals integer, occurrences bigint, total_matches bigint, seasons_covered bigint)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with counts as (
    select full_time_home_goals, full_time_away_goals, count(*) as occurrences
    from public.matches
    where league_id = p_league_id
    group by full_time_home_goals, full_time_away_goals
  ), total as (
    select count(*) as total_matches, count(distinct season_id) as seasons_covered
    from public.matches where league_id = p_league_id
  )
  select c.full_time_home_goals, c.full_time_away_goals, c.occurrences, t.total_matches, t.seasons_covered
  from counts c, total t
  order by c.occurrences desc
  limit 4;
$$;


ALTER FUNCTION public.get_most_common_scoreline(p_league_id bigint) OWNER TO postgres;

--
-- Name: get_overround_trend(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_overround_trend(p_bookmaker text DEFAULT 'Avg'::text) RETURNS TABLE(season_label text, league_code text, matches bigint, overround numeric)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select s.label, l.code, count(*)::bigint,
    round(avg(1/o.price_home + 1/o.price_draw + 1/o.price_away)::numeric, 4)
  from public.match_odds o
  join public.matches m on m.match_id = o.match_id
  join public.seasons s on s.season_id = m.season_id
  join public.leagues l on l.league_id = m.league_id
  where o.market = '1x2'
    and o.bookmaker = p_bookmaker
    and o.is_closing
    and o.price_home is not null and o.price_draw is not null and o.price_away is not null
  group by s.label, l.code
  -- A part-played season or a thin division reads as a spike otherwise.
  having count(*) >= 100
  order by min(s.start_year), l.code;
$$;


ALTER FUNCTION public.get_overround_trend(p_bookmaker text) OWNER TO postgres;

--
-- Name: get_player_by_slug(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_player_by_slug(p_slug text) RETURNS TABLE(fpl_code bigint, slug text, canonical_name text, latest_web_name text, latest_team text, element_type integer, seasons_played bigint, career_points bigint, career_minutes bigint, first_season text, last_season text, current_slug text, current_fpl_player_id bigint, current_total_points integer, current_minutes integer, current_goals integer, current_assists integer, current_bonus integer, current_now_cost integer)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select i.fpl_code, i.slug, i.canonical_name,
    (array_agg(t.web_name order by public.season_start_year(t.season_id) desc))[1],
    (array_agg(t.team_name order by public.season_start_year(t.season_id) desc))[1],
    (array_agg(t.element_type order by public.season_start_year(t.season_id) desc))[1],
    count(t.season_id)::bigint,
    coalesce(sum(t.total_points), 0)::bigint,
    coalesce(sum(t.minutes), 0)::bigint,
    fs.slug, ls.slug,
    cur.slug,
    cur.fpl_player_id::bigint,
    cur.total_points, cur.minutes, cur.goals_scored, cur.assists, cur.bonus, cur.now_cost
  from public.player_identity i
  left join public.fpl_player_season_totals t on t.fpl_code = i.fpl_code
  left join public.seasons fs on fs.season_id = i.first_seen_season_id
  left join public.seasons ls on ls.season_id = i.last_seen_season_id
  -- Current squad only. A player who has left has no row here, and every
  -- current_* column comes back null.
  left join public.fpl_players cur on cur.fpl_code = i.fpl_code and cur.season_id = (SELECT public.fpl_current_season_id())
  where i.slug = p_slug
  group by i.fpl_code, i.slug, i.canonical_name, fs.slug, ls.slug,
    cur.slug, cur.fpl_player_id, cur.total_points, cur.minutes,
    cur.goals_scored, cur.assists, cur.bonus, cur.now_cost;
$$;


ALTER FUNCTION public.get_player_by_slug(p_slug text) OWNER TO postgres;

--
-- Name: get_player_career(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_player_career(p_fpl_code bigint) RETURNS TABLE(season_id bigint, season_slug text, web_name text, team_name text, element_type integer, start_cost integer, end_cost integer, total_points integer, minutes integer, goals_scored integer, assists integer, clean_sheets integer, bonus integer, points_per_start_million numeric, points_early integer, points_mid integer, points_late integer)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select t.season_id, s.slug, t.web_name, t.team_name, t.element_type,
    t.start_cost, t.end_cost, t.total_points, t.minutes,
    t.goals_scored, t.assists, t.clean_sheets, t.bonus,
    case when t.start_cost > 0
         then round((t.total_points / (t.start_cost / 10.0))::numeric, 2) end,
    h.early, h.mid, h.late
  from public.fpl_player_season_totals t
  join public.seasons s on s.season_id = t.season_id
  left join lateral (
    select sum(g.total_points) filter (where g.gameweek <= 13)::int early,
           sum(g.total_points) filter (where g.gameweek between 14 and 26)::int mid,
           sum(g.total_points) filter (where g.gameweek >= 27)::int late
    from public.fpl_player_gameweek_history g
    where g.season_id = t.season_id and g.fpl_code = t.fpl_code
  ) h on true
  where t.fpl_code = p_fpl_code
  order by s.start_year desc;
$$;


ALTER FUNCTION public.get_player_career(p_fpl_code bigint) OWNER TO postgres;

--
-- Name: get_player_gameweek_breakdown(bigint, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_player_gameweek_breakdown(p_fpl_player_id bigint, p_season_id bigint DEFAULT public.fpl_current_season_id()) RETURNS TABLE(gameweek integer, opponent text, was_home boolean, kickoff_date date, minutes integer, total_points integer, goals_scored integer, assists integer, clean_sheets integer, goals_conceded integer, bonus integer, bps integer, saves integer, yellow_cards integer, red_cards integer, own_goals integer, penalties_missed integer, penalties_saved integer, defensive_contribution integer, projected_points numeric)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select
    g.fpl_event_id::integer,
    opp.display_name,
    case when ff.fpl_home_team_id = p.fpl_team_id then true else false end,
    f.kickoff_date,
    g.minutes, g.total_points, g.goals_scored, g.assists, g.clean_sheets,
    g.goals_conceded, g.bonus, g.bps, g.saves, g.yellow_cards, g.red_cards,
    g.own_goals, g.penalties_missed, g.penalties_saved,
    coalesce((g.source_payload->'stats'->>'defensive_contribution')::int, 0),
    (
      select round(pr.expected_fpl_points::numeric, 1)
      from public.fpl_player_projections pr
      where pr.fixture_id = f.fixture_id
        and pr.fpl_player_id = g.fpl_player_id
        and pr.model_version = 'leaguewide_v6'
        and pr.generated_at < (f.kickoff_date::timestamp + coalesce(f.kickoff_time, '00:00:00'::time)::interval)
      order by pr.generated_at desc
      limit 1
    )
  from public.fpl_player_gameweeks g
  join public.fpl_players p
    on p.fpl_player_id = g.fpl_player_id and p.season_id = g.season_id
  join public.fpl_fixtures ff
    on ff.fpl_fixture_id = g.fpl_fixture_id and ff.season_id = g.season_id
  left join public.fixtures f on f.fixture_id = ff.canonical_fixture_id
  left join public.fpl_teams oppt
    on oppt.fpl_team_id = case when ff.fpl_home_team_id = p.fpl_team_id
                               then ff.fpl_away_team_id else ff.fpl_home_team_id end
   and oppt.season_id = g.season_id
  left join public.teams opp on opp.team_id = oppt.canonical_team_id
  where g.fpl_player_id = p_fpl_player_id and g.season_id = p_season_id
  order by g.fpl_event_id;
$$;


ALTER FUNCTION public.get_player_gameweek_breakdown(p_fpl_player_id bigint, p_season_id bigint) OWNER TO postgres;

--
-- Name: get_player_season_gameweeks(bigint, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_player_season_gameweeks(p_fpl_code bigint, p_season_id bigint) RETURNS TABLE(gameweek integer, opponent text, was_home boolean, minutes integer, total_points integer, goals_scored integer, assists integer, clean_sheets integer, goals_conceded integer, bonus integer, saves integer, yellow_cards integer, red_cards integer, own_goals integer, penalties_missed integer, penalties_saved integer, defensive_contribution integer, price integer)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select
    g.fpl_event_id::integer, opp.display_name,
    case when ff.fpl_home_team_id = p.fpl_team_id then true else false end,
    g.minutes, g.total_points, g.goals_scored, g.assists, g.clean_sheets,
    g.goals_conceded, g.bonus, g.saves, g.yellow_cards, g.red_cards,
    g.own_goals, g.penalties_missed, g.penalties_saved,
    coalesce((g.source_payload->'stats'->>'defensive_contribution')::int, 0),
    null::int
  from public.fpl_players p
  join public.fpl_player_gameweeks g
    on g.fpl_player_id = p.fpl_player_id and g.season_id = p.season_id
  join public.fpl_fixtures ff
    on ff.fpl_fixture_id = g.fpl_fixture_id and ff.season_id = g.season_id
  left join public.fpl_teams oppt
    on oppt.fpl_team_id = case when ff.fpl_home_team_id = p.fpl_team_id
                               then ff.fpl_away_team_id else ff.fpl_home_team_id end
   and oppt.season_id = g.season_id
  left join public.teams opp on opp.team_id = oppt.canonical_team_id
  where p.fpl_code = p_fpl_code and p.season_id = p_season_id

  union all

  select
    h.gameweek, null::text, h.was_home,
    h.minutes, h.total_points, h.goals_scored, h.assists, h.clean_sheets,
    h.goals_conceded, h.bonus, h.saves, h.yellow_cards, h.red_cards,
    0, 0, 0, 0, h.value
  from public.fpl_player_gameweek_history h
  where h.fpl_code = p_fpl_code and h.season_id = p_season_id

  order by 1;
$$;


ALTER FUNCTION public.get_player_season_gameweeks(p_fpl_code bigint, p_season_id bigint) OWNER TO postgres;

--
-- Name: get_player_seasons(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_player_seasons(p_fpl_code bigint) RETURNS TABLE(season_id bigint, season_slug text, total_points integer, is_current boolean)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select distinct on (s.start_year) x.season_id, s.slug, x.total_points, (x.season_id = (SELECT public.fpl_current_season_id()))
  from (
    select t.season_id, t.total_points from public.fpl_player_season_totals t where t.fpl_code = p_fpl_code
    union all
    select p.season_id, p.total_points from public.fpl_players p
      where p.fpl_code = p_fpl_code and p.season_id = (SELECT public.fpl_current_season_id())
  ) x
  join public.seasons s on s.season_id = x.season_id
  order by s.start_year desc;
$$;


ALTER FUNCTION public.get_player_seasons(p_fpl_code bigint) OWNER TO postgres;

--
-- Name: get_price_change_risk(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_price_change_risk(p_season_id bigint DEFAULT public.fpl_current_season_id()) RETURNS TABLE(fpl_player_id bigint, web_name text, slug text, team_name text, position_label text, price numeric, ownership numeric, transfers_in integer, transfers_out integer, net_transfers integer, pressure numeric, direction text)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with latest as (
    select max(snapshot_date) as d from public.fpl_player_snapshots where season_id = p_season_id
  ),
  snap as (
    select s.* from public.fpl_player_snapshots s
    join latest l on s.snapshot_date = l.d
  ),
  -- Total squads is unknown, so ownership share stands in for the owner
  -- base. Any constant scale factor cancels when players are compared
  -- with each other, which is all this ranking needs.
  calc as (
    select sn.*,
      coalesce(sn.transfers_in_event, 0) - coalesce(sn.transfers_out_event, 0) as net,
      greatest(sn.selected_by_percent::numeric, 0.1) as owned
    from snap sn
  )
  select
    p.fpl_player_id, p.web_name, p.slug, t.display_name,
    case p.element_type when 1 then 'GKP' when 2 then 'DEF' when 3 then 'MID' when 4 then 'FWD' else '?' end,
    round(c.now_cost / 10.0, 1),
    round(c.selected_by_percent::numeric, 1),
    coalesce(c.transfers_in_event, 0),
    coalesce(c.transfers_out_event, 0),
    c.net::integer,
    round((c.net / c.owned / 1000.0)::numeric, 2),
    case when c.net > 0 then 'rise' when c.net < 0 then 'fall' else 'steady' end
  from calc c
  join public.fpl_players p on p.fpl_player_id = c.fpl_player_id and p.season_id = c.season_id
  left join public.teams t on t.team_id = p.canonical_team_id
  where p.web_name is not null and c.net <> 0
  order by abs(c.net / c.owned) desc;
$$;


ALTER FUNCTION public.get_price_change_risk(p_season_id bigint) OWNER TO postgres;

--
-- Name: get_public_read_audit(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_public_read_audit() RETURNS TABLE(object_name text, object_kind text, rls_enabled boolean, has_select_policy boolean, anon_has_select_grant boolean, anon_can_read boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
begin
  perform public._require_admin();
  return query select * from public._get_public_read_audit_impl();
end;
$$;


ALTER FUNCTION public.get_public_read_audit() OWNER TO postgres;

--
-- Name: get_rolling_xi_candidates(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_rolling_xi_candidates(p_season_id bigint DEFAULT public.fpl_current_season_id()) RETURNS TABLE(fpl_code bigint, web_name text, team_name text, element_type integer, august_cost integer, now_cost integer, total_points integer, minutes integer)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select
    p.fpl_code, p.web_name, t.display_name, p.element_type,
    -- cost_change_start is the movement SINCE the season opened, so
    -- subtracting it recovers the opening price.
    (p.now_cost - coalesce((p.source_payload->>'cost_change_start')::int, 0)),
    p.now_cost, coalesce(p.total_points, 0), coalesce(p.minutes, 0)
  from public.fpl_players p
  left join public.teams t on t.team_id = p.canonical_team_id
  where p.season_id = p_season_id
    and p.now_cost is not null
    and p.element_type is not null
    -- A player who hasn't appeared can't be in a best XI, and including
    -- them only slows the solve.
    and coalesce(p.minutes, 0) > 0
  order by coalesce(p.total_points, 0) desc;
$$;


ALTER FUNCTION public.get_rolling_xi_candidates(p_season_id bigint) OWNER TO postgres;

--
-- Name: get_scout_vs_model(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_scout_vs_model() RETURNS TABLE(scored_fixtures bigint, scout_mae numeric, model_mae numeric, scout_better bigint, model_better bigint, ties bigint)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with played as (
    select f.fixture_id,
      f.predicted_home_goals ph, f.predicted_away_goals pa,
      f.raw_predicted_home_goals rh, f.raw_predicted_away_goals ra,
      m.full_time_home_goals gh, m.full_time_away_goals ga
    from public.fixtures f
    join public.matches m
      on m.league_id = f.league_id and m.season_id = f.season_id
     and m.home_team_id = f.home_team_id and m.away_team_id = f.away_team_id
     and m.match_date = f.kickoff_date
    where f.status = 'played'
      and f.predicted_home_goals is not null
      and f.raw_predicted_home_goals is not null
      and m.full_time_home_goals is not null
      -- Only where the adjustment bit.
      and (abs(f.raw_predicted_home_goals - f.predicted_home_goals) > 0.001
        or abs(f.raw_predicted_away_goals - f.predicted_away_goals) > 0.001)
  ),
  errs as (
    select
      (abs(ph - gh) + abs(pa - ga)) / 2 as scout_err,
      (abs(rh - gh) + abs(ra - ga)) / 2 as model_err
    from played
  )
  select
    count(*)::bigint,
    round(avg(scout_err)::numeric, 3),
    round(avg(model_err)::numeric, 3),
    count(*) filter (where scout_err < model_err)::bigint,
    count(*) filter (where model_err < scout_err)::bigint,
    count(*) filter (where abs(scout_err - model_err) < 1e-9)::bigint
  from errs;
$$;


ALTER FUNCTION public.get_scout_vs_model() OWNER TO postgres;

--
-- Name: get_season_player_projections_json(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_season_player_projections_json(p_matchweek integer) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
with target_fixtures as materialized (
  select fixture_id, matchweek, kickoff_date, home_team_id, away_team_id, predicted_home_goals, predicted_away_goals
  from public.fixtures
  where matchweek = p_matchweek and season_id = (SELECT public.fpl_current_season_id())
    and predicted_home_goals is not null and predicted_away_goals is not null
),
alloc as materialized (
  select a.*
  from public.fpl_projection_leaguewide_allocation_v2 a
  join target_fixtures tf on tf.fixture_id = a.fixture_id
),
dc as materialized (
  select d.*
  from public.fpl_defensive_contribution_projection_leaguewide d
  join target_fixtures tf on tf.fixture_id = d.fixture_id
),
bonus as materialized (
  select b.fixture_id, b.fpl_player_id, b.expected_bonus_points
  from public.fpl_fixture_bonus_montecarlo_v1 b
  join target_fixtures tf on tf.fixture_id = b.fixture_id
)
select jsonb_agg(row_to_json(t)) from (
  select alloc.fixture_id, tf.matchweek, tf.kickoff_date, alloc.team_id, p.web_name, alloc.fpl_player_id,
    alloc.element_type as fpl_position, alloc.real_tactical_role as tactical_role, alloc.expected_minutes,
    alloc.prob_starting_xi as start_probability, alloc.prob_sub_appearance as sub_appearance_probability,
    alloc.shrunk_xg90, alloc.shrunk_xa90, alloc.expected_goals, alloc.expected_assists,
    exp(-(case when alloc.team_id = tf.home_team_id then tf.predicted_away_goals else tf.predicted_home_goals end))::numeric as clean_sheet_probability,
    coalesce(dc.defensive_contribution_probability, 0) as defensive_contribution_probability,
    coalesce(bonus.expected_bonus_points, 0) as experimental_expected_bonus
  from alloc
  join target_fixtures tf on tf.fixture_id = alloc.fixture_id
  join public.fpl_players p on p.fpl_player_id = alloc.fpl_player_id and p.season_id = (SELECT public.fpl_current_season_id())
  left join dc on dc.fixture_id = alloc.fixture_id and dc.fpl_player_id = alloc.fpl_player_id
  left join bonus on bonus.fixture_id = alloc.fixture_id and bonus.fpl_player_id = alloc.fpl_player_id
) t;
$$;


ALTER FUNCTION public.get_season_player_projections_json(p_matchweek integer) OWNER TO postgres;

--
-- Name: get_set_piece_index(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_set_piece_index(p_season_id bigint DEFAULT public.fpl_current_season_id()) RETURNS TABLE(team_id bigint, team_name text, player_name text, duties integer, index_score numeric, detail text)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with weights as (
    -- Per-taker value, from opta_slot_breakdown. A share of goals is
    -- worth more than the same share of assists (6 points vs 3 for a
    -- midfielder), so goals carry double.
    select
      (select sum(goals_from_penalties)::numeric / nullif(sum(goals), 0) from public.opta_slot_breakdown) * 2 as w_pen,
      (select sum(goals_from_direct_fk)::numeric / nullif(sum(goals), 0) from public.opta_slot_breakdown) * 2
        + (select sum(assist_free_kick)::numeric / nullif(sum(assists), 0) from public.opta_slot_breakdown) as w_fk,
      (select sum(goals_from_corners)::numeric / nullif(sum(goals), 0) from public.opta_slot_breakdown) * 2
        + (select sum(assist_corner)::numeric / nullif(sum(assists), 0) from public.opta_slot_breakdown) as w_corner
  ),
  scored as (
    select h.team_id, h.player_name,
      case h.set_piece_type
        when 'penalty' then w.w_pen
        when 'direct_free_kick' then w.w_fk
        when 'corner_left' then w.w_corner / 2      -- one side only
        when 'corner_right' then w.w_corner / 2
        else 0
      end
      -- Rank decay: a second-choice taker only takes them when the
      -- first isn't on the pitch. Steeper than linear because a
      -- third-choice penalty taker almost never takes one.
      * (1.0 / h.rank)
      as value,
      h.set_piece_type, h.rank
    from public.set_piece_hierarchies h
    cross join weights w
    where h.season_id = p_season_id
      and (h.valid_to is null or h.valid_to > now())
      and h.set_piece_type <> 'indirect_free_kick'
  )
  select s.team_id, t.display_name, s.player_name,
    count(*)::integer,
    round(sum(s.value) * 100, 1),
    string_agg(
      replace(replace(s.set_piece_type, '_', ' '), 'direct free kick', 'free kicks') || ' #' || s.rank,
      ', ' order by s.value desc
    )
  from scored s
  join public.teams t on t.team_id = s.team_id
  group by s.team_id, t.display_name, s.player_name
  having sum(s.value) > 0
  order by sum(s.value) desc;
$$;


ALTER FUNCTION public.get_set_piece_index(p_season_id bigint) OWNER TO postgres;

--
-- Name: get_set_piece_takers(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_set_piece_takers(p_season_id bigint DEFAULT public.fpl_current_season_id()) RETURNS TABLE(team_id bigint, team_name text, team_slug text, set_piece_type text, player_name text, rank integer, confidence numeric, source_name text, updated_at timestamp with time zone)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select
    t.team_id, t.display_name, t.slug,
    h.set_piece_type, h.player_name, h.rank, h.confidence, h.source_name, h.updated_at
  from public.set_piece_hierarchies h
  join public.teams t on t.team_id = h.team_id
  where h.season_id = p_season_id
    and (h.valid_to is null or h.valid_to > now())
  order by t.display_name, h.set_piece_type, h.rank;
$$;


ALTER FUNCTION public.get_set_piece_takers(p_season_id bigint) OWNER TO postgres;

--
-- Name: get_strictest_referees(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_strictest_referees() RETURNS TABLE(referee text, red_cards bigint, matches bigint)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select m.referee, sum(m.home_red_cards + m.away_red_cards)::bigint, count(*)::bigint
  from public.matches m
  where m.referee is not null and m.home_red_cards is not null
  group by m.referee
  having count(*) >= 50
  order by 2 desc
  limit 4;
$$;


ALTER FUNCTION public.get_strictest_referees() OWNER TO postgres;

--
-- Name: get_tactical_role_worklist(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_tactical_role_worklist(p_season_id bigint DEFAULT public.fpl_current_season_id()) RETURNS TABLE(team_id bigint, team_name text, fpl_player_id bigint, web_name text, slug text, position_label text, assigned_role text, confidence numeric, minutes integer, ownership numeric, total_points integer, priority text)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with mins as (
    select g.fpl_player_id, sum(g.minutes)::integer as m, sum(g.total_points)::integer as pts
    from public.fpl_player_gameweeks g
    where g.season_id = p_season_id
    group by g.fpl_player_id
  ),
  latest_snap as (
    select distinct on (s.fpl_player_id) s.fpl_player_id, s.selected_by_percent
    from public.fpl_player_snapshots s
    where s.season_id = p_season_id
    order by s.fpl_player_id, s.snapshot_date desc
  )
  select
    d.team_id, t.display_name, d.fpl_player_id, p.web_name, p.slug,
    case p.element_type when 1 then 'GKP' when 2 then 'DEF' when 3 then 'MID' when 4 then 'FWD' else '?' end,
    d.tactical_role, d.confidence,
    coalesce(m.m, 0), round(coalesce(ls.selected_by_percent, 0)::numeric, 1), coalesce(m.pts, 0),
    case
      when coalesce(m.m, 0) >= 270 then 'starter'
      when coalesce(m.m, 0) >= 90 then 'rotation'
      else 'fringe'
    end
  from public.team_player_tactical_defaults d
  join public.fpl_players p on p.fpl_player_id = d.fpl_player_id and p.season_id = d.season_id
  left join public.teams t on t.team_id = d.team_id
  left join mins m on m.fpl_player_id = d.fpl_player_id
  left join latest_snap ls on ls.fpl_player_id = d.fpl_player_id
  where d.season_id = p_season_id
    and d.source_name = 'fpl_position_fallback'
    -- A keeper's position IS their role.
    and p.element_type <> 1
  order by coalesce(m.m, 0) desc, coalesce(ls.selected_by_percent, 0) desc;
$$;


ALTER FUNCTION public.get_tactical_role_worklist(p_season_id bigint) OWNER TO postgres;

--
-- Name: get_team_month_profile(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_team_month_profile(p_team_id bigint) RETURNS TABLE(month_num integer, month_label text, venue text, played integer, points integer, goals_for integer, goals_against integer, ppg numeric)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with res as (
    select extract(month from m.match_date)::int as mo, 'home'::text as v,
           m.full_time_home_goals as gf, m.full_time_away_goals as ga
    from public.matches m
    where m.home_team_id = p_team_id and m.league_id between 1 and 5 and m.full_time_home_goals is not null
    union all
    select extract(month from m.match_date)::int, 'away',
           m.full_time_away_goals, m.full_time_home_goals
    from public.matches m
    where m.away_team_id = p_team_id and m.league_id between 1 and 5 and m.full_time_home_goals is not null
  )
  select mo, to_char(make_date(2000, mo, 1), 'Mon'), v, count(*)::int,
    (3 * count(*) filter (where gf > ga) + count(*) filter (where gf = ga))::int,
    sum(gf)::int, sum(ga)::int,
    round((3 * count(*) filter (where gf > ga) + count(*) filter (where gf = ga))::numeric / count(*), 2)
  from res group by mo, v
  order by (mo + 5) % 12, v;
$$;


ALTER FUNCTION public.get_team_month_profile(p_team_id bigint) OWNER TO postgres;

--
-- Name: get_team_of_the_week(integer, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_team_of_the_week(p_event_id integer DEFAULT NULL::integer, p_season_id bigint DEFAULT public.fpl_current_season_id()) RETURNS TABLE(fpl_event_id integer, fpl_player_id bigint, web_name text, slug text, team_name text, position_label text, points integer, minutes integer, is_mandatory boolean, goals integer, assists integer, clean_sheets integer, bonus integer)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_event integer;
  v_historic boolean;
  excluded_ids bigint[] := '{}';
  offender bigint;
  guard int := 0;
begin
  select exists (select 1 from public.fpl_player_gameweek_history h where h.season_id = p_season_id)
    into v_historic;

  if v_historic then
    select coalesce(p_event_id, (
      select max(h.gameweek) from public.fpl_player_gameweek_history h where h.season_id = p_season_id
    )) into v_event;
  else
    select coalesce(p_event_id, (
      select max(f.fpl_event_id) from public.fpl_fixtures f
      where f.season_id = p_season_id
      group by f.fpl_event_id having bool_and(f.finished)
      order by max(f.fpl_event_id) desc limit 1
    )) into v_event;
  end if;

  if v_event is null then return; end if;

  loop
    guard := guard + 1;
    select k.pid into offender
    from (
      with src as (
        select h.fpl_code as pid, sum(h.total_points)::int pts, sum(h.minutes)::int mins,
               t.team_name tname, t.element_type
        from public.fpl_player_gameweek_history h
        join public.fpl_player_season_totals t on t.season_id = h.season_id and t.fpl_code = h.fpl_code
        where v_historic and h.season_id = p_season_id and h.gameweek = v_event
        group by h.fpl_code, t.team_name, t.element_type
        union all
        select g.fpl_player_id::bigint, g.total_points, g.minutes, tm.display_name, p.element_type
        from public.fpl_player_gameweeks g
        join public.fpl_players p on p.fpl_player_id = g.fpl_player_id and p.season_id = g.season_id
        left join public.teams tm on tm.team_id = p.canonical_team_id
        where not v_historic and g.season_id = p_season_id and g.fpl_event_id = v_event
          and g.total_points is not null
      ),
      ranked as (
        select *, row_number() over (partition by element_type order by pts desc, mins desc) rn
        from src where not (pid = any(excluded_ids))
      ),
      picked as (
        select * from ranked
        where (element_type=1 and rn<=1) or (element_type=2 and rn<=3)
           or (element_type=3 and rn<=3) or (element_type=4 and rn<=1)
        union all
        select * from (
          select * from ranked
          where (element_type=2 and rn between 4 and 5) or (element_type=3 and rn between 4 and 5)
             or (element_type=4 and rn between 2 and 3)
          order by pts desc, mins desc limit 3
        ) f
      )
      select pk.pid, pk.pts, pk.mins, count(*) over (partition by pk.tname) per_club from picked pk
    ) k
    where k.per_club > 3
    order by k.pts asc, k.mins asc limit 1;

    exit when offender is null or guard > 8;
    excluded_ids := excluded_ids || offender;
    offender := null;
  end loop;

  return query
  with src as (
    select h.fpl_code pid, sum(h.total_points)::int pts, sum(h.minutes)::int mins,
           sum(h.goals_scored)::int gls, sum(h.assists)::int ast,
           sum(h.clean_sheets)::int cs, sum(h.bonus)::int bns,
           t.web_name wn, null::text sl, t.team_name tname, t.element_type
    from public.fpl_player_gameweek_history h
    join public.fpl_player_season_totals t on t.season_id = h.season_id and t.fpl_code = h.fpl_code
    where v_historic and h.season_id = p_season_id and h.gameweek = v_event
    group by h.fpl_code, t.web_name, t.team_name, t.element_type
    union all
    select g.fpl_player_id::bigint, g.total_points, g.minutes,
           coalesce(g.goals_scored,0), coalesce(g.assists,0),
           coalesce(g.clean_sheets,0), coalesce(g.bonus,0),
           p.web_name, p.slug, tm.display_name, p.element_type
    from public.fpl_player_gameweeks g
    join public.fpl_players p on p.fpl_player_id = g.fpl_player_id and p.season_id = g.season_id
    left join public.teams tm on tm.team_id = p.canonical_team_id
    where not v_historic and g.season_id = p_season_id and g.fpl_event_id = v_event
      and g.total_points is not null
  ),
  ranked as (
    select *, row_number() over (partition by element_type order by pts desc, mins desc) rn
    from src where not (pid = any(excluded_ids))
  ),
  picked as (
    select *, true mand from ranked
    where (element_type=1 and rn<=1) or (element_type=2 and rn<=3)
       or (element_type=3 and rn<=3) or (element_type=4 and rn<=1)
    union all
    select * from (
      select *, false from ranked
      where (element_type=2 and rn between 4 and 5) or (element_type=3 and rn between 4 and 5)
         or (element_type=4 and rn between 2 and 3)
      order by pts desc, mins desc limit 3
    ) f
  )
  select v_event, k.pid, k.wn, k.sl, k.tname,
         case k.element_type when 1 then 'GKP' when 2 then 'DEF' when 3 then 'MID' when 4 then 'FWD' end,
         k.pts, k.mins, k.mand, k.gls, k.ast, k.cs, k.bns
  from picked k order by k.element_type, k.pts desc;
end $$;


ALTER FUNCTION public.get_team_of_the_week(p_event_id integer, p_season_id bigint) OWNER TO postgres;

