--
-- Name: get_totw_vs_model(integer, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_totw_vs_model(p_event_id integer DEFAULT NULL::integer, p_season_id bigint DEFAULT public.fpl_current_season_id()) RETURNS TABLE(fpl_event_id integer, actual_xi_points integer, model_xi_actual_points integer, overlap_count integer, model_xi_projected numeric, overlap_names text[])
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with totw as (
    select * from public.get_team_of_the_week(p_event_id, p_season_id)
  ),
  ev as (select coalesce(p_event_id, (select max(fpl_event_id) from totw)) as e),
  -- The model's preferred XI for the same gameweek, by projected points,
  -- under the same formation minimums.
  proj as (
    select pr.fpl_player_id, p.element_type,
      sum(pr.expected_fpl_points) as proj_pts,
      row_number() over (
        partition by p.element_type order by sum(pr.expected_fpl_points) desc
      ) as rn
    from public.fpl_player_projections pr
    join public.fixtures f on f.fixture_id = pr.fixture_id
    join public.fpl_players p on p.fpl_player_id = pr.fpl_player_id and p.season_id = f.season_id
    join ev on f.matchweek = ev.e
    where pr.model_version = 'leaguewide_v6' and pr.scenario_key = 'baseline'
      and f.season_id = p_season_id
    group by pr.fpl_player_id, p.element_type
  ),
  model_xi as (
    select * from (
      select *, true as mand from proj
      where (element_type=1 and rn<=1) or (element_type=2 and rn<=3)
         or (element_type=3 and rn<=3) or (element_type=4 and rn<=1)
      union all
      select * from (
        select *, false from proj
        where (element_type=2 and rn between 4 and 5) or (element_type=3 and rn between 4 and 5)
           or (element_type=4 and rn between 2 and 3)
        order by proj_pts desc limit 3
      ) f2
    ) m
  ),
  model_actual as (
    select mx.fpl_player_id, coalesce(g.total_points, 0) as pts, mx.proj_pts
    from model_xi mx
    left join public.fpl_player_gameweeks g
      on g.fpl_player_id = mx.fpl_player_id and g.season_id = p_season_id
     and g.fpl_event_id = (select e from ev)
  )
  select
    (select e from ev)::integer,
    (select sum(points)::integer from totw),
    (select sum(pts)::integer from model_actual),
    (select count(*)::integer from totw t where t.fpl_player_id in (select fpl_player_id from model_xi)),
    (select round(sum(proj_pts)::numeric, 1) from model_actual),
    (select array_agg(t.web_name order by t.points desc) from totw t where t.fpl_player_id in (select fpl_player_id from model_xi));
$$;


ALTER FUNCTION public.get_totw_vs_model(p_event_id integer, p_season_id bigint) OWNER TO postgres;

--
-- Name: get_unmapped_alias_names(text, text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_unmapped_alias_names(p_source text, p_raw_names text[]) RETURNS TABLE(raw_name text)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select rn from unnest(p_raw_names) as rn
  where not exists (
    select 1 from team_aliases ta where ta.source_name = p_source and ta.raw_name = rn
  )
  order by rn;
$$;


ALTER FUNCTION public.get_unmapped_alias_names(p_source text, p_raw_names text[]) OWNER TO postgres;

--
-- Name: get_xi_weekly_by_codes(bigint, bigint[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_xi_weekly_by_codes(p_season_id bigint, p_codes bigint[]) RETURNS TABLE(gameweek integer, total_points integer, players_returning integer, blanks integer)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with weekly as (
    -- completed seasons: the imported history, keyed by player code
    select h.gameweek, h.total_points, h.minutes
    from public.fpl_player_gameweek_history h
    where h.season_id = p_season_id and h.fpl_code = any(p_codes)
    union all
    -- the season in progress: live rows, mapped to codes through fpl_players
    select g.fpl_event_id as gameweek, g.total_points, g.minutes
    from public.fpl_player_gameweeks g
    join public.fpl_players p
      on p.fpl_player_id = g.fpl_player_id and p.season_id = g.season_id
    where g.season_id = p_season_id and p.fpl_code = any(p_codes)
  )
  select gameweek::integer,
         sum(total_points)::integer,
         count(*) filter (where minutes > 0)::integer,
         count(*) filter (where minutes = 0)::integer
  from weekly
  group by gameweek
  order by gameweek;
$$;


ALTER FUNCTION public.get_xi_weekly_by_codes(p_season_id bigint, p_codes bigint[]) OWNER TO postgres;

--
-- Name: handle_new_auth_user(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.handle_new_auth_user() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  v_is_admin boolean;
begin
  -- Case-insensitive: email providers treat the local part as
  -- case-insensitive in practice, and a capitalised sign-in silently
  -- failing to match would be a confusing way to lose admin.
  select exists (
    select 1 from public.admin_bootstrap_emails
    where lower(email) = lower(new.email)
  ) into v_is_admin;

  insert into public.app_users (user_id, email, is_admin)
  values (new.id, new.email, coalesce(v_is_admin, false))
  on conflict (user_id) do update
    set email = excluded.email,
        is_admin = public.app_users.is_admin or excluded.is_admin;

  return new;
end;
$$;


ALTER FUNCTION public.handle_new_auth_user() OWNER TO postgres;

--
-- Name: history_record_matches(bigint, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.history_record_matches(p_league_id bigint, p_limit integer DEFAULT 10) RETURNS TABLE(record text, rank integer, match_id bigint, season_id bigint, start_year integer, match_date date, home_team_id bigint, away_team_id bigint, home_goals integer, away_goals integer)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  (
    select 'biggest_win'::text, (rank() over (order by m.margin desc))::int,
      m.match_id, m.season_id, m.start_year, m.match_date, m.home_team_id, m.away_team_id, m.home_goals, m.away_goals
    from public.history_league_matches m
    where m.league_id = p_league_id
    order by m.margin desc, m.total_goals desc, m.match_date
    limit least(greatest(p_limit, 1), 100)
  )
  union all
  (
    select 'highest_scoring'::text, (rank() over (order by m.total_goals desc))::int,
      m.match_id, m.season_id, m.start_year, m.match_date, m.home_team_id, m.away_team_id, m.home_goals, m.away_goals
    from public.history_league_matches m
    where m.league_id = p_league_id
    order by m.total_goals desc, m.margin desc, m.match_date
    limit least(greatest(p_limit, 1), 100)
  );
$$;


ALTER FUNCTION public.history_record_matches(p_league_id bigint, p_limit integer) OWNER TO postgres;

--
-- Name: history_record_streaks(bigint, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.history_record_streaks(p_league_id bigint, p_limit integer DEFAULT 10) RETURNS TABLE(streak_type text, rank integer, team_id bigint, length integer, start_date date, end_date date, start_season_id bigint, end_season_id bigint, ongoing boolean, truncated_start boolean)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select x.streak_type, x.rk::int, x.team_id, x.length, x.start_date, x.end_date,
    x.start_season_id, x.end_season_id, x.ongoing, x.truncated_start
  from (
    select h.*,
      rank() over (partition by h.streak_type order by h.length desc) as rk,
      row_number() over (partition by h.streak_type order by h.length desc, h.start_date) as rn
    from public.history_streaks h
    where h.league_id = p_league_id
  ) x
  where x.rn <= least(greatest(p_limit, 1), 100)
  order by x.streak_type, x.rn;
$$;


ALTER FUNCTION public.history_record_streaks(p_league_id bigint, p_limit integer) OWNER TO postgres;

--
-- Name: history_scorelines(bigint, integer, integer, bigint, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.history_scorelines(p_league_id bigint, p_from_year integer DEFAULT NULL::integer, p_to_year integer DEFAULT NULL::integer, p_team_id bigint DEFAULT NULL::bigint, p_venue text DEFAULT NULL::text) RETURNS TABLE(goals_a integer, goals_b integer, outcome text, matches bigint)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select least(s.goals_for, 5), least(s.goals_against, 5), s.result, count(*)
  from public.team_match_snapshot s
  join public.seasons se using (season_id)
  where s.league_id = p_league_id
    and (p_from_year is null or se.start_year >= p_from_year)
    and (p_to_year is null or se.start_year <= p_to_year)
    and case
          when p_team_id is null then s.venue = 'H'
          else s.team_id = p_team_id and (p_venue is null or s.venue = p_venue)
        end
  group by 1, 2, 3
  order by 1, 2, 3;
$$;


ALTER FUNCTION public.history_scorelines(p_league_id bigint, p_from_year integer, p_to_year integer, p_team_id bigint, p_venue text) OWNER TO postgres;

--
-- Name: history_what_happened_next(bigint, integer, integer, integer, integer, integer, integer, integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.history_what_happened_next(p_league_id bigint, p_matches_played integer, p_position_min integer DEFAULT NULL::integer, p_position_max integer DEFAULT NULL::integer, p_points_min integer DEFAULT NULL::integer, p_points_max integer DEFAULT NULL::integer, p_from_year integer DEFAULT NULL::integer, p_to_year integer DEFAULT NULL::integer, p_comparable_group text DEFAULT NULL::text) RETURNS TABLE(season_id bigint, season_label text, start_year integer, team_id bigint, team_name text, team_slug text, position_at_played integer, teams_at_played integer, points integer, goal_difference integer, final_position integer, final_points integer, clubs bigint, champion boolean, top_four boolean, top_six boolean, relegated boolean, promoted boolean)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select s.season_id, t.season_label, t.start_year, s.team_id, tm.display_name, tm.slug,
    s.position_at_played, s.teams_at_played, s.points, s.goal_difference,
    t.position, t.points, t.clubs,
    t.champion, t.top_four, t.top_six, t.relegated, t.promoted
  from public.team_match_snapshot s
  join public.team_season_summary t using (league_id, season_id, team_id)
  join public.teams tm on tm.team_id = s.team_id
  where s.league_id = p_league_id
    and s.matches_played = p_matches_played
    and t.is_final and not t.curtailed and not t.split_format
    and (p_comparable_group is null or t.comparable_group = p_comparable_group)
    and (p_position_min is null or s.position_at_played >= p_position_min)
    and (p_position_max is null or s.position_at_played <= p_position_max)
    and (p_points_min is null or s.points >= p_points_min)
    and (p_points_max is null or s.points <= p_points_max)
    and (p_from_year is null or t.start_year >= p_from_year)
    and (p_to_year is null or t.start_year <= p_to_year)
  order by t.start_year desc, s.position_at_played, tm.display_name
  limit 2000;
$$;


ALTER FUNCTION public.history_what_happened_next(p_league_id bigint, p_matches_played integer, p_position_min integer, p_position_max integer, p_points_min integer, p_points_max integer, p_from_year integer, p_to_year integer, p_comparable_group text) OWNER TO postgres;

--
-- Name: import_fpl_gameweeks(bigint, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.import_fpl_gameweeks(p_season_id bigint, p_folder text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  raw_content text;
  header text[];
  http_status int;
  n_total int;
  n_bad int;
  n_rows int;
  n_unmatched int;
begin
  if not exists (select 1 from public.fpl_player_season_totals where season_id = p_season_id) then
    raise exception 'Season % has no player totals; import those first so elements can resolve to codes', p_season_id;
  end if;

  drop table if exists gw_lines;
  drop table if exists gw_staged;

  select status, content into http_status, raw_content
  from extensions.http_get('https://raw.githubusercontent.com/vaastav/Fantasy-Premier-League/master/data/' || p_folder || '/gws/merged_gw.csv');
  if http_status <> 200 then
    raise exception 'Fetch failed for %/gws/merged_gw.csv (HTTP %)', p_folder, http_status;
  end if;

  create temp table gw_lines as
  select row_number() over () as ln, replace(l, E'\r', '') as l
  from (select unnest(string_to_array(raw_content, E'\n')) as l) s
  where length(trim(l)) > 0;

  select string_to_array(l, ',') into header from gw_lines where ln = 1;

  if array_position(header,'element') is null or array_position(header,'round') is null
     or array_position(header,'fixture') is null or array_position(header,'total_points') is null then
    raise exception 'Required columns missing from %/gws header', p_folder;
  end if;

  select count(*) into n_total from gw_lines where ln > 1;
  select count(*) into n_bad from gw_lines
  where ln > 1 and (array_length(string_to_array(l, ','), 1) <> array_length(header, 1) or l like '%"%');

  if n_bad > greatest(5, n_total / 100) then
    raise exception '%/gws has % malformed row(s) of % -- format change, not a quirk; aborting', p_folder, n_bad, n_total;
  end if;

  create temp table gw_staged as
  select string_to_array(l, ',') as f from gw_lines
  where ln > 1
    and array_length(string_to_array(l, ','), 1) = array_length(header, 1)
    and l not like '%"%';

  insert into public.fpl_player_gameweek_history (
    season_id, fpl_code, gameweek, fixture_id, opponent_team_num, was_home, minutes,
    total_points, starts, goals_scored, assists, clean_sheets, goals_conceded, bonus, bps,
    saves, yellow_cards, red_cards, value, selected, transfers_in, transfers_out,
    expected_goals, expected_assists
  )
  select p_season_id, tot.fpl_code,
    (f[array_position(header,'round')])::int,
    (f[array_position(header,'fixture')])::int,
    nullif(f[array_position(header,'opponent_team')],'')::int,
    lower(f[array_position(header,'was_home')]) = 'true',
    (f[array_position(header,'minutes')])::int,
    (f[array_position(header,'total_points')])::int,
    coalesce(nullif(f[array_position(header,'starts')],'')::int, 0),
    (f[array_position(header,'goals_scored')])::int,
    (f[array_position(header,'assists')])::int,
    (f[array_position(header,'clean_sheets')])::int,
    (f[array_position(header,'goals_conceded')])::int,
    (f[array_position(header,'bonus')])::int,
    (f[array_position(header,'bps')])::int,
    (f[array_position(header,'saves')])::int,
    (f[array_position(header,'yellow_cards')])::int,
    (f[array_position(header,'red_cards')])::int,
    nullif(f[array_position(header,'value')],'')::int,
    nullif(f[array_position(header,'selected')],'')::bigint,
    nullif(f[array_position(header,'transfers_in')],'')::bigint,
    nullif(f[array_position(header,'transfers_out')],'')::bigint,
    nullif(f[array_position(header,'expected_goals')],'')::numeric,
    nullif(f[array_position(header,'expected_assists')],'')::numeric
  from gw_staged g
  join public.fpl_player_season_totals tot
    on tot.season_id = p_season_id
   and tot.fpl_element_id = (g.f[array_position(header,'element')])::int
  on conflict (season_id, fpl_code, gameweek, fixture_id) do nothing;

  get diagnostics n_rows = row_count;

  select count(*) into n_unmatched
  from gw_staged g
  where not exists (
    select 1 from public.fpl_player_season_totals tot
    where tot.season_id = p_season_id
      and tot.fpl_element_id = (g.f[array_position(header,'element')])::int
  );

  drop table if exists gw_lines;
  drop table if exists gw_staged;

  return jsonb_build_object(
    'season_id', p_season_id, 'folder', p_folder,
    'rows_imported', n_rows, 'rows_skipped_malformed', n_bad,
    'rows_unmatched_element', n_unmatched
  );
end $$;


ALTER FUNCTION public.import_fpl_gameweeks(p_season_id bigint, p_folder text) OWNER TO postgres;

--
-- Name: import_fpl_season(bigint, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.import_fpl_season(p_season_id bigint, p_folder text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  raw_content text;
  header text[];
  n_bad int;
  n_total int;
  n_rows int;
  http_status int;
begin
  drop table if exists lines_t;
  drop table if exists staged_t;

  select status, content into http_status, raw_content
  from extensions.http_get('https://raw.githubusercontent.com/vaastav/Fantasy-Premier-League/master/data/' || p_folder || '/players_raw.csv');

  if http_status <> 200 then
    raise exception 'Fetch failed for % (HTTP %)', p_folder, http_status;
  end if;

  create temp table lines_t as
  select row_number() over () as ln, replace(l, E'\r', '') as l
  from (select unnest(string_to_array(raw_content, E'\n')) as l) s
  where length(trim(l)) > 0;

  select string_to_array(l, ',') into header from lines_t where ln = 1;

  if array_position(header,'code') is null or array_position(header,'cost_change_start') is null
     or array_position(header,'now_cost') is null or array_position(header,'total_points') is null then
    raise exception 'Required columns missing from % header', p_folder;
  end if;

  select count(*) into n_total from lines_t where ln > 1;
  select count(*) into n_bad from lines_t
  where ln > 1 and (array_length(string_to_array(l, ','), 1) <> array_length(header, 1) or l like '%"%');

  if n_bad > greatest(5, n_total / 100) then
    raise exception '% has % malformed row(s) of % -- that is a format change, not a quirk; aborting',
      p_folder, n_bad, n_total;
  end if;

  create temp table staged_t as
  select string_to_array(l, ',') as f from lines_t
  where ln > 1
    and array_length(string_to_array(l, ','), 1) = array_length(header, 1)
    and l not like '%"%';

  insert into public.fpl_player_season_totals (
    season_id, fpl_code, fpl_element_id, web_name, full_name, element_type,
    start_cost, end_cost, total_points, minutes, goals_scored, assists, clean_sheets,
    goals_conceded, bonus, bps, saves, yellow_cards, red_cards, penalties_missed,
    penalties_saved, own_goals, selected_by_percent
  )
  select p_season_id,
    (f[array_position(header,'code')])::bigint,
    (f[array_position(header,'id')])::int,
    f[array_position(header,'web_name')],
    trim(f[array_position(header,'first_name')] || ' ' || f[array_position(header,'second_name')]),
    (f[array_position(header,'element_type')])::int,
    (f[array_position(header,'now_cost')])::int - (f[array_position(header,'cost_change_start')])::int,
    (f[array_position(header,'now_cost')])::int,
    (f[array_position(header,'total_points')])::int,
    (f[array_position(header,'minutes')])::int,
    (f[array_position(header,'goals_scored')])::int,
    (f[array_position(header,'assists')])::int,
    (f[array_position(header,'clean_sheets')])::int,
    (f[array_position(header,'goals_conceded')])::int,
    (f[array_position(header,'bonus')])::int,
    (f[array_position(header,'bps')])::int,
    (f[array_position(header,'saves')])::int,
    (f[array_position(header,'yellow_cards')])::int,
    (f[array_position(header,'red_cards')])::int,
    (f[array_position(header,'penalties_missed')])::int,
    (f[array_position(header,'penalties_saved')])::int,
    (f[array_position(header,'own_goals')])::int,
    nullif(f[array_position(header,'selected_by_percent')], '')::numeric
  from staged_t
  where (f[array_position(header,'minutes')])::int > 0
  on conflict (season_id, fpl_code) do nothing;

  get diagnostics n_rows = row_count;

  insert into public.player_identity (fpl_code, canonical_name, first_seen_season_id, last_seen_season_id)
  select t.fpl_code, t.full_name, p_season_id, p_season_id
  from public.fpl_player_season_totals t
  where t.season_id = p_season_id
  on conflict (fpl_code) do update set
    first_seen_season_id = public.earlier_season(public.player_identity.first_seen_season_id, excluded.first_seen_season_id),
    last_seen_season_id = public.later_season(public.player_identity.last_seen_season_id, excluded.last_seen_season_id),
    updated_at = now();

  drop table if exists lines_t;
  drop table if exists staged_t;

  return jsonb_build_object(
    'season_id', p_season_id, 'folder', p_folder,
    'players_imported', n_rows, 'rows_skipped_malformed', n_bad
  );
end $$;


ALTER FUNCTION public.import_fpl_season(p_season_id bigint, p_folder text) OWNER TO postgres;

--
-- Name: intl_delete_matches(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.intl_delete_matches(keys jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare n int;
begin
  delete from intl.matches where match_key in (select jsonb_array_elements_text(keys));
  get diagnostics n = row_count;
  return n;
end $$;


ALTER FUNCTION public.intl_delete_matches(keys jsonb) OWNER TO postgres;

--
-- Name: intl_load_reference(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.intl_load_reference(payload jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  insert into intl.teams (team, slug, confederation, first_match, last_match, matches)
  select r->>'team', r->>'slug', r->>'confederation', (r->>'first_match')::date, (r->>'last_match')::date,
         (r->>'matches')::int
  from jsonb_array_elements(payload->'teams') r
  on conflict (team) do update set slug = excluded.slug, confederation = excluded.confederation,
    first_match = excluded.first_match, last_match = excluded.last_match, matches = excluded.matches;

  delete from intl.team_names where true;
  insert into intl.team_names (team, name, valid_from, valid_to)
  select r->>'team', r->>'name', (r->>'valid_from')::date, (r->>'valid_to')::date
  from jsonb_array_elements(payload->'team_names') r;

  insert into intl.competitions (name, slug, kind, confederation, matches)
  select r->>'name', r->>'slug', r->>'kind', r->>'confederation', (r->>'matches')::int
  from jsonb_array_elements(payload->'competitions') r
  on conflict (name) do update set slug = excluded.slug, kind = excluded.kind,
    confederation = excluded.confederation, matches = excluded.matches;

  insert into intl.editions (edition_key, competition, label, season_start, teams, matches, hosts,
                             first_match, last_match, stage_source)
  select r->>'edition_key', r->>'competition', r->>'label', (r->>'season_start')::int, (r->>'teams')::int,
         (r->>'matches')::int, array(select jsonb_array_elements_text(r->'hosts')),
         (r->>'first_match')::date, (r->>'last_match')::date, r->>'stage_source'
  from jsonb_array_elements(payload->'editions') r
  on conflict (edition_key) do update set competition = excluded.competition, label = excluded.label,
    season_start = excluded.season_start, teams = excluded.teams, matches = excluded.matches,
    hosts = excluded.hosts, first_match = excluded.first_match, last_match = excluded.last_match,
    stage_source = excluded.stage_source;

  insert into intl.stages (stage_key, edition_key, code, name, type, stage_order)
  select r->>'stage_key', r->>'edition_key', r->>'code', r->>'name', r->>'type', (r->>'stage_order')::int
  from jsonb_array_elements(payload->'stages') r
  on conflict (stage_key) do update set name = excluded.name, type = excluded.type,
    stage_order = excluded.stage_order;
  delete from intl.stages s
  where not exists (select 1 from jsonb_array_elements(payload->'stages') r where r->>'stage_key' = s.stage_key);

  insert into intl.groups (group_key, stage_key, label, league, size)
  select r->>'group_key', r->>'stage_key', r->>'label', r->>'league', (r->>'size')::int
  from jsonb_array_elements(payload->'groups') r
  on conflict (group_key) do update set label = excluded.label, league = excluded.league, size = excluded.size;
  delete from intl.groups g
  where not exists (select 1 from jsonb_array_elements(payload->'groups') r where r->>'group_key' = g.group_key);

  delete from intl.group_members where true;
  insert into intl.group_members (group_key, team)
  select r->>'group_key', r->>'team' from jsonb_array_elements(payload->'group_members') r;
end $$;


ALTER FUNCTION public.intl_load_reference(payload jsonb) OWNER TO postgres;

--
-- Name: intl_match_keys(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.intl_match_keys(p_year integer) RETURNS SETOF text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select match_key from intl.matches where extract(year from match_date) = p_year
$$;


ALTER FUNCTION public.intl_match_keys(p_year integer) OWNER TO postgres;

--
-- Name: intl_refresh(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.intl_refresh() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  delete from intl.team_competition_totals where true;
  insert into intl.team_competition_totals
  select team, competition, count(*), count(*) filter (where gf > ga), count(*) filter (where gf = ga),
         count(*) filter (where gf < ga), sum(gf), sum(ga), min(match_date), max(match_date)
  from (select home_team team, competition, home_score gf, away_score ga, match_date from intl.matches
        union all
        select away_team, competition, away_score, home_score, match_date from intl.matches) s
  group by team, competition;

  delete from intl.pair_records where true;
  insert into intl.pair_records
  select a, b, count(*), count(*) filter (where ag > bg), count(*) filter (where ag = bg),
         count(*) filter (where ag < bg), sum(ag), sum(bg), min(match_date), max(match_date)
  from (select least(home_team, away_team) a, greatest(home_team, away_team) b,
               case when home_team < away_team then home_score else away_score end ag,
               case when home_team < away_team then away_score else home_score end bg, match_date
        from intl.matches) s
  group by a, b;

  -- Editions: winner and runner-up.
  delete from intl.edition_summary where true;
  insert into intl.edition_summary (edition_key, competition, label, season_start, teams, matches, goals, hosts,
                                    winner, runner_up, final_key, first_match, last_match)
  with fin as (
    select distinct on (m.edition_key) m.edition_key, m.match_key,
      case when m.home_score > m.away_score then m.home_team when m.away_score > m.home_score then m.away_team
           else m.shootout_winner end as winner,
      case when m.home_score > m.away_score then m.away_team when m.away_score > m.home_score then m.home_team
           when m.shootout_winner = m.home_team then m.away_team when m.shootout_winner = m.away_team then m.home_team end as runner_up
    from intl.matches m where m.stage_code = 'F'
    order by m.edition_key, m.match_date desc, m.match_key desc
  ),
  fr as (  -- final group (World Cup 1950): 2 points a win, then goal difference
    select edition_key, team, row_number() over (partition by edition_key order by sum(pts) desc, sum(gf - ga) desc) as pos
    from (select edition_key, home_team team, home_score gf, away_score ga,
                 case when home_score > away_score then 2 when home_score = away_score then 1 else 0 end pts
          from intl.matches where stage_code = 'FR'
          union all
          select edition_key, away_team, away_score, home_score,
                 case when away_score > home_score then 2 when home_score = away_score then 1 else 0 end
          from intl.matches where stage_code = 'FR') s
    group by edition_key, team
  ),
  totals as (
    select edition_key, count(*) n, sum(home_score + away_score) g from intl.matches where edition_key is not null group by 1
  )
  select e.edition_key, e.competition, e.label, e.season_start, e.teams, coalesce(t.n, 0), coalesce(t.g, 0), e.hosts,
         coalesce(fin.winner, (select team from fr where fr.edition_key = e.edition_key and pos = 1)),
         coalesce(fin.runner_up, (select team from fr where fr.edition_key = e.edition_key and pos = 2)),
         fin.match_key, e.first_match, e.last_match
  from intl.editions e
  left join fin on fin.edition_key = e.edition_key
  left join totals t on t.edition_key = e.edition_key;

  -- Teams: record, Elo now and at its peak, titles.
  delete from intl.team_summary where true;
  insert into intl.team_summary
  with sides as (
    select home_team team, match_date d, match_key k, elo_home_pre + elo_change after from intl.matches
    union all
    select away_team, match_date, match_key, elo_away_pre - elo_change from intl.matches
  ),
  latest as (select distinct on (team) team, after from sides order by team, d desc, k desc),
  peak as (select distinct on (team) team, after, d from sides order by team, after desc, d asc),
  rec as (
    select team, sum(played) p, sum(won) w, sum(drawn) dr, sum(lost) l, sum(goals_for) gf, sum(goals_against) ga
    from intl.team_competition_totals group by team
  ),
  titles as (
    select winner team,
           count(*) filter (where competition = 'FIFA World Cup') wc,
           count(*) filter (where competition = 'UEFA Euro') eu,
           count(*) filter (where competition = 'UEFA Nations League') nl
    from intl.edition_summary where winner is not null group by winner
  )
  select t.team, t.slug, t.confederation, rec.p, rec.w, rec.dr, rec.l, rec.gf, rec.ga, t.first_match, t.last_match,
         round(latest.after, 1),
         case when t.confederation is not null and t.last_match >= current_date - interval '4 years'
              then rank() over (partition by (t.confederation is not null and t.last_match >= current_date - interval '4 years')
                                order by latest.after desc) end,
         round(peak.after, 1), peak.d,
         coalesce(titles.wc, 0), coalesce(titles.eu, 0), coalesce(titles.nl, 0)
  from intl.teams t
  join rec on rec.team = t.team
  join latest on latest.team = t.team
  join peak on peak.team = t.team
  left join titles on titles.team = t.team;
end $$;


ALTER FUNCTION public.intl_refresh() OWNER TO postgres;

--
-- Name: intl_replace_goals(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.intl_replace_goals(rows jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  delete from intl.goals g
  where g.match_key in (select distinct r->>'match_key' from jsonb_array_elements(rows) r);
  insert into intl.goals (match_key, seq, team, scorer, minute, own_goal, penalty)
  select r->>'match_key', (r->>'seq')::int, r->>'team', r->>'scorer', (r->>'minute')::int,
         (r->>'own_goal')::boolean, (r->>'penalty')::boolean
  from jsonb_array_elements(rows) r;
end $$;


ALTER FUNCTION public.intl_replace_goals(rows jsonb) OWNER TO postgres;

--
-- Name: intl_replace_shootouts(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.intl_replace_shootouts(rows jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  delete from intl.shootouts where true;
  insert into intl.shootouts (match_key, winner, first_shooter)
  select r->>'match_key', r->>'winner', r->>'first_shooter' from jsonb_array_elements(rows) r;
end $$;


ALTER FUNCTION public.intl_replace_shootouts(rows jsonb) OWNER TO postgres;

--
-- Name: intl_upsert_fixtures(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.intl_upsert_fixtures(rows jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare n int;
begin
  insert into intl.fixtures as f (fixture_key, edition_key, kickoff_utc, home_team, away_team, group_label,
    round_number, venue, home_score, away_score, source, raw, updated_at)
  select r->>'fixture_key', r->>'edition_key', (r->>'kickoff_utc')::timestamptz, r->>'home_team', r->>'away_team',
    r->>'group_label', (r->>'round_number')::int, r->>'venue', (r->>'home_score')::int, (r->>'away_score')::int,
    r->>'source', r->'raw', now()
  from jsonb_array_elements(rows) r
  on conflict (fixture_key) do update set kickoff_utc = excluded.kickoff_utc, home_team = excluded.home_team,
    away_team = excluded.away_team, group_label = excluded.group_label, round_number = excluded.round_number,
    venue = excluded.venue,
    -- never let the feed blank a score it once carried
    home_score = coalesce(excluded.home_score, f.home_score), away_score = coalesce(excluded.away_score, f.away_score),
    raw = excluded.raw, updated_at = now();
  get diagnostics n = row_count;
  return n;
end $$;


ALTER FUNCTION public.intl_upsert_fixtures(rows jsonb) OWNER TO postgres;

--
-- Name: intl_upsert_matches(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.intl_upsert_matches(rows jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare n int;
begin
  insert into intl.matches as m (match_key, match_date, home_team, away_team, home_score, away_score, competition,
    city, country, neutral, edition_key, stage_code, group_label, matchday, home_score_90, away_score_90,
    went_extra_time, shootout_winner, elo_home_pre, elo_away_pre, elo_change, raw, imported_at)
  select r->>'match_key', (r->>'match_date')::date, r->>'home_team', r->>'away_team',
    (r->>'home_score')::int, (r->>'away_score')::int, r->>'competition', r->>'city', r->>'country',
    (r->>'neutral')::boolean, r->>'edition_key', r->>'stage_code', r->>'group_label', (r->>'matchday')::int,
    (r->>'home_score_90')::int, (r->>'away_score_90')::int, (r->>'went_extra_time')::boolean,
    r->>'shootout_winner', (r->>'elo_home_pre')::numeric, (r->>'elo_away_pre')::numeric,
    (r->>'elo_change')::numeric, r->'raw', now()
  from jsonb_array_elements(rows) r
  on conflict (match_key) do update set
    match_date = excluded.match_date, home_team = excluded.home_team, away_team = excluded.away_team,
    home_score = excluded.home_score, away_score = excluded.away_score, competition = excluded.competition,
    city = excluded.city, country = excluded.country, neutral = excluded.neutral,
    edition_key = excluded.edition_key, stage_code = excluded.stage_code, group_label = excluded.group_label,
    matchday = excluded.matchday, home_score_90 = excluded.home_score_90, away_score_90 = excluded.away_score_90,
    went_extra_time = excluded.went_extra_time, shootout_winner = excluded.shootout_winner,
    elo_home_pre = excluded.elo_home_pre, elo_away_pre = excluded.elo_away_pre, elo_change = excluded.elo_change,
    raw = excluded.raw, imported_at = now()
  where m.raw is distinct from excluded.raw or m.edition_key is distinct from excluded.edition_key
     or m.stage_code is distinct from excluded.stage_code or m.group_label is distinct from excluded.group_label
     or m.home_score_90 is distinct from excluded.home_score_90 or m.elo_change is distinct from excluded.elo_change
     or m.elo_home_pre is distinct from excluded.elo_home_pre or m.shootout_winner is distinct from excluded.shootout_winner;
  get diagnostics n = row_count;
  return n;
end $$;


ALTER FUNCTION public.intl_upsert_matches(rows jsonb) OWNER TO postgres;

