--
-- Name: lab_devig_power(numeric, numeric, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.lab_devig_power(p_h numeric, p_d numeric, p_a numeric) RETURNS double precision[]
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
declare
  rh double precision := 1 / p_h; rd double precision := 1 / p_d; ra double precision := 1 / p_a;
  lo double precision := 0.5; hi double precision := 3; k double precision; s double precision;
begin
  for i in 1..60 loop
    k := (lo + hi) / 2;
    s := power(rh, k) + power(rd, k) + power(ra, k);
    if s > 1 then lo := k; else hi := k; end if;
  end loop;
  return array[power(rh, k), power(rd, k), power(ra, k)];
end;
$$;


ALTER FUNCTION public.lab_devig_power(p_h numeric, p_d numeric, p_a numeric) OWNER TO postgres;

--
-- Name: lab_devig_shin(numeric, numeric, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.lab_devig_shin(p_h numeric, p_d numeric, p_a numeric) RETURNS double precision[]
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
declare
  r double precision[] := array[1 / p_h::double precision, 1 / p_d::double precision, 1 / p_a::double precision];
  b double precision := r[1] + r[2] + r[3];
  lo double precision := 0; hi double precision := 0.4; z double precision; s double precision;
  p double precision[] := array[0, 0, 0]::double precision[];
begin
  if b <= 1 then
    return array[r[1] / b, r[2] / b, r[3] / b];
  end if;
  for i in 1..60 loop
    z := (lo + hi) / 2;
    s := 0;
    for j in 1..3 loop
      p[j] := (sqrt(z * z + 4 * (1 - z) * r[j] * r[j] / b) - z) / (2 * (1 - z));
      s := s + p[j];
    end loop;
    if s > 1 then lo := z; else hi := z; end if;
  end loop;
  return p;
end;
$$;


ALTER FUNCTION public.lab_devig_shin(p_h numeric, p_d numeric, p_a numeric) OWNER TO postgres;

--
-- Name: lab_guard_holdout(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.lab_guard_holdout() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_rule text;
  v_opened timestamptz;
begin
  if tg_op <> 'INSERT' then
    raise exception 'lab_scorings is append-only: % refused', tg_op;
  end if;
  if new.split = 'holdout' then
    select decision_rule, holdout_opened_at into v_rule, v_opened from public.lab_experiments where experiment_id = new.experiment_id;
    if v_rule is null or length(trim(v_rule)) = 0 then
      raise exception 'Experiment % has no registered decision rule: holdout refused', new.experiment_id;
    end if;
    if v_opened is not null and v_opened < now() - interval '1 hour' then
      raise exception 'Holdout for % was opened at %; it can only be scored once', new.experiment_id, v_opened;
    end if;
    update public.lab_experiments
      set holdout_opened_at = coalesce(holdout_opened_at, now()), status = 'holdout_opened'
      where experiment_id = new.experiment_id;
  end if;
  return new;
end;
$$;


ALTER FUNCTION public.lab_guard_holdout() OWNER TO postgres;

--
-- Name: later_season(bigint, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.later_season(a bigint, b bigint) RETURNS bigint
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  -- greatest(a, b) by start_year: nulls ignored, as greatest() does.
  select case when a is null then b
              when b is null then a
              when public.season_start_year(a) >= public.season_start_year(b) then a
              else b end
$$;


ALTER FUNCTION public.later_season(a bigint, b bigint) OWNER TO postgres;

--
-- Name: league_name_for_season(bigint, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.league_name_for_season(p_league_id bigint, p_season_id bigint) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  -- The division's name in that season; today's name where no era row applies.
  select coalesce(
    (select n.name
       from public.league_season_names n
       join public.seasons s on s.season_id = p_season_id
      where n.league_id = p_league_id
        and s.start_year >= n.from_season_start_year
        and (n.to_season_start_year is null or s.start_year <= n.to_season_start_year)
      order by n.from_season_start_year desc
      limit 1),
    (select l.name from public.leagues l where l.league_id = p_league_id))
$$;


ALTER FUNCTION public.league_name_for_season(p_league_id bigint, p_season_id bigint) OWNER TO postgres;

--
-- Name: list_scout_players(bigint, integer, bigint, integer, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.list_scout_players(p_season_id bigint DEFAULT public.fpl_current_season_id(), p_position integer DEFAULT NULL::integer, p_team_id bigint DEFAULT NULL::bigint, p_min_minutes integer DEFAULT 0, p_search text DEFAULT NULL::text, p_limit integer DEFAULT 100) RETURNS TABLE(fpl_code bigint, slug text, fpl_player_id bigint, web_name text, full_name text, team_name text, team_id bigint, element_type integer, now_cost integer, total_points integer, minutes integer, goals_scored integer, assists integer, clean_sheets integer, bonus integer, selected_by_percent numeric, points_per_million numeric, seasons_played bigint, price_pressure numeric, price_direction text)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with pressure as (
    select r.fpl_player_id, r.pressure, r.direction
    from public.get_price_change_risk(p_season_id) r
  )
  select
    p.fpl_code, i.slug, p.fpl_player_id::bigint, p.web_name,
    trim(coalesce(p.first_name,'') || ' ' || coalesce(p.second_name,'')),
    t.display_name, p.canonical_team_id::bigint, p.element_type,
    p.now_cost, p.total_points, p.minutes, p.goals_scored, p.assists,
    p.clean_sheets, p.bonus, p.selected_by_percent,
    case when p.now_cost > 0
         then round((p.total_points / (p.now_cost / 10.0))::numeric, 2) end,
    (select count(*) from public.fpl_player_season_totals st where st.fpl_code = p.fpl_code),
    round(abs(pr.pressure)::numeric, 1), pr.direction
  from public.fpl_players p
  left join public.teams t on t.team_id = p.canonical_team_id
  left join public.player_identity i on i.fpl_code = p.fpl_code
  left join pressure pr on pr.fpl_player_id = p.fpl_player_id
  where p.season_id = p_season_id
    and (p_position is null or p.element_type = p_position)
    and (p_team_id is null or p.canonical_team_id = p_team_id)
    and coalesce(p.minutes, 0) >= coalesce(p_min_minutes, 0)
    and (
      p_search is null or length(trim(p_search)) = 0
      or p.web_name ilike '%' || trim(p_search) || '%'
      or trim(coalesce(p.first_name,'') || ' ' || coalesce(p.second_name,'')) ilike '%' || trim(p_search) || '%'
    )
  order by p.total_points desc nulls last, p.minutes desc nulls last
  limit greatest(1, least(p_limit, 700));
$$;


ALTER FUNCTION public.list_scout_players(p_season_id bigint, p_position integer, p_team_id bigint, p_min_minutes integer, p_search text, p_limit integer) OWNER TO postgres;

