-- Name: list_scout_teams(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.list_scout_teams(p_season_id bigint DEFAULT public.fpl_current_season_id()) RETURNS TABLE(team_id bigint, team_name text, players integer)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select t.team_id::bigint, t.display_name, count(*)::int
  from public.fpl_players p
  join public.teams t on t.team_id = p.canonical_team_id
  where p.season_id = p_season_id
