-- Name: record_team_slug_change(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.record_team_slug_change() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if old.slug is distinct from new.slug then
    insert into public.team_slug_history (team_id, old_slug) values (old.team_id, old.slug);
  end if;
  return new;
end;
$$;


