--
-- Name: refresh_feed_nearest_date(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.refresh_feed_nearest_date(p_code text, p_url text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_catalog'
    AS $$
declare
  v_league bigint; v_season bigint; v_status int; v_body text; v_changed int := 0; v_n int;
begin
  select league_id into v_league from public.leagues where code = p_code;
  v_season := public.current_season_id();  -- docs/season-rollover.md
  if v_league is null or v_season is null then return 0; end if;
  select status, content into v_status, v_body from extensions.http_get(p_url);
  if v_status <> 200 then raise exception '% feed returned HTTP %', p_code, v_status; end if;

  drop table if exists _feed, _feed_match;
  create temp table _feed on commit drop as
  select coalesce(ha.team_id, ht.team_id) home_id, coalesce(aa.team_id, at.team_id) away_id,
    x.ko,
    case when (x.ko at time zone 'UTC')::time = '00:00' or (x.ko at time zone 'Europe/Paris')::time = '00:00'
         then (x.ko at time zone 'Europe/Paris')::date else (x.ko at time zone 'Europe/London')::date end ko_date,
    case when (x.ko at time zone 'UTC')::time = '00:00' or (x.ko at time zone 'Europe/Paris')::time = '00:00'
         then null else (x.ko at time zone 'Europe/London')::time end ko_time,
    x.rnd
  from (select e->>'HomeTeam' h, e->>'AwayTeam' a, (e->>'DateUtc')::timestamptz ko,
          nullif(regexp_replace(coalesce(e->>'RoundNumber',''),'[^0-9]','','g'),'')::int rnd
        from jsonb_array_elements(v_body::jsonb) e where e ? 'DateUtc') x
  left join public.team_aliases ha on ha.source_name='FixtureDownload' and ha.raw_name=x.h
  left join public.teams ht on ht.canonical_name=x.h
  left join public.team_aliases aa on aa.source_name='FixtureDownload' and aa.raw_name=x.a
  left join public.teams at on at.canonical_name=x.a;
  delete from _feed where home_id is null or away_id is null or ko is null;

  create temp table _feed_match on commit drop as
  select distinct on (f.fixture_id) f.fixture_id, s.ko, s.ko_date, s.ko_time, s.rnd
  from _feed s
  join public.fixtures f on f.league_id = v_league and f.season_id = v_season
    and f.home_team_id = s.home_id and f.away_team_id = s.away_id
    and abs(f.kickoff_date - s.ko_date) <= 60
  order by f.fixture_id, abs(f.kickoff_date - s.ko_date);

  insert into public.fixture_changes(fixture_id, old_kickoff_date, new_kickoff_date, old_kickoff_time, new_kickoff_time)
  select f.fixture_id, f.kickoff_date, m.ko_date, f.kickoff_time, m.ko_time
  from _feed_match m join public.fixtures f on f.fixture_id = m.fixture_id
  where f.kickoff_date <> m.ko_date or f.kickoff_time is distinct from m.ko_time;

  update public.fixtures f set
    kickoff_date = m.ko_date, kickoff_time = m.ko_time, matchweek = coalesce(m.rnd, f.matchweek),
    status = case when m.ko < now() then 'played' else 'scheduled' end, updated_at = now()
  from _feed_match m
  where f.fixture_id = m.fixture_id
    and (f.kickoff_date <> m.ko_date or f.kickoff_time is distinct from m.ko_time
      or f.status <> case when m.ko < now() then 'played' else 'scheduled' end);
  get diagnostics v_n = row_count; v_changed := v_changed + v_n;

  insert into public.fixtures (league_id, season_id, home_team_id, away_team_id, kickoff_date, kickoff_time, matchweek, status, source_name, source_file)
  select v_league, v_season, s.home_id, s.away_id, s.ko_date, s.ko_time, s.rnd,
    case when s.ko < now() then 'played' else 'scheduled' end, 'FixtureDownload', p_url
  from _feed s
  where not exists (
    select 1 from public.fixtures f where f.league_id = v_league and f.season_id = v_season
      and f.home_team_id = s.home_id and f.away_team_id = s.away_id
      and abs(f.kickoff_date - s.ko_date) <= 60)
  on conflict (league_id, season_id, kickoff_date, home_team_id, away_team_id) do nothing;
  get diagnostics v_n = row_count; v_changed := v_changed + v_n;
  return v_changed;
end;
$$;


ALTER FUNCTION public.refresh_feed_nearest_date(p_code text, p_url text) OWNER TO postgres;

--
-- Name: refresh_fixture_feeds(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.refresh_fixture_feeds() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_catalog'
    AS $$
declare v_year int; v_skipped text[] := '{}'; v_run_id bigint; v_code text; v_url text; v_league_id bigint; v_season_id bigint; v_body text; v_json jsonb; v_seen int:=0; v_updated int:=0; v_count int; v_http_status int; v_predictions int;
begin
 insert into public.fixture_refresh_runs(competitions) values(array['E0','E1','E2','E3','UCL','UEL','UECL','D1']) returning refresh_run_id into v_run_id;
 -- Current season (docs/season-rollover.md); feed URLs carry its start year.
 v_season_id := public.current_season_id();
 select start_year into v_year from public.seasons where season_id = v_season_id;
 for v_code,v_url in select * from (values
 ('E0','https://fixturedownload.com/feed/json/epl-' || v_year),('E1','https://fixturedownload.com/feed/json/championship-' || v_year),('E2','https://fixturedownload.com/feed/json/efl-league-one-' || v_year),('E3','https://fixturedownload.com/feed/json/efl-league-two-' || v_year),('UCL','https://fixturedownload.com/feed/json/champions-league-' || v_year),('UEL','https://fixturedownload.com/feed/json/europa-league-' || v_year),('UECL','https://fixturedownload.com/feed/json/conference-league-' || v_year),('D1','https://fixturedownload.com/feed/json/bundesliga-' || v_year)) x(code,url)
 loop
  select league_id into v_league_id from public.leagues where code=v_code limit 1; if v_league_id is null then continue; end if;
  select status,content into v_http_status,v_body from extensions.http_get(v_url);
  -- Next season's feed only exists once its fixtures are published (UEFA:
  -- after the late-August draw). Until 1 October a 404 is skipped and noted
  -- on the run; after that it is an error again.
  if v_http_status=404 and current_date < make_date(v_year,10,1) then v_skipped:=v_skipped||v_code; continue; end if;
  if v_http_status<>200 then raise exception 'Feed % returned HTTP %',v_code,v_http_status; end if;
  v_json:=v_body::jsonb; v_count:=jsonb_array_length(v_json); v_seen:=v_seen+v_count;
  -- New season: no fixtures for this league yet, so insert the whole list
  -- once (the matcher below only updates existing rows).
  if not exists (select 1 from public.fixtures where league_id=v_league_id and season_id=v_season_id) then
   perform public.refresh_feed_nearest_date(v_code, v_url);
  end if;
  with src as (select elem->>'HomeTeam' home_raw,elem->>'AwayTeam' away_raw,(elem->>'DateUtc')::timestamptz ko,nullif(regexp_replace(coalesce(elem->>'RoundNumber',''),'[^0-9]','','g'),'')::int round_no from jsonb_array_elements(v_json) elem where elem ? 'DateUtc'),
  mapped as (select s.*,coalesce(ha.team_id,ht.team_id) home_id,coalesce(aa.team_id,at.team_id) away_id from src s left join public.team_aliases ha on ha.source_name='FixtureDownload' and ha.raw_name=s.home_raw left join public.teams ht on ht.canonical_name=s.home_raw left join public.team_aliases aa on aa.source_name='FixtureDownload' and aa.raw_name=s.away_raw left join public.teams at on at.canonical_name=s.away_raw),
  pending_changes as (
    select f.fixture_id, f.kickoff_date as old_date, (m.ko at time zone 'Europe/London')::date as new_date,
           f.kickoff_time as old_time, (case when (m.ko at time zone 'UTC')::time = '00:00' then null else (m.ko at time zone 'Europe/London')::time end) as new_time
    from mapped m
    join public.fixtures f on f.league_id=v_league_id and f.season_id=v_season_id and f.home_team_id=m.home_id and f.away_team_id=m.away_id
    where m.ko is not null and m.home_id is not null and m.away_id is not null
      and (f.kickoff_date <> (m.ko at time zone 'Europe/London')::date or f.kickoff_time is distinct from (case when (m.ko at time zone 'UTC')::time = '00:00' then null else (m.ko at time zone 'Europe/London')::time end))
  )
  insert into public.fixture_changes(fixture_id, old_kickoff_date, new_kickoff_date, old_kickoff_time, new_kickoff_time)
  select fixture_id, old_date, new_date, old_time, new_time from pending_changes;

  with src as (select elem->>'HomeTeam' home_raw,elem->>'AwayTeam' away_raw,(elem->>'DateUtc')::timestamptz ko,nullif(regexp_replace(coalesce(elem->>'RoundNumber',''),'[^0-9]','','g'),'')::int round_no from jsonb_array_elements(v_json) elem where elem ? 'DateUtc'),
  mapped as (select s.*,coalesce(ha.team_id,ht.team_id) home_id,coalesce(aa.team_id,at.team_id) away_id from src s left join public.team_aliases ha on ha.source_name='FixtureDownload' and ha.raw_name=s.home_raw left join public.teams ht on ht.canonical_name=s.home_raw left join public.team_aliases aa on aa.source_name='FixtureDownload' and aa.raw_name=s.away_raw left join public.teams at on at.canonical_name=s.away_raw)
  update public.fixtures f set kickoff_date=(m.ko at time zone 'Europe/London')::date,kickoff_time=(case when (m.ko at time zone 'UTC')::time = '00:00' then null else (m.ko at time zone 'Europe/London')::time end),matchweek=coalesce(m.round_no,f.matchweek),status=case when m.ko<now() then 'played' else 'scheduled' end,source_name='FixtureDownload',source_file=v_url,updated_at=now() from mapped m where m.ko is not null and m.home_id is not null and m.away_id is not null and f.league_id=v_league_id and f.season_id=v_season_id and f.home_team_id=m.home_id and f.away_team_id=m.away_id;
  get diagnostics v_count=row_count; v_updated:=v_updated+v_count;
  -- Reported score (display only until football-data confirms it).
  with src as (select elem->>'HomeTeam' home_raw, elem->>'AwayTeam' away_raw, (elem->>'DateUtc')::timestamptz ko,
                      nullif(elem->>'HomeTeamScore','')::int hg, nullif(elem->>'AwayTeamScore','')::int ag
               from jsonb_array_elements(v_json) elem where elem ? 'DateUtc'),
  mapped as (select s.*, coalesce(ha.team_id, ht.team_id) home_id, coalesce(aa.team_id, at.team_id) away_id
             from src s
             left join public.team_aliases ha on ha.source_name = 'FixtureDownload' and ha.raw_name = s.home_raw
             left join public.teams ht on ht.canonical_name = s.home_raw
             left join public.team_aliases aa on aa.source_name = 'FixtureDownload' and aa.raw_name = s.away_raw
             left join public.teams at on at.canonical_name = s.away_raw)
  update public.fixtures f set reported_home_goals = m.hg, reported_away_goals = m.ag,
    reported_at = now(), reported_source = 'FixtureDownload'
  from mapped m
  where m.ko < now() and m.hg is not null and m.ag is not null and m.home_id is not null and m.away_id is not null
    and f.league_id = v_league_id and f.season_id = v_season_id
    and f.home_team_id = m.home_id and f.away_team_id = m.away_id
    and f.kickoff_date = (m.ko at time zone 'Europe/London')::date
    and (f.reported_home_goals is distinct from m.hg or f.reported_away_goals is distinct from m.ag);
  -- UEFA competitions: the feed carries the result, and nothing else ingests
  -- these (2026-09-26). League phase only -- see migration
  -- 20260926190000_uefa_results_from_fixture_feed.
  if v_code in ('UCL','UEL','UECL') then
   with src as (select elem->>'HomeTeam' home_raw,elem->>'AwayTeam' away_raw,(elem->>'DateUtc')::timestamptz ko,nullif(regexp_replace(coalesce(elem->>'RoundNumber',''),'[^0-9]','','g'),'')::int round_no,nullif(elem->>'HomeTeamScore','')::int hg,nullif(elem->>'AwayTeamScore','')::int ag from jsonb_array_elements(v_json) elem where elem ? 'DateUtc'),
   mapped as (select s.*,coalesce(ha.team_id,ht.team_id) home_id,coalesce(aa.team_id,at.team_id) away_id from src s left join public.team_aliases ha on ha.source_name='FixtureDownload' and ha.raw_name=s.home_raw left join public.teams ht on ht.canonical_name=s.home_raw left join public.team_aliases aa on aa.source_name='FixtureDownload' and aa.raw_name=s.away_raw left join public.teams at on at.canonical_name=s.away_raw)
   insert into public.matches as mt(league_id,season_id,home_team_id,away_team_id,match_date,kickoff_time,full_time_home_goals,full_time_away_goals,full_time_result,round_number,source_name,source_file,updated_at)
   select v_league_id,v_season_id,m.home_id,m.away_id,(m.ko at time zone 'Europe/London')::date,(case when (m.ko at time zone 'UTC')::time = '00:00' then null else (m.ko at time zone 'Europe/London')::time end),m.hg,m.ag,case when m.hg>m.ag then 'H' when m.hg<m.ag then 'A' else 'D' end,m.round_no,'FixtureDownload',v_url,now()
   from mapped m
   where m.ko<now() and m.hg is not null and m.ag is not null and m.home_id is not null and m.away_id is not null and m.round_no between 1 and 8
   on conflict (league_id,season_id,match_date,home_team_id,away_team_id) do update
     set full_time_home_goals=excluded.full_time_home_goals,full_time_away_goals=excluded.full_time_away_goals,full_time_result=excluded.full_time_result,updated_at=now()
     where mt.source_name='FixtureDownload'
       and (mt.full_time_home_goals,mt.full_time_away_goals) is distinct from (excluded.full_time_home_goals,excluded.full_time_away_goals);
  end if;
 end loop;
 -- Scotland has its own matcher (repeat home fixtures); isolated so a
 -- Scottish feed problem can never fail the English/European refresh.
 begin perform public.refresh_scottish_premiership_fixtures();
 exception when others then raise warning 'SC0 fixture refresh failed: %', sqlerrm; end;
 -- Serie A, Ligue 1, La Liga use the nearest-date matcher too (the feed
 -- can list a pairing twice); each isolated like Scotland.
 begin perform public.refresh_feed_nearest_date('I1','https://fixturedownload.com/feed/json/serie-a-' || v_year);
 exception when others then raise warning 'I1 fixture refresh failed: %', sqlerrm; end;
 begin perform public.refresh_feed_nearest_date('F1','https://fixturedownload.com/feed/json/ligue-1-' || v_year);
 exception when others then raise warning 'F1 fixture refresh failed: %', sqlerrm; end;
 begin perform public.refresh_feed_nearest_date('SP1','https://fixturedownload.com/feed/json/la-liga-' || v_year);
 exception when others then raise warning 'SP1 fixture refresh failed: %', sqlerrm; end;
 select public.backfill_fixture_predictions() into v_predictions;
 update public.fixture_refresh_runs set finished_at=now(),rows_seen=v_seen,rows_updated=v_updated,status='success',error_message=case when cardinality(v_skipped)>0 then 'Feeds not published yet (HTTP 404): '||array_to_string(v_skipped,', ') end where refresh_run_id=v_run_id;
exception when others then update public.fixture_refresh_runs set finished_at=now(),rows_seen=v_seen,rows_updated=v_updated,status='failed',error_message=sqlerrm where refresh_run_id=v_run_id; raise;
end;$$;


ALTER FUNCTION public.refresh_fixture_feeds() OWNER TO postgres;

--
-- Name: refresh_fpl(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.refresh_fpl() RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
    AS $$
  -- Wrapper only. The body lives in private.refresh_fpl(), which is what
  -- pg_cron runs. Two independent copies diverged silently once and took
  -- the pipeline down for half a day; never let that happen again.
  select private.refresh_fpl();
$$;


ALTER FUNCTION public.refresh_fpl() OWNER TO postgres;

--
-- Name: refresh_fpl_bonus_v3_for_fixture(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.refresh_fpl_bonus_v3_for_fixture(p_fixture_id bigint) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_count integer;
begin
with hist as (
 select p.fpl_player_id,p.element_type,coalesce(sum(g.minutes),0)::numeric mins,coalesce(sum(g.bps),0)::numeric bps
 from fpl_players p left join fpl_player_gameweeks g on g.season_id = (SELECT public.fpl_current_season_id()) and g.fpl_player_id=p.fpl_player_id where p.season_id = (SELECT public.fpl_current_season_id()) group by p.fpl_player_id,p.element_type
), base as (
 select a.fixture_id,a.team_id,a.fpl_player_id,a.element_type,a.expected_minutes,a.expected_goals,a.expected_assists,
 exp(-case when a.team_id=f.home_team_id then f.predicted_away_goals else f.predicted_home_goals end)::numeric cs,
 coalesce(d.defensive_contribution_probability,0::numeric) dc,h.mins,h.bps,
 case a.element_type when 1 then 15.88 when 2 then 19.27 when 3 then 27.39 when 4 then 33.24 else 20 end::numeric prior
 from fpl_projection_leaguewide_allocation_v2 a join fixtures f on f.fixture_id=a.fixture_id join hist h on h.fpl_player_id=a.fpl_player_id
 left join fpl_defensive_contribution_projection_leaguewide d on d.fixture_id=a.fixture_id and d.fpl_player_id=a.fpl_player_id
 where a.fixture_id=p_fixture_id
), score as (
 select *, (bps+prior*5)/(mins+450)*expected_minutes + expected_goals*(case element_type when 1 then 12 when 2 then 12 when 3 then 18 when 4 then 24 else 18 end) + expected_assists*9 + cs*least(1,expected_minutes/60)*(case when element_type in(1,2) then 6 else 0 end) + dc*2 expected_bps_score from base
), weights as (
 select fixture_id,fpl_player_id,exp(least(50::numeric,expected_bps_score/12::numeric)) w from score
), totals as (select sum(w) s from weights),
p1 as (select i.fpl_player_id,i.w/t.s p1 from weights i cross join totals t),
p2 as (select i.fpl_player_id,sum((j.w/t.s)*(i.w/nullif(t.s-j.w,0))) p2 from weights i join weights j on j.fpl_player_id<>i.fpl_player_id cross join totals t group by i.fpl_player_id),
p3 as (select i.fpl_player_id,sum((j.w/t.s)*(k.w/nullif(t.s-j.w,0))*(i.w/nullif(t.s-j.w-k.w,0))) p3 from weights i join weights j on j.fpl_player_id<>i.fpl_player_id join weights k on k.fpl_player_id<>i.fpl_player_id and k.fpl_player_id<>j.fpl_player_id cross join totals t group by i.fpl_player_id),
bonus as (select w.fixture_id,w.fpl_player_id,round((3*p1.p1+2*p2.p2+p3.p3)::numeric,8) bonus from weights w join p1 using(fpl_player_id) join p2 using(fpl_player_id) join p3 using(fpl_player_id))
update fpl_player_projections pr set expected_bonus=b.bonus,xpts_bonus=b.bonus,expected_fpl_points=pr.expected_fpl_points-pr.xpts_bonus+b.bonus,generated_at=now() from bonus b where pr.fixture_id=p_fixture_id and pr.fixture_id=b.fixture_id and pr.fpl_player_id=b.fpl_player_id and pr.model_version='leaguewide_v6' and pr.scenario_key='baseline';
get diagnostics v_count=row_count; return v_count;
end $$;


ALTER FUNCTION public.refresh_fpl_bonus_v3_for_fixture(p_fixture_id bigint) OWNER TO postgres;

--
-- Name: refresh_fpl_projection_fixture_v6(bigint, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.refresh_fpl_projection_fixture_v6(p_fixture_id bigint, p_allow_played boolean DEFAULT false) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_status text;
  v_rows integer;
begin
  if not p_allow_played then
    select status into v_status from public.fixtures where fixture_id = p_fixture_id;
    if v_status = 'played' then
      -- Nothing written, and deliberately not an error: the routine
      -- pipeline sweeps a matchweek range that may include just-played
      -- fixtures, and that is normal, not a failure.
      return 0;
    end if;
  end if;

  select public.refresh_fpl_projection_fixture_v6_impl(p_fixture_id) into v_rows;
  return v_rows;
end;
$$;


ALTER FUNCTION public.refresh_fpl_projection_fixture_v6(p_fixture_id bigint, p_allow_played boolean) OWNER TO postgres;

--
-- Name: refresh_fpl_projection_fixture_v6_impl(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.refresh_fpl_projection_fixture_v6_impl(p_fixture_id bigint) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_count integer;
  v_has_mc boolean;
begin
  select exists(select 1 from public.fpl_fixture_bonus_montecarlo_v1 where fixture_id = p_fixture_id) into v_has_mc;

  if v_has_mc then
    insert into public.fpl_player_projections(season_id,fixture_id,fpl_player_id,generated_at,model_version,expected_minutes,expected_goals,expected_assists,clean_sheet_probability,expected_saves,defensive_contribution_probability,expected_bonus,xpts_appearance,xpts_goals,xpts_assists,xpts_clean_sheet,xpts_saves,xpts_defensive_contribution,xpts_cards_own_goals,xpts_bonus,expected_fpl_points,start_probability,sub_appearance_probability,xpts_goals_conceded,xpts_penalties,availability_probability,lineup_confidence,tactical_role,minutes_source)
    select public.fpl_current_season_id(),p.fixture_id,p.fpl_player_id,now(),'leaguewide_v6',p.expected_minutes,p.expected_goals,p.expected_assists,p.clean_sheet_probability,case when p.element_type=1 then s.xpts_saves*3 else 0 end,p.defensive_contribution_probability,
      coalesce(mc.expected_bonus_points, p.expected_bonus),
      p.xpts_appearance,p.xpts_goals,p.xpts_assists,p.xpts_clean_sheet,s.xpts_saves,p.xpts_defensive_contribution,s.xpts_cards_own_goals,
      coalesce(mc.expected_bonus_points, p.xpts_bonus),
      (p.xpts_appearance + p.xpts_goals + p.xpts_assists + p.xpts_clean_sheet + p.xpts_defensive_contribution + coalesce(mc.expected_bonus_points, p.xpts_bonus) + s.xpts_saves + s.xpts_goals_conceded + s.xpts_cards_own_goals + s.xpts_penalties) as expected_fpl_points,
      p.prob_starting_xi,p.prob_sub_appearance,s.xpts_goals_conceded,s.xpts_penalties,coalesce(m.availability_probability,1),case m.minutes_source when 'consensus_v3' then .90 when 'lineup_consensus_v3' then .90 when 'squad_state_override' then .95 when 'nailed_history_v6' then .80 when 'strong_history_v6' then .70 else .55 end,coalesce(tc.tactical_role,m.tactical_role,td.tactical_role,case p.element_type when 1 then 'GK' when 2 then 'DEF' when 3 then 'MID' when 4 then 'CF' else 'TBC' end),m.minutes_source
    from public.fpl_projection_leaguewide_final p
      join public.fpl_projection_secondary_scoring s on s.fixture_id=p.fixture_id and s.fpl_player_id=p.fpl_player_id
      left join public.fixture_player_expected_minutes_resolved_v3 m on m.fixture_id=p.fixture_id and m.fpl_player_id=p.fpl_player_id
      left join public.fixture_player_tactical_consensus tc on tc.fixture_id=p.fixture_id and tc.fpl_player_id=p.fpl_player_id
      left join public.team_player_tactical_defaults td on td.season_id = (SELECT public.fpl_current_season_id()) and td.team_id=p.team_id and td.fpl_player_id=p.fpl_player_id
      left join public.fpl_fixture_bonus_montecarlo_v1 mc on mc.fixture_id=p.fixture_id and mc.fpl_player_id=p.fpl_player_id
    where p.fixture_id=p_fixture_id
    on conflict(fixture_id,fpl_player_id,model_version) do update set generated_at=excluded.generated_at,expected_minutes=excluded.expected_minutes,expected_goals=excluded.expected_goals,expected_assists=excluded.expected_assists,clean_sheet_probability=excluded.clean_sheet_probability,expected_saves=excluded.expected_saves,defensive_contribution_probability=excluded.defensive_contribution_probability,expected_bonus=excluded.expected_bonus,xpts_appearance=excluded.xpts_appearance,xpts_goals=excluded.xpts_goals,xpts_assists=excluded.xpts_assists,xpts_clean_sheet=excluded.xpts_clean_sheet,xpts_saves=excluded.xpts_saves,xpts_defensive_contribution=excluded.xpts_defensive_contribution,xpts_cards_own_goals=excluded.xpts_cards_own_goals,xpts_bonus=excluded.xpts_bonus,expected_fpl_points=excluded.expected_fpl_points,start_probability=excluded.start_probability,sub_appearance_probability=excluded.sub_appearance_probability,xpts_goals_conceded=excluded.xpts_goals_conceded,xpts_penalties=excluded.xpts_penalties,availability_probability=excluded.availability_probability,lineup_confidence=excluded.lineup_confidence,tactical_role=excluded.tactical_role,minutes_source=excluded.minutes_source;
  else
    insert into public.fpl_player_projections(season_id,fixture_id,fpl_player_id,generated_at,model_version,expected_minutes,expected_goals,expected_assists,clean_sheet_probability,expected_saves,defensive_contribution_probability,expected_bonus,xpts_appearance,xpts_goals,xpts_assists,xpts_clean_sheet,xpts_saves,xpts_defensive_contribution,xpts_cards_own_goals,xpts_bonus,expected_fpl_points,start_probability,sub_appearance_probability,xpts_goals_conceded,xpts_penalties,availability_probability,lineup_confidence,tactical_role,minutes_source)
    select public.fpl_current_season_id(),p.fixture_id,p.fpl_player_id,now(),'leaguewide_v6',p.expected_minutes,p.expected_goals,p.expected_assists,p.clean_sheet_probability,case when p.element_type=1 then s.xpts_saves*3 else 0 end,p.defensive_contribution_probability,
      coalesce(bv4.expected_bonus_points, p.expected_bonus),
      p.xpts_appearance,p.xpts_goals,p.xpts_assists,p.xpts_clean_sheet,s.xpts_saves,p.xpts_defensive_contribution,s.xpts_cards_own_goals,
      coalesce(bv4.expected_bonus_points, p.xpts_bonus),
      (p.xpts_appearance + p.xpts_goals + p.xpts_assists + p.xpts_clean_sheet + p.xpts_defensive_contribution + coalesce(bv4.expected_bonus_points, p.xpts_bonus) + s.xpts_saves + s.xpts_goals_conceded + s.xpts_cards_own_goals + s.xpts_penalties) as expected_fpl_points,
      p.prob_starting_xi,p.prob_sub_appearance,s.xpts_goals_conceded,s.xpts_penalties,coalesce(m.availability_probability,1),case m.minutes_source when 'consensus_v3' then .90 when 'lineup_consensus_v3' then .90 when 'squad_state_override' then .95 when 'nailed_history_v6' then .80 when 'strong_history_v6' then .70 else .55 end,coalesce(tc.tactical_role,m.tactical_role,td.tactical_role,case p.element_type when 1 then 'GK' when 2 then 'DEF' when 3 then 'MID' when 4 then 'CF' else 'TBC' end),m.minutes_source
    from public.fpl_projection_leaguewide_final p
      join public.fpl_projection_secondary_scoring s on s.fixture_id=p.fixture_id and s.fpl_player_id=p.fpl_player_id
      left join public.fixture_player_expected_minutes_resolved_v3 m on m.fixture_id=p.fixture_id and m.fpl_player_id=p.fpl_player_id
      left join public.fixture_player_tactical_consensus tc on tc.fixture_id=p.fixture_id and tc.fpl_player_id=p.fpl_player_id
      left join public.team_player_tactical_defaults td on td.season_id = (SELECT public.fpl_current_season_id()) and td.team_id=p.team_id and td.fpl_player_id=p.fpl_player_id
      left join public.get_fpl_fixture_bonus_v4(p_fixture_id) bv4 on bv4.fpl_player_id=p.fpl_player_id
    where p.fixture_id=p_fixture_id
    on conflict(fixture_id,fpl_player_id,model_version) do update set generated_at=excluded.generated_at,expected_minutes=excluded.expected_minutes,expected_goals=excluded.expected_goals,expected_assists=excluded.expected_assists,clean_sheet_probability=excluded.clean_sheet_probability,expected_saves=excluded.expected_saves,defensive_contribution_probability=excluded.defensive_contribution_probability,expected_bonus=excluded.expected_bonus,xpts_appearance=excluded.xpts_appearance,xpts_goals=excluded.xpts_goals,xpts_assists=excluded.xpts_assists,xpts_clean_sheet=excluded.xpts_clean_sheet,xpts_saves=excluded.xpts_saves,xpts_defensive_contribution=excluded.xpts_defensive_contribution,xpts_cards_own_goals=excluded.xpts_cards_own_goals,xpts_bonus=excluded.xpts_bonus,expected_fpl_points=excluded.expected_fpl_points,start_probability=excluded.start_probability,sub_appearance_probability=excluded.sub_appearance_probability,xpts_goals_conceded=excluded.xpts_goals_conceded,xpts_penalties=excluded.xpts_penalties,availability_probability=excluded.availability_probability,lineup_confidence=excluded.lineup_confidence,tactical_role=excluded.tactical_role,minutes_source=excluded.minutes_source;
  end if;

  get diagnostics v_count = row_count;
  return v_count;
end;
$$;


ALTER FUNCTION public.refresh_fpl_projection_fixture_v6_impl(p_fixture_id bigint) OWNER TO postgres;

--
-- Name: refresh_fpl_projections_range(integer, integer, bigint, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.refresh_fpl_projections_range(p_from_matchweek integer, p_to_matchweek integer, p_season_id bigint DEFAULT public.fpl_current_season_id(), p_league_id bigint DEFAULT 1) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_fixture record;
  v_total integer := 0;
begin
  for v_fixture in select fixture_id from public.fixtures where matchweek between p_from_matchweek and p_to_matchweek and season_id = p_season_id and league_id = p_league_id
  loop
    perform public.refresh_fpl_projection_fixture_v6(v_fixture.fixture_id);
    v_total := v_total + 1;
  end loop;
  return v_total;
end;
$$;


ALTER FUNCTION public.refresh_fpl_projections_range(p_from_matchweek integer, p_to_matchweek integer, p_season_id bigint, p_league_id bigint) OWNER TO postgres;

--
-- Name: refresh_history_derived(boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.refresh_history_derived(p_force boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  r record;
  v_seasons int := 0;
  v_rows bigint := 0;
  v_started timestamptz := clock_timestamp();
begin
  for r in
    select m.league_id, m.season_id
    from public.matches m join public.leagues l on l.league_id = m.league_id and l.competition_type = 'league'
    where m.full_time_home_goals is not null
    group by m.league_id, m.season_id
    having p_force
        or count(*) * 2 <> coalesce((select count(*) from public.team_match_snapshot s
                                     where s.league_id = m.league_id and s.season_id = m.season_id), 0)
        or max(m.updated_at) > coalesce((select min(s.refreshed_at) from public.team_match_snapshot s
                                         where s.league_id = m.league_id and s.season_id = m.season_id), '-infinity')
        or exists (select 1 from public.point_deductions d where d.league_id = m.league_id and d.season_id = m.season_id
                   and d.created_at > coalesce((select min(s.refreshed_at) from public.team_match_snapshot s
                                                where s.league_id = m.league_id and s.season_id = m.season_id), '-infinity'))
  loop
    v_rows := v_rows + public.refresh_team_match_snapshot(r.league_id, r.season_id);
    v_seasons := v_seasons + 1;
  end loop;

  refresh materialized view concurrently public.team_season_summary;
  refresh materialized view concurrently public.league_season_summary;
  refresh materialized view concurrently public.league_pace_benchmarks;
  refresh materialized view concurrently public.league_table_reliability;
  if v_seasons > 0 or p_force then
    refresh materialized view concurrently public.history_streaks;
  end if;

  return jsonb_build_object('league_seasons_rebuilt', v_seasons, 'snapshot_rows', v_rows,
    'seconds', round(extract(epoch from clock_timestamp() - v_started)::numeric, 1));
end;
$$;


ALTER FUNCTION public.refresh_history_derived(p_force boolean) OWNER TO postgres;

--
-- Name: refresh_model_scorecard(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.refresh_model_scorecard() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  refresh materialized view concurrently public.model_scorecard_matches;
  return (select count(*)::integer from public.model_scorecard_matches);
end $$;


