--
-- Name: resolve_broadcast_team(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.resolve_broadcast_team(p_raw text) RETURNS bigint
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with c as (
    select 1 lvl, team_id from public.team_aliases where source_name = 'Airtable' and raw_name = p_raw
    union all select 2, team_id from public.teams where lower(canonical_name) = lower(p_raw) or lower(display_name) = lower(p_raw)
    union all select 3, team_id from public.team_aliases where raw_name = p_raw
  ), lv as (
    select lvl, min(team_id) team_id, count(distinct team_id) n from c group by lvl
  )
  select team_id from lv where n = 1 order by lvl limit 1;
$$;


ALTER FUNCTION public.resolve_broadcast_team(p_raw text) OWNER TO postgres;

--
-- Name: safe_numeric(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.safe_numeric(p_text text) RETURNS numeric
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $_$
  select case
    when p_text ~ '^-?[0-9]+(\.[0-9]+)?$' then p_text::numeric
    else null
  end;
$_$;


ALTER FUNCTION public.safe_numeric(p_text text) OWNER TO postgres;

--
-- Name: score_model_experiment(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.score_model_experiment(p_experiment text) RETURNS TABLE(variant text, league_id bigint, season_id bigint, n bigint, ll_model numeric, ll_market numeric, p_draw numeric, draws bigint, pred_goals numeric, goals bigint)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  with e as (select * from public.model_experiment_predictions where experiment = p_experiment),
  common as (select match_id from e group by match_id having count(distinct variant) = (select count(distinct variant) from e)),
  mk as (select o.match_id, 1/o.price_home ih, 1/o.price_draw id, 1/o.price_away ia from public.match_odds o
         where o.market = '1x2' and o.is_closing and o.bookmaker = 'Avg' and o.price_home > 1 and o.price_draw > 1 and o.price_away > 1)
  select e.variant, m.league_id, m.season_id, count(*),
    sum(-ln((case when m.full_time_home_goals > m.full_time_away_goals then e.p_home when m.full_time_home_goals = m.full_time_away_goals then e.p_draw else e.p_away end)::numeric)),
    sum(-ln(case when m.full_time_home_goals > m.full_time_away_goals then mk.ih when m.full_time_home_goals = m.full_time_away_goals then mk.id else mk.ia end / (mk.ih + mk.id + mk.ia))),
    sum(e.p_draw::numeric), count(*) filter (where m.full_time_home_goals = m.full_time_away_goals),
    sum((e.pred_home_goals + e.pred_away_goals)::numeric), sum(m.full_time_home_goals + m.full_time_away_goals)
  from e join common using (match_id) join public.matches m using (match_id) join mk using (match_id)
  where e.as_of_date < m.match_date::date
  group by 1, 2, 3;
$$;


ALTER FUNCTION public.score_model_experiment(p_experiment text) OWNER TO postgres;

--
-- Name: search_players(text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.search_players(p_query text, p_limit integer DEFAULT 20) RETURNS TABLE(fpl_code bigint, slug text, canonical_name text, latest_web_name text, latest_team text, element_type integer, seasons_played bigint, career_points bigint, first_season text, last_season text, current_slug text)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with matches as (
    select i.fpl_code, i.slug, i.canonical_name, i.first_seen_season_id, i.last_seen_season_id
    from public.player_identity i
    where p_query is not null and length(trim(p_query)) >= 2
      and i.canonical_name ilike '%' || trim(p_query) || '%'
  ),
  agg as (
    select m.fpl_code, m.slug, m.canonical_name, m.first_seen_season_id, m.last_seen_season_id,
      count(*)::bigint seasons_played, sum(t.total_points)::bigint career_points,
      (array_agg(t.web_name order by public.season_start_year(t.season_id) desc))[1] latest_web_name,
      (array_agg(t.team_name order by public.season_start_year(t.season_id) desc))[1] latest_team,
      (array_agg(t.element_type order by public.season_start_year(t.season_id) desc))[1] element_type
    from matches m
    join public.fpl_player_season_totals t on t.fpl_code = m.fpl_code
    group by m.fpl_code, m.slug, m.canonical_name, m.first_seen_season_id, m.last_seen_season_id
  )
  select a.fpl_code, a.slug, a.canonical_name, a.latest_web_name, a.latest_team, a.element_type,
    a.seasons_played, a.career_points, fs.slug, ls.slug,
    (select p.slug from public.fpl_players p where p.fpl_code = a.fpl_code and p.season_id = (SELECT public.fpl_current_season_id()) limit 1)
  from agg a
  left join public.seasons fs on fs.season_id = a.first_seen_season_id
  left join public.seasons ls on ls.season_id = a.last_seen_season_id
  order by a.career_points desc
  limit greatest(1, least(p_limit, 50));
$$;


ALTER FUNCTION public.search_players(p_query text, p_limit integer) OWNER TO postgres;

--
-- Name: season_id_for_date(date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.season_id_for_date(p_date date) RETURNS bigint
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  -- The season whose 1 July - 30 June window contains p_date (null if no
  -- seasons row covers it).
  select s.season_id from public.seasons s
   where p_date >= make_date(s.start_year, 7, 1)
     and p_date <  make_date(s.start_year + 1, 7, 1)
   order by s.start_year desc
   limit 1
$$;


ALTER FUNCTION public.season_id_for_date(p_date date) OWNER TO postgres;

--
-- Name: season_start_year(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.season_start_year(p_season_id bigint) RETURNS integer
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  -- The chronological sort key for a season. season_id is NOT in date
  -- order (historic seasons were added after 2026/27); sort by this.
  select start_year from public.seasons where season_id = p_season_id
$$;


ALTER FUNCTION public.season_start_year(p_season_id bigint) OWNER TO postgres;

--
-- Name: set_current_season_id(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.set_current_season_id() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_season bigint;
begin
  if new.season_id is not null then
    return new;
  end if;
  -- Seasons run August to May, so the season a date belongs to is the
  -- one whose August start it falls after. Derived rather than
  -- hardcoded, so this keeps working at the 2027/28 rollover instead of
  -- silently stamping next season's data as 2026/27.
  select s.season_id into v_season
  from public.seasons s
  where current_date >= make_date(s.start_year, 8, 1)
    and current_date <  make_date(s.end_year, 8, 1)
  limit 1;

  new.season_id := v_season;
  return new;
end;
$$;


ALTER FUNCTION public.set_current_season_id() OWNER TO postgres;

--
-- Name: set_fixture_market_goals(bigint, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.set_fixture_market_goals(p_league_id bigint, p_rows jsonb) RETURNS integer
    LANGUAGE sql
    SET search_path TO 'public'
    AS $$
  with x as (
    select f.fixture_id, r.home, r.away
    from public.fixtures f
    left join jsonb_to_recordset(coalesce(p_rows, '[]'::jsonb)) as r(fixture_id bigint, home double precision, away double precision)
      on r.fixture_id = f.fixture_id
    where f.league_id = p_league_id and f.status = 'scheduled'
  ), u as (
    update public.fixtures f
    set market_home_goals = x.home, market_away_goals = x.away,
        market_rated_at = case when x.home is null then null else now() end
    from x where f.fixture_id = x.fixture_id
    returning (x.home is not null) as rated
  )
  select count(*) filter (where rated)::int from u
$$;


ALTER FUNCTION public.set_fixture_market_goals(p_league_id bigint, p_rows jsonb) OWNER TO postgres;

--
-- Name: set_fpl_code_from_payload(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.set_fpl_code_from_payload() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if new.fpl_code is null and new.source_payload ? 'code' then
    new.fpl_code := (new.source_payload->>'code')::bigint;
  end if;
  return new;
end;
$$;


ALTER FUNCTION public.set_fpl_code_from_payload() OWNER TO postgres;

--
-- Name: set_player_identity_slug(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.set_player_identity_slug() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_base text; v_candidate text; v_suffix int := 1;
begin
  if tg_op = 'UPDATE' and new.slug is not null and new.canonical_name is not distinct from old.canonical_name then
    return new;                              -- name unchanged: leave the slug alone
  end if;
  if new.slug is not null and new.slug <> '' then
    return new;                              -- caller supplied one
  end if;
  v_base := public.slugify_player_name(new.canonical_name);
  if v_base is null or v_base = '' then
    v_base := 'player-' || new.fpl_code::text;
  end if;
  v_candidate := v_base;
  while exists (select 1 from public.player_identity pi
                where pi.slug = v_candidate and pi.fpl_code <> new.fpl_code) loop
    v_suffix := v_suffix + 1;
    v_candidate := v_base || '-' || v_suffix::text;
  end loop;
  new.slug := v_candidate;
  return new;
end $$;


ALTER FUNCTION public.set_player_identity_slug() OWNER TO postgres;

--
-- Name: slugify(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.slugify(input text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select nullif(
    trim(both '-' from
      regexp_replace(
        regexp_replace(lower(public.unaccent(coalesce(input, ''))), '[^a-z0-9]+', '-', 'g'),
        '-{2,}', '-', 'g'
      )
    ),
    ''
  )
$$;


ALTER FUNCTION public.slugify(input text) OWNER TO postgres;

--
-- Name: slugify_player_name(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.slugify_player_name(p_name text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select nullif(
    trim(both '-' from
      regexp_replace(
        regexp_replace(
          lower(unaccent(coalesce(p_name, ''))),
          '[^a-z0-9]+', '-', 'g'
        ),
        '-{2,}', '-', 'g'
      )
    ),
  '');
$$;


ALTER FUNCTION public.slugify_player_name(p_name text) OWNER TO postgres;

--
-- Name: snapshot_due_fpl_projections(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.snapshot_due_fpl_projections() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare g record; v_out jsonb := '[]'; v_refresh text;
begin
  for g in
    select gw.season_id, gw.fpl_event_id, gw.deadline_time,
      exists (select 1 from public.fpl_projection_snapshots s where s.season_id = gw.season_id and s.fpl_event_id = gw.fpl_event_id
              and s.snapshot_kind in ('pre_deadline','late')) already,
      (select min(kickoff_time) from public.fpl_fixtures ff where ff.season_id = gw.season_id and ff.fpl_event_id = gw.fpl_event_id) first_kickoff
    from public.fpl_gameweeks gw
    where gw.deadline_time between now() - interval '2 days' and now() + interval '60 minutes'
  loop
    continue when g.already;
    if now() <= g.deadline_time then
      begin
        perform private.refresh_fpl();
        v_refresh := 'ok';
      exception when others then
        v_refresh := 'failed: ' || sqlerrm;
      end;
      v_out := v_out || (public.snapshot_fpl_projections(g.season_id, g.fpl_event_id, 'pre_deadline')
                         || jsonb_build_object('fpl_refresh', v_refresh));
    elsif g.first_kickoff is null or now() < g.first_kickoff then
      v_out := v_out || public.snapshot_fpl_projections(g.season_id, g.fpl_event_id, 'late');
    end if;
  end loop;
  return v_out;
end;
$$;


ALTER FUNCTION public.snapshot_due_fpl_projections() OWNER TO postgres;

--
-- Name: snapshot_fpl_projections(bigint, integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.snapshot_fpl_projections(p_season_id bigint, p_event integer, p_kind text DEFAULT 'manual'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_deadline timestamptz; v_players int; v_fixtures int; v_state int;
begin
  select deadline_time into v_deadline from public.fpl_gameweeks where season_id = p_season_id and fpl_event_id = p_event;
  if v_deadline is null then raise exception 'No gameweek % in season %', p_event, p_season_id; end if;

  insert into public.fpl_projection_fixture_snapshots (season_id, fpl_event_id, snapshot_kind, deadline_time, fixture_id,
    predicted_home_goals, predicted_away_goals, kickoff_date, kickoff_time)
  select p_season_id, p_event, p_kind, v_deadline, f.fixture_id, f.predicted_home_goals, f.predicted_away_goals, f.kickoff_date, f.kickoff_time
  from public.fpl_fixtures ff join public.fixtures f on f.fixture_id = ff.canonical_fixture_id
  where ff.season_id = p_season_id and ff.fpl_event_id = p_event
  on conflict do nothing;
  get diagnostics v_fixtures = row_count;

  insert into public.fpl_projection_snapshots (season_id, fpl_event_id, snapshot_kind, deadline_time, fixture_id, fpl_player_id,
    model_version, projection_generated_at, expected_minutes, start_probability, sub_appearance_probability, availability_probability,
    lineup_confidence, minutes_source, tactical_role, expected_goals, expected_assists, clean_sheet_probability, expected_saves,
    defensive_contribution_probability, expected_bonus, xpts_appearance, xpts_goals, xpts_assists, xpts_clean_sheet, xpts_saves,
    xpts_defensive_contribution, xpts_cards_own_goals, xpts_bonus, xpts_goals_conceded, xpts_penalties, expected_fpl_points)
  select p_season_id, p_event, p_kind, v_deadline, p.fixture_id, p.fpl_player_id, p.model_version, p.generated_at,
    p.expected_minutes, p.start_probability, p.sub_appearance_probability, p.availability_probability, p.lineup_confidence,
    p.minutes_source, p.tactical_role, p.expected_goals, p.expected_assists, p.clean_sheet_probability, p.expected_saves,
    p.defensive_contribution_probability, p.expected_bonus, p.xpts_appearance, p.xpts_goals, p.xpts_assists, p.xpts_clean_sheet,
    p.xpts_saves, p.xpts_defensive_contribution, p.xpts_cards_own_goals, p.xpts_bonus, p.xpts_goals_conceded, p.xpts_penalties,
    p.expected_fpl_points
  from public.fpl_player_projections p
  join public.fpl_fixtures ff on ff.canonical_fixture_id = p.fixture_id and ff.season_id = p_season_id and ff.fpl_event_id = p_event
  on conflict do nothing;
  get diagnostics v_players = row_count;

  insert into public.fpl_deadline_player_state (season_id, fpl_event_id, snapshot_kind, deadline_time, fpl_player_id, fpl_code,
    fpl_team_id, element_type, status, chance_of_playing_this_round, chance_of_playing_next_round, news, news_added,
    now_cost, selected_by_percent, form, ep_this, ep_next, transfers_in_event, transfers_out_event, total_points, minutes,
    source_updated_at, source_payload)
  select p_season_id, p_event, p_kind, v_deadline, fp.fpl_player_id, fp.fpl_code,
    fp.fpl_team_id, fp.element_type, fp.status, fp.chance_of_playing_this_round, fp.chance_of_playing_next_round, fp.news, fp.news_added,
    fp.now_cost, fp.selected_by_percent,
    public.safe_numeric(fp.source_payload->>'form'),
    public.safe_numeric(fp.source_payload->>'ep_this'),
    public.safe_numeric(fp.source_payload->>'ep_next'),
    public.safe_numeric(fp.source_payload->>'transfers_in_event')::bigint,
    public.safe_numeric(fp.source_payload->>'transfers_out_event')::bigint,
    fp.total_points, fp.minutes, fp.updated_at, fp.source_payload
  from public.fpl_players fp
  where fp.season_id = p_season_id
  on conflict do nothing;
  get diagnostics v_state = row_count;

  return jsonb_build_object('event', p_event, 'kind', p_kind, 'deadline', v_deadline, 'fixtures', v_fixtures,
    'player_rows', v_players, 'player_state_rows', v_state);
end;
$$;


ALTER FUNCTION public.snapshot_fpl_projections(p_season_id bigint, p_event integer, p_kind text) OWNER TO postgres;

--
-- Name: sync_airtable_broadcasts(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sync_airtable_broadcasts(p_records jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  r jsonb; f jsonb; rid text;
  v_match text; v_date date; v_home_raw text; v_away_raw text; v_comp text; v_code text; v_league bigint;
  v_home bigint; v_away bigint; v_fixture bigint; v_tie boolean; v_reason text;
  v_status text; v_access text; v_conf text; v_delivery text[];
  v_row public.fixture_broadcasts%rowtype; v_existing public.fixture_broadcasts%rowtype; v_found boolean;
  n_seen int := 0; n_ins int := 0; n_upd int := 0; n_same int := 0; n_kept int := 0; n_unm int := 0;
  synced text[] := '{}'; unmatched jsonb := '[]'; v_run bigint;
  sel constant text := 'name';
begin
  for r in select * from jsonb_array_elements(p_records) loop
    n_seen := n_seen + 1;
    rid := r->>'id';
    f := coalesce(r->'cellValuesByFieldId', r->'fields', '{}'::jsonb);
    v_match    := f->>'flddeM6xuoqoaPzea';
    v_date     := nullif(f->>'fldMtKYUVzWSvfjsw','')::date;
    v_home_raw := trim(f->>'fldiJTg56BqKPlJgd');
    v_away_raw := trim(f->>'fldpfiQHbbfjbDhn7');
    v_comp     := coalesce(nullif(trim(f->>'fldmK8oDxqwE9qzqJ'),''), f->'fldBFu0wI75sQ8k6B'->>sel, f->>'fldBFu0wI75sQ8k6B');
    v_code     := (select league_code from public.broadcast_competition_map where label = v_comp);
    v_league   := (select league_id from public.leagues where code = v_code);
    v_reason := null; v_fixture := null;

    if rid is null or v_date is null or v_home_raw is null or v_away_raw is null then
      v_reason := 'missing record id, date or team';
    else
      v_home := public.resolve_broadcast_team(v_home_raw);
      v_away := public.resolve_broadcast_team(v_away_raw);
      if v_home is null then v_reason := 'unknown team: ' || v_home_raw; end if;
      if v_away is null then v_reason := coalesce(v_reason || '; ', '') || 'unknown team: ' || v_away_raw; end if;
      if v_comp is not null and v_code is null then
        v_reason := coalesce(v_reason || '; ', '') || 'competition not mapped: ' || v_comp;
      elsif v_code is not null and v_league is null then
        v_reason := coalesce(v_reason || '; ', '') || 'competition not in database: ' || v_comp;
      end if;
    end if;

    if v_reason is null then
      select x.fixture_id, x.tie into v_fixture, v_tie from (
        select fx.fixture_id,
          count(*) over (partition by abs(fx.kickoff_date - v_date)) > 1 tie,
          abs(fx.kickoff_date - v_date) dist
        from public.fixtures fx
        where fx.home_team_id = v_home and fx.away_team_id = v_away
          and fx.kickoff_date between v_date - 3 and v_date + 3
          and (v_league is null or fx.league_id = v_league)
        order by dist limit 1) x;
      if v_fixture is null then v_reason := 'no fixture within 3 days';
      elsif v_tie then v_reason := 'ambiguous fixture'; v_fixture := null; end if;
    end if;

    if v_reason is not null then
      n_unm := n_unm + 1;
      unmatched := unmatched || jsonb_build_object('id', rid, 'match', v_match, 'reason', v_reason);
      insert into public.broadcast_sync_unmatched (airtable_record_id, match_label, kickoff_date, home_raw, away_raw, competition_label, reason, record)
      values (coalesce(rid, 'missing-' || md5(r::text)), v_match, v_date, v_home_raw, v_away_raw, v_comp, v_reason, r)
      on conflict (airtable_record_id) do update set match_label = excluded.match_label, kickoff_date = excluded.kickoff_date,
        home_raw = excluded.home_raw, away_raw = excluded.away_raw, competition_label = excluded.competition_label,
        reason = excluded.reason, record = excluded.record, last_seen_at = now(), resolved_at = null;
      continue;
    end if;

    v_status := case when (f->'fld2ke4qZAxCzthoG'->>sel) = 'Confirmed not televised' then 'confirmed_not_televised' else 'confirmed_broadcast' end;
    v_access := case f->'fldC79K6Q8tQJEGzn'->>sel
      when 'Free' then 'free' when 'Free with compatible device' then 'free_compatible_device'
      when 'Subscription' then 'subscription' when 'PPV' then 'ppv' when 'Unknown' then 'unknown'
      else case when (f->>'fldZmTOM5AulyXZ3j')::boolean then 'ppv'
                when (f->>'fldJcv7Kh5u3HkCj8')::boolean then 'free'
                when (f->>'fldgg1RA8DF9oTFrV')::boolean then 'subscription' end end;
    v_conf := case f->'fld2paMWsFES1xcJW'->>sel
      when 'Confirmed - primary source' then 'confirmed_primary' when 'Confirmed - reliable secondary' then 'confirmed_secondary'
      when 'Probable' then 'probable' when 'Needs verification' then 'needs_verification' end;
    select coalesce(array_agg(distinct case d->>sel when 'TV channel' then 'tv_channel' when 'Streaming' then 'streaming'
      when 'FAST' then 'fast' when 'Web' then 'web' when 'App' then 'app' end) filter (where d->>sel is not null), '{}')
      into v_delivery from jsonb_array_elements(coalesce(f->'fld4n1V81E2yrUfHc', '[]'::jsonb)) d;

    v_row := null;
    v_row.fixture_id := v_fixture; v_row.market := 'GB'; v_row.status := v_status;
    v_row.airtable_record_id := rid; v_row.competition_label := v_comp;
    v_row.source := coalesce(nullif(f->>'fldfCjtvOiCOVhnCn',''), 'Airtable');
    v_row.source_url := nullif(f->>'fldBXex42rGUfLPOv','');
    v_row.verified_at := coalesce(nullif(f->>'fldfJd50DRoyC5S3D','')::timestamptz, now());
    v_row.confidence := v_conf;
    v_row.availability_notes := nullif(coalesce(f->>'fldCitDScZReOzIje', f->>'fldP2hFkflQx0r94y'),'');
    v_row.delivery_methods := '{}'; v_row.is_fast := false;
    v_row.is_free_to_air := false; v_row.is_subscription := false; v_row.is_ppv := false;
    if v_status = 'confirmed_broadcast' then
      v_row.broadcaster := coalesce(nullif(trim(f->>'fld2FM3N1abudVRXm'),''), 'Unknown');
      v_row.channel := nullif(trim(f->>'fldi4828fym50CtEk'),'');
      v_row.streaming_service := nullif(trim(f->>'fldJvGS3iqvmD568s'),'');
      v_row.service_product := nullif(trim(f->>'fldaSUf1mQ1hjlRvf'),'');
      v_row.watch_url := nullif(f->>'fldnN8HersdQmC6t2','');
      v_row.access_type := v_access;
      v_row.delivery_methods := v_delivery;
      v_row.platform_device := nullif(trim(f->>'fldzUcmQsuCu3nOjU'),'');
      v_row.is_live := coalesce((f->>'fldthqHgW0SyD7aaU')::boolean, true);
      v_row.uk_available := coalesce((f->>'fldig3IxVuSB2OY8F')::boolean, true);
      v_row.is_fast := coalesce((f->>'fldrz9HaAUpscP5dA')::boolean, false) or 'fast' = any(v_delivery);
      v_row.is_free_to_air := v_access in ('free','free_compatible_device');
      v_row.is_subscription := v_access = 'subscription';
      v_row.is_ppv := v_access = 'ppv';
    end if;

    select * into v_existing from public.fixture_broadcasts where airtable_record_id = rid;
    v_found := found;
    if not v_found then
      select * into v_existing from public.fixture_broadcasts fb
      where fb.airtable_record_id is null and fb.fixture_id = v_fixture and fb.status = v_status
        and (v_status = 'confirmed_not_televised' or lower(fb.broadcaster) = lower(v_row.broadcaster))
      order by fb.broadcast_id limit 1;
      v_found := found;
    end if;

    if not v_found then
      insert into public.fixture_broadcasts (fixture_id, market, status, broadcaster, channel, streaming_service, is_free_to_air, is_subscription, is_ppv,
        watch_url, source, source_url, verified_at, airtable_record_id, service_product, access_type, delivery_methods, platform_device,
        is_live, uk_available, is_fast, confidence, availability_notes, competition_label, last_synced_at)
      values (v_row.fixture_id, v_row.market, v_row.status, v_row.broadcaster, v_row.channel, v_row.streaming_service, v_row.is_free_to_air,
        v_row.is_subscription, v_row.is_ppv, v_row.watch_url, v_row.source, v_row.source_url, v_row.verified_at, rid, v_row.service_product,
        v_row.access_type, v_row.delivery_methods, v_row.platform_device, v_row.is_live, v_row.uk_available, v_row.is_fast, v_row.confidence,
        v_row.availability_notes, v_row.competition_label, now());
      n_ins := n_ins + 1;
    elsif (v_existing.fixture_id, v_existing.status, v_existing.broadcaster, v_existing.channel, v_existing.streaming_service,
           v_existing.service_product, v_existing.access_type, v_existing.delivery_methods, v_existing.platform_device, v_existing.is_live,
           v_existing.uk_available, v_existing.is_fast, v_existing.confidence, v_existing.availability_notes, v_existing.watch_url,
           v_existing.source, v_existing.source_url, v_existing.verified_at, v_existing.airtable_record_id)
      is not distinct from
          (v_row.fixture_id, v_row.status, v_row.broadcaster, v_row.channel, v_row.streaming_service,
           v_row.service_product, v_row.access_type, v_row.delivery_methods, v_row.platform_device, v_row.is_live,
           v_row.uk_available, v_row.is_fast, v_row.confidence, v_row.availability_notes, v_row.watch_url,
           v_row.source, v_row.source_url, v_row.verified_at, rid) then
      update public.fixture_broadcasts set last_synced_at = now() where broadcast_id = v_existing.broadcast_id;
      n_same := n_same + 1;
    else
      update public.fixture_broadcasts set fixture_id = v_row.fixture_id, status = v_row.status, broadcaster = v_row.broadcaster,
        channel = v_row.channel, streaming_service = v_row.streaming_service, is_free_to_air = v_row.is_free_to_air,
        is_subscription = v_row.is_subscription, is_ppv = v_row.is_ppv, watch_url = coalesce(v_row.watch_url, watch_url),
        source = v_row.source, source_url = v_row.source_url, verified_at = v_row.verified_at, airtable_record_id = rid,
        service_product = v_row.service_product, access_type = v_row.access_type, delivery_methods = v_row.delivery_methods,
        platform_device = v_row.platform_device, is_live = v_row.is_live, uk_available = v_row.uk_available, is_fast = v_row.is_fast,
        confidence = v_row.confidence, availability_notes = v_row.availability_notes, competition_label = v_row.competition_label,
        last_synced_at = now(), updated_at = now()
      where broadcast_id = v_existing.broadcast_id;
      n_upd := n_upd + 1;
    end if;

    synced := synced || rid;
    update public.broadcast_sync_unmatched set resolved_at = now() where airtable_record_id = rid and resolved_at is null;
  end loop;

  -- Saturday 3pm blackout rows, after Airtable so a real listing wins.
  perform public.apply_uk_3pm_blackout();

  insert into public.broadcast_sync_runs (records_seen, inserted, updated, unchanged, kept_stronger, unmatched)
  values (n_seen, n_ins, n_upd, n_same, n_kept, n_unm) returning run_id into v_run;

  return jsonb_build_object('run_id', v_run, 'seen', n_seen, 'inserted', n_ins, 'updated', n_upd, 'unchanged', n_same,
    'kept_stronger', n_kept, 'unmatched', n_unm, 'synced_ids', to_jsonb(synced), 'unmatched_records', unmatched);
end;
$$;


ALTER FUNCTION public.sync_airtable_broadcasts(p_records jsonb) OWNER TO postgres;

--
-- Name: sync_airtable_broadcasts_from_api(boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sync_airtable_broadcasts_from_api(p_update_airtable boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'vault', 'pg_catalog'
    AS $$
declare
  v_token text; v_url text; v_offset text; v_status int; v_body jsonb;
  v_records jsonb := '[]'; v_pages int := 0; v_result jsonb;
  v_synced text[]; v_unmatched text[]; v_ticked text[]; v_to_tick text[]; v_to_untick text[];
  v_batch jsonb; v_patched int := 0; v_patch_errors int := 0; i int;
  v_prune text[]; v_pruned int := 0; v_prune_errors int := 0; v_qs text;
  c_base constant text := 'appstYcYUotrVwbVJ';
  c_table constant text := 'tblhMHaKsodKoD6sV';
  c_synced constant text := 'fldegUzhGYWDPaA2R';
begin
  select decrypted_secret into v_token from vault.decrypted_secrets where name = 'airtable_token';
  if v_token is null then raise exception 'airtable_token not found in Vault'; end if;
  perform extensions.http_set_curlopt('CURLOPT_TIMEOUT', '30');

  -- page through every record (100 per page)
  loop
    v_url := format('https://api.airtable.com/v0/%s/%s?pageSize=100&returnFieldsByFieldId=true', c_base, c_table)
             || coalesce('&offset=' || v_offset, '');
    select status, content::jsonb into v_status, v_body
    from extensions.http(('GET', v_url, array[extensions.http_header('Authorization', 'Bearer ' || v_token)], null, null)::extensions.http_request);
    if v_status <> 200 then raise exception 'Airtable list returned HTTP % on page %', v_status, v_pages + 1; end if;
    v_pages := v_pages + 1;
    -- The API gives select values as plain strings; the sync expects the
    -- connector's {name: ...} shape. Normalise single- and multi-selects.
    v_records := v_records || coalesce((
      select jsonb_agg(jsonb_build_object('id', r->>'id', 'fields',
        (select coalesce(jsonb_object_agg(k,
           case
             when k in ('fld2ke4qZAxCzthoG','fldC79K6Q8tQJEGzn','fld2paMWsFES1xcJW','fldBFu0wI75sQ8k6B') and jsonb_typeof(v) = 'string'
               then jsonb_build_object('name', v #>> '{}')
             when k = 'fld4n1V81E2yrUfHc' and jsonb_typeof(v) = 'array'
               then (select coalesce(jsonb_agg(case when jsonb_typeof(x) = 'string' then jsonb_build_object('name', x #>> '{}') else x end), '[]') from jsonb_array_elements(v) x)
             else v end), '{}')
         from jsonb_each(r->'fields') as e(k, v))))
      from jsonb_array_elements(v_body->'records') r), '[]');
    v_offset := v_body->>'offset';
    exit when v_offset is null;
    perform pg_sleep(0.25); -- Airtable allows 5 requests/second per base
  end loop;

  v_result := public.sync_airtable_broadcasts(v_records);

  if p_update_airtable then
    v_synced := array(select jsonb_array_elements_text(v_result->'synced_ids'));
    v_unmatched := array(select x->>'id' from jsonb_array_elements(v_result->'unmatched_records') x where x->>'id' is not null);
    v_ticked := array(select r->>'id' from jsonb_array_elements(v_records) r where (r->'fields'->>c_synced)::boolean);
    v_to_tick := array(select unnest(v_synced) except select unnest(v_ticked));
    v_to_untick := array(select unnest(v_unmatched) intersect select unnest(v_ticked));

    -- PATCH in batches of 10 (Airtable's per-request limit)
    for i in 0 .. greatest(ceil((coalesce(array_length(v_to_tick,1),0) + coalesce(array_length(v_to_untick,1),0)) / 10.0)::int - 1, -1) loop
      select jsonb_build_object('records', jsonb_agg(jsonb_build_object('id', id, 'fields', jsonb_build_object(c_synced, val))))
      into v_batch
      from (select id, val from (
              select unnest(v_to_tick) id, true val
              union all select unnest(v_to_untick), false) all_changes
            order by id offset i * 10 limit 10) b;
      select status into v_status from extensions.http((
        'PATCH', format('https://api.airtable.com/v0/%s/%s', c_base, c_table),
        array[extensions.http_header('Authorization', 'Bearer ' || v_token)], 'application/json', v_batch::text)::extensions.http_request);
      if v_status = 200 then v_patched := v_patched + jsonb_array_length(v_batch->'records');
      else v_patch_errors := v_patch_errors + 1; end if;
      perform pg_sleep(0.25);
    end loop;
  end if;

  -- Prune: Airtable's free plan caps a base at 1,000 records, so rows for
  -- matches played more than a day ago are deleted from Airtable once the
  -- site holds them (the site copy is permanent; the sync never deletes a
  -- site row because Airtable no longer lists it). Unmatched records are
  -- never pruned -- they're not on the site yet.
  if p_update_airtable then
    v_prune := array(
      select fb.airtable_record_id from public.fixture_broadcasts fb
      join public.fixtures f on f.fixture_id = fb.fixture_id
      where fb.airtable_record_id = any(array(select jsonb_array_elements_text(v_result->'synced_ids')))
        and f.kickoff_date < current_date - 1);
    for i in 0 .. greatest(ceil(coalesce(array_length(v_prune,1),0) / 10.0)::int - 1, -1) loop
      select string_agg('records%5B%5D=' || id, '&') into v_qs
      from (select unnest(v_prune) id order by 1 offset i * 10 limit 10) b;
      select status into v_status from extensions.http((
        'DELETE', format('https://api.airtable.com/v0/%s/%s?%s', c_base, c_table, v_qs),
        array[extensions.http_header('Authorization', 'Bearer ' || v_token)], null, null)::extensions.http_request);
      if v_status = 200 then v_pruned := v_pruned + (length(v_qs) - length(replace(v_qs, 'records%5B%5D=', ''))) / length('records%5B%5D=');
      else v_prune_errors := v_prune_errors + 1; end if;
      perform pg_sleep(0.25);
    end loop;
  end if;

  update public.broadcast_sync_runs set notes = format('API pull: %s page(s); Airtable "Synced to site" updated on %s record(s), %s failed batch(es); pruned %s played record(s), %s failed batch(es)',
    v_pages, v_patched, v_patch_errors, v_pruned, v_prune_errors)
  where run_id = (v_result->>'run_id')::bigint;

  return (v_result - 'synced_ids') || jsonb_build_object('pages', v_pages, 'airtable_ticks_updated', v_patched, 'airtable_patch_errors', v_patch_errors, 'pruned', v_pruned, 'prune_errors', v_prune_errors);
end;
$$;


ALTER FUNCTION public.sync_airtable_broadcasts_from_api(p_update_airtable boolean) OWNER TO postgres;

--
-- Name: sync_fixture_status_from_results(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sync_fixture_status_from_results() RETURNS integer
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with upd as (
    update public.fixtures f set status = 'played', updated_at = now()
    where f.status in ('scheduled', 'postponed')
      and f.kickoff_date < current_date
      and exists (select 1 from public.matches m
                  where m.home_team_id = f.home_team_id and m.away_team_id = f.away_team_id
                    and m.match_date::date = f.kickoff_date and m.full_time_home_goals is not null)
    returning 1)
  select count(*)::integer from upd;
$$;


ALTER FUNCTION public.sync_fixture_status_from_results() OWNER TO postgres;

--
-- Name: sync_player_identity(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sync_player_identity() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_name text;
  v_slug text;
begin
  if new.fpl_code is null then
    return new;
  end if;

  v_name := trim(coalesce(new.first_name,'') || ' ' || coalesce(new.second_name,''));
  v_slug := coalesce(public.slugify_player_name(v_name), 'player-' || new.fpl_code);

  -- Deterministic collision handling: append the code, never a counter,
  -- so two players can't swap slugs on a reimport.
  if exists (select 1 from public.player_identity i where i.slug = v_slug and i.fpl_code <> new.fpl_code) then
    v_slug := v_slug || '-' || new.fpl_code;
  end if;

  insert into public.player_identity (fpl_code, canonical_name, slug, first_seen_season_id, last_seen_season_id)
  values (new.fpl_code, v_name, v_slug, new.season_id, new.season_id)
  on conflict (fpl_code) do update set
    -- Widen the seen-range; never narrow it. Slug and name are left
    -- alone on conflict: an existing URL must keep working.
    first_seen_season_id = public.earlier_season(public.player_identity.first_seen_season_id, excluded.first_seen_season_id),
    last_seen_season_id  = public.later_season(public.player_identity.last_seen_season_id, excluded.last_seen_season_id),
    updated_at = now();
  return new;
end;
$$;


ALTER FUNCTION public.sync_player_identity() OWNER TO postgres;

--
-- Name: tennis_refresh(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.tennis_refresh() RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  perform tennis.rebuild_events();
  perform tennis.rebuild_summaries();
  return format('%s events, %s editions, %s player totals',
    (select count(*) from tennis.events), (select count(*) from tennis.editions), (select count(*) from tennis.player_totals));
end $$;


ALTER FUNCTION public.tennis_refresh() OWNER TO postgres;

--
-- Name: tennis_refresh_if_stale(boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.tennis_refresh_if_stale(p_force boolean DEFAULT false) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare run bigint; result text; last_ok timestamptz;
begin
  select max(started_at) into last_ok from public.pipeline_runs where job_name = 'tennis_refresh' and status = 'success';
  if not p_force and coalesce((select max(imported_at) from tennis.matches) <= last_ok, false) then
    return 'up to date';
  end if;
  insert into public.pipeline_runs (job_name, status) values ('tennis_refresh', 'running') returning run_id into run;
  begin
    result := public.tennis_refresh();
    update public.pipeline_runs set status = 'success', summary = result, finished_at = now() where run_id = run;
  exception when others then
    update public.pipeline_runs set status = 'failed', error_message = left(sqlerrm, 4000), finished_at = now() where run_id = run;
    result := 'failed: ' || sqlerrm;
  end;
  return result;
end $$;


ALTER FUNCTION public.tennis_refresh_if_stale(p_force boolean) OWNER TO postgres;

--
-- Name: tennis_set_people(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.tennis_set_people(rows jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare n int;
begin
  delete from tennis.player_people where true;
  insert into tennis.player_people (player_id, wikidata_qid, full_name, country, all_countries, birth_date, hand, match_method)
  select r.player_id, r.wikidata_qid, r.full_name, r.country, r.all_countries, r.birth_date, r.hand, r.match_method
  from jsonb_to_recordset(rows) r(player_id bigint, wikidata_qid text, full_name text, country text, all_countries text[],
                                  birth_date date, hand text, match_method text)
  where exists (select 1 from tennis.players p where p.player_id = r.player_id);
  get diagnostics n = row_count;
  return n;
end $$;


ALTER FUNCTION public.tennis_set_people(rows jsonb) OWNER TO postgres;

--
-- Name: tennis_upsert_matches(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.tennis_upsert_matches(rows jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare n int; r record; base text; s text; k int; pid bigint;
begin
  for r in
    select distinct x->>'tour' tour, x->>'tournament' nm from jsonb_array_elements(rows) x
    where not exists (select 1 from tennis.tournaments t where t.tour = x->>'tour' and t.name = x->>'tournament')
  loop
    base := tennis.slugify(r.nm);
    s := base; k := 1;
    while exists (select 1 from tennis.tournaments q where q.tour = r.tour and q.slug = s) loop
      k := k + 1; s := base || '-' || k;
    end loop;
    insert into tennis.tournaments (tour, name, slug) values (r.tour, r.nm, s);
  end loop;

  for r in
    select distinct x->>'tour' tour, nm
    from jsonb_array_elements(rows) x, lateral (values (x->>'winner'), (x->>'loser')) v(nm)
    where not exists (select 1 from tennis.player_aliases a where a.tour = x->>'tour' and a.source_name = nm)
  loop
    base := tennis.slugify(r.nm);
    s := base; k := 1;
    while exists (select 1 from tennis.players q where q.tour = r.tour and q.slug = s) loop
      k := k + 1; s := base || '-' || k;
    end loop;
    insert into tennis.players (tour, name, slug) values (r.tour, r.nm, s) returning player_id into pid;
    insert into tennis.player_aliases (tour, source_name, player_id) values (r.tour, r.nm, pid);
  end loop;

  insert into tennis.matches (source_key, tour, year, tournament_id, location, series, court, surface, round,
    best_of, match_date, winner_id, loser_id, w_rank, l_rank, w_pts, l_pts, w_games, l_games, w_sets, l_sets,
    status, b365_w, b365_l, ps_w, ps_l, max_w, max_l, avg_w, avg_l, bfe_w, bfe_l, raw, imported_at)
  select x->>'source_key', x->>'tour', (x->>'year')::int, t.tournament_id, x->>'location', x->>'series',
    x->>'court', x->>'surface', x->>'round', (x->>'best_of')::int, (x->>'match_date')::date,
    aw.player_id, al.player_id, (x->>'w_rank')::int, (x->>'l_rank')::int, (x->>'w_pts')::int, (x->>'l_pts')::int,
    array(select jsonb_array_elements_text(x->'w_games')::int), array(select jsonb_array_elements_text(x->'l_games')::int),
    (x->>'w_sets')::int, (x->>'l_sets')::int, x->>'status',
    (x->>'b365_w')::numeric, (x->>'b365_l')::numeric, (x->>'ps_w')::numeric, (x->>'ps_l')::numeric,
    (x->>'max_w')::numeric, (x->>'max_l')::numeric, (x->>'avg_w')::numeric, (x->>'avg_l')::numeric,
    (x->>'bfe_w')::numeric, (x->>'bfe_l')::numeric, x->'raw', now()
  from jsonb_array_elements(rows) x
  join tennis.tournaments t on t.tour = x->>'tour' and t.name = x->>'tournament'
  join tennis.player_aliases aw on aw.tour = x->>'tour' and aw.source_name = x->>'winner'
  join tennis.player_aliases al on al.tour = x->>'tour' and al.source_name = x->>'loser'
  on conflict (source_key) do update set
    tournament_id = excluded.tournament_id, location = excluded.location, series = excluded.series,
    court = excluded.court, surface = excluded.surface, best_of = excluded.best_of,
    match_date = excluded.match_date, w_rank = excluded.w_rank, l_rank = excluded.l_rank,
    w_pts = excluded.w_pts, l_pts = excluded.l_pts, w_games = excluded.w_games, l_games = excluded.l_games,
    w_sets = excluded.w_sets, l_sets = excluded.l_sets, status = excluded.status,
    b365_w = excluded.b365_w, b365_l = excluded.b365_l, ps_w = excluded.ps_w, ps_l = excluded.ps_l,
    max_w = excluded.max_w, max_l = excluded.max_l, avg_w = excluded.avg_w, avg_l = excluded.avg_l,
    bfe_w = excluded.bfe_w, bfe_l = excluded.bfe_l, raw = excluded.raw, imported_at = now()
  where tennis.matches.raw is distinct from excluded.raw;
  get diagnostics n = row_count;
  return n;
end $$;


ALTER FUNCTION public.tennis_upsert_matches(rows jsonb) OWNER TO postgres;

--
-- Name: tennis_year_totals(text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.tennis_year_totals(p_tour text, p_year integer) RETURNS TABLE(matches bigint, games bigint, key_hash text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select count(*),
         coalesce(sum((select coalesce(sum(g), 0) from unnest(m.w_games || m.l_games) g)), 0),
         md5(coalesce(string_agg(m.source_key, '#' order by m.source_key collate "C"), ''))
  from tennis.matches m where m.tour = p_tour and m.year = p_year
$$;


ALTER FUNCTION public.tennis_year_totals(p_tour text, p_year integer) OWNER TO postgres;

