    CONSTRAINT fixture_broadcasts_access_type_check CHECK (((access_type IS NULL) OR (access_type = ANY (ARRAY['free'::text, 'free_compatible_device'::text, 'subscription'::text, 'ppv'::text, 'unknown'::text])))),
    CONSTRAINT fixture_broadcasts_confidence_check CHECK (((confidence IS NULL) OR (confidence = ANY (ARRAY['confirmed_primary'::text, 'confirmed_secondary'::text, 'probable'::text, 'needs_verification'::text])))),
    CONSTRAINT fixture_broadcasts_delivery_check CHECK ((delivery_methods <@ ARRAY['tv_channel'::text, 'streaming'::text, 'fast'::text, 'web'::text, 'app'::text])),
    CONSTRAINT fixture_broadcasts_status_check CHECK ((status = ANY (ARRAY['confirmed_broadcast'::text, 'confirmed_not_televised'::text]))),
    CONSTRAINT fixture_broadcasts_status_shape CHECK ((((status = 'confirmed_not_televised'::text) AND (broadcaster IS NULL) AND (channel IS NULL) AND (streaming_service IS NULL) AND (NOT is_free_to_air) AND (NOT is_subscription) AND (NOT is_ppv) AND (watch_url IS NULL)) OR ((status = 'confirmed_broadcast'::text) AND (broadcaster IS NOT NULL))))
);


