    CONSTRAINT fpl_player_squad_state_state_check CHECK ((state = ANY (ARRAY['active'::text, 'favoured'::text, 'rotation'::text, 'out_of_favour'::text, 'injured'::text, 'doubtful'::text, 'suspended'::text, 'transferred'::text, 'loaned'::text, 'unavailable'::text])))
);


ALTER TABLE public.fpl_player_squad_state OWNER TO postgres;

--
-- Name: fpl_player_squad_state_current; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.fpl_player_squad_state_current WITH (security_invoker='true') AS
 SELECT DISTINCT ON (season_id, fpl_player_id) season_id,
    fpl_player_id,
    team_id,
    state,
    availability_probability,
    start_probability_override,
    effective_from,
    effective_to,
    source_name,
    source_reference,
    evidence,
    updated_at
   FROM public.fpl_player_squad_state
  WHERE ((effective_from <= now()) AND ((effective_to IS NULL) OR (effective_to > now())))
  ORDER BY season_id, fpl_player_id, (source_name = 'manual_tactical_override'::text) DESC, effective_from DESC;


ALTER VIEW public.fpl_player_squad_state_current OWNER TO postgres;

--
-- Name: fixture_player_expected_minutes_resolved_v3_raw; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.fixture_player_expected_minutes_resolved_v3_raw WITH (security_invoker='true') AS
 SELECT r.fixture_id,
    r.team_id,
    r.fpl_player_id,
    r.web_name,
    r.element_type,
        CASE
            WHEN (src.fpl_player_id IS NOT NULL) THEN r.expected_minutes
            WHEN (ss.start_probability_override IS NOT NULL) THEN LEAST((90)::numeric, GREATEST((0)::numeric, ((ss.start_probability_override * (
            CASE
                WHEN (r.element_type = 1) THEN 90
                ELSE 80
            END)::numeric) + (r.prob_sub_appearance * (20)::numeric))))
            ELSE LEAST((90)::numeric, GREATEST((0)::numeric, ((p.start_probability * (
            CASE
                WHEN (r.element_type = 1) THEN 90
                ELSE 80
            END)::numeric) + (r.prob_sub_appearance * (20)::numeric))))
        END AS expected_minutes,
    COALESCE(src.prob_starting_xi, ss.start_probability_override, p.start_probability, r.prob_starting_xi) AS prob_starting_xi,
    r.prob_sub_appearance,
    COALESCE(ss.availability_probability, p.availability, r.availability_probability) AS availability_probability,
    r.tactical_role,
        CASE
            WHEN (src.fpl_player_id IS NOT NULL) THEN r.minutes_source
            WHEN (ss.start_probability_override IS NOT NULL) THEN 'squad_state_override'::text
            WHEN (p.probability_source = 'nailed_history'::text) THEN 'nailed_history_v6'::text
            WHEN (p.probability_source = 'strong_history'::text) THEN 'strong_history_v6'::text
            ELSE 'fallback_history_v6'::text
        END AS minutes_source
   FROM (((public.fixture_player_expected_minutes_resolved r
     LEFT JOIN public.fixture_player_expected_minutes_v3 src ON (((src.fixture_id = r.fixture_id) AND (src.fpl_player_id = r.fpl_player_id))))
     LEFT JOIN public.fpl_fallback_start_probability_v6 p ON (((p.fixture_id = r.fixture_id) AND (p.fpl_player_id = r.fpl_player_id))))
     LEFT JOIN public.fpl_player_squad_state_current ss ON (((ss.season_id = ( SELECT public.fpl_current_season_id() AS fpl_current_season_id)) AND (ss.fpl_player_id = r.fpl_player_id) AND (ss.team_id = r.team_id))));


ALTER VIEW public.fixture_player_expected_minutes_resolved_v3_raw OWNER TO postgres;

--
-- Name: fixture_player_expected_minutes_resolved_v3; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.fixture_player_expected_minutes_resolved_v3 WITH (security_invoker='true') AS
 WITH r AS (
         SELECT raw.fixture_id,
            raw.team_id,
            raw.fpl_player_id,
            raw.web_name,
            raw.element_type,
            raw.expected_minutes,
            raw.prob_starting_xi,
            raw.prob_sub_appearance,
            raw.availability_probability,
            raw.tactical_role,
            raw.minutes_source,
            (raw.element_type = 1) AS is_gk,
            row_number() OVER (PARTITION BY raw.fixture_id, raw.team_id, (raw.element_type = 1) ORDER BY raw.expected_minutes DESC, raw.prob_starting_xi DESC, raw.fpl_player_id) AS gk_rank
           FROM public.fixture_player_expected_minutes_resolved_v3_raw raw
        ), t AS (
         SELECT r.fixture_id,
            r.team_id,
            r.fpl_player_id,
            r.web_name,
            r.element_type,
            r.expected_minutes,
            r.prob_starting_xi,
            r.prob_sub_appearance,
            r.availability_probability,
            r.tactical_role,
            r.minutes_source,
            r.is_gk,
            r.gk_rank,
            sum(r.expected_minutes) OVER w AS team_min,
            sum(r.prob_starting_xi) OVER w AS team_start,
            sum((r.expected_minutes * ((1)::numeric - LEAST(r.prob_starting_xi, (1)::numeric)))) OVER w AS w_min_sum,
            sum((r.prob_starting_xi * ((1)::numeric - LEAST(r.prob_starting_xi, (1)::numeric)))) OVER w AS w_start_sum,
            max(
                CASE
                    WHEN (r.gk_rank = 1) THEN LEAST(r.expected_minutes, (90)::numeric)
                    ELSE NULL::numeric
                END) OVER w AS lead_gk_min,
            max(
                CASE
                    WHEN (r.gk_rank = 1) THEN LEAST(r.prob_starting_xi, (1)::numeric)
                    ELSE NULL::numeric
                END) OVER w AS lead_gk_start,
            sum(
                CASE
                    WHEN (r.gk_rank > 1) THEN r.expected_minutes
                    ELSE (0)::numeric
                END) OVER w AS other_gk_min,
            sum(
                CASE
                    WHEN (r.gk_rank > 1) THEN r.prob_starting_xi
                    ELSE (0)::numeric
                END) OVER w AS other_gk_start
           FROM r
          WINDOW w AS (PARTITION BY r.fixture_id, r.team_id, r.is_gk)
        ), n AS (
         SELECT t.fixture_id,
            t.team_id,
            t.fpl_player_id,
            t.web_name,
            t.element_type,
            t.expected_minutes,
            t.prob_starting_xi,
            t.prob_sub_appearance,
            t.availability_probability,
            t.tactical_role,
            t.minutes_source,
            t.is_gk,
            t.gk_rank,
            t.team_min,
            t.team_start,
            t.w_min_sum,
            t.w_start_sum,
            t.lead_gk_min,
            t.lead_gk_start,
            t.other_gk_min,
            t.other_gk_start,
                CASE
                    WHEN (t.is_gk AND (t.gk_rank = 1)) THEN LEAST(t.expected_minutes, (90)::numeric)
                    WHEN t.is_gk THEN (t.expected_minutes * LEAST((1)::numeric, (GREATEST(((90)::numeric - t.lead_gk_min), (0)::numeric) / NULLIF(t.other_gk_min, (0)::numeric))))
                    WHEN ((t.team_min <= (900)::numeric) OR (t.w_min_sum = (0)::numeric)) THEN t.expected_minutes
                    ELSE GREATEST((0)::numeric, (t.expected_minutes - ((((t.team_min - (900)::numeric) * t.expected_minutes) * ((1)::numeric - LEAST(t.prob_starting_xi, (1)::numeric))) / t.w_min_sum)))
                END AS new_min,
                CASE
                    WHEN (t.is_gk AND (t.gk_rank = 1)) THEN LEAST(t.prob_starting_xi, (1)::numeric)
                    WHEN t.is_gk THEN (t.prob_starting_xi * LEAST((1)::numeric, (GREATEST(((1)::numeric - t.lead_gk_start), (0)::numeric) / NULLIF(t.other_gk_start, (0)::numeric))))
                    WHEN ((t.team_start <= (10)::numeric) OR (t.w_start_sum = (0)::numeric)) THEN t.prob_starting_xi
                    ELSE GREATEST((0)::numeric, (t.prob_starting_xi - ((((t.team_start - (10)::numeric) * t.prob_starting_xi) * ((1)::numeric - LEAST(t.prob_starting_xi, (1)::numeric))) / t.w_start_sum)))
                END AS new_start
           FROM t
        )
 SELECT fixture_id,
    team_id,
    fpl_player_id,
    web_name,
    element_type,
    COALESCE(new_min, expected_minutes) AS expected_minutes,
    COALESCE(new_start, prob_starting_xi) AS prob_starting_xi,
        CASE
            WHEN (is_gk AND (gk_rank > 1) AND (expected_minutes > (0)::numeric)) THEN ((prob_sub_appearance * COALESCE(new_min, expected_minutes)) / expected_minutes)
            ELSE prob_sub_appearance
        END AS prob_sub_appearance,
    availability_probability,
    tactical_role,
    minutes_source
   FROM n;


ALTER VIEW public.fixture_player_expected_minutes_resolved_v3 OWNER TO postgres;

