--
-- Name: fixture_team_tactical_consensus; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.fixture_team_tactical_consensus WITH (security_invoker='true') AS
 WITH x AS (
         SELECT lp.fixture_id,
            lp.team_id,
            lp.formation,
            sum(s.source_weight) AS weight,
            count(*) AS sources,
            row_number() OVER (PARTITION BY lp.fixture_id, lp.team_id ORDER BY (sum(s.source_weight)) DESC, (count(*)) DESC, lp.formation) AS rn
           FROM (public.fixture_lineup_predictions lp
             JOIN public.lineup_prediction_sources s ON (((s.lineup_source_id = lp.lineup_source_id) AND s.active)))
          GROUP BY lp.fixture_id, lp.team_id, lp.formation
        ), manual AS (
         SELECT f.fixture_id,
            t.team_id,
            d.formation,
            d.confidence AS consensus_weight,
            (0)::bigint AS sources
           FROM ((public.fixtures f
             CROSS JOIN LATERAL ( VALUES (f.home_team_id), (f.away_team_id)) t(team_id))
             JOIN public.team_tactical_defaults d ON (((d.season_id = f.season_id) AND (d.team_id = t.team_id))))
          WHERE ((f.season_id = ( SELECT public.fpl_current_season_id() AS fpl_current_season_id)) AND (d.source_name = 'manual'::text) AND (EXISTS ( SELECT 1
                   FROM public.fpl_fixtures ff
                  WHERE ((ff.canonical_fixture_id = f.fixture_id) AND (ff.season_id = f.season_id)))))
        ), src AS (
         SELECT x.fixture_id,
            x.team_id,
            x.formation,
            x.weight AS consensus_weight,
            x.sources
           FROM x
          WHERE ((x.rn = 1) AND (NOT (EXISTS ( SELECT 1
                   FROM manual m
                  WHERE ((m.fixture_id = x.fixture_id) AND (m.team_id = x.team_id))))))
        ), fallback AS (
         SELECT f.fixture_id,
            t.team_id,
            d.formation,
            d.confidence AS consensus_weight,
            (0)::bigint AS sources
           FROM ((public.fixtures f
             CROSS JOIN LATERAL ( VALUES (f.home_team_id), (f.away_team_id)) t(team_id))
             JOIN public.team_tactical_defaults d ON (((d.season_id = f.season_id) AND (d.team_id = t.team_id))))
          WHERE ((f.season_id = ( SELECT public.fpl_current_season_id() AS fpl_current_season_id)) AND (d.source_name <> 'manual'::text) AND (EXISTS ( SELECT 1
                   FROM public.fpl_fixtures ff
                  WHERE ((ff.canonical_fixture_id = f.fixture_id) AND (ff.season_id = f.season_id)))) AND (NOT (EXISTS ( SELECT 1
                   FROM src s
                  WHERE ((s.fixture_id = f.fixture_id) AND (s.team_id = t.team_id))))))
        )
 SELECT manual.fixture_id,
    manual.team_id,
    manual.formation,
    manual.consensus_weight,
    manual.sources
   FROM manual
UNION ALL
 SELECT src.fixture_id,
    src.team_id,
    src.formation,
    src.consensus_weight,
    src.sources
   FROM src
UNION ALL
 SELECT fallback.fixture_id,
    fallback.team_id,
    fallback.formation,
    fallback.consensus_weight,
    fallback.sources
   FROM fallback;


ALTER VIEW public.fixture_team_tactical_consensus OWNER TO postgres;

