CREATE VIEW public.fixtures_reported_unconfirmed WITH (security_invoker='true') AS
 SELECT fixture_id,
    slug,
    league_id,
    season_id,
    kickoff_date,
    home_team_id,
    away_team_id,
    reported_home_goals,
    reported_away_goals,
    reported_at,
