--
-- Name: fpl_player_defensive_contribution_usage; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.fpl_player_defensive_contribution_usage WITH (security_invoker='true') AS
 SELECT p.season_id,
    p.fpl_player_id,
    p.element_type,
    count(g.fpl_fixture_id) FILTER (WHERE (g.minutes > 0)) AS appearances,
    sum(g.minutes) AS minutes,
    sum(COALESCE((((g.source_payload -> 'stats'::text) ->> 'clearances_blocks_interceptions'::text))::numeric, (0)::numeric)) AS cbi,
    sum(COALESCE((((g.source_payload -> 'stats'::text) ->> 'recoveries'::text))::numeric, (0)::numeric)) AS recoveries,
    sum(COALESCE((((g.source_payload -> 'stats'::text) ->> 'tackles'::text))::numeric, (0)::numeric)) AS tackles
   FROM (public.fpl_players p
     LEFT JOIN public.fpl_player_gameweeks g ON (((g.fpl_player_id = p.fpl_player_id) AND (g.season_id = p.season_id))))
  GROUP BY p.season_id, p.fpl_player_id, p.element_type;


ALTER VIEW public.fpl_player_defensive_contribution_usage OWNER TO postgres;

--
-- Name: fpl_projection_v4_leaguewide_inputs; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.fpl_projection_v4_leaguewide_inputs WITH (security_invoker='true') AS
 SELECT m.fixture_id,
    m.team_id,
    m.fpl_player_id,
    m.expected_minutes,
    m.prob_starting_xi,
    m.prob_sub_appearance,
    m.availability_probability,
    m.tactical_role AS real_tactical_role,
    p.web_name,
    p.element_type,
    p.minutes AS season_minutes,
    COALESCE((((p.expected_goals / (NULLIF(p.minutes, 0))::numeric) * (90)::numeric) * (((p.goals_scored)::numeric + 6.0) / (NULLIF(p.expected_goals, (0)::numeric) + 6.0))), (0)::numeric) AS raw_xg90,
    COALESCE(((p.expected_assists / (NULLIF(p.minutes, 0))::numeric) * (90)::numeric), (0)::numeric) AS raw_xa90
   FROM ((public.fixture_player_expected_minutes_resolved_v3 m
     JOIN public.fpl_players p ON (((p.fpl_player_id = m.fpl_player_id) AND (p.season_id = ( SELECT public.fpl_current_season_id() AS fpl_current_season_id)))))
     JOIN public.fixtures f ON ((f.fixture_id = m.fixture_id)))
  WHERE ((f.season_id = ( SELECT public.fpl_current_season_id() AS fpl_current_season_id)) AND (f.predicted_home_goals IS NOT NULL) AND (f.predicted_away_goals IS NOT NULL));


ALTER VIEW public.fpl_projection_v4_leaguewide_inputs OWNER TO postgres;

