    source_payload jsonb,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT set_piece_hierarchies_confidence_check CHECK (((confidence >= (0)::numeric) AND (confidence <= (1)::numeric))),
    CONSTRAINT set_piece_hierarchies_rank_check CHECK ((rank > 0)),
    CONSTRAINT set_piece_hierarchies_set_piece_type_check CHECK ((set_piece_type = ANY (ARRAY['penalty'::text, 'direct_free_kick'::text, 'corner_left'::text, 'corner_right'::text, 'indirect_free_kick'::text])))
);


