--
-- Name: fpl_projection_frontend_feed; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.fpl_projection_frontend_feed WITH (security_invoker='true') AS
 SELECT pr.fixture_id,
    f.kickoff_date,
    pr.fpl_player_id,
    p.web_name,
    p.canonical_team_id AS team_id,
    p.element_type AS fpl_position,
    m.tactical_role,
    m.minutes_source,
    pr.model_version,
    pr.expected_minutes,
    pr.start_probability,
    pr.sub_appearance_probability,
    pr.expected_goals,
    pr.expected_assists,
    pr.clean_sheet_probability,
    pr.defensive_contribution_probability,
    pr.expected_bonus,
    pr.expected_fpl_points,
    pr.lineup_confidence,
    pr.generated_at
   FROM (((public.fpl_player_projections pr
     JOIN public.fixtures f ON ((f.fixture_id = pr.fixture_id)))
     JOIN public.fpl_players p ON (((p.season_id = pr.season_id) AND (p.fpl_player_id = pr.fpl_player_id))))
     LEFT JOIN public.fixture_player_expected_minutes_resolved m ON (((m.fixture_id = pr.fixture_id) AND (m.fpl_player_id = pr.fpl_player_id))))
  WHERE (pr.model_version = 'leaguewide_v4'::text);


ALTER VIEW public.fpl_projection_frontend_feed OWNER TO postgres;

--
-- Name: fpl_optimizer_candidate_feed_v1; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.fpl_optimizer_candidate_feed_v1 WITH (security_invoker='true') AS
 SELECT p.fixture_id,
    f.matchweek,
    p.fpl_player_id,
    p.web_name,
    p.team_id,
    t.canonical_name AS team_name,
    p.fpl_position,
    fp.now_cost,
    ((fp.now_cost)::numeric / (10)::numeric) AS price_m,
    p.expected_minutes,
    LEAST((1)::numeric, GREATEST((0)::numeric, p.start_probability)) AS start_probability,
    LEAST(GREATEST((0)::numeric, ((1)::numeric - LEAST((1)::numeric, GREATEST((0)::numeric, p.start_probability)))), GREATEST((0)::numeric, p.sub_appearance_probability)) AS sub_appearance_probability,
    p.expected_fpl_points,
    p.lineup_confidence,
    p.model_version,
    p.generated_at
   FROM (((public.fpl_projection_frontend_feed p
     JOIN public.fixtures f ON ((f.fixture_id = p.fixture_id)))
     LEFT JOIN public.fpl_players fp ON (((fp.fpl_player_id = p.fpl_player_id) AND (fp.season_id = f.season_id))))
     LEFT JOIN public.teams t ON ((t.team_id = p.team_id)))
  WHERE (f.season_id = ( SELECT public.fpl_current_season_id() AS fpl_current_season_id));


ALTER VIEW public.fpl_optimizer_candidate_feed_v1 OWNER TO postgres;

