--
-- Name: fpl_projection_leaguewide_points; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.fpl_projection_leaguewide_points WITH (security_invoker='true') AS
 SELECT a.fixture_id,
    a.team_id,
    a.fpl_player_id,
    p.web_name,
    a.element_type,
    a.real_tactical_role,
    a.expected_minutes,
    a.prob_starting_xi,
    a.prob_sub_appearance,
    a.expected_goals,
    a.expected_assists,
        CASE
            WHEN (a.team_id = f.home_team_id) THEN exp((- COALESCE(f.market_away_goals, f.predicted_away_goals)))
            ELSE exp((- COALESCE(f.market_home_goals, f.predicted_home_goals)))
        END AS clean_sheet_probability,
    COALESCE(dc.defensive_contribution_probability, (0)::numeric) AS defensive_contribution_probability,
    (0)::numeric AS expected_bonus,
    ((a.prob_starting_xi * ((2)::numeric - COALESCE(eb.p_off_before_60, (0)::numeric))) + a.prob_sub_appearance) AS xpts_appearance,
    (a.expected_goals * (
        CASE a.element_type
            WHEN 1 THEN 10
            WHEN 2 THEN 6
            WHEN 3 THEN 5
            ELSE 4
        END)::numeric) AS xpts_goals,
    (a.expected_assists * (3)::numeric) AS xpts_assists,
    (((
        CASE
            WHEN (a.element_type = ANY (ARRAY[1, 2])) THEN 4
            WHEN (a.element_type = 3) THEN 1
            ELSE 0
        END)::double precision * (a.prob_starting_xi)::double precision) * (((COALESCE(eb.p_full, (1)::numeric))::double precision *
        CASE
            WHEN (a.team_id = f.home_team_id) THEN exp((- COALESCE(f.market_away_goals, f.predicted_away_goals)))
            ELSE exp((- COALESCE(f.market_home_goals, f.predicted_home_goals)))
        END) + ((COALESCE(eb.p_off_60_84, (0)::numeric))::double precision * power(
        CASE
            WHEN (a.team_id = f.home_team_id) THEN exp((- COALESCE(f.market_away_goals, f.predicted_away_goals)))
            ELSE exp((- COALESCE(f.market_home_goals, f.predicted_home_goals)))
        END, ((72.7)::double precision / (90)::double precision))))) AS xpts_clean_sheet,
    (COALESCE(dc.defensive_contribution_probability, (0)::numeric) * (2)::numeric) AS xpts_defensive_contribution,
    (0)::numeric AS xpts_bonus
   FROM ((((public.fpl_projection_leaguewide_allocation_v2 a
     JOIN public.fpl_players p ON (((p.season_id = ( SELECT public.fpl_current_season_id() AS fpl_current_season_id)) AND (p.fpl_player_id = a.fpl_player_id))))
     JOIN public.fixtures f ON ((f.fixture_id = a.fixture_id)))
     LEFT JOIN public.fpl_defensive_contribution_projection_leaguewide dc ON (((dc.fixture_id = a.fixture_id) AND (dc.fpl_player_id = a.fpl_player_id))))
     LEFT JOIN public.fpl_player_exit_bands eb ON (((eb.season_id = p.season_id) AND (eb.fpl_player_id = a.fpl_player_id))));


ALTER VIEW public.fpl_projection_leaguewide_points OWNER TO postgres;

--
-- Name: fpl_projection_secondary_scoring; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.fpl_projection_secondary_scoring WITH (security_invoker='true') AS
 WITH h AS (
         SELECT p.fpl_player_id,
            p.element_type,
            (COALESCE(sum(g.minutes), (0)::bigint))::numeric AS mins,
            (COALESCE(sum(g.saves), (0)::bigint))::numeric AS saves,
            (COALESCE(sum(g.yellow_cards), (0)::bigint))::numeric AS yc,
            (COALESCE(sum(g.red_cards), (0)::bigint))::numeric AS rc,
            (COALESCE(sum(g.own_goals), (0)::bigint))::numeric AS og,
            (COALESCE(sum(g.penalties_saved), (0)::bigint))::numeric AS ps,
            (COALESCE(sum(g.penalties_missed), (0)::bigint))::numeric AS pm
           FROM (public.fpl_players p
             LEFT JOIN public.fpl_player_gameweeks g ON (((g.season_id = ( SELECT public.fpl_current_season_id() AS fpl_current_season_id)) AND (g.fpl_player_id = p.fpl_player_id))))
          WHERE (p.season_id = ( SELECT public.fpl_current_season_id() AS fpl_current_season_id))
          GROUP BY p.fpl_player_id, p.element_type
        ), b AS (
         SELECT a.fixture_id,
            a.team_id,
            a.fpl_player_id,
            a.element_type,
            a.expected_minutes,
            a.penalty_exposure,
            f.home_team_id,
            COALESCE(f.market_home_goals, f.predicted_home_goals) AS predicted_home_goals,
            COALESCE(f.market_away_goals, f.predicted_away_goals) AS predicted_away_goals,
            a.prob_starting_xi,
            a.prob_sub_appearance,
            COALESCE(eb.p_full, (1)::numeric) AS eb_full,
            COALESCE(eb.p_off_60_84, (0)::numeric) AS eb_mid,
            COALESCE(eb.p_off_before_60, (0)::numeric) AS eb_early,
            h.mins,
            h.saves,
            h.yc,
            h.rc,
            h.og,
            h.ps,
            h.pm
           FROM (((public.fpl_projection_leaguewide_allocation_v2 a
             JOIN public.fixtures f ON ((f.fixture_id = a.fixture_id)))
             JOIN h ON ((h.fpl_player_id = a.fpl_player_id)))
             LEFT JOIN public.fpl_player_exit_bands eb ON (((eb.season_id = ( SELECT public.fpl_current_season_id() AS fpl_current_season_id)) AND (eb.fpl_player_id = a.fpl_player_id))))
        )
 SELECT fixture_id,
    team_id,
    fpl_player_id,
        CASE
            WHEN (element_type = 1) THEN ((((saves + (2.8846 * (5)::numeric)) / (mins + (450)::numeric)) * expected_minutes) / (3)::numeric)
            ELSE (0)::numeric
        END AS xpts_saves,
        CASE
            WHEN (element_type = ANY (ARRAY[1, 2])) THEN (- (((prob_starting_xi)::double precision * ((((eb_full)::double precision * ((
            CASE
                WHEN (team_id = home_team_id) THEN predicted_away_goals
                ELSE predicted_home_goals
            END / (2.0)::double precision) - (((1.0)::double precision - exp((('-2.0'::numeric)::double precision *
            CASE
                WHEN (team_id = home_team_id) THEN predicted_away_goals
                ELSE predicted_home_goals
            END))) / (4.0)::double precision))) + ((eb_mid)::double precision * (((
            CASE
                WHEN (team_id = home_team_id) THEN predicted_away_goals
                ELSE predicted_home_goals
            END * ((72.7 / 90.0))::double precision) / (2.0)::double precision) - (((1.0)::double precision - exp(((('-2.0'::numeric)::double precision *
            CASE
                WHEN (team_id = home_team_id) THEN predicted_away_goals
                ELSE predicted_home_goals
            END) * ((72.7 / 90.0))::double precision))) / (4.0)::double precision)))) + ((eb_early)::double precision * (((
            CASE
                WHEN (team_id = home_team_id) THEN predicted_away_goals
                ELSE predicted_home_goals
            END * ((47.0 / 90.0))::double precision) / (2.0)::double precision) - (((1.0)::double precision - exp(((('-2.0'::numeric)::double precision *
            CASE
                WHEN (team_id = home_team_id) THEN predicted_away_goals
                ELSE predicted_home_goals
            END) * ((47.0 / 90.0))::double precision))) / (4.0)::double precision))))) + ((prob_sub_appearance)::double precision * (((
            CASE
                WHEN (team_id = home_team_id) THEN predicted_away_goals
                ELSE predicted_home_goals
            END * ((18.2 / 90.0))::double precision) / (2.0)::double precision) - (((1.0)::double precision - exp(((('-2.0'::numeric)::double precision *
            CASE
                WHEN (team_id = home_team_id) THEN predicted_away_goals
                ELSE predicted_home_goals
            END) * ((18.2 / 90.0))::double precision))) / (4.0)::double precision)))))
            ELSE (0)::double precision
        END AS xpts_goals_conceded,
    ((((- ((yc + (0.35 * (5)::numeric)) / (mins + (450)::numeric))) * expected_minutes) - (((3)::numeric * ((rc + (0.03 * (5)::numeric)) / (mins + (450)::numeric))) * expected_minutes)) - (((2)::numeric * ((og + (0.02 * (5)::numeric)) / (mins + (450)::numeric))) * expected_minutes)) AS xpts_cards_own_goals,
    (
        CASE
            WHEN (element_type = 1) THEN (((5)::numeric * ((ps + (0.03 * (5)::numeric)) / (mins + (450)::numeric))) * expected_minutes)
            ELSE (0)::numeric
        END -
        CASE
            WHEN (penalty_exposure > (0)::numeric) THEN (((2)::numeric * ((pm + (0.02 * (5)::numeric)) / (mins + (450)::numeric))) * expected_minutes)
            ELSE (0)::numeric
        END) AS xpts_penalties
   FROM b;


ALTER VIEW public.fpl_projection_secondary_scoring OWNER TO postgres;

--
-- Name: fpl_projection_leaguewide_final; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.fpl_projection_leaguewide_final WITH (security_invoker='true') AS
 SELECT p.fixture_id,
    p.team_id,
    p.fpl_player_id,
    p.web_name,
    p.element_type,
    p.real_tactical_role,
    p.expected_minutes,
    p.prob_starting_xi,
    p.prob_sub_appearance,
    p.expected_goals,
    p.expected_assists,
    p.clean_sheet_probability,
    p.defensive_contribution_probability,
    p.expected_bonus,
    p.xpts_appearance,
    p.xpts_goals,
    p.xpts_assists,
    p.xpts_clean_sheet,
    p.xpts_defensive_contribution,
    p.xpts_bonus,
    s.xpts_saves,
    s.xpts_goals_conceded,
    s.xpts_cards_own_goals,
    s.xpts_penalties,
    ((((((((((p.xpts_appearance + p.xpts_goals) + p.xpts_assists))::double precision + p.xpts_clean_sheet) + (p.xpts_defensive_contribution)::double precision) + (p.xpts_bonus)::double precision) + (s.xpts_saves)::double precision) + s.xpts_goals_conceded) + (s.xpts_cards_own_goals)::double precision) + (s.xpts_penalties)::double precision) AS expected_fpl_points
   FROM (public.fpl_projection_leaguewide_points p
     JOIN public.fpl_projection_secondary_scoring s ON (((s.fixture_id = p.fixture_id) AND (s.fpl_player_id = p.fpl_player_id))));


ALTER VIEW public.fpl_projection_leaguewide_final OWNER TO postgres;

