--
-- Name: fpl_season_fixture_feed; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.fpl_season_fixture_feed WITH (security_invoker='true') AS
 SELECT f.fixture_id,
    f.season_id,
    f.matchweek,
    f.round,
    f.round_number,
    f.kickoff_date,
    f.kickoff_time,
    f.status,
    f.home_team_id,
    ht.canonical_name AS home_team,
    f.away_team_id,
    at.canonical_name AS away_team,
    f.predicted_home_goals,
    f.predicted_away_goals,
    f.predicted_at,
        CASE
            WHEN ((f.predicted_home_goals IS NOT NULL) AND (f.predicted_away_goals IS NOT NULL)) THEN true
            ELSE false
        END AS has_projection
   FROM ((public.fixtures f
     JOIN public.teams ht ON ((ht.team_id = f.home_team_id)))
     JOIN public.teams at ON ((at.team_id = f.away_team_id)))
  WHERE ((f.season_id = ( SELECT public.fpl_current_season_id() AS fpl_current_season_id)) AND (f.league_id = ( SELECT leagues.league_id
           FROM public.leagues
          WHERE (leagues.code = 'E0'::text)
         LIMIT 1)));


ALTER VIEW public.fpl_season_fixture_feed OWNER TO postgres;

--
-- Name: fpl_season_player_projection_feed; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.fpl_season_player_projection_feed WITH (security_invoker='true') AS
 SELECT pr.fixture_id,
    f.matchweek,
    f.kickoff_date,
    COALESCE(fp.canonical_team_id, (fp.fpl_team_id)::bigint) AS team_id,
    fp.web_name,
    pr.fpl_player_id,
    fp.element_type AS fpl_position,
    tc.tactical_role,
    pr.expected_minutes,
    pr.start_probability,
    pr.sub_appearance_probability,
    NULL::numeric AS shrunk_xg90,
    NULL::numeric AS shrunk_xa90,
    pr.expected_goals,
    pr.expected_assists,
    pr.clean_sheet_probability,
    pr.defensive_contribution_probability,
    pr.expected_bonus AS experimental_expected_bonus
   FROM (((public.fpl_player_projections pr
     JOIN public.fixtures f ON ((f.fixture_id = pr.fixture_id)))
     JOIN public.fpl_players fp ON (((fp.season_id = pr.season_id) AND (fp.fpl_player_id = pr.fpl_player_id))))
     LEFT JOIN public.fixture_player_tactical_consensus tc ON (((tc.fixture_id = pr.fixture_id) AND (tc.fpl_player_id = pr.fpl_player_id))))
  WHERE ((pr.season_id = ( SELECT public.fpl_current_season_id() AS fpl_current_season_id)) AND (pr.model_version = 'leaguewide_v6'::text));


ALTER VIEW public.fpl_season_player_projection_feed OWNER TO postgres;

