-- Name: league_season_formats; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.league_season_formats (
    league_id bigint NOT NULL,
    season_id bigint NOT NULL,
    format text NOT NULL,
    regular_meetings smallint,
    halved_groups smallint[],
    halving_rounding text,
    curtailed_on_ppg boolean,
    notes text NOT NULL,
    source_url text,
    group_sizes smallint[],
    group_games smallint[],
    tiebreak text,
    CONSTRAINT league_season_formats_format_check CHECK ((format = ANY (ARRAY['split'::text, 'curtailed'::text, 'regular_season_only'::text]))),
    CONSTRAINT league_season_formats_halving_pair CHECK (((halved_groups IS NULL) = (halving_rounding IS NULL))),
    CONSTRAINT league_season_formats_halving_rounding_check CHECK ((halving_rounding = ANY (ARRAY['up'::text, 'down'::text]))),
    CONSTRAINT league_season_formats_regular_meetings_check CHECK (((regular_meetings >= 1) AND (regular_meetings <= 4))),
    CONSTRAINT league_season_formats_split_fields CHECK (
CASE
    WHEN (format = 'split'::text) THEN ((regular_meetings IS NOT NULL) AND (group_sizes IS NOT NULL) AND (group_games IS NOT NULL) AND (tiebreak IS NOT NULL) AND (cardinality(group_sizes) = cardinality(group_games)))
    ELSE ((regular_meetings IS NULL) AND (halved_groups IS NULL) AND (group_sizes IS NULL) AND (group_games IS NULL) AND (tiebreak IS NULL))
END),
    CONSTRAINT league_season_formats_split_needs_meetings CHECK (((format <> 'split'::text) OR (regular_meetings IS NOT NULL))),
    CONSTRAINT league_season_formats_tiebreak_check CHECK ((tiebreak = ANY (ARRAY['goal_difference'::text, 'head_to_head'::text, 'regular_position'::text, 'regular_points'::text])))
);


