--
-- Name: league_standings; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.league_standings AS
 WITH domestic_leagues AS (
         SELECT leagues.league_id,
            leagues.country_id
           FROM public.leagues
          WHERE (leagues.competition_type = 'league'::text)
        ), cur AS (
         SELECT se_cur.season_id
           FROM public.seasons se_cur
          WHERE (se_cur.start_year = ( SELECT max(se_m.start_year) AS max
                   FROM public.seasons se_m
                  WHERE (se_m.season_id IN ( SELECT matches.season_id
                           FROM public.matches
                          WHERE (matches.league_id IN ( SELECT domestic_leagues.league_id
                                   FROM domestic_leagues))))))
        ), fmt AS (
         SELECT f.league_id,
            f.season_id,
            ((f.league_id * 10000) + f.season_id) AS ls,
            f.regular_meetings,
            f.halved_groups,
            f.halving_rounding,
            f.group_sizes,
            f.group_games,
            f.tiebreak
           FROM public.league_season_formats f
          WHERE (f.format = 'split'::text)
        ), sm AS (
         SELECT m.match_id,
            f.ls,
            m.match_date,
            m.kickoff_time,
            ((f.ls * 10000000) + m.home_team_id) AS hk,
            ((f.ls * 10000000) + m.away_team_id) AS ak,
            m.full_time_home_goals AS hg,
            m.full_time_away_goals AS ag,
            ((row_number() OVER (PARTITION BY f.ls, LEAST(m.home_team_id, m.away_team_id), GREATEST(m.home_team_id, m.away_team_id) ORDER BY m.match_date, m.kickoff_time, m.match_id))::integer - f.regular_meetings) AS post_no
           FROM (public.matches m
             JOIN fmt f ON (((f.league_id = m.league_id) AND (f.season_id = m.season_id))))
          WHERE (m.full_time_home_goals IS NOT NULL)
        ), sm_side AS (
         SELECT sm.ls,
            sm.match_id,
            sm.match_date,
            sm.kickoff_time,
            sm.post_no,
            sm.hk AS tk,
            sm.ak AS ok,
            sm.hg AS gf,
            sm.ag AS ga
           FROM sm
        UNION ALL
         SELECT sm.ls,
            sm.match_id,
            sm.match_date,
            sm.kickoff_time,
            sm.post_no,
            sm.ak,
            sm.hk,
            sm.ag,
            sm.hg
           FROM sm
        ), split_start AS (
         SELECT sm.ls,
            min(sm.match_date) AS first_post_date
           FROM sm
          WHERE (sm.post_no > 0)
          GROUP BY sm.ls
        ), pre_ded AS (
         SELECT ((((d.league_id * 10000) + d.season_id) * 10000000) + d.team_id) AS tk,
            (sum(d.points))::integer AS pts
           FROM (public.point_deductions d
             JOIN split_start ss ON ((ss.ls = ((d.league_id * 10000) + d.season_id))))
          WHERE ((d.effective_date IS NULL) OR (d.effective_date < ss.first_post_date))
          GROUP BY ((((d.league_id * 10000) + d.season_id) * 10000000) + d.team_id)
        ), pre AS (
         SELECT s.ls,
            s.tk,
            ((sum(
                CASE
                    WHEN (s.gf > s.ga) THEN 3
                    WHEN (s.gf = s.ga) THEN 1
                    ELSE 0
                END))::integer + COALESCE(max(pd.pts), 0)) AS pre_total,
            count(*) FILTER (WHERE (s.gf > s.ga)) AS pre_wins,
            sum((s.gf - s.ga)) AS pre_gd,
            sum(s.gf) AS pre_gf
           FROM (sm_side s
             LEFT JOIN pre_ded pd ON ((pd.tk = s.tk)))
          WHERE ((s.post_no <= 0) AND (s.ls IN ( SELECT split_start.ls
                   FROM split_start)))
          GROUP BY s.ls, s.tk
        ), prov AS (
         SELECT r_1.ls,
            r_1.tk,
            r_1.pre_total,
            r_1.rnk,
            COALESCE(( SELECT min(i.i) AS min
                   FROM generate_subscripts(f.group_sizes, 1) i(i)
                  WHERE (r_1.rnk <= ( SELECT sum(x.x) AS sum
                           FROM unnest(f.group_sizes[1:i.i]) x(x)))), cardinality(f.group_sizes)) AS pblock
           FROM (( SELECT pre.ls,
                    pre.tk,
                    pre.pre_total,
                    row_number() OVER (PARTITION BY pre.ls ORDER BY pre.pre_total DESC, pre.pre_wins DESC, pre.pre_gd DESC, pre.pre_gf DESC, pre.tk) AS rnk
                   FROM pre) r_1
             JOIN fmt f ON ((f.ls = r_1.ls)))
        ), post_seq AS (
         SELECT s.ls,
            s.match_id,
            s.tk,
            s.ok,
            row_number() OVER (PARTITION BY s.tk ORDER BY s.match_date, s.kickoff_time, s.match_id) AS gno
           FROM sm_side s
          WHERE (s.post_no > 0)
        ), votes AS (
         SELECT v.tk,
            v.pblock,
            row_number() OVER (PARTITION BY v.tk ORDER BY v.n DESC, (v.pblock = v.own_block) DESC, v.pblock) AS rn
           FROM ( SELECT q.tk,
                    o.pblock,
                    me.pblock AS own_block,
                    count(*) AS n
                   FROM (((post_seq q
                     JOIN prov me ON ((me.tk = q.tk)))
                     JOIN prov o ON ((o.tk = q.ok)))
                     JOIN fmt f ON ((f.ls = q.ls)))
                  WHERE (q.gno <= f.group_games[me.pblock])
                  GROUP BY q.tk, o.pblock, me.pblock) v
        ), blocks AS (
         SELECT p.ls,
            p.tk,
            p.pre_total,
            p.rnk,
            COALESCE(v.pblock, p.pblock) AS blk
           FROM (prov p
             LEFT JOIN votes v ON (((v.tk = p.tk) AND (v.rn = 1))))
        ), knockout AS (
         SELECT DISTINCT q.match_id
           FROM (((post_seq q
             JOIN blocks b ON ((b.tk = q.tk)))
             JOIN blocks bo ON ((bo.tk = q.ok)))
             JOIN fmt f ON ((f.ls = q.ls)))
          WHERE ((b.blk <> bo.blk) OR (q.gno > f.group_games[b.blk]))
        ), split_team AS (
         SELECT b.tk,
            (b.blk)::smallint AS split_group,
            (b.blk = ANY (f.halved_groups)) AS halved,
            f.halving_rounding,
            b.pre_total,
            f.tiebreak,
            b.rnk AS pre_rank
           FROM (blocks b
             JOIN fmt f ON ((f.ls = b.ls)))
        ), home AS (
         SELECT m.league_id,
            m.season_id,
            m.home_team_id AS team_id,
            count(*) AS n,
            count(*) FILTER (WHERE (m.full_time_home_goals > m.full_time_away_goals)) AS w,
            count(*) FILTER (WHERE (m.full_time_home_goals = m.full_time_away_goals)) AS d,
            count(*) FILTER (WHERE (m.full_time_home_goals < m.full_time_away_goals)) AS l,
            sum(m.full_time_home_goals) AS gf,
            sum(m.full_time_away_goals) AS ga,
            count(*) FILTER (WHERE (m.full_time_away_goals = 0)) AS cs,
            count(*) FILTER (WHERE (m.full_time_home_goals = 0)) AS fts
           FROM public.matches m
          WHERE ((m.league_id IN ( SELECT domestic_leagues.league_id
                   FROM domestic_leagues)) AND (m.full_time_home_goals IS NOT NULL) AND (NOT (EXISTS ( SELECT 1
                   FROM knockout
                  WHERE (knockout.match_id = m.match_id)))))
          GROUP BY m.league_id, m.season_id, m.home_team_id
        ), away AS (
         SELECT m.league_id,
            m.season_id,
            m.away_team_id AS team_id,
            count(*) AS n,
            count(*) FILTER (WHERE (m.full_time_away_goals > m.full_time_home_goals)) AS w,
            count(*) FILTER (WHERE (m.full_time_away_goals = m.full_time_home_goals)) AS d,
            count(*) FILTER (WHERE (m.full_time_away_goals < m.full_time_home_goals)) AS l,
            sum(m.full_time_away_goals) AS gf,
            sum(m.full_time_home_goals) AS ga,
            count(*) FILTER (WHERE (m.full_time_home_goals = 0)) AS cs,
            count(*) FILTER (WHERE (m.full_time_away_goals = 0)) AS fts
           FROM public.matches m
          WHERE ((m.league_id IN ( SELECT domestic_leagues.league_id
                   FROM domestic_leagues)) AND (m.full_time_home_goals IS NOT NULL) AND (NOT (EXISTS ( SELECT 1
                   FROM knockout
                  WHERE (knockout.match_id = m.match_id)))))
          GROUP BY m.league_id, m.season_id, m.away_team_id
        ), agg AS (
         SELECT COALESCE(h.league_id, a.league_id) AS league_id,
            COALESCE(h.season_id, a.season_id) AS season_id,
            COALESCE(h.team_id, a.team_id) AS team_id,
            ((COALESCE(h.n, (0)::bigint) + COALESCE(a.n, (0)::bigint)))::integer AS played,
            ((COALESCE(h.w, (0)::bigint) + COALESCE(a.w, (0)::bigint)))::integer AS won,
            ((COALESCE(h.d, (0)::bigint) + COALESCE(a.d, (0)::bigint)))::integer AS drawn,
            ((COALESCE(h.l, (0)::bigint) + COALESCE(a.l, (0)::bigint)))::integer AS lost,
            ((COALESCE(h.gf, (0)::bigint) + COALESCE(a.gf, (0)::bigint)))::integer AS goals_for,
            ((COALESCE(h.ga, (0)::bigint) + COALESCE(a.ga, (0)::bigint)))::integer AS goals_against,
            ((COALESCE(h.cs, (0)::bigint) + COALESCE(a.cs, (0)::bigint)))::integer AS clean_sheets,
            ((COALESCE(h.fts, (0)::bigint) + COALESCE(a.fts, (0)::bigint)))::integer AS failed_to_score,
            (((3 * (COALESCE(h.w, (0)::bigint) + COALESCE(a.w, (0)::bigint))) + (COALESCE(h.d, (0)::bigint) + COALESCE(a.d, (0)::bigint))))::integer AS points_won,
            (COALESCE(h.n, (0)::bigint))::integer AS home_played,
            (((3 * COALESCE(h.w, (0)::bigint)) + COALESCE(h.d, (0)::bigint)))::integer AS home_points,
            (COALESCE(h.gf, (0)::bigint))::integer AS home_goals_for,
            (COALESCE(h.ga, (0)::bigint))::integer AS home_goals_against,
            (COALESCE(a.n, (0)::bigint))::integer AS away_played,
            (((3 * COALESCE(a.w, (0)::bigint)) + COALESCE(a.d, (0)::bigint)))::integer AS away_points,
            (COALESCE(a.gf, (0)::bigint))::integer AS away_goals_for,
            (COALESCE(a.ga, (0)::bigint))::integer AS away_goals_against,
            (COALESCE(h.w, (0)::bigint))::integer AS home_won,
            (COALESCE(h.d, (0)::bigint))::integer AS home_drawn,
            (COALESCE(h.l, (0)::bigint))::integer AS home_lost,
            (COALESCE(h.cs, (0)::bigint))::integer AS home_clean_sheets,
            (COALESCE(a.w, (0)::bigint))::integer AS away_won,
            (COALESCE(a.d, (0)::bigint))::integer AS away_drawn,
            (COALESCE(a.l, (0)::bigint))::integer AS away_lost,
            (COALESCE(a.cs, (0)::bigint))::integer AS away_clean_sheets
           FROM (home h
             FULL JOIN away a ON (((a.league_id = h.league_id) AND (a.season_id = h.season_id) AND (a.team_id = h.team_id))))
        ), shape AS (
         SELECT a.league_id,
            a.season_id,
            (count(*))::integer AS teams,
            ((sum(a.played))::integer / 2) AS matches,
            (a.season_id = ( SELECT cur.season_id
                   FROM cur)) AS is_current
           FROM agg a
          GROUP BY a.league_id, a.season_id
        ), ded AS MATERIALIZED (
         SELECT ((((point_deductions.league_id * 10000) + point_deductions.season_id) * 10000000) + point_deductions.team_id) AS tk,
            (sum(point_deductions.points))::integer AS pts
           FROM public.point_deductions
          GROUP BY ((((point_deductions.league_id * 10000) + point_deductions.season_id) * 10000000) + point_deductions.team_id)
        ), scored AS (
         SELECT a.league_id,
            a.season_id,
            a.team_id,
            a.played,
            a.won,
            a.drawn,
            a.lost,
            a.goals_for,
            a.goals_against,
            a.clean_sheets,
            a.failed_to_score,
            a.points_won,
            a.home_played,
            a.home_points,
            a.home_goals_for,
            a.home_goals_against,
            a.away_played,
            a.away_points,
            a.away_goals_for,
            a.away_goals_against,
            a.home_won,
            a.home_drawn,
            a.home_lost,
            a.home_clean_sheets,
            a.away_won,
            a.away_drawn,
            a.away_lost,
            a.away_clean_sheets,
            s.teams,
            s.is_current,
            COALESCE(d.pts, 0) AS deduction,
            ((a.points_won + COALESCE(d.pts, 0)) + adj.split_adjustment) AS points,
            (((a.points_won + COALESCE(d.pts, 0)))::numeric - adj.exact_cut) AS rank_points,
            COALESCE(lf.curtailed_on_ppg, ((NOT s.is_current) AND (s.matches < (s.teams * (s.teams - 1))))) AS curtailed,
            ((lg.code = ANY (ARRAY['E1'::text, 'E2'::text, 'E3'::text])) AND (se_1.start_year <= 1998)) AS goals_scored_first,
            st.split_group,
            adj.split_adjustment,
            st.tiebreak,
            st.pre_rank,
            st.pre_total,
            ((((a.league_id * 10000) + a.season_id) * 10000000) + a.team_id) AS tk
           FROM (((((((agg a
             JOIN shape s USING (league_id, season_id))
             LEFT JOIN ded d ON ((d.tk = ((((a.league_id * 10000) + a.season_id) * 10000000) + a.team_id))))
             JOIN public.leagues lg ON ((lg.league_id = a.league_id)))
             JOIN public.seasons se_1 ON ((se_1.season_id = a.season_id)))
             LEFT JOIN public.league_season_formats lf ON (((lf.league_id = a.league_id) AND (lf.season_id = a.season_id))))
             LEFT JOIN split_team st ON ((st.tk = ((((a.league_id * 10000) + a.season_id) * 10000000) + a.team_id))))
             CROSS JOIN LATERAL ( SELECT
                        CASE
                            WHEN COALESCE(st.halved, false) THEN ((
                            CASE
                                WHEN (st.halving_rounding = 'up'::text) THEN ceil(((st.pre_total)::numeric / 2.0))
                                ELSE floor(((st.pre_total)::numeric / 2.0))
                            END - (st.pre_total)::numeric))::integer
                            ELSE 0
                        END AS split_adjustment,
                        CASE
                            WHEN COALESCE(st.halved, false) THEN ((st.pre_total)::numeric / 2.0)
                            ELSE (0)::numeric
                        END AS exact_cut) adj)
        ), tied AS MATERIALIZED (
         SELECT x.tk,
            x.tiebreak,
            x.tie_key
           FROM ( SELECT sc.tk,
                    sc.tiebreak,
                    k.tie_key,
                    count(*) OVER (PARTITION BY k.tie_key) AS n
                   FROM (scored sc
                     CROSS JOIN LATERAL ( SELECT ((((((((sc.league_id * 10000) + sc.season_id))::text || '/'::text) || (sc.split_group)::text) || '/'::text) || (sc.rank_points)::text) ||
                                CASE
                                    WHEN (sc.tiebreak = 'regular_points'::text) THEN ('/'::text || (sc.pre_total)::text)
                                    ELSE ''::text
                                END) AS tie_key) k)
                  WHERE (sc.tiebreak = ANY (ARRAY['head_to_head'::text, 'regular_points'::text]))) x
          WHERE (x.n > 1)
        ), tied_games AS MATERIALIZED (
         SELECT s.match_id,
            s.tk,
            s.ok,
            s.post_no,
            s.gf,
            s.ga
           FROM sm_side s
          WHERE ((s.tk IN ( SELECT tied.tk
                   FROM tied)) AND (s.ok IN ( SELECT tied.tk
                   FROM tied)))
        ), h2h AS MATERIALIZED (
         SELECT a.tk,
            sum(
                CASE
                    WHEN (g.gf > g.ga) THEN 3
                    WHEN (g.gf = g.ga) THEN 1
                    ELSE 0
                END) AS pts,
            sum((g.gf - g.ga)) AS gd,
            sum(g.gf) AS gf
           FROM ((tied_games g
             JOIN tied a ON ((a.tk = g.tk)))
             JOIN tied b ON (((b.tk = g.ok) AND (b.tie_key = a.tie_key))))
          WHERE (((a.tiebreak = 'head_to_head'::text) OR (g.post_no <= 0)) AND (NOT (EXISTS ( SELECT 1
                   FROM knockout k
                  WHERE (k.match_id = g.match_id)))))
          GROUP BY a.tk
        ), ranked AS (
         SELECT sc.league_id,
            sc.season_id,
            sc.team_id,
            sc.played,
            sc.won,
            sc.drawn,
            sc.lost,
            sc.goals_for,
            sc.goals_against,
            sc.clean_sheets,
            sc.failed_to_score,
            sc.points_won,
            sc.home_played,
            sc.home_points,
            sc.home_goals_for,
            sc.home_goals_against,
            sc.away_played,
            sc.away_points,
            sc.away_goals_for,
            sc.away_goals_against,
            sc.home_won,
            sc.home_drawn,
            sc.home_lost,
            sc.home_clean_sheets,
            sc.away_won,
            sc.away_drawn,
            sc.away_lost,
            sc.away_clean_sheets,
            sc.teams,
            sc.is_current,
            sc.deduction,
            sc.points,
            sc.curtailed,
            sc.split_group,
            sc.split_adjustment,
            (row_number() OVER (PARTITION BY sc.league_id, sc.season_id ORDER BY COALESCE((sc.split_group)::integer, 0),
                CASE
                    WHEN sc.curtailed THEN ((sc.points)::numeric / (NULLIF(sc.played, 0))::numeric)
                    ELSE sc.rank_points
                END DESC,
                CASE sc.tiebreak
                    WHEN 'regular_position'::text THEN (- sc.pre_rank)
                    WHEN 'regular_points'::text THEN (sc.pre_total)::bigint
                    ELSE COALESCE(h.pts, (0)::bigint)
                END DESC,
                CASE sc.tiebreak
                    WHEN 'regular_points'::text THEN COALESCE(h.pts, (0)::bigint)
                    ELSE COALESCE(h.gd, (0)::bigint)
                END DESC,
                CASE sc.tiebreak
                    WHEN 'regular_points'::text THEN COALESCE(h.gd, (0)::bigint)
                    ELSE COALESCE(h.gf, (0)::bigint)
                END DESC,
                CASE sc.tiebreak
                    WHEN 'regular_points'::text THEN COALESCE(h.gf, (0)::bigint)
                    ELSE (0)::bigint
                END DESC,
                CASE
                    WHEN sc.goals_scored_first THEN sc.goals_for
                    ELSE (sc.goals_for - sc.goals_against)
                END DESC,
                CASE
                    WHEN sc.goals_scored_first THEN (sc.goals_for - sc.goals_against)
                    ELSE sc.goals_for
                END DESC, t.canonical_name))::integer AS "position"
           FROM ((scored sc
             JOIN public.teams t USING (team_id))
             LEFT JOIN h2h h ON ((h.tk = sc.tk)))
        )
 SELECT r.league_id,
    l.code AS league_code,
    public.league_name_for_season(r.league_id, r.season_id) AS league_name,
    (r.league_id)::integer AS tier,
    r.season_id,
    se.label AS season_label,
    r.team_id,
    r."position",
    (r."position" + (COALESCE(( SELECT sum(s2.teams) AS sum
           FROM (shape s2
             JOIN public.leagues l2 ON ((l2.league_id = s2.league_id)))
          WHERE ((s2.season_id = r.season_id) AND (s2.league_id < r.league_id) AND (l2.country_id = l.country_id))), (0)::bigint))::integer) AS pyramid_position,
    r.teams,
    (NOT r.is_current) AS is_final,
    r.curtailed,
        CASE
            WHEN r.curtailed THEN 'points per game'::text
            ELSE 'points'::text
        END AS ranked_on,
    r.played,
    r.won,
    r.drawn,
    r.lost,
    r.goals_for,
    r.goals_against,
    r.clean_sheets,
    r.failed_to_score,
    r.points_won,
    r.deduction,
    r.points,
    round(((r.points)::numeric / (NULLIF(r.played, 0))::numeric), 2) AS ppg,
    r.home_played,
    r.home_points,
    r.home_goals_for,
    r.home_goals_against,
    r.away_played,
    r.away_points,
    r.away_goals_for,
    r.away_goals_against,
    r.home_won,
    r.home_drawn,
    r.home_lost,
    r.home_clean_sheets,
    r.away_won,
    r.away_drawn,
    r.away_lost,
    r.away_clean_sheets,
    se.start_year AS season_start_year,
    r.split_group,
    r.split_adjustment
   FROM ((ranked r
     JOIN public.leagues l USING (league_id))
     JOIN public.seasons se USING (season_id));


ALTER VIEW public.league_standings OWNER TO postgres;

--
-- Name: team_season_summary; Type: MATERIALIZED VIEW; Schema: public; Owner: postgres
--

CREATE MATERIALIZED VIEW public.team_season_summary AS
 WITH ls AS (
         SELECT l.league_id,
            l.league_code,
            l.league_name,
            l.tier,
            l.season_id,
            l.season_label,
            l.team_id,
            l."position",
            l.pyramid_position,
            l.teams,
            l.is_final,
            l.curtailed,
            l.ranked_on,
            l.played,
            l.won,
            l.drawn,
            l.lost,
            l.goals_for,
            l.goals_against,
            l.clean_sheets,
            l.failed_to_score,
            l.points_won,
            l.deduction,
            l.points,
            l.ppg,
            l.home_played,
            l.home_points,
            l.home_goals_for,
            l.home_goals_against,
            l.away_played,
            l.away_points,
            l.away_goals_for,
            l.away_goals_against,
            l.home_won,
            l.home_drawn,
            l.home_lost,
            l.home_clean_sheets,
            l.away_won,
            l.away_drawn,
            l.away_lost,
            l.away_clean_sheets,
            l.season_start_year,
            l.split_group,
            l.split_adjustment,
            s.start_year
           FROM ((public.league_standings l
             JOIN public.seasons s ON ((s.season_id = l.season_id)))
             JOIN public.leagues lg ON (((lg.league_id = l.league_id) AND (lg.competition_type = 'league'::text))))
        ), next_season AS (
         SELECT s.season_id,
            n.season_id AS next_season_id
           FROM (public.seasons s
             JOIN public.seasons n ON ((n.start_year = (s.start_year + 1))))
        ), games AS (
         SELECT ls_1.league_id,
            ls_1.season_id,
            max(ls_1.played) AS games_in_season,
            count(*) AS clubs
           FROM ls ls_1
          GROUP BY ls_1.league_id, ls_1.season_id
        )
 SELECT ls.league_id,
    ls.league_code,
    ls.league_name,
    ls.season_id,
    ls.season_label,
    ls.start_year,
    ls.team_id,
    ls."position",
    ls.teams,
    ls.is_final,
    ls.curtailed,
    ls.ranked_on,
    ls.played,
    ls.won,
    ls.drawn,
    ls.lost,
    ls.goals_for,
    ls.goals_against,
    (ls.goals_for - ls.goals_against) AS goal_difference,
    ls.clean_sheets,
    ls.failed_to_score,
    ls.points_won,
    ls.deduction,
    ls.points,
    ls.ppg,
    ls.home_played,
    ls.home_won,
    ls.home_drawn,
    ls.home_lost,
    ls.home_points,
    ls.home_goals_for,
    ls.home_goals_against,
    ls.away_played,
    ls.away_won,
    ls.away_drawn,
    ls.away_lost,
    ls.away_points,
    ls.away_goals_for,
    ls.away_goals_against,
    ls.split_group,
    g.games_in_season,
    g.clubs,
    ((g.clubs || 'x'::text) || (2 * (g.clubs - 1))) AS comparable_group,
    (EXISTS ( SELECT 1
           FROM public.league_season_formats f
          WHERE ((f.league_id = ls.league_id) AND (f.season_id = ls.season_id) AND (f.format = 'split'::text)))) AS split_format,
    (ls.is_final AND (ls."position" = 1)) AS champion,
        CASE
            WHEN ls.is_final THEN (ls."position" <= 4)
            ELSE NULL::boolean
        END AS top_four,
        CASE
            WHEN ls.is_final THEN (ls."position" <= 6)
            ELSE NULL::boolean
        END AS top_six,
    nxt.league_id AS next_league_id,
        CASE
            WHEN ((NOT ls.is_final) OR (NOT nx.next_known)) THEN NULL::boolean
            WHEN (((ls.league_id >= 1) AND (ls.league_id <= 5)) AND (nxt.league_id IS NULL)) THEN
            CASE
                WHEN (ls.league_id = 5) THEN true
                ELSE NULL::boolean
            END
            WHEN ((ls.league_id >= 1) AND (ls.league_id <= 5)) THEN (nxt.league_id > ls.league_id)
            ELSE (nxt.league_id IS NULL)
        END AS relegated,
        CASE
            WHEN ((NOT ls.is_final) OR (NOT nx.next_known)) THEN NULL::boolean
            WHEN ((ls.league_id >= 1) AND (ls.league_id <= 5)) THEN (nxt.league_id < ls.league_id)
            ELSE false
        END AS promoted
   FROM ((((ls
     JOIN games g ON (((g.league_id = ls.league_id) AND (g.season_id = ls.season_id))))
     LEFT JOIN next_season ns ON ((ns.season_id = ls.season_id)))
     LEFT JOIN LATERAL ( SELECT (EXISTS ( SELECT 1
                   FROM ls l2
                  WHERE ((l2.season_id = ns.next_season_id) AND ((l2.league_id = ls.league_id) OR (((ls.league_id >= 1) AND (ls.league_id <= 5)) AND ((l2.league_id >= 1) AND (l2.league_id <= 5))))))) AS next_known) nx ON (true))
     LEFT JOIN LATERAL ( SELECT l3.league_id
           FROM ls l3
          WHERE ((l3.season_id = ns.next_season_id) AND (l3.team_id = ls.team_id) AND ((l3.league_id = ls.league_id) OR (((ls.league_id >= 1) AND (ls.league_id <= 5)) AND ((l3.league_id >= 1) AND (l3.league_id <= 5)))))
         LIMIT 1) nxt ON (true))
  WITH NO DATA;


ALTER MATERIALIZED VIEW public.team_season_summary OWNER TO postgres;

--
-- Name: league_season_summary; Type: MATERIALIZED VIEW; Schema: public; Owner: postgres
--

CREATE MATERIALIZED VIEW public.league_season_summary AS
 WITH m AS (
         SELECT m.league_id,
            m.season_id,
            m.full_time_home_goals AS hg,
            m.full_time_away_goals AS ag,
            (m.half_time_home_goals IS NOT NULL) AS has_ht,
            (m.home_shots IS NOT NULL) AS has_stats
           FROM (public.matches m
             JOIN public.leagues l ON (((l.league_id = m.league_id) AND (l.competition_type = 'league'::text))))
          WHERE ((m.full_time_home_goals IS NOT NULL) AND (m.full_time_away_goals IS NOT NULL))
        ), mm AS (
         SELECT m.league_id,
            m.season_id,
            count(*) AS matches,
            avg((m.hg + m.ag)) AS goals_per_game,
            avg(m.hg) AS home_goals_per_game,
            avg(m.ag) AS away_goals_per_game,
            avg(((m.hg > m.ag))::integer) AS home_win_share,
            avg(((m.hg = m.ag))::integer) AS draw_share,
            avg(((m.hg < m.ag))::integer) AS away_win_share,
            avg((((m.hg = 0) AND (m.ag = 0)))::integer) AS goalless_share,
            ((avg(((m.ag = 0))::integer) + avg(((m.hg = 0))::integer)) / (2)::numeric) AS clean_sheet_share,
            avg(abs((m.hg - m.ag))) FILTER (WHERE (m.hg <> m.ag)) AS avg_winning_margin,
            (avg(
                CASE
                    WHEN (m.hg > m.ag) THEN 3
                    WHEN (m.hg = m.ag) THEN 1
                    ELSE 0
                END) - avg(
                CASE
                    WHEN (m.ag > m.hg) THEN 3
                    WHEN (m.hg = m.ag) THEN 1
                    ELSE 0
                END)) AS home_ppg_advantage,
            avg((m.has_ht)::integer) AS half_time_coverage,
            avg((m.has_stats)::integer) AS stats_coverage
           FROM m
          GROUP BY m.league_id, m.season_id
        ), t AS (
         SELECT team_season_summary.league_id,
            team_season_summary.season_id,
            max(team_season_summary.league_code) AS league_code,
            max(team_season_summary.season_label) AS season_label,
            max(team_season_summary.start_year) AS start_year,
            max(team_season_summary.clubs) AS clubs,
            max(team_season_summary.games_in_season) AS games_in_season,
            max(team_season_summary.comparable_group) AS comparable_group,
            bool_and(team_season_summary.is_final) AS is_final,
            bool_or(team_season_summary.curtailed) AS curtailed,
            bool_or(team_season_summary.split_format) AS split_format,
            max(team_season_summary.points) FILTER (WHERE team_season_summary.champion) AS champion_points,
            max(team_season_summary.ppg) FILTER (WHERE team_season_summary.champion) AS champion_ppg,
            max(team_season_summary.points) FILTER (WHERE team_season_summary.relegated) AS highest_relegated_points,
            min(team_season_summary.points) FILTER (WHERE (team_season_summary.relegated = false)) AS lowest_safe_points,
            stddev_samp(team_season_summary.ppg) AS ppg_sd,
            ((stddev_samp((((team_season_summary.won)::numeric + (0.5 * (team_season_summary.drawn)::numeric)) / (NULLIF(team_season_summary.played, 0))::numeric)))::double precision / ((0.5)::double precision / sqrt((max(team_season_summary.games_in_season))::double precision))) AS noll_scully,
            (max(team_season_summary.points) - min(team_season_summary.points)) AS points_spread
           FROM public.team_season_summary
          GROUP BY team_season_summary.league_id, team_season_summary.season_id
        )
 SELECT t.league_id,
    t.season_id,
    t.league_code,
    t.season_label,
    t.start_year,
    t.clubs,
    t.games_in_season,
    t.comparable_group,
    t.is_final,
    t.curtailed,
    t.split_format,
    t.champion_points,
    t.champion_ppg,
    t.highest_relegated_points,
    t.lowest_safe_points,
    t.ppg_sd,
    t.noll_scully,
    t.points_spread,
    mm.matches,
    mm.goals_per_game,
    mm.home_goals_per_game,
    mm.away_goals_per_game,
    mm.home_win_share,
    mm.draw_share,
    mm.away_win_share,
    mm.goalless_share,
    mm.clean_sheet_share,
    mm.avg_winning_margin,
    mm.home_ppg_advantage,
    mm.half_time_coverage,
    mm.stats_coverage,
    (t.start_year = ANY (ARRAY[2019, 2020])) AS covid_affected
   FROM (t
     JOIN mm ON (((mm.league_id = t.league_id) AND (mm.season_id = t.season_id))))
  WITH NO DATA;


ALTER MATERIALIZED VIEW public.league_season_summary OWNER TO postgres;

--
-- Name: history_streaks; Type: MATERIALIZED VIEW; Schema: public; Owner: postgres
--

CREATE MATERIALIZED VIEW public.history_streaks AS
 WITH base AS (
         SELECT s.league_id,
            s.team_id,
            s.season_id,
            se.start_year,
            s.match_id,
            s.match_date,
            s.matches_played,
            s.result,
            s.goals_for,
            s.goals_against,
            (se.start_year - dense_rank() OVER (PARTITION BY s.league_id, s.team_id ORDER BY se.start_year)) AS spell
           FROM (public.team_match_snapshot s
             JOIN public.seasons se USING (season_id))
        ), typed AS (
         SELECT b.league_id,
            b.team_id,
            b.season_id,
            b.start_year,
            b.match_id,
            b.match_date,
            b.matches_played,
            b.result,
            b.goals_for,
            b.goals_against,
            b.spell,
            k.streak_type,
                CASE k.streak_type
                    WHEN 'won'::text THEN (b.result = 'W'::text)
                    WHEN 'unbeaten'::text THEN (b.result <> 'L'::text)
                    WHEN 'winless'::text THEN (b.result <> 'W'::text)
                    WHEN 'lost'::text THEN (b.result = 'L'::text)
                    WHEN 'scored'::text THEN (b.goals_for > 0)
                    WHEN 'clean_sheet'::text THEN (b.goals_against = 0)
                    WHEN 'no_goal'::text THEN (b.goals_for = 0)
                    ELSE NULL::boolean
                END AS ok
           FROM (base b
             CROSS JOIN ( VALUES ('won'::text), ('unbeaten'::text), ('winless'::text), ('lost'::text), ('scored'::text), ('clean_sheet'::text), ('no_goal'::text)) k(streak_type))
        ), islands AS (
         SELECT typed.league_id,
            typed.team_id,
            typed.season_id,
            typed.start_year,
            typed.match_id,
            typed.match_date,
            typed.matches_played,
            typed.result,
            typed.goals_for,
            typed.goals_against,
            typed.spell,
            typed.streak_type,
            typed.ok,
            (row_number() OVER (PARTITION BY typed.league_id, typed.team_id, typed.spell, typed.streak_type ORDER BY typed.match_date, typed.match_id) - row_number() OVER (PARTITION BY typed.league_id, typed.team_id, typed.spell, typed.streak_type, typed.ok ORDER BY typed.match_date, typed.match_id)) AS grp
           FROM typed
        ), runs AS (
         SELECT islands.league_id,
            islands.team_id,
            islands.streak_type,
            (count(*))::integer AS length,
            min(islands.match_date) AS start_date,
            max(islands.match_date) AS end_date,
            (array_agg(islands.season_id ORDER BY islands.match_date, islands.match_id))[1] AS start_season_id,
            (array_agg(islands.season_id ORDER BY islands.match_date DESC, islands.match_id DESC))[1] AS end_season_id,
            (array_agg(islands.match_id ORDER BY islands.match_date, islands.match_id))[1] AS start_match_id,
            (array_agg(islands.match_id ORDER BY islands.match_date DESC, islands.match_id DESC))[1] AS end_match_id,
            (array_agg(islands.matches_played ORDER BY islands.match_date, islands.match_id))[1] AS start_matches_played
           FROM islands
          WHERE islands.ok
          GROUP BY islands.league_id, islands.team_id, islands.spell, islands.streak_type, islands.grp
         HAVING (count(*) >= 3)
        ), last_match AS (
         SELECT team_match_snapshot.league_id,
            team_match_snapshot.team_id,
            max(team_match_snapshot.match_date) AS last_date
           FROM public.team_match_snapshot
          GROUP BY team_match_snapshot.league_id, team_match_snapshot.team_id
        ), league_edges AS (
         SELECT league_season_summary.league_id,
            (array_agg(league_season_summary.season_id ORDER BY league_season_summary.start_year))[1] AS first_season_id,
            (array_agg(league_season_summary.season_id ORDER BY league_season_summary.start_year DESC))[1] AS latest_season_id,
            (array_agg(league_season_summary.is_final ORDER BY league_season_summary.start_year DESC))[1] AS latest_is_final
           FROM public.league_season_summary
          GROUP BY league_season_summary.league_id
        )
 SELECT r.league_id,
    r.team_id,
    r.streak_type,
    r.length,
    r.start_date,
    r.end_date,
    r.start_season_id,
    r.end_season_id,
    r.start_match_id,
    r.end_match_id,
    ((r.end_season_id = e.latest_season_id) AND (NOT e.latest_is_final) AND (r.end_date = lm.last_date)) AS ongoing,
    ((r.start_season_id = e.first_season_id) AND (r.start_matches_played = 1)) AS truncated_start
   FROM ((runs r
     JOIN league_edges e USING (league_id))
     JOIN last_match lm USING (league_id, team_id))
  WITH NO DATA;


ALTER MATERIALIZED VIEW public.history_streaks OWNER TO postgres;

