    variants_tried integer DEFAULT 0 NOT NULL,
    registered_at timestamp with time zone DEFAULT now() NOT NULL,
    holdout_opened_at timestamp with time zone,
    concluded_at timestamp with time zone,
    conclusion text,
    CONSTRAINT lab_experiments_status_check CHECK ((status = ANY (ARRAY['registered'::text, 'tuned'::text, 'validated'::text, 'holdout_opened'::text, 'passed'::text, 'failed'::text, 'null_result'::text, 'abandoned'::text])))
);


