);


ALTER TABLE public.match_odds OWNER TO postgres;

--
-- Name: lab_market_probs; Type: MATERIALIZED VIEW; Schema: public; Owner: postgres
--

CREATE MATERIALIZED VIEW public.lab_market_probs AS
 SELECT o.match_id,
    o.bookmaker,
    o.is_closing,
    ((((1)::numeric / o.price_home) + ((1)::numeric / o.price_draw)) + ((1)::numeric / o.price_away)) AS overround,
    (((1)::numeric / o.price_home) / ((((1)::numeric / o.price_home) + ((1)::numeric / o.price_draw)) + ((1)::numeric / o.price_away))) AS basic_home,
    (((1)::numeric / o.price_draw) / ((((1)::numeric / o.price_home) + ((1)::numeric / o.price_draw)) + ((1)::numeric / o.price_away))) AS basic_draw,
    (((1)::numeric / o.price_away) / ((((1)::numeric / o.price_home) + ((1)::numeric / o.price_draw)) + ((1)::numeric / o.price_away))) AS basic_away,
    x.pw[1] AS power_home,
    x.pw[2] AS power_draw,
    x.pw[3] AS power_away,
    x.sh[1] AS shin_home,
    x.sh[2] AS shin_draw,
    x.sh[3] AS shin_away
   FROM (public.match_odds o
     CROSS JOIN LATERAL ( SELECT public.lab_devig_power(o.price_home, o.price_draw, o.price_away) AS pw,
            public.lab_devig_shin(o.price_home, o.price_draw, o.price_away) AS sh) x)
  WHERE ((o.market = '1x2'::text) AND (o.bookmaker = ANY (ARRAY['Avg'::text, 'PS'::text, 'BFE'::text, 'B365'::text, 'Max'::text])) AND (o.price_home > (1)::numeric) AND (o.price_draw > (1)::numeric) AND (o.price_away > (1)::numeric) AND (EXISTS ( SELECT 1
           FROM public.matches m
          WHERE ((m.match_id = o.match_id) AND (m.match_date >= '2016-07-01'::date)))))
  WITH NO DATA;


ALTER MATERIALIZED VIEW public.lab_market_probs OWNER TO postgres;

--
-- Name: model_experiment_predictions; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.model_experiment_predictions (
    experiment text NOT NULL,
    variant text NOT NULL,
    half_life_days double precision NOT NULL,
    shrinkage double precision NOT NULL,
    match_id bigint NOT NULL,
    as_of_date date NOT NULL,
    pred_home_goals double precision NOT NULL,
    pred_away_goals double precision NOT NULL,
    rho double precision NOT NULL,
    p_home double precision NOT NULL,
    p_draw double precision NOT NULL,
    p_away double precision NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


ALTER TABLE public.model_experiment_predictions OWNER TO postgres;

--
-- Name: lab_f1_dataset; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.lab_f1_dataset WITH (security_invoker='true') AS
 SELECT m.match_id,
    m.league_id,
    s.start_year,
    m.match_date,
        CASE
            WHEN (m.full_time_home_goals > m.full_time_away_goals) THEN 'H'::text
            WHEN (m.full_time_home_goals = m.full_time_away_goals) THEN 'D'::text
            ELSE 'A'::text
        END AS result,
    e.p_home AS dc_home,
    e.p_draw AS dc_draw,
    e.p_away AS dc_away,
    e.as_of_date AS dc_as_of,
    c.basic_home AS close_home,
    c.basic_draw AS close_draw,
    c.basic_away AS close_away,
    o.basic_home AS open_home,
    o.basic_draw AS open_draw,
    o.basic_away AS open_away
   FROM ((((public.matches m
     JOIN public.seasons s USING (season_id))
     JOIN public.model_experiment_predictions e ON (((e.match_id = m.match_id) AND (e.experiment = 'dc_walkforward_v1'::text) AND (e.variant = 'hl180_s0'::text) AND (e.as_of_date < m.match_date))))
     JOIN public.lab_market_probs c ON (((c.match_id = m.match_id) AND (c.bookmaker = 'Avg'::text) AND c.is_closing)))
     JOIN public.lab_market_probs o ON (((o.match_id = m.match_id) AND (o.bookmaker = 'Avg'::text) AND (NOT o.is_closing))))
  WHERE (((m.league_id >= 1) AND (m.league_id <= 4)) AND (s.start_year >= 2019) AND (m.full_time_home_goals IS NOT NULL));


ALTER VIEW public.lab_f1_dataset OWNER TO postgres;

--
-- Name: lab_f4_lines; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.lab_f4_lines WITH (security_invoker='true') AS
 SELECT m.match_id,
    m.league_id,
    s.start_year,
    m.match_date,
    m.home_team_id,
    m.away_team_id,
    m.full_time_home_goals AS hg,
    m.full_time_away_goals AS ag,
    c.basic_home AS p_home,
    c.basic_draw AS p_draw,
    c.basic_away AS p_away,
    (((1)::numeric / ou.price_over) / (((1)::numeric / ou.price_over) + ((1)::numeric / ou.price_under))) AS p_over
   FROM (((public.matches m
     JOIN public.seasons s USING (season_id))
     JOIN public.lab_market_probs c ON (((c.match_id = m.match_id) AND (c.bookmaker = 'Avg'::text) AND c.is_closing)))
     JOIN public.match_odds ou ON (((ou.match_id = m.match_id) AND (ou.market = 'ou25'::text) AND (ou.bookmaker = 'Avg'::text) AND ou.is_closing AND (ou.price_over > (1)::numeric) AND (ou.price_under > (1)::numeric))))
  WHERE (((m.league_id >= 1) AND (m.league_id <= 4)) AND (s.start_year >= 2019) AND (m.full_time_home_goals IS NOT NULL));


ALTER VIEW public.lab_f4_lines OWNER TO postgres;

