--
-- Name: league_fit_status; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.league_fit_status WITH (security_invoker='true') AS
 SELECT l.league_id,
    l.code AS league_code,
    l.name AS league_name,
    latest_attempt.fit_run_id AS latest_attempted_fit_run_id,
    latest_attempt.status AS latest_attempted_status,
    latest_attempt.fitted_at AS latest_attempted_fitted_at,
    latest_attempt.matches_used AS latest_attempted_matches_used,
    latest_attempt.converged AS latest_attempted_converged,
    latest_attempt.rejection_reason AS latest_attempted_rejection_reason,
    latest_attempt.validation_warnings AS latest_attempted_validation_warnings,
    accepted.fit_run_id AS accepted_fit_run_id,
    accepted.fitted_at AS accepted_fitted_at,
    accepted.matches_used AS accepted_matches_used,
    accepted.rho AS accepted_rho,
    accepted.home_advantage AS accepted_home_advantage
   FROM ((public.leagues l
     LEFT JOIN LATERAL ( SELECT m.fit_run_id,
            m.league_id,
            m.window_start_date,
            m.window_end_date,
            m.rho,
            m.home_advantage,
            m.decay_half_life_days,
            m.log_likelihood,
            m.converged,
            m.matches_used,
            m.fitted_at,
            m.status,
            m.rejection_reason,
            m.validation_warnings,
            m.validation_checks
           FROM public.model_fit_runs m
          WHERE (m.league_id = l.league_id)
          ORDER BY m.fitted_at DESC
         LIMIT 1) latest_attempt ON (true))
     LEFT JOIN LATERAL ( SELECT m.fit_run_id,
            m.league_id,
            m.window_start_date,
            m.window_end_date,
            m.rho,
            m.home_advantage,
            m.decay_half_life_days,
            m.log_likelihood,
            m.converged,
            m.matches_used,
            m.fitted_at,
            m.status,
            m.rejection_reason,
            m.validation_warnings,
            m.validation_checks
           FROM public.model_fit_runs m
          WHERE ((m.league_id = l.league_id) AND (m.status = 'accepted'::text))
          ORDER BY m.fitted_at DESC
         LIMIT 1) accepted ON (true))
  WHERE (l.competition_type = 'league'::text);


ALTER VIEW public.league_fit_status OWNER TO postgres;

--
-- Name: league_pace_benchmarks; Type: MATERIALIZED VIEW; Schema: public; Owner: postgres
--

CREATE MATERIALIZED VIEW public.league_pace_benchmarks AS
 WITH base AS (
         SELECT s.league_id,
            t.comparable_group,
            s.matches_played,
            s.points,
            t.champion,
            t.top_four,
            t.top_six,
            t.relegated
           FROM (public.team_match_snapshot s
             JOIN public.team_season_summary t USING (league_id, season_id, team_id))
          WHERE (t.is_final AND (NOT t.curtailed) AND (NOT t.split_format))
        ), grouped AS (
         SELECT base.league_id,
            base.comparable_group,
            base.matches_played,
            'all'::text AS outcome,
            base.points
           FROM base
        UNION ALL
         SELECT base.league_id,
            base.comparable_group,
            base.matches_played,
            'champion'::text,
            base.points
           FROM base
          WHERE base.champion
        UNION ALL
         SELECT base.league_id,
            base.comparable_group,
            base.matches_played,
            'top_four'::text,
            base.points
           FROM base
          WHERE base.top_four
        UNION ALL
         SELECT base.league_id,
            base.comparable_group,
            base.matches_played,
            'top_six'::text,
            base.points
           FROM base
          WHERE base.top_six
        UNION ALL
         SELECT base.league_id,
            base.comparable_group,
            base.matches_played,
            'relegated'::text,
            base.points
           FROM base
          WHERE base.relegated
        )
 SELECT league_id,
    comparable_group,
    matches_played,
    outcome,
    count(*) AS team_seasons,
    percentile_cont((0.10)::double precision) WITHIN GROUP (ORDER BY ((points)::double precision)) AS p10,
    percentile_cont((0.25)::double precision) WITHIN GROUP (ORDER BY ((points)::double precision)) AS p25,
    percentile_cont((0.50)::double precision) WITHIN GROUP (ORDER BY ((points)::double precision)) AS p50,
    percentile_cont((0.75)::double precision) WITHIN GROUP (ORDER BY ((points)::double precision)) AS p75,
    percentile_cont((0.90)::double precision) WITHIN GROUP (ORDER BY ((points)::double precision)) AS p90,
    min(points) AS min_points,
    max(points) AS max_points,
    avg(points) AS mean_points
   FROM grouped
  GROUP BY league_id, comparable_group, matches_played, outcome
  WITH NO DATA;


ALTER MATERIALIZED VIEW public.league_pace_benchmarks OWNER TO postgres;

