--
-- Name: team_season_movement; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.team_season_movement AS
 WITH ts AS (
         SELECT matches.league_id,
            matches.season_id,
            matches.home_team_id AS team_id
           FROM public.matches
          WHERE ((matches.league_id >= 1) AND (matches.league_id <= 5))
        UNION
         SELECT matches.league_id,
            matches.season_id,
            matches.away_team_id
           FROM public.matches
          WHERE ((matches.league_id >= 1) AND (matches.league_id <= 5))
        ), first_season AS (
         SELECT se_first.season_id
           FROM public.seasons se_first
          WHERE (se_first.start_year = ( SELECT min(se_m.start_year) AS min
                   FROM public.seasons se_m
                  WHERE (se_m.season_id IN ( SELECT ts.season_id
                           FROM ts))))
        )
 SELECT t.league_id,
    t.season_id,
    t.team_id,
    p.league_id AS previous_league_id,
        CASE
            WHEN (t.season_id = ( SELECT first_season.season_id
               FROM first_season)) THEN 'unknown'::text
            WHEN (p.league_id IS NULL) THEN 'new'::text
            WHEN (p.league_id > t.league_id) THEN 'promoted'::text
            WHEN (p.league_id < t.league_id) THEN 'relegated'::text
            ELSE 'stayed'::text
        END AS movement,
    ((t.season_id <> ( SELECT first_season.season_id
           FROM first_season)) AND ((p.league_id IS NULL) OR (p.league_id > t.league_id))) AS is_promoted
   FROM (((ts t
     LEFT JOIN public.seasons se_t ON ((se_t.season_id = t.season_id)))
     LEFT JOIN public.seasons se_prev ON ((se_prev.start_year = (se_t.start_year - 1))))
     LEFT JOIN ts p ON (((p.team_id = t.team_id) AND (p.season_id = se_prev.season_id))));


ALTER VIEW public.team_season_movement OWNER TO postgres;

--
-- Name: model_scorecard_matches; Type: MATERIALIZED VIEW; Schema: public; Owner: postgres
--

CREATE MATERIALIZED VIEW public.model_scorecard_matches AS
 WITH cur AS (
         SELECT se_cur.season_id AS s,
            se_cur.start_year AS y
           FROM public.seasons se_cur
          WHERE (se_cur.start_year = ( SELECT max(se_m.start_year) AS max
                   FROM public.seasons se_m
                  WHERE (se_m.season_id IN ( SELECT matches.season_id
                           FROM public.matches
                          WHERE ((matches.league_id >= 1) AND (matches.league_id <= 5))))))
        ), preds AS (
         SELECT m.match_id,
            m.league_id,
            m.season_id,
            m.match_date AS md,
            m.home_team_id,
            m.away_team_id,
            m.full_time_home_goals AS hg,
            m.full_time_away_goals AS ag,
            (mp.predicted_home_goals)::numeric AS lh,
            (mp.predicted_away_goals)::numeric AS la,
            mp.fit_run_id
           FROM (public.match_predictions mp
             JOIN public.matches m USING (match_id))
          WHERE ((( SELECT se_p.start_year
                   FROM public.seasons se_p
                  WHERE (se_p.season_id = m.season_id)) < ( SELECT cur.y
                   FROM cur)) AND (m.full_time_home_goals IS NOT NULL))
        UNION ALL
         SELECT m.match_id,
            m.league_id,
            m.season_id,
            m.match_date,
            m.home_team_id,
            m.away_team_id,
            m.full_time_home_goals,
            m.full_time_away_goals,
            (f.predicted_home_goals)::numeric AS predicted_home_goals,
            (f.predicted_away_goals)::numeric AS predicted_away_goals,
            f.prediction_fit_run_id
           FROM (public.fixtures f
             JOIN public.matches m ON (((m.home_team_id = f.home_team_id) AND (m.away_team_id = f.away_team_id) AND (m.match_date = f.kickoff_date) AND (m.league_id = f.league_id))))
          WHERE ((f.season_id = ( SELECT cur.s
                   FROM cur)) AND (f.status = 'played'::text) AND (f.predicted_home_goals IS NOT NULL) AND (m.full_time_home_goals IS NOT NULL))
        ), mk AS (
         SELECT o.match_id,
            ((1)::numeric / o.price_home) AS ih,
            ((1)::numeric / o.price_draw) AS id,
            ((1)::numeric / o.price_away) AS ia
           FROM public.match_odds o
          WHERE ((o.market = '1x2'::text) AND o.is_closing AND (o.bookmaker = 'Avg'::text) AND (o.price_home > (1)::numeric) AND (o.price_draw > (1)::numeric) AND (o.price_away > (1)::numeric))
        )
 SELECT p.match_id,
    p.league_id,
    p.season_id,
    p.md AS match_date,
    p.fit_run_id,
    r.model_version,
        CASE
            WHEN (EXISTS ( SELECT 1
               FROM public.team_ratings t
              WHERE ((t.fit_run_id = p.fit_run_id) AND (t.team_id = ANY (ARRAY[p.home_team_id, p.away_team_id])) AND t.is_estimated))) THEN 'estimated'::text
            WHEN (EXISTS ( SELECT 1
               FROM public.team_season_movement v
              WHERE ((v.season_id = p.season_id) AND (v.league_id = p.league_id) AND (v.team_id = ANY (ARRAY[p.home_team_id, p.away_team_id])) AND (v.movement = 'relegated'::text)))) THEN 'relegated'::text
            WHEN (EXISTS ( SELECT 1
               FROM public.team_season_movement v
              WHERE ((v.season_id = p.season_id) AND (v.league_id = p.league_id) AND (v.team_id = ANY (ARRAY[p.home_team_id, p.away_team_id])) AND v.is_promoted))) THEN 'promoted'::text
            ELSE 'established'::text
        END AS team_type,
        CASE
            WHEN (EXTRACT(month FROM p.md) = ANY (ARRAY[(7)::numeric, (8)::numeric, (9)::numeric, (10)::numeric])) THEN '1 Aug-Oct'::text
            WHEN (EXTRACT(month FROM p.md) = ANY (ARRAY[(11)::numeric, (12)::numeric])) THEN '2 Nov-Dec'::text
            WHEN (EXTRACT(month FROM p.md) = ANY (ARRAY[(1)::numeric, (2)::numeric, (3)::numeric])) THEN '3 Jan-Mar'::text
            ELSE '4 Apr-May'::text
        END AS phase,
        CASE
            WHEN (p.hg > p.ag) THEN 'H'::text
            WHEN (p.hg = p.ag) THEN 'D'::text
            ELSE 'A'::text
        END AS result,
    p.hg,
    p.ag,
    p.lh,
    p.la,
    (dm.home_win / 100.0) AS p_home,
    (dm.draw / 100.0) AS p_draw,
    (dm.away_win / 100.0) AS p_away,
    (mk.ih / ((mk.ih + mk.id) + mk.ia)) AS m_home,
    (mk.id / ((mk.ih + mk.id) + mk.ia)) AS m_draw,
    (mk.ia / ((mk.ih + mk.id) + mk.ia)) AS m_away
   FROM (((preds p
     JOIN mk USING (match_id))
     LEFT JOIN public.model_fit_runs r ON ((r.fit_run_id = p.fit_run_id)))
     CROSS JOIN LATERAL public.fixture_derived_markets(p.lh, p.la, (COALESCE(r.rho, (0)::double precision))::numeric) dm(home_win, draw, away_win, over_2_5, under_2_5, btts, home_clean_sheet, away_clean_sheet))
  WITH NO DATA;


ALTER MATERIALIZED VIEW public.model_scorecard_matches OWNER TO postgres;

--
-- Name: model_versions; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.model_versions (
    version text NOT NULL,
    component text NOT NULL,
    description text NOT NULL,
    params jsonb DEFAULT '{}'::jsonb NOT NULL,
    introduced_at date,
    retired_at date,
    CONSTRAINT model_versions_component_check CHECK ((component = ANY (ARRAY['fit'::text, 'prediction'::text])))
);


ALTER TABLE public.model_versions OWNER TO postgres;

--
-- Name: model_vs_market_by_league; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.model_vs_market_by_league WITH (security_invoker='true') AS
 SELECT league_id,
    min(match_date) AS from_date,
    max(match_date) AS to_date,
    count(*) AS matches,
    avg((- ln(
        CASE result
            WHEN 'H'::text THEN p_home
            WHEN 'D'::text THEN p_draw
            ELSE p_away
        END))) AS model_log_loss,
    avg((- ln(
        CASE result
            WHEN 'H'::text THEN m_home
            WHEN 'D'::text THEN m_draw
            ELSE m_away
        END))) AS market_log_loss,
    avg((((((
        CASE result
            WHEN 'H'::text THEN 1
            ELSE 0
        END)::numeric - p_home) ^ (2)::numeric) + (((
        CASE result
            WHEN 'D'::text THEN 1
            ELSE 0
        END)::numeric - p_draw) ^ (2)::numeric)) + (((
        CASE result
            WHEN 'A'::text THEN 1
            ELSE 0
        END)::numeric - p_away) ^ (2)::numeric))) AS model_brier,
    avg((((((
        CASE result
            WHEN 'H'::text THEN 1
            ELSE 0
        END)::numeric - m_home) ^ (2)::numeric) + (((
        CASE result
            WHEN 'D'::text THEN 1
            ELSE 0
        END)::numeric - m_draw) ^ (2)::numeric)) + (((
        CASE result
            WHEN 'A'::text THEN 1
            ELSE 0
        END)::numeric - m_away) ^ (2)::numeric))) AS market_brier
   FROM public.model_scorecard_matches
  WHERE ((m_home IS NOT NULL) AND (p_home IS NOT NULL))
  GROUP BY league_id;


ALTER VIEW public.model_vs_market_by_league OWNER TO postgres;

--
-- Name: nfl_game_model; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.nfl_game_model WITH (security_invoker='true') AS
 SELECT DISTINCT ON (p.game_id) p.game_id,
    p.model_version,
    p.predicted_at,
    p.home_edge,
    p.p_home,
    p.predicted_margin,
    p.market_p_home,
    p.spread_line,
    p.total_line
   FROM (nfl.model_predictions p
     JOIN nfl.games g ON ((g.game_id = p.game_id)))
  WHERE ((g.kickoff_at IS NULL) OR (p.predicted_at < g.kickoff_at))
  ORDER BY p.game_id, p.predicted_at DESC;


ALTER VIEW public.nfl_game_model OWNER TO postgres;

--
-- Name: nfl_games; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.nfl_games WITH (security_invoker='true') AS
 SELECT g.game_id,
    g.season,
    g.game_type,
    g.week,
    g.gameday,
    g.kickoff_at,
    ha.franchise AS home_franchise,
    hf.slug AS home_slug,
    COALESCE(hs.full_name, hf.name) AS home_name,
    hf.short_name AS home_short,
    aa.franchise AS away_franchise,
    af.slug AS away_slug,
    COALESCE(aws.full_name, af.name) AS away_name,
    af.short_name AS away_short,
    g.home_score,
    g.away_score,
    g.overtime,
    g.neutral_site,
    g.div_game,
    g.spread_line,
    g.total_line,
    g.stadium,
    g.roof,
    g.surface,
    g.home_qb_name,
    g.away_qb_name
   FROM ((((((nfl.games g
     JOIN nfl.team_codes ha ON ((ha.code = g.home_code)))
     JOIN nfl.franchises hf ON ((hf.franchise = ha.franchise)))
     JOIN nfl.team_codes aa ON ((aa.code = g.away_code)))
     JOIN nfl.franchises af ON ((af.franchise = aa.franchise)))
     LEFT JOIN nfl.team_seasons hs ON (((hs.season = g.season) AND (hs.code = g.home_code))))
     LEFT JOIN nfl.team_seasons aws ON (((aws.season = g.season) AND (aws.code = g.away_code))));


ALTER VIEW public.nfl_games OWNER TO postgres;

--
-- Name: nfl_lab_games; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.nfl_lab_games WITH (security_invoker='true') AS
 SELECT g.game_id,
    g.season,
