    g.gametime,
    g.kickoff_at,
    g.away_code,
    g.home_code,
    g.away_score,
    g.home_score,
    g.overtime,
    g.neutral_site,
    g.div_game,
    g.spread_line,
    g.total_line,
    g.away_moneyline,
    g.home_moneyline,
    g.roof,
    g.surface,
    g.stadium,
    g.away_qb_name,
    g.home_qb_name,
    g.away_coach,
    g.home_coach,
    g.imported_at,
    g.away_rest,
    g.home_rest,
