    hc.franchise AS home_franchise,
    ac.franchise AS away_franchise
   FROM ((nfl.games g
     JOIN nfl.team_codes hc ON ((hc.code = g.home_code)))
     JOIN nfl.team_codes ac ON ((ac.code = g.away_code)));


ALTER VIEW public.nfl_lab_games OWNER TO postgres;

--
-- Name: nfl_player_seasons; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.nfl_player_seasons WITH (security_invoker='true') AS
 WITH w AS (
         SELECT pw.player_id,
            pw.game_id,
            pw.season,
            pw.week,
            pw.season_type,
            pw.team,
            pw.opponent,
            pw."position",
            pw.completions,
            pw.attempts,
            pw.passing_yards,
            pw.passing_tds,
            pw.interceptions,
            pw.sacks,
            pw.passing_2pt,
            pw.carries,
            pw.rushing_yards,
            pw.rushing_tds,
            pw.rushing_2pt,
            pw.receptions,
            pw.targets,
            pw.receiving_yards,
            pw.receiving_tds,
            pw.receiving_2pt,
            pw.fumbles_lost,
            pw.special_teams_tds,
            pw.target_share,
            pw.air_yards_share,
            pw.wopr,
            pw.fg_made_0_39,
            pw.fg_made_40_49,
            pw.fg_made_50_plus,
            pw.fg_att,
            pw.fg_missed,
            pw.pat_made,
            pw.pat_missed,
            pw.src_points_std,
            pw.src_points_ppr,
            pw.imported_at,
            nfl.points_std(pw.*) AS s,
            tc.franchise AS fr,
            row_number() OVER (PARTITION BY pw.player_id, pw.season ORDER BY pw.week DESC) AS recency
           FROM (nfl.player_weeks pw
             JOIN nfl.team_codes tc ON ((tc.code = pw.team)))
          WHERE (pw.season_type = 'REG'::text)
        )
 SELECT w.player_id,
    p.slug AS player_slug,
    p.name AS player_name,
    (array_agg(w."position" ORDER BY w.week DESC))[1] AS "position",
    w.season,
    (array_agg(f.franchise ORDER BY w.week DESC))[1] AS team,
    (array_agg(f.slug ORDER BY w.week DESC))[1] AS team_slug,
    (array_agg(f.short_name ORDER BY w.week DESC))[1] AS team_short,
    count(*) AS games,
    sum(w.completions) AS completions,
    sum(w.attempts) AS attempts,
    sum(w.passing_yards) AS passing_yards,
    sum(w.passing_tds) AS passing_tds,
    sum(w.interceptions) AS interceptions,
    sum(w.carries) AS carries,
    sum(w.rushing_yards) AS rushing_yards,
    sum(w.rushing_tds) AS rushing_tds,
    sum(w.receptions) AS receptions,
    sum(w.targets) AS targets,
    sum(w.receiving_yards) AS receiving_yards,
    sum(w.receiving_tds) AS receiving_tds,
    sum(w.fumbles_lost) AS fumbles_lost,
    round(avg(w.target_share), 3) AS target_share,
    sum(((w.fg_made_0_39 + w.fg_made_40_49) + w.fg_made_50_plus)) AS fg_made,
    sum(w.fg_att) AS fg_att,
    sum(w.pat_made) AS pat_made,
    sum(w.s) AS pts_std,
    sum((w.s + (0.5 * (w.receptions)::numeric))) AS pts_half,
    sum((w.s + (w.receptions)::numeric)) AS pts_ppr,
    round(avg(w.s), 2) AS ppg_std,
    round(avg((w.s + (0.5 * (w.receptions)::numeric))), 2) AS ppg_half,
    round(avg((w.s + (w.receptions)::numeric)), 2) AS ppg_ppr,
    round(avg((w.s + (w.receptions)::numeric)) FILTER (WHERE (w.recency <= 3)), 2) AS last3_ppg_ppr,
    round(avg(w.s) FILTER (WHERE (w.recency <= 3)), 2) AS last3_ppg_std,
    round(avg((w.s + (0.5 * (w.receptions)::numeric))) FILTER (WHERE (w.recency <= 3)), 2) AS last3_ppg_half,
    round(stddev_pop((w.s + (w.receptions)::numeric)), 2) AS sd_ppr,
    max((w.s + (w.receptions)::numeric)) AS best_ppr,
    max(w.week) AS last_week
   FROM ((w
     JOIN nfl.players p ON ((p.player_id = w.player_id)))
     JOIN nfl.franchises f ON ((f.franchise = w.fr)))
  GROUP BY w.player_id, p.slug, p.name, w.season;


ALTER VIEW public.nfl_player_seasons OWNER TO postgres;

--
-- Name: nfl_player_weeks; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.nfl_player_weeks WITH (security_invoker='true') AS
 SELECT w.player_id,
    p.slug AS player_slug,
    p.name AS player_name,
    w."position",
    w.season,
    w.week,
    w.season_type,
    w.game_id,
    tf.franchise AS team,
    opf.franchise AS opponent,
    opf.slug AS opponent_slug,
    opf.short_name AS opponent_short,
    (g.home_code = w.team) AS at_home,
    g.gameday,
    g.kickoff_at,
        CASE
            WHEN (g.home_code = w.team) THEN g.home_score
            ELSE g.away_score
        END AS team_score,
        CASE
            WHEN (g.home_code = w.team) THEN g.away_score
            ELSE g.home_score
        END AS opponent_score,
    w.completions,
    w.attempts,
    w.passing_yards,
    w.passing_tds,
    w.interceptions,
    w.sacks,
    w.carries,
    w.rushing_yards,
    w.rushing_tds,
    w.receptions,
    w.targets,
    w.receiving_yards,
    w.receiving_tds,
    w.fumbles_lost,
    ((w.passing_2pt + w.rushing_2pt) + w.receiving_2pt) AS two_pt,
    w.special_teams_tds,
    w.target_share,
    w.air_yards_share,
    w.wopr,
    ((w.fg_made_0_39 + w.fg_made_40_49) + w.fg_made_50_plus) AS fg_made,
    w.fg_att,
    w.pat_made,
    w.pat_missed,
    nfl.points_std(w.*) AS pts_std,
    (nfl.points_std(w.*) + (0.5 * (w.receptions)::numeric)) AS pts_half,
    (nfl.points_std(w.*) + (w.receptions)::numeric) AS pts_ppr
   FROM ((((((nfl.player_weeks w
     JOIN nfl.players p ON ((p.player_id = w.player_id)))
     JOIN nfl.games g ON ((g.game_id = w.game_id)))
     JOIN nfl.team_codes tc ON ((tc.code = w.team)))
     JOIN nfl.franchises tf ON ((tf.franchise = tc.franchise)))
     JOIN nfl.team_codes oc ON ((oc.code = w.opponent)))
     JOIN nfl.franchises opf ON ((opf.franchise = oc.franchise)));


ALTER VIEW public.nfl_player_weeks OWNER TO postgres;

--
-- Name: nfl_players; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.nfl_players WITH (security_invoker='true') AS
 SELECT p.player_id,
    p.slug,
    p.name,
    p."position",
    p.position_group,
    f.franchise AS team,
    f.slug AS team_slug,
    f.name AS team_name,
    p.birth_date,
    p.height_in,
    p.weight_lb,
    p.college,
    p.rookie_season,
    p.draft_year,
    p.draft_round,
    p.draft_pick,
    p.jersey_number,
    p.status,
    p.years_exp
   FROM ((nfl.players p
     LEFT JOIN nfl.team_codes tc ON ((tc.code = p.latest_team)))
     LEFT JOIN nfl.franchises f ON ((f.franchise = tc.franchise)));


ALTER VIEW public.nfl_players OWNER TO postgres;

--
-- Name: nfl_points_allowed; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.nfl_points_allowed WITH (security_invoker='true') AS
 WITH by_game AS (
         SELECT w.season,
            oc.franchise AS defence,
            w.game_id,
                CASE
                    WHEN (w."position" = 'FB'::text) THEN 'RB'::text
                    ELSE w."position"
                END AS "position",
            sum(nfl.points_std(w.*)) AS std,
            sum((nfl.points_std(w.*) + (w.receptions)::numeric)) AS ppr,
            sum((nfl.points_std(w.*) + (0.5 * (w.receptions)::numeric))) AS half
           FROM (nfl.player_weeks w
             JOIN nfl.team_codes oc ON ((oc.code = w.opponent)))
          WHERE (w.season_type = 'REG'::text)
          GROUP BY w.season, oc.franchise, w.game_id,
                CASE
                    WHEN (w."position" = 'FB'::text) THEN 'RB'::text
                    ELSE w."position"
                END
        ), agg AS (
         SELECT by_game.season,
            by_game.defence,
            by_game."position",
            count(*) AS games,
            round(avg(by_game.std), 2) AS std_per_game,
            round(avg(by_game.half), 2) AS half_per_game,
            round(avg(by_game.ppr), 2) AS ppr_per_game
           FROM by_game
          GROUP BY by_game.season, by_game.defence, by_game."position"
        )
 SELECT a.season,
    a.defence,
    a."position",
    a.games,
    a.std_per_game,
    a.half_per_game,
    a.ppr_per_game,
    f.slug AS defence_slug,
    f.name AS defence_name,
    f.short_name AS defence_short,
    rank() OVER (PARTITION BY a.season, a."position" ORDER BY a.ppr_per_game DESC) AS ppr_rank
   FROM (agg a
     JOIN nfl.franchises f ON ((f.franchise = a.defence)));


ALTER VIEW public.nfl_points_allowed OWNER TO postgres;

--
-- Name: nfl_projections; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.nfl_projections WITH (security_invoker='true') AS
 SELECT pr.game_id,
    pr.season,
    pr.week,
    g.kickoff_at,
    g.gameday,
    pr.player_id,
    p.slug AS player_slug,
    p.name AS player_name,
    pr."position",
    tf.franchise AS team,
    tf.slug AS team_slug,
    tf.short_name AS team_short,
    tf.name AS team_name,
    opf.franchise AS opponent,
    opf.slug AS opponent_slug,
    opf.short_name AS opponent_short,
    (g.home_code = pr.team) AS at_home,
    pr.method,
    pr.proj_ppr,
    pr.proj_half,
    pr.proj_std,
    pr.low_ppr,
    pr.high_ppr,
    pr.base_ppr,
    pr.season_avg_ppr,
    pr.team_implied,
    pr.team_usual,
    pr.opp_factor,
    pr.games_used,
    pr.injury_status,
    pr.injury,
    pr.practice_status,
    pr.computed_at
   FROM ((((((nfl.projections pr
     JOIN nfl.players p ON ((p.player_id = pr.player_id)))
     JOIN nfl.games g ON ((g.game_id = pr.game_id)))
     JOIN nfl.team_codes tc ON ((tc.code = pr.team)))
     JOIN nfl.franchises tf ON ((tf.franchise = tc.franchise)))
     JOIN nfl.team_codes oc ON ((oc.code = pr.opponent)))
     JOIN nfl.franchises opf ON ((opf.franchise = oc.franchise)));


ALTER VIEW public.nfl_projections OWNER TO postgres;

--
-- Name: nfl_season_summary; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.nfl_season_summary WITH (security_invoker='true') AS
 SELECT season,
    count(*) FILTER (WHERE (game_type = 'REG'::text)) AS reg_games,
    count(*) FILTER (WHERE ((game_type = 'REG'::text) AND (home_score IS NOT NULL))) AS reg_played,
    round(avg((home_score + away_score)) FILTER (WHERE (game_type = 'REG'::text)), 2) AS points_per_game,
    round(avg(
        CASE
            WHEN (home_score > away_score) THEN 1.0
            WHEN (home_score < away_score) THEN 0.0
            ELSE 0.5
        END) FILTER (WHERE ((game_type = 'REG'::text) AND (NOT neutral_site))), 3) AS home_win_share,
    round(avg(
        CASE
            WHEN (abs((home_score - away_score)) <= 8) THEN 1.0
            ELSE 0.0
        END) FILTER (WHERE (game_type = 'REG'::text)), 3) AS one_score_share,
    count(*) FILTER (WHERE ((game_type = 'REG'::text) AND overtime)) AS overtime_games,
    count(*) FILTER (WHERE ((game_type = 'REG'::text) AND (home_score = away_score))) AS ties,
    round(avg(
        CASE
            WHEN ((spread_line > (0)::numeric) AND (home_score > away_score)) THEN 1.0
            WHEN ((spread_line < (0)::numeric) AND (away_score > home_score)) THEN 1.0
            WHEN ((spread_line <> (0)::numeric) AND (home_score <> away_score)) THEN 0.0
            ELSE NULL::numeric
        END) FILTER (WHERE (game_type = 'REG'::text)), 3) AS favourite_win_share,
    count(*) FILTER (WHERE ((game_type = 'REG'::text) AND neutral_site)) AS neutral_games
   FROM nfl.games g
  WHERE (home_score IS NOT NULL)
  GROUP BY season;


ALTER VIEW public.nfl_season_summary OWNER TO postgres;

--
-- Name: nfl_standings; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.nfl_standings WITH (security_invoker='true') AS
 WITH sides AS (
         SELECT g.season,
            g.game_type,
            tc.franchise,
            g.home_code AS code,
            g.home_score AS pf,
            g.away_score AS pa,
            true AS is_home,
            g.div_game,
            ha.franchise AS me,
            aa.franchise AS opp
           FROM (((nfl.games g
             JOIN nfl.team_codes tc ON ((tc.code = g.home_code)))
             JOIN nfl.team_codes ha ON ((ha.code = g.home_code)))
             JOIN nfl.team_codes aa ON ((aa.code = g.away_code)))
          WHERE (g.home_score IS NOT NULL)
        UNION ALL
         SELECT g.season,
            g.game_type,
            tc.franchise,
            g.away_code,
            g.away_score,
            g.home_score,
            false,
            g.div_game,
            aa.franchise,
            ha.franchise
           FROM (((nfl.games g
             JOIN nfl.team_codes tc ON ((tc.code = g.away_code)))
             JOIN nfl.team_codes ha ON ((ha.code = g.home_code)))
             JOIN nfl.team_codes aa ON ((aa.code = g.away_code)))
          WHERE (g.home_score IS NOT NULL)
        ), reg AS (
         SELECT s.season,
            s.franchise,
            max(s.code) AS code,
            count(*) AS played,
            count(*) FILTER (WHERE (s.pf > s.pa)) AS won,
            count(*) FILTER (WHERE (s.pf < s.pa)) AS lost,
            count(*) FILTER (WHERE (s.pf = s.pa)) AS tied,
            sum(s.pf) AS points_for,
            sum(s.pa) AS points_against,
            count(*) FILTER (WHERE (s.is_home AND (s.pf > s.pa))) AS home_won,
            count(*) FILTER (WHERE (s.is_home AND (s.pf < s.pa))) AS home_lost,
            count(*) FILTER (WHERE ((NOT s.is_home) AND (s.pf > s.pa))) AS away_won,
            count(*) FILTER (WHERE ((NOT s.is_home) AND (s.pf < s.pa))) AS away_lost,
            count(*) FILTER (WHERE (s.div_game AND (s.pf > s.pa))) AS div_won,
            count(*) FILTER (WHERE (s.div_game AND (s.pf < s.pa))) AS div_lost,
            count(*) FILTER (WHERE (s.div_game AND (s.pf = s.pa))) AS div_tied,
            count(*) FILTER (WHERE ((fo.conference = fm.conference) AND (s.pf > s.pa))) AS conf_won,
            count(*) FILTER (WHERE ((fo.conference = fm.conference) AND (s.pf < s.pa))) AS conf_lost
           FROM ((sides s
             JOIN nfl.franchises fm ON ((fm.franchise = s.me)))
             JOIN nfl.franchises fo ON ((fo.franchise = s.opp)))
          WHERE (s.game_type = 'REG'::text)
          GROUP BY s.season, s.franchise
        ), post AS (
         SELECT sides.season,
            sides.franchise,
            max(
                CASE sides.game_type
                    WHEN 'WC'::text THEN 1
                    WHEN 'DIV'::text THEN 2
                    WHEN 'CON'::text THEN 3
                    WHEN 'SB'::text THEN 4
                    ELSE NULL::integer
                END) AS round_reached,
            bool_or(((sides.game_type = 'SB'::text) AND (sides.pf > sides.pa))) AS won_title
           FROM sides
          WHERE (sides.game_type <> 'REG'::text)
          GROUP BY sides.season, sides.franchise
        ), div_winners AS (
         SELECT sides.season,
            sides.franchise
           FROM sides
          WHERE (sides.game_type <> 'REG'::text)
          GROUP BY sides.season, sides.franchise
         HAVING (bool_or(((sides.game_type = 'WC'::text) AND sides.is_home)) OR ((NOT bool_or((sides.game_type = 'WC'::text))) AND bool_or((sides.game_type = 'DIV'::text))))
        ), seasons_done AS (
         SELECT games.season,
            bool_or(((games.game_type = 'SB'::text) AND (games.home_score IS NOT NULL))) AS complete
           FROM nfl.games
          GROUP BY games.season
        )
 SELECT r.season,
    f.franchise,
    f.slug,
    COALESCE(ts.full_name, f.name) AS team_name,
    f.short_name,
    f.conference,
    f.division,
    r.played,
    r.won,
    r.lost,
    r.tied,
    round((((r.won)::numeric + (0.5 * (r.tied)::numeric)) / (NULLIF(r.played, 0))::numeric), 3) AS win_pct,
    r.points_for,
    r.points_against,
    (r.points_for - r.points_against) AS point_diff,
    r.home_won,
    r.home_lost,
    r.away_won,
    r.away_lost,
    r.div_won,
    r.div_lost,
    r.div_tied,
    r.conf_won,
    r.conf_lost,
        CASE
            WHEN p.won_title THEN 'Won Super Bowl'::text
            WHEN (p.round_reached = 4) THEN 'Lost Super Bowl'::text
            WHEN (p.round_reached = 3) THEN 'Lost conference championship'::text
            WHEN (p.round_reached = 2) THEN 'Lost divisional round'::text
            WHEN (p.round_reached = 1) THEN 'Lost wild card round'::text
            ELSE NULL::text
        END AS playoff_result,
    COALESCE(p.round_reached, 0) AS playoff_round,
    COALESCE(sd.complete, false) AS season_complete,
    rank() OVER (PARTITION BY r.season, f.conference, f.division ORDER BY (dw.franchise IS NOT NULL) DESC, (((r.won)::numeric + (0.5 * (r.tied)::numeric)) / (NULLIF(r.played, 0))::numeric) DESC, (((r.div_won)::numeric + (0.5 * (r.div_tied)::numeric)) / (NULLIF(((r.div_won + r.div_lost) + r.div_tied), 0))::numeric) DESC NULLS LAST, (r.points_for - r.points_against) DESC) AS division_rank,
        CASE
            WHEN COALESCE(sd.complete, false) THEN (dw.franchise IS NOT NULL)
            ELSE NULL::boolean
        END AS won_division
   FROM (((((reg r
     JOIN nfl.franchises f ON ((f.franchise = r.franchise)))
     LEFT JOIN nfl.team_seasons ts ON (((ts.season = r.season) AND (ts.code = r.code))))
     LEFT JOIN post p ON (((p.season = r.season) AND (p.franchise = r.franchise))))
     LEFT JOIN seasons_done sd ON ((sd.season = r.season)))
     LEFT JOIN div_winners dw ON (((dw.season = r.season) AND (dw.franchise = r.franchise))));


ALTER VIEW public.nfl_standings OWNER TO postgres;

