--
-- Name: team_strength_current; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.team_strength_current AS
 WITH latest_fit AS (
         SELECT DISTINCT ON (model_fit_runs.league_id) model_fit_runs.fit_run_id,
            model_fit_runs.league_id,
            model_fit_runs.window_start_date,
            model_fit_runs.window_end_date,
            model_fit_runs.rho,
            model_fit_runs.home_advantage,
            model_fit_runs.decay_half_life_days,
            model_fit_runs.matches_used,
            model_fit_runs.fitted_at
           FROM public.model_fit_runs
          WHERE (model_fit_runs.status = 'accepted'::text)
          ORDER BY model_fit_runs.league_id, model_fit_runs.fitted_at DESC, model_fit_runs.fit_run_id DESC
        ), rated AS (
         SELECT lf.league_id,
            lf.fit_run_id,
            lf.window_start_date,
            lf.window_end_date,
            lf.rho,
            lf.home_advantage,
            lf.decay_half_life_days,
            lf.matches_used,
            lf.fitted_at,
            tr.team_id,
            t.canonical_name,
            tr.attack_strength,
            tr.defence_strength,
            tr.is_estimated,
            round((((100)::double precision * percent_rank() OVER (PARTITION BY lf.fit_run_id ORDER BY tr.attack_strength)))::numeric, 1) AS attack_score,
            round((((100)::double precision * percent_rank() OVER (PARTITION BY lf.fit_run_id ORDER BY tr.defence_strength)))::numeric, 1) AS defence_score,
            rank() OVER (PARTITION BY lf.fit_run_id ORDER BY tr.attack_strength DESC) AS attack_rank,
            rank() OVER (PARTITION BY lf.fit_run_id ORDER BY tr.defence_strength DESC) AS defence_rank
           FROM ((latest_fit lf
             JOIN public.team_ratings tr ON ((tr.fit_run_id = lf.fit_run_id)))
             JOIN public.teams t ON ((t.team_id = tr.team_id)))
        )
 SELECT r.league_id,
    r.fit_run_id,
    r.window_start_date,
    r.window_end_date,
    r.rho,
    r.home_advantage,
    r.decay_half_life_days,
    r.matches_used,
    r.fitted_at,
    r.team_id,
    r.canonical_name,
    r.attack_strength,
    r.defence_strength,
    r.is_estimated,
    r.attack_score,
    r.defence_score,
    r.attack_rank,
    r.defence_rank,
    round(((r.attack_score + r.defence_score) / (2)::numeric), 1) AS overall_score,
    ft.fpl_team_id,
    ft.name AS fpl_team_name,
    ft.short_name AS fpl_short_name
   FROM (rated r
     LEFT JOIN public.fpl_teams ft ON (((ft.canonical_team_id = r.team_id) AND (ft.season_id = ( SELECT public.fpl_current_season_id() AS fpl_current_season_id)))));


ALTER VIEW public.team_strength_current OWNER TO postgres;

--
-- Name: team_strength_forward_adjustments; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.team_strength_forward_adjustments (
    id bigint NOT NULL,
    season_id bigint NOT NULL,
    team_id bigint NOT NULL,
    scope text DEFAULT 'admin'::text NOT NULL,
    scenario_key text DEFAULT 'baseline'::text NOT NULL,
    attack_log_adjustment numeric DEFAULT 0 NOT NULL,
    defence_log_adjustment numeric DEFAULT 0 NOT NULL,
    effective_from date NOT NULL,
    effective_to date,
    decay_fixtures numeric,
    reason text,
    source_name text,
    source_reference text,
    is_active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT team_strength_forward_adjustments_check CHECK (((effective_to IS NULL) OR (effective_to >= effective_from))),
    CONSTRAINT team_strength_forward_adjustments_decay_fixtures_check CHECK (((decay_fixtures IS NULL) OR (decay_fixtures > (0)::numeric))),
    CONSTRAINT team_strength_forward_adjustments_scope_check CHECK ((scope = ANY (ARRAY['system'::text, 'admin'::text, 'user'::text])))
);


ALTER TABLE public.team_strength_forward_adjustments OWNER TO postgres;

