CREATE VIEW public.tennis_events WITH (security_invoker='true') AS
 SELECT event_id,
    tour,
    slug,
    name,
    city,
    country,
    level,
    level_rank,
    surface,
    first_year,
    last_year,
    editions
   FROM tennis.events e;


ALTER VIEW public.tennis_events OWNER TO postgres;

--
-- Name: tennis_matches; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.tennis_matches WITH (security_invoker='true') AS
 SELECT m.source_key,
    m.tour,
    m.year,
    m.match_date,
    t.tournament_id,
    t.name AS tournament,
    t.slug AS tournament_slug,
    m.location,
    m.series,
    m.court,
    m.surface,
    m.round,
    m.best_of,
    m.winner_id,
    w.name AS winner,
    w.slug AS winner_slug,
    m.loser_id,
    l.name AS loser,
    l.slug AS loser_slug,
    m.w_rank,
    m.l_rank,
    m.w_pts,
    m.l_pts,
    m.w_games,
    m.l_games,
    m.w_sets,
    m.l_sets,
    m.status,
    m.ps_w,
    m.ps_l,
    m.avg_w,
    m.avg_l,
    m.max_w,
    m.max_l,
    m.b365_w,
    m.b365_l,
    m.bfe_w,
    m.bfe_l,
    tennis.level_of(m.tour, m.series, t.name) AS level,
    tennis.level_rank(tennis.level_of(m.tour, m.series, t.name)) AS level_rank,
    tennis.round_order(m.round) AS round_order,
    tennis.result_of(m.status, m.w_games) AS result,
    (tennis.result_of(m.status, m.w_games) = ANY (ARRAY['Completed'::text, 'Retired'::text, 'Awarded'::text, 'Disqualified'::text])) AS played,
        CASE
            WHEN (m.surface = 'Greenset'::text) THEN 'Hard'::text
            ELSE m.surface
        END AS surface_group
   FROM (((tennis.matches m
     JOIN tennis.tournaments t ON ((t.tournament_id = m.tournament_id)))
     JOIN tennis.players w ON ((w.player_id = m.winner_id)))
     JOIN tennis.players l ON ((l.player_id = m.loser_id)));


ALTER VIEW public.tennis_matches OWNER TO postgres;

--
-- Name: tennis_player_editions; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.tennis_player_editions WITH (security_invoker='true') AS
 SELECT pe.player_id,
    p.tour,
    p.slug,
    pe.tournament_id,
    pe.year,
    pe.event_id,
    ev.slug AS event_slug,
    d.name,
    d.level,
    d.level_rank,
    d.surface,
    d.start_date,
    pe.won,
    pe.lost,
    pe.last_round,
    pe.last_round_order,
    pe.champion
   FROM (((tennis.player_editions pe
     JOIN tennis.players p USING (player_id))
     JOIN tennis.editions d ON (((d.tournament_id = pe.tournament_id) AND (d.year = pe.year))))
     JOIN tennis.events ev ON ((ev.event_id = pe.event_id)));


ALTER VIEW public.tennis_player_editions OWNER TO postgres;

