--
-- Name: tennis_players; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.tennis_players WITH (security_invoker='true') AS
 SELECT p.player_id,
    p.tour,
    p.name,
    p.slug,
    t.matches,
    t.wins,
    t.first_match,
    t.last_match,
    t.won,
    t.lost,
    t.titles,
    t.finals,
    t.first_year,
    t.last_year,
    t.recent_matches,
    pp.country,
    pp.full_name,
    pp.birth_date,
    pp.hand,
    pp.wikidata_qid,
    t.best_rank,
    t.best_rank_date
   FROM ((tennis.players p
     JOIN tennis.player_totals t USING (player_id))
     LEFT JOIN tennis.player_people pp USING (player_id));


ALTER VIEW public.tennis_players OWNER TO postgres;

--
-- Name: tennis_tournaments; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.tennis_tournaments WITH (security_invoker='true') AS
 SELECT t.tournament_id,
    t.tour,
    t.name,
    t.slug,
    min(m.year) AS first_year,
    max(m.year) AS last_year,
    count(*) AS matches
   FROM (tennis.tournaments t
     JOIN tennis.matches m ON ((m.tournament_id = t.tournament_id)))
  GROUP BY t.tournament_id;


ALTER VIEW public.tennis_tournaments OWNER TO postgres;

--
-- Name: upcoming_broadcast_fixtures; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.upcoming_broadcast_fixtures AS
 SELECT fb.broadcast_id,
    fb.market,
    fb.broadcaster,
    fb.channel,
    fb.streaming_service,
    fb.is_free_to_air,
    fb.is_subscription,
    fb.is_ppv,
    fb.watch_url,
    f.fixture_id,
    f.slug,
    f.kickoff_date,
    f.kickoff_time,
    f.league_id,
    l.code AS league_code,
    l.name AS league_name,
    co.name AS country_name,
    ht.team_id AS home_team_id,
    ht.display_name AS home_team_name,
    at.team_id AS away_team_id,
    at.display_name AS away_team_name,
    f.predicted_home_goals,
    f.predicted_away_goals
   FROM (((((public.fixture_broadcasts fb
     JOIN public.fixtures f ON ((f.fixture_id = fb.fixture_id)))
     JOIN public.leagues l ON ((l.league_id = f.league_id)))
     JOIN public.countries co ON ((co.country_id = l.country_id)))
     JOIN public.teams ht ON ((ht.team_id = f.home_team_id)))
     JOIN public.teams at ON ((at.team_id = f.away_team_id)))
  WHERE ((fb.status = 'confirmed_broadcast'::text) AND (f.kickoff_date >= CURRENT_DATE))
  ORDER BY f.kickoff_date, f.kickoff_time;


ALTER VIEW public.upcoming_broadcast_fixtures OWNER TO postgres;

--
-- Name: upcoming_watch_guide; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.upcoming_watch_guide WITH (security_invoker='true') AS
 SELECT fb.broadcast_id,
    fb.market,
    fb.status,
    fb.broadcaster,
    fb.channel,
    fb.streaming_service,
    fb.service_product,
    fb.access_type,
    fb.delivery_methods,
    fb.platform_device,
    fb.is_live,
    fb.uk_available,
    fb.is_fast,
    fb.is_free_to_air,
    fb.is_subscription,
    fb.is_ppv,
    fb.watch_url,
    fb.confidence,
    fb.availability_notes,
    fb.source,
    fb.source_url,
    fb.verified_at,
    f.fixture_id,
    f.slug,
    f.kickoff_date,
    f.kickoff_time,
    f.league_id,
    l.code AS league_code,
    l.name AS league_name,
    co.name AS country_name,
    ht.team_id AS home_team_id,
    ht.display_name AS home_team_name,
    at.team_id AS away_team_id,
    at.display_name AS away_team_name,
    f.predicted_home_goals,
    f.predicted_away_goals,
    hc.name AS home_team_country,
    ac.name AS away_team_country,
    l.competition_type,
    l.tier AS league_tier
   FROM (((((((public.fixture_broadcasts fb
     JOIN public.fixtures f ON ((f.fixture_id = fb.fixture_id)))
     JOIN public.leagues l ON ((l.league_id = f.league_id)))
     JOIN public.countries co ON ((co.country_id = l.country_id)))
     JOIN public.teams ht ON ((ht.team_id = f.home_team_id)))
     JOIN public.teams at ON ((at.team_id = f.away_team_id)))
     LEFT JOIN public.countries hc ON ((hc.country_id = ht.country_id)))
     LEFT JOIN public.countries ac ON ((ac.country_id = at.country_id)))
  WHERE ((f.kickoff_date >= CURRENT_DATE) AND ((fb.status = 'confirmed_not_televised'::text) OR COALESCE(fb.uk_available, true)))
  ORDER BY f.kickoff_date, f.kickoff_time;


ALTER VIEW public.upcoming_watch_guide OWNER TO postgres;

